export const CARDIOLOGIE_V2=[
q("cardiologie-adv-001",["Suportul vital de bază la adult și la copil:",
 ["fiecare respirație de salvare durează 3-4 secunde","compresiuni sternale de 5-6 cm, cu frecvența 100-120/minut","raportul compresiuni:ventilații 30:2 la adult, 15:2 la copil","pauze de reevaluare la 2 minute, chiar fără semne de viață","la copil, salvatorul unic alertează după minimum un minut de RCP"],"BCE",1046,"Proceduri terapeutice — Suportul vital de bază",
 "Aplicarea parametrilor numerici ai compresiunilor și ventilațiilor din suportul vital de bază, cu diferențele dintre adult și copil.",
 ["Nu: fiecare dintre cele două respirații eficiente durează 1 secundă, nu 3-4 secunde.","Sternul se comprimă la 5-6 cm, cu 100-120 compresiuni pe minut, permițând revenirea lui după fiecare compresiune.","Raportul compresiuni toracice:ventilații este 30:2 la adulți și 15:2 la pacienții pediatrici.","Nu: RCP nu se întrerupe pentru reevaluare decât dacă victima prezintă semne de viață și reîncepe să respire normal.","Stopul respirator fiind mai frecvent la copii, salvatorul unic aplică respirații de salvare și cel puțin un minut de RCP înainte de a cere ajutor."]],
 [8,"Combină trei praguri numerice reale (adâncime, frecvență, raport pediatric) cu doi distractori care alterează durata ventilației și introduc o pauză de reevaluare pe care textul o interzice."],["5-6 cm","hands only BLS"]),

q("cardiologie-adv-002",["Bărbat de 78 de ani cu sincope repetate; ECG: disociație AV completă, ritm ventricular 30 b.p.m., QRS de 0,16 sec. În acest caz:",
 ["ritm de scăpare hisian, de 50-60/minut","atropina i.v. rezolvă durabil blocul, fără cardiostimulare","bloc distal, cu ritm de scăpare sub fasciculul His","cauza probabilă la această vârstă este boala Lenegre","cardiostimularea permanentă nu reduce semnificativ mortalitatea"],"C",1055,"Bradicardiile și tulburările de conducere — Bloc AV gradul III (complet)",
 "Localizarea sediului blocului AV complet pe baza duratei QRS și a frecvenței ritmului de scăpare, cu implicațiile etiologice și terapeutice.",
 ["Nu: ritmul din fasciculul His are complexe înguste (<0,12 sec) și 50-60 b.p.m.; aici complexele sunt largi și ritmul este lent.","Nu: atropina poate fi utilă doar în BAV cu complexe înguste, debut recent și cauze tranzitorii, nu în blocul distal cu complexe largi.","Cu QRS >0,12 sec, ritmul de scăpare are originea sub fasciculul His, blocul fiind distal în sistemul His-Purkinje; ritmul este lent (15-40 b.p.m.) și instabil.","Nu: la vârstnici cauza frecventă este boala Lev (fibroză degenerativă distală); boala Lenegre apare la tineri.","Nu: cardiostimularea permanentă este indicată întrucât reduce semnificativ mortalitatea."]],
 [8,"Cere deducerea sediului blocului din parametrii ECG ai vignetei și inversează perechea Lev/Lenegre după vârstă, precum și efectul cardiostimulării asupra mortalității."],["sincopa Stokes-Adams","Boala Lev"]),

q("cardiologie-adv-003",["Căile accesorii din tahicardia prin reintrare atrioventriculară:",
 ["sunt cel mai frecvent pe partea stângă","sunt multiple în circa 10% din cazuri","dau preexcitație cu PR prelungit și QRS îngust","cele ascunse conduc doar retrograd, invizibile în ritm sinusal","fibrele Mahaim intră în miocard în regiunea ramurii drepte"],"ABDE",1058,"Tahicardiile supraventriculare — Tahicardia prin reintrare atrioventriculară",
 "Cunoașterea anatomiei și a comportamentului electrofiziologic al căilor accesorii (localizare, multiplicitate, căi ascunse/manifeste, fibre Mahaim) și a semnelor ECG de preexcitație.",
 ["Căile accesorii sunt cel mai frecvent localizate pe partea stângă, dar pot apărea oriunde în apropierea șanțului atrioventricular.","Multiple căi accesorii sunt prezente la același pacient în aproximativ 10% din cazuri.","Nu: preexcitația produce interval PR scurt și complex QRS larg, prin lărgirea pantei ascendente (unda delta).","Căile care conduc doar dinspre ventricul spre atriu nu sunt vizibile pe ECG în ritm sinusal și se numesc căi ascunse.","Fibrele Mahaim sunt fibre atriofasciculare sau nodofasciculare care pătrund în miocardul ventricular în regiunea ramurii drepte."]],
 [8,"Patru detalii electrofiziologice fine sunt adevărate, iar singurul distractor inversează ambele componente ale aspectului ECG de preexcitație."],["fascicule Kent","căi ascunse"]),

q("cardiologie-adv-004",["Femeie de 68 de ani, hipertensivă, fără alte comorbidități, cu fibrilație atrială non-valvulară. În acest caz:",
 ["scorul CHA2DS2-VASc este de 3 puncte","antiagregantele sunt o alternativă recomandată anticoagulării","risc anual de AVC al categoriei sale de 2,2%, cu anticoagulare orală","scorul este 2, vârsta sub 75 ani nepunctându-se","anticoagulantele orale directe nu necesită monitorizarea INR"],"ACE",1062,"Tahicardiile supraventriculare — Fibrilația atrială: anticoagularea",
 "Calcularea scorului CHA2DS2-VASc pe un caz concret și alegerea strategiei antitrombotice conform riscului estimat.",
 ["Hipertensiunea (1 punct), vârsta 65-74 ani (1 punct) și sexul feminin (1 punct) totalizează 3 puncte (Cadranul 30.15).","Nu: folosirea antiagregantelor plachetare pentru prevenția AVC nu este recomandată.","Cadranul 30.15 indică pentru categoria de 2+ puncte un risc anual de AVC ischemic de 2,2% și recomandă anticoagularea orală.","Nu: vârsta de 65-74 ani se punctează cu 1 punct (≥75 ani cu 2 puncte), iar scorul pacientei este 3.","Anticoagulantele orale directe nu necesită monitorizarea INR și au mai puține interacțiuni medicamentoase sau alimentare decât warfarina."]],
 [8,"Necesită aplicarea corectă a punctajului diferențiat pe vârstă și sex, iar distractorii oferă un scor plauzibil greșit și o strategie (antiagregante) explicit nerecomandată."],["INR de 2,0-3,0","urechiuşei atriale"]),

q("cardiologie-adv-005",["Antiaritmicele în clasificarea Vaughan Williams:",
 ["clasa Ib (lidocaină, mexiletină) scurtează potențialul de acțiune","sotalolul are risc de torsadă redus în prezența hipopotasemiei","clasa Ic (flecainidă, propafenonă) nu modifică durata potențialului de acțiune","clasa I se evită în boala coronariană sau structurală","dronedarona este contraindicată în insuficiența cardiacă"],"ACDE",1067,"Aritmiile ventriculare — Medicamentele antiaritmice: clasificarea Vaughan Williams",
 "Diferențierea subclaselor de antiaritmice după efectul pe potențialul de acțiune și cunoașterea restricțiilor de utilizare în boala cardiacă structurală.",
 ["Cadranul 30.19: clasa Ib (lidocaină, mexiletină) scurtează potențialul de acțiune.","Nu: riscul de torsadă a vârfurilor sub sotalol este crescut dacă pacientul are hipopotasemie, în special sub diuretice.","Cadranul 30.19: clasa Ic (flecainidă, propafenonă) nu are efect asupra duratei potențialului de acțiune.","După trialurile CAST, agenții de clasă I se limitează la pacienții fără boală coronariană, disfuncție de VS sau boală cardiacă structurală.","Dronedarona scade recurența fibrilației atriale, dar este nocivă în disfuncția VS și contraindicată în insuficiența cardiacă."]],
 [8,"Solicită memorarea efectelor opuse ale subclaselor Ia/Ib/Ic asupra potențialului de acțiune și inversează relația dintre hipopotasemie și riscul de torsadă sub sotalol."],["trialurile CAST","torsada vârfurilor"]),

q("cardiologie-adv-006",["Medicația insuficienței cardiace cronice:",
 ["spironolactona: ginecomastie la circa 1 din 100 de bărbați","nebivololul se rezervă formei stabile ușoare-moderate sub 70 de ani","RALES: spironolactona reduce mortalitatea cu 30% în forma severă","sacubitril/valsartan se asociază cu un IECA, potențând efectul","EPHESUS: eplerenona reduce moartea subită cu 21%, fără ginecomastie"],"CE",1074,"Insuficiența cardiacă — Tratament: antagoniștii de aldosteron și ARNI",
 "Cunoașterea rezultatelor studiilor RALES, EPHESUS și PARADIGM-HF și a precauțiilor specifice fiecărei clase terapeutice.",
 ["Nu: ginecomastia sau durerea mamară au apărut la 1 din 10 bărbați tratați cu spironolactonă.","Nu: nebivololul se utilizează în insuficiența cardiacă stabilă ușoară-moderată la pacienții peste 70 de ani; bisoprololul și carvedilolul reduc mortalitatea în toate gradele de severitate.","În studiul RALES, spironolactona a redus mortalitatea totală cu 30% în insuficiența cardiacă severă.","Nu: IECA se oprește cu 3 zile înainte de începerea sacubitril/valsartan (Cadranul 30.25).","În EPHESUS, eplerenona a redus mortalitatea totală cu 15% și moartea subită cu 21%, fără apariția ginecomastiei."]],
 [8,"Distractorii modifică o frecvență reală a efectului advers (1/10 devine 1/100), atribuie nebivololului beneficiul bisoprololului/carvedilolului și inversează regula de tranziție IECA-ARNI."],["studiul RALES","PARADIGM-HF"]),

q("cardiologie-adv-007",["Pacient de 66 de ani cu ortopnee, raluri bilaterale, TA 80/50 mmHg, 112 b.p.m., diureză 0,3 ml/kg/oră și disfuncție sistolică severă de VS. În acest caz:",
 ["tabloul corespunde șocului cardiogen","la TAS sub 85 mmHg se indică inotrope/vasopresoare","gliceril trinitrat în perfuzie, ca primă intenție","anticoagulare profilactică cu heparină cu greutate moleculară mică","NT-proBNP peste 300 pg/ml ar exclude diagnosticul"],"ABD",1077,"Insuficiența cardiacă acută — Sindroame clinice, diagnostic și tratament",
 "Recunoașterea șocului cardiogen după criteriile hemodinamice și alegerea treptei terapeutice corespunzătoare tensiunii arteriale sistolice în algoritmul ESC.",
 ["Cadranul 30.28 definește șocul cardiogen prin TAS <90 mmHg, diureză <0,5 ml/kg/oră și frecvență cardiacă >60 b.p.m.","Algoritmul ESC (Fig. 30.59) indică la TAS <85 mmHg inotrope și/sau vasopresoare (dopamină și/sau noradrenalină), după evaluarea încărcării de volum.","Nu: vasodilatatoarele (NTG/nitrați) sunt rezervate pacienților cu TAS mai mare; la TAS <85 mmHg se indică inotrope/vasopresoare.","Toți pacienții cu insuficiență cardiacă acută necesită anticoagulare profilactică cu heparină cu greutate moleculară mică.","Nu: BNP >100 pg/ml sau NT-proBNP >300 pg/ml sunt sugestive pentru insuficiența cardiacă."]],
 [8,"Cere încadrarea vignetei în definiția hemodinamică a șocului cardiogen și aplicarea pragului de TAS din algoritm, cu un distractor care inversează semnificația peptidelor natriuretice."],["clasificarea Forrester","miocardului siderat"]),

q("cardiologie-adv-008",["Tratamentul farmacologic al anginei stabile:",
 ["verapamilul dă frecvent edeme retromaleolare și tahicardie reflexă","nitrații sunt contraindicați cu inhibitorii de fosfodiesterază 5","ivabradina (inhibitor If) se folosește în fibrilația atrială","nicorandilul activează canalele K-ATP și are proprietăți de nitrat","ranolazina, metabolizată de CYP3A4, poate prelungi QT"],"BDE",1083,"Angina — Tratamentul farmacologic al anginei stabile (Cadranul 30.33)",
 "Cunoașterea mecanismelor, precauțiilor și reacțiilor adverse specifice ale claselor de antianginoase din Cadranul 30.33.",
 ["Nu: Cadranul 30.33 atribuie verapamilului constipația; edemele retromaleolare țin de amlodipină și diltiazem, iar tahicardia reflexă de amlodipină.","Cadranul 30.33 contraindică asocierea nitraților cu inhibitorii de fosfodiesterază 5 (sildenafil, tadalafil).","Nu: ivabradina inhibă curentul If al nodului sino-atrial și se utilizează în ritm sinusal, cu sau fără beta-blocante.","Nicorandilul este activator al canalelor de potasiu sensibile la ATP, cu proprietăți de nitrat și vasodilatație coronară și periferică.","Ranolazina este metabolizată de citocromul P450 3A4, iar reacțiile adverse includ QT lung."]],
 [8,"Patru mecanisme farmacologice puțin cunoscute sunt corecte, iar distractorul atribuie verapamilului reacțiile adverse specifice dihidropiridinelor din același tabel."],["fosfene","canale de potasiu sensibile la ATP"]),

q("cardiologie-adv-009",["În sindromul coronarian acut se recomandă:",
 ["prasugrel 300-600 mg încărcare, apoi 75 mg/zi","ticagrelor 180 mg încărcare, apoi 2 × 90 mg/zi","inhibitori GP IIb/IIIa de rutină, indiferent de încărcarea trombotică","fondaparinux, care inactivează factorul Xa prin antitrombină","bivalirudină, inhibitor direct și reversibil al trombinei"],"BDE",1086,"Sindroamele coronariene acute — Medicația antiplachetară și anti-trombinică",
 "Cunoașterea dozelor de încărcare și de întreținere ale inhibitorilor P2Y12 și a mecanismelor agenților anti-trombinici din SCA.",
 ["Nu: 300-600 mg, apoi 75 mg pe zi sunt dozele clopidogrelului; prasugrelul se administrează 60 mg încărcare, apoi 10 mg pe zi.","Ticagrelorul se administrează 180 mg doză de încărcare, apoi 90 mg de două ori pe zi, în cadrul dublei antiagregări.","Nu: inhibitorii GP IIb/IIIa se rezervă pacienților cu încărcare trombotică marcată la coronarografie și complicațiilor PCI.","Fondaparinux este un pentazaharid sintetic care activează selectiv antitrombina, inactivând factorul Xa, fără efecte antiplachetare.","Bivalirudina este un inhibitor direct al trombinei, care se leagă reversibil de aceasta și îi inhibă fixarea de cheag."]],
 [8,"Schimbă dozele între doi inhibitori P2Y12 înrudiți și extinde la rutină o indicație pe care textul o restrânge la încărcarea trombotică marcată și la complicațiile PCI."],["pentazaharid","inhibitor direct al trombinei"]),

q("cardiologie-adv-010",["Bărbat de 58 de ani cu durere toracică de 40 de minute; ECG: subdenivelare ST în V1-V3 cu undă R amplă, supradenivelare ST în V5/V6. Localizarea infarctului este:",
 ["anterioară, modificările interesând V1-V3","inferioară, cu modificări în oglindă în V5/V6","posterioară, cu modificări în oglindă în V1-V3","laterală, prin supradenivelarea ST izolată din V5/V6","de ventricul drept, de confirmat în derivația V4R"],"C",1088,"Sindroamele coronariene acute — STEMI: modificările ECG (Cadranul 30.40)",
 "Recunoașterea infarctului miocardic posterior după modificările ST în oglindă și unda R amplă din derivațiile precordiale drepte.",
 ["Nu: IM anterior produce supradenivelare ST în V1-V3/V4, nu subdenivelare cu undă R amplă.","Nu: IM inferior se diagnostichează prin supradenivelare ST în DII, DIII și aVF, nu prin modificări în V1-V3.","În IM posterior apar subdenivelare ST în V1-V3 cu undă R amplă (modificări în oglindă) și supradenivelare ST în V5/V6.","Nu: IM lateral produce modificări ST-T în DI, aVL și V5/V6, dar nu explică subdenivelarea cu undă R amplă din V1-V3.","Nu: IM de ventricul drept se diagnostichează prin supradenivelare ST în V4R, nu prin acest tipar precordial."]],
 [8,"Tiparul ECG al infarctului posterior este contraintuitiv (subdenivelare ca semn de infarct), iar distractorii oferă localizări justificate plauzibil prin câte o derivație din vignetă."],["modificări în oglindă","undă R amplă"]),

q("cardiologie-adv-011",["Valvulotomia mitrală cu balon prin puncție transseptală:",
 ["necesită by-pass cardiopulmonar, ca valvulotomia pe cord deschis","se preferă la valve suple, cu afectare subvalvulară și regurgitare minime","folosește un dilatator transapical, ghidat digital","este contraindicată în tromboza atrială stângă","este indicată mai ales când coexistă regurgitare mitrală moderată"],"BD",1094,"Valvulopatiile — Stenoza mitrală: tratament",
 "Diferențierea indicațiilor, contraindicațiilor și tehnicii valvulotomiei percutane cu balon de celelalte metode de corecție a stenozei mitrale.",
 ["Nu: procedura se desfășoară în laboratorul de cateterism, sub anestezie locală, fără by-pass cardiopulmonar (necesar doar pe cord deschis).","Procedura este preferabilă la valve suple, cu afectare minimă a aparatului subvalvular și regurgitare mitrală minimă.","Nu: dilatatorul avansat prin apexul VS și ghidat de degetul chirurgului descrie valvulotomia pe cord închis, nu procedura cu balon.","Tromboza atrială stângă este o contraindicație, exclusă înaintea procedurii prin ecografie transesofagiană.","Nu: regurgitarea mitrală mai mult decât ușoară este o contraindicație, iar coexistența regurgitării impune protezarea mitrală."]],
 [8,"Distractorii atribuie procedurii percutane elemente tehnice ale valvulotomiei pe cord închis și deschis și transformă o contraindicație (regurgitarea moderată) în indicație."],["Scorul Wilkins","comisurilor mitrale fuzionate"]),

q("cardiologie-adv-012",["Stenoza aortică se caracterizează prin:",
 ["suflu de ejecție a cărui durată crește cu severitatea","intensitatea suflului bine corelată cu severitatea","dedublare paradoxală a zgomotului 2, în expir","șoc apexian deplasat inferior și lateral, difuz","zgomot 4 intens, accentuat de o stenoză mitrală asociată"],"AC",1098,"Valvulopatiile — Stenoza aortică: tablou clinic",
 "Interpretarea semnelor auscultatorii și palpatorii ale stenozei aortice și a relației lor cu severitatea leziunii.",
 ["Durata suflului crescendo-descrescendo crește cu severitatea stenozei, prin prelungirea timpului de ejecție sistolică.","Nu: nu există o bună corelație între intensitatea suflului și severitate; în stenozele foarte severe suflul poate fi inaudibil.","Dedublarea paradoxală a zgomotului 2 (în expir) este enumerată printre semnele stenozei aortice.","Nu: șocul apexian nu este deplasat, deoarece hipertrofia nu produce cardiomegalie semnificativă; este însă susținut și amplu.","Nu: zgomotul 4 intens este audibil doar în absența stenozei mitrale."]],
 [8,"Inversează două relații reale (intensitate/severitate și zgomot 4/stenoză mitrală) și atribuie stenozei aortice șocul apexian deplasat, caracteristic regurgitării aortice de pe pagina următoare."],["diamond-shaped","dilatare poststenotică"]),

q("cardiologie-adv-013",["Indicațiile chirurgicale în regurgitarea aortică includ:",
 ["regurgitarea severă acută, de exemplu în endocardită","regurgitarea severă cronică simptomatică (NYHA II-IV, angină)","pacienții asimptomatici cu FEVS ≤50%","asimptomatici, FEVS >50%, diametru VS telediastolic >70 sau telesistolic >50 mm","asimptomatici cu FEVS >50% și VS nedilatat, preventiv"],"ABCD",1100,"Valvulopatiile — Regurgitarea aortică: tratament",
 "Cunoașterea criteriilor clinice, funcționale și dimensionale care indică înlocuirea valvei aortice în regurgitarea aortică.",
 ["Regurgitarea aortică severă acută (de exemplu în endocardita infecțioasă acută) este indicație chirurgicală.","Regurgitarea severă cronică la pacienți simptomatici (dispnee clasă NYHA II-IV sau angină) este indicație chirurgicală.","Pacienții asimptomatici cu FEVS ≤50% au indicație chirurgicală.","La asimptomaticii cu FEVS >50%, chirurgia se indică dacă VS este dilatat (diametru telediastolic >70 mm sau telesistolic >50 mm).","Nu: asimptomaticii cu FEVS >50% și VS nedilatat nu îndeplinesc niciun criteriu chirurgical; chirurgia nu se face pentru prevenirea remodelării."]],
 [8,"Cere reținerea pragurilor exacte de FEVS și de diametre ventriculare, distractorul fiind o variantă plauzibilă fără criteriu dimensional."],["Semnul Quincke","uruitura Austin Flint"]),

q("cardiologie-adv-014",["Protezele valvulare și anticoagularea în sarcină:",
 ["heparina cu greutate moleculară mică traversează placenta","valvele mecanice sunt preferate, fiind mai puțin trombogene","heparina nefracționată: tromboză valvulară sub 5%","warfarina traversează placenta: 5-12% embriopatie în trimestrul I","la vârstă fertilă, valvele biologice se degradează 50% abia la 15 ani"],"D",1103,"Valvulopatiile — Protezele valvulare: sarcina și protezele valvulare",
 "Cunoașterea riscurilor materne și fetale ale diferitelor strategii de anticoagulare la gravidele cu proteze valvulare.",
 ["Nu: heparinele (nefracționată și cu greutate moleculară mică) nu traversează placenta și nu cauzează embriopatii.","Nu: în sarcină sunt preferate valvele biologice, mai puțin trombogene; valvele mecanice necesită anticoagulare pe viață.","Nu: heparina nefracționată poate să nu ofere o anticoagulare consecventă, cu o incidență ridicată (25%) a trombozei valvulare.","Warfarina traversează bariera placentară, cu un risc de 5-12% de embriopatie în primul trimestru.","Nu: la femeile aflate la vârstă fertilă, degradarea valvelor biologice este de 50% la 10 ani și de 90% la 15 ani."]],
 [8,"Distractorii inversează proprietățile heparinei și ale tipurilor de proteze și modifică pragurile numerice reale (25% tromboză, 50%/10 ani și 90%/15 ani)."],["status hipercoagulant","nivelul anti-Xa"]),

q("cardiologie-adv-015",["Explorările paraclinice în endocardita infecțioasă:",
 ["ecocardiografia transtoracică: primă linie, sensibilitate 60-75%","hemoculturi într-un singur set, înaintea antibioterapiei","ecocardiografia transesofagiană: sensibilitate >90%, esențială pe proteză","PR prelungit se asociază cu abcesul rădăcinii aortice","proteina C reactivă crește sub antibioterapie eficientă"],"ACD",1106,"Endocardita infecțioasă — Explorări și rezultate (Cadranul 30.47)",
 "Cunoașterea performanței diagnostice a ecocardiografiei transtoracice și transesofagiene și a semnificației modificărilor ECG și inflamatorii în endocardită.",
 ["Cadranul 30.47 descrie ecocardiografia transtoracică drept explorarea imagistică de primă linie, cu sensibilitate de 60-75%.","Nu: se recoltează trei seturi de hemoculturi, din locuri de puncție diferite.","Ecocardiografia transesofagiană, explorare de a doua linie cu sensibilitate >90%, este utilă pentru abcesul rădăcinii aortice și esențială în endocardita pe proteză.","Prelungirea intervalului PR și alte tulburări de conducere se asociază cu abcesele rădăcinii aortice (Cadranul 30.47).","Nu: proteina C reactivă scade ca răspuns la terapia antibiotică și crește din nou în recăderi."]],
 [8,"Solicită valorile de sensibilitate ale celor două tehnici ecografice și inversează dinamica PCR sub tratament, plus numărul de seturi de hemoculturi."],["abces al rădăcinii aortice","Febra persistentă"]),

q("cardiologie-adv-016",["Cardiomiopatia aritmogenă:",
 ["prevalență de 7-12 la 100.000 de locuitori","sindromul Carvajal ține de mutația RyR2","insuficiența dreaptă precede aritmiile, care apar tardiv","afectarea VS, raportată în până la 75% din cazuri","boala Naxos ține de mutația plakoglobinei"],"DE",1121,"Bolile miocardului — Cardiomiopatia aritmogenă",
 "Cunoașterea epidemiologiei, geneticii și evoluției stadiale a cardiomiopatiei aritmogene, inclusiv formele recesive sindromice.",
 ["Nu: prevalența de 7-12/100.000 aparține cardiomiopatiei dilatative; cardiomiopatia aritmogenă apare la 1 din 1.000-5.000 de locuitori.","Nu: sindromul Carvajal se datorează mutației desmoplakinei; receptorul de rianodină RyR2 este asociat formei autosomal dominante și TVPC.","Nu: aritmiile ventriculare și riscul de moarte subită apar în stadiile precoce, iar insuficiența dreaptă sau biventriculară în stadiile avansate.","Afectarea ventriculului stâng a fost raportată în până la 75% din cazuri.","Boala Naxos, formă recesivă cu keratodermă plantară și păr lânos, se datorează mutației plakoglobinei joncționale."]],
 [8,"Distractorii împrumută prevalența cardiomiopatiei dilatative din pagina următoare, schimbă genele celor două forme recesive și inversează cronologia aritmii/insuficiență cardiacă."],["boala Naxos","păr lânos"]),

q("cardiologie-adv-017",["Cardiomiopatia dilatativă:",
 ["prevalență de 7-12 la 100.000 de locuitori","dilatare și disfuncție sistolică, cu grosime parietală prezervată","distrofina: forma autosomal dominantă; lamin A/C: forma X-linkată","boala Chagas nu e cauză a formei sporadice","forma familială: predominant autosomal dominantă, peste 20 de loci"],"ABE",1122,"Bolile miocardului — Cardiomiopatia dilatativă",
 "Cunoașterea definiției, epidemiologiei și bazelor genetice ale cardiomiopatiei dilatative, cu diferențierea formelor X-linkate de cele autosomal dominante.",
 ["Cardiomiopatia dilatativă are o prevalență de 7-12 cazuri la 100.000 de locuitori.","Cardiomiopatia dilatativă se definește prin dilatarea cavităților ventriculare și disfuncție sistolică, cu grosime parietală prezervată.","Nu: distrofina este implicată în cardiomiopatia X-linkată, iar lamin A/C în forma autosomal dominantă.","Nu: boala Chagas (paraziți) este printre cauzele de miocardită din forma sporadică, alături de virusuri, bacterii, fungi și micobacterii.","Forma familială este predominant autosomal dominantă și a fost asociată cu peste 20 de loci și gene anormale."]],
 [8,"Inversează asocierea genă-mod de transmitere (distrofină/lamin a/c) și restrânge nejustificat etiologia infecțioasă, restul enunțurilor conținând cifre exacte."],["grosime parietală prezervată","cardiomiopatia X-linkată"]),

q("cardiologie-adv-018",["Pericardita constrictivă se deosebește de tamponada cardiacă prin:",
 ["absența pulsului paradoxal, prezent în tamponadă","descendent y adânc (semnul Friedreich)","absența semnului Kussmaul, specific tamponadei","compromiterea acută a circulației, tamponada fiind cronică","cord globulos radiologic, tamponada având cord mic"],"B",1127,"Bolile pericardului — Revărsatul pericardic și pericardita constrictivă",
 "Diferențierea hemodinamică și clinică a pericarditei constrictive de tamponada cardiacă pe baza curbei venoase jugulare, a evoluției și a aspectului radiologic.",
 ["Nu: pulsul paradoxal este descris atât în tamponadă, cât și în pericardita constrictivă, deci nu le diferențiază.","În constricție presiunea venoasă jugulară crește cu descendent y adânc (semnul Friedreich), pe când în tamponadă panta descendentă x este ascuțită.","Nu: semnul Kussmaul este menționat atât în tamponadă, cât și în pericardita constrictivă.","Nu: tamponada compromite acut circulația, iar constricția este cronică, lăsând organismului timp să compenseze.","Nu: revărsatul cu tamponadă produce un cord mărit, globulos, iar pericardita constrictivă un cord relativ mic."]],
 [8,"Distractorii folosesc semne comune ambelor entități ca elemente de diferențiere și inversează evoluția temporală și aspectul radiologic."],["semnul Friedreich","semnul lui Ewart"]),

q("cardiologie-adv-019",["În țările occidentale, boala arterială coronariană:",
 ["reprezintă aproximativ 88% din cauzele de moarte subită","reprezintă circa 50% din cauzele de moarte subită","explică aproximativ 88% din decesele prin bradiaritmii severe","cauzează rar stopul în absența unui infarct acut evident","explică o minoritate a deceselor din primele 24 de ore"],"A",1045,"Proceduri terapeutice — Resuscitarea cardiacă",
 "Cunoașterea ponderii bolii coronariene în moartea subită și a mecanismului aritmic dominant.",
 ["Boala arterială coronariană reprezintă aproximativ 88% din cauzele de moarte subită în țările occidentale.","Nu: valoarea de 50% se referă la decesele care survin rapid; boala coronariană reprezintă circa 88% din cauzele de moarte subită.","Nu: bradiaritmiile severe produc o proporție mai mică de decese; 88% este ponderea bolii coronariene în moartea subită.","Nu: boala coronariană reprezintă circa 88% din moartea subită, deși doar o mică proporție din supraviețuitori au semne evidente de infarct acut.","Nu: din până la 100.000 de decese produse în Marea Britanie în primele 24 de ore de la simptomele cardiace, majoritatea au cauză coronariană."]],
 [8,"Confundă ponderea 88% a bolii coronariene cu jumătatea de decese rapide și cu mecanismul bradiaritmic minor."],["88%","moarte subită"]),

q("cardiologie-adv-020",["Lanțul supraviețuirii și căile aeriene în suportul vital de bază:",
 ["include recunoașterea, alertarea, RCP, defibrilarea, îngrijirea post-resuscitare","extensia capului, evitată la suspiciunea de leziune cervicală","protezele dentare mobile și obstacolele orale se îndepărtează","primul pas este palparea imediată a pulsului carotidian","manevra Heimlich vizează obstrucția căilor aeriene inferioare"],"ABC",1045,"Proceduri terapeutice — Lanțul supraviețuirii și căile aeriene",
 "Recunoașterea celor cinci verigi ale lanțului supraviețuirii și a manevrei de deschidere a căilor aeriene, cu excepția leziunii cervicale.",
 ["Lanțul supraviețuirii cuprinde recunoașterea timpurie a stopului, alertarea, RCP imediată, defibrilarea rapidă și îngrijirea post-resuscitare.","Flexia gâtului și extensia capului deschid căile aeriene, dar nu se recomandă la suspiciune de leziune a coloanei cervicale.","Obstacolele din cavitatea bucală sau faringe (sânge, mucus) și protezele dentare mobile trebuie îndepărtate.","Nu: primul pas este evitarea pericolelor suplimentare, apoi testarea răspunsului la stimuli; detectarea pulsului poate fi dificilă.","Nu: compresiunile abdominale și/sau toracice (Heimlich) se aplică obstrucției din cavitatea bucală posterioară sau din căile aeriene superioare."]],
 [8,"Inversează ordinea BLS (puls înaintea siguranței) și limitează greșit Heimlich la căile inferioare."],["Lanţul supravieţuirii","manevra Heimlich"]),

q("cardiologie-adv-021",["Compresiunile și ventilațiile în suportul vital de bază:",
 ["RCP mecanică este metoda de rutină extraspitalicească","compresiunile izolate mențin perfuzia cerebrală și coronariană","oboseala salvatorului scade eficiența compresiunilor","raportul 15:2 la adult și 30:2 la copil","oprirea RCP în fiecare minut pentru verificarea pulsului"],"BC",1046,"Suportul vital de bază — Compresiuni și respirație",
 "Diferențierea BLS „hands only” de RCP mecanică și recunoașterea efectului oboselii asupra calității compresiunilor.",
 ["Nu: RCP mecanică este posibilă, dar nu este încă utilizată de rutină.","Compresiunile izolate („hands only” BLS) sunt mai ușoare pentru neinițiați și mențin perfuzia cerebrală și coronariană până la sosirea personalului calificat.","Oboseala din timpul compresiunilor scade eficiența acestora și calitatea resuscitării.","Nu: raportul este 30:2 la adulți și 15:2 la pacienții pediatrici, nu invers.","Nu: RCP nu se întrerupe pentru reevaluare decât dacă apar semne de viață și respirație normală."]],
 [8,"Transformă o tehnică încă nedevenită rutină în standard și inversează rapoartele adult/copil deja clasice."],["hands only BLS","Resucitarea cardiopulmonara mecanică"]),

q("cardiologie-adv-022",["În algoritmul suportului vital avansat la adult se recomandă:",
 ["FV/TV fără puls: șoc bifazic 150-200 J, apoi 2 minute RCP","asistolă/AEP: adrenalină 1 mg la fiecare 3-5 minute","amiodaronă după 3 șocuri, în timpul RCP","șoc monofazic de 150 J ca standard actual","cale aeriană avansată: 20 ventilații/minut, cu pauze de masaj"],"ABC",1047,"Suportul vital cardiac avansat — Algoritmul ACLS",
 "Aplicarea energiilor de defibrilare, a adrenalinei în ritmurile neșocabile și a momentului amiodaronei.",
 ["Ritmul șocabil (FV/TV fără puls) impune un șoc bifazic nesincronizat de 150-200 J (360 J monofazic), urmat imediat de 2 minute de RCP.","În asistolă sau AEP se administrează 1 mg adrenalină la fiecare 3-5 minute de RCP.","Algoritmul prevede administrarea de amiodaronă după 3 șocuri.","Nu: 150-200 J este doza bifazică; defibrilatoarele bifazice necesită mai puțină energie și sunt tot mai utilizate.","Nu: după abordarea avansată a căilor aeriene, RCP continuă cu ventilație 10/minut, fără întreruperea masajului."]],
 [8,"Schimbă energia bifazică cu cea monofazică și dublează rata de ventilație post-intubație, două praguri adiacente din algoritm."],["150-200 J","Amiodaronă după 3 şocuri"]),

q("cardiologie-adv-023",["Tratamentul cauzelor reversibile ale stopului („patru H și patru T”):",
 ["hipoxia: oxigen pe mască, intubație sau dispozitiv supraglotic","hipovolemia hemoragică, cauză frecventă de AEP: repleție volemică","hipopotasemia: clorură de calciu i.v., ca în hipocalcemie","pneumotoracele în tensiune: toracocenteză cu ac sau toracostomie","hipotermia: exclusă cu termometru obișnuit, fără încălzire internă"],"ABD",1048,"Suportul vital avansat — Cauze reversibile (4H și 4T)",
 "Recunoașterea tratamentului specific al hipoxiei, hipovolemiei, tulburărilor de potasiu și pneumotoracelui în tensiune.",
 ["Hipoxia se limitează prin ventilație cu oxigen suplimentar pe mască cu rezervor, intubație sau dispozitive supraglotice, verificând ventilația ambelor arii pulmonare.","Hipovolemia este o cauză frecventă de AEP pe fond de hemoragie și necesită repleție volemică.","Nu: clorura de calciu intravenos poate fi utilă în hiperpotasemie sau hipocalcemie, nu în hipopotasemie.","Pneumotoracele în tensiune se diagnostichează clinic (deviere traheală, hipersonoritate, murmur absent, ecografie) și se tratează prin toracocenteză cu ac sau toracostomie.","Nu: hipotermia se exclude cu un termometru pentru temperaturi scăzute și se tratează prin încălzire externă și internă."]],
 [8,"Patru măsuri specifice sunt corecte, iar distractorul înlocuiește termometrul de hipotermie și încălzirea internă cu un instrument obișnuit."],["clorura de calciu","Hipovolemia"]),

q("cardiologie-adv-024",["Hipotermia terapeutică la adultul inconștient după stop prin FV extraspitalicesc vizează:",
 ["28-30°C, menținută 48-72 de ore","32-34°C, menținută 12-24 de ore","36-37°C, hipotermia fiind interzisă","32-34°C, menținută 2-4 ore","32-34°C, contraindicată în ritmurile neșocabile"],"B",1048,"Post resuscitare — Hipotermia terapeutică",
 "Reținerea intervalului termic 32-34°C și a duratei 12-24 de ore, cu nuanța studiului din 2013.",
 ["Nu: intervalul 28-30°C și durata de câteva zile nu apar în text; ținta citată este 32-34°C timp de 12-24 de ore.","Studiile au arătat că 32-34°C timp de 12-24 de ore poate îmbunătăți prognosticul adulților inconștienți după FV extraspitalicească.","Nu: un studiu din 2013 a găsit rezultate similare la 33°C și 36°C; importanța hipotermiei rămâne neclară, dar ținta citată este 32-34°C.","Nu: hipotermia de 32-34°C se menține 12-24 de ore, nu câteva ore.","Nu: hipotermia nu este contraindicată în ritmurile neșocabile; studiile au inclus și pacienți cu ritmuri neșocabile."]],
 [8,"Alege între trei ferestre termice plauzibile; doar 32-34°C/12-24 h este cifra din paragraf."],["32-34°C","12-24 ore"]),

q("cardiologie-adv-025",["Cardioversia cu curent direct a tahiaritmiilor instabile hemodinamic:",
 ["anestezic cu acțiune scurtă, fără miorelaxante de rutină","șoc nesincronizat, ca în defibrilarea fibrilației ventriculare","șoc livrat sincron pe panta descendentă a QRS","indicată în tahiaritmiile care au răspuns la medicație","poziția padelelor parasternal drept–apex este contraindicată"],"AC",1048,"Cardioversia cu curent direct",
 "Diferențierea șocului sincronizat pe panta descendentă a QRS de defibrilarea nesincronizată.",
 ["Se folosește un anestezic cu acțiune scurtă, iar miorelaxantele nu sunt utilizate de rutină.","Nu: spre deosebire de defibrilare, cardioversia folosește un șoc sincron.","Transmiterea șocului trebuie să coincidă cu panta descendentă a complexului QRS; aparatul declanșează automat șocul sincron.","Nu: cardioversia se indică tocmai în tahiaritmiile care nu răspund medicamentos sau sunt instabile.","Nu: sunt descrise două poziții ale padelelor, inclusiv dreapta sternului superior și apexul."]],
 [8,"Confundă cardioversia sincronă cu defibrilarea FV și anulează una dintre cele două poziții clasice de padele."],["panta descendentă","Cardioversia cu curent direct"]),

q("cardiologie-adv-026",["Balonul de contrapulsație aortică și definițiile aritmiilor:",
 ["complicațiile contrapulsației aortice apar la circa 20%","bradicardia: <60 b.p.m. ziua sau <50 b.p.m. nocturn","tahicardia: frecvență cardiacă peste 100/minut","complicațiile embolice sunt frecvente chiar sub heparină","bradicardia sportivului ține de tonusul simpatic crescut"],"ABC",1051,"Aritmiile cardiace — Definiții; contrapulsația aortică",
 "Memorarea ratei de complicații a IABP și a pragurilor numerice care definesc bradi- și tahicardia.",
 ["Complicațiile balonului de contrapulsație (disecție de aortă, ischemie de membru, embolizare, ruptură de balon) apar la aproximativ 20% dintre pacienți.","Bradicardia se definește ca frecvență <60 b.p.m. în timpul zilei sau <50 b.p.m. nocturn.","Tahicardia se definește ca frecvență cardiacă rapidă, >100 b.p.m.","Nu: complicațiile embolice sunt rare dacă se utilizează anticoagulare cu heparină.","Nu: la sportivi bradicardia se datorează tonusului vagal crescut, nu simpatic."]],
 [8,"Modifică 20% în „embolie frecventă sub heparină” și inversează tonusul vegetativ al bradicardiei de sportiv."],["20%","<60 b.p.m."]),

q("cardiologie-adv-027",["Mecanismul tahicardiilor atriale din intoxicația digitalică este:",
 ["reintrarea în jurul unui miez cicatricial ventricular","activitatea declanșată (postdepolarizări)","hipersensibilitatea sinusului carotidian, mediată neural","blocul unidirecțional pe o cale accesorie Kent","creșterea izolată a pantei fazei 0, fără postpotențiale"],"B",1052,"Mecanismele de producere a aritmiilor — Activitatea declanșată",
 "Identificarea activității trigger ca mecanism al tahicardiei atriale digitalice, distinct de reintrare.",
 ["Nu: reintrarea explică majoritatea tahicardiilor paroxistice regulate, nu specific intoxicația digitalică.","Tahicardiile atriale din intoxicația digitalică au ca mecanism activitatea declanșată (trigger), prin post-potențiale.","Nu: sinusul carotidian este implicat în sindroamele mediate neural, nu în intoxicația digitalică.","Nu: calea Kent aparține tahicardiei prin reintrare atrioventriculară, nu intoxicației digitalice.","Nu: activitatea trigger este definită de post-potențiale precoce sau tardive, nu de absența lor."]],
 [8,"Atribuie digitalicei mecanismul de reintrare sau de cale accesorie, deși textul o leagă explicit de postdepolarizări."],["intoxicaţia digitalică","post-potenţiale"]),

q("cardiologie-adv-028",["Sindroamele mediate neural și boala de nod sinusal:",
 ["sindromul de sinus carotidian: vârstnici, frecvent bradicardie","POTS: tahicardie la ortostatism, cu TA normală sau ușor scăzută","asistolă carotidiană >3 sec, simptomatică reproductibil: posibil pacing permanent","sincopa vasovagală afectează mai ales vârstnicii, rar tinerii","boala de nod simptomatică contraindică stimularea DDD"],"ABC",1053,"Bradicardiile — Sindroame mediate neural și boala de nod",
 "Diferențierea sinusului carotidian, POTS și indicația de pacing la asistolă >3 sec de sincopa vasovagală a tânărului.",
 ["Sindromul de sinus carotidian apare la vârstnici și determină frecvent bradicardie.","POTS se definește prin creșterea acută semnificativă a frecvenței cardiace, cu TA normală sau ușor redusă la ortostatism.","Hipersensibilitatea carotidiană cu asistolă >3 sec și simptome reproductibile la masaj poate beneficia de cardiostimulare permanentă.","Nu: sincopa reflexă (vasovagală) afectează mai frecvent adulții tineri, putând apărea și la vârstnici.","Nu: boala de nod simptomatică poate necesita stimulare permanentă DDD, asociată cu antiaritmice sau ablație pentru tahicardii."]],
 [8,"Inversează vârsta sincopei vasovagale și interzice stimularea DDD, deși textul o indică în boala de nod simptomatică."],["asistolă >3 sec","POTS"]),

q("cardiologie-adv-029",["Blocul atrioventricular de gradul II:",
 ["Mobitz I: PR prelungit progresiv până la P blocată","Mobitz II: PR constant, de obicei QRS >0,12 sec","conducerea 2:1/3:1 nu se clasifică Mobitz I sau II","Wenckebach de obicei infranodal, Mobitz II nodal","Wenckebach progresează mai des spre BAV complet decât Mobitz II"],"ABC",1053,"Bradicardiile — BAV de gradul II",
 "Localizarea nodală versus infranodală a subtipurilor Mobitz și recunoașterea conducerii 2:1 ca formă aparte.",
 ["Mobitz I (Wenckebach) se definește prin prelungirea progresivă a PR până la o undă P blocată.","Mobitz II are undă P blocată fără prelungirea progresivă a PR, iar QRS este de obicei larg (>0,12 sec).","Conducerea 2:1 sau 3:1 este o formă aparte, neîncadrată ca Mobitz I sau II.","Nu: relația este inversă — Wenckebach la nivelul nodului AV, Mobitz II infranodal (fascicul His).","Nu: riscul de progresie spre BAV complet este mai mare în Mobitz II decât în Wenckebach, ritmul de scăpare fiind mai puțin eficient."]],
 [8,"Inversează sediul Wenckebach/Mobitz II, capcana clasică de localizare a blocului de grad II."],["Mobitz I","conducere 2: 1"]),

q("cardiologie-adv-030",["BAV de gradul II în infarctul miocardic acut:",
 ["infarct inferior: monitorizare și stimulare temporară","infarct anterior: risc mai mare de BAV complet, pacing temporar","în infarctul anterior este benign, fără indicație de stimulare","blocul 2:1 are sediu infranodal, nu în nodul AV","atropina rezolvă durabil blocul din infarctul anterior"],"AB",1055,"Bradicardiile — BAV II în infarctul miocardic",
 "Diferențierea prognosticului BAV II din infarctul inferior față de cel anterior.",
 ["În BAV II din infarctul inferior se recomandă monitorizare și cardiostimulare temporară.","BAV II din infarctul anterior are risc mai mare de progresie spre BAV complet; se indică stimulare percutană temporară până la implantarea stimulatorului permanent.","Nu: forma din infarctul anterior nu este benignă, riscul de BAV complet fiind mai mare.","Nu: blocurile 2:1 se pot localiza atât la nivelul nodului AV, cât și infranodal.","Nu: atropina este discutată în BAV cu complexe înguste și cauze tranzitorii, nu ca vindecare a blocului anterior distal."]],
 [8,"Inversează gravitatea infarctului anterior versus inferior, perechea clasică de prognostic al BAV peri-infarct."],["infarctul miocardic anterior","cardiostimulare temporară"]),

q("cardiologie-adv-031",["Blocul atrioventricular complet congenital:",
 ["nu necesită stimulare dacă este asimptomatic","răspunde durabil la verapamil intravenos","se datorează bolii Lev, specifică vârstnicului","cardiostimulare indicată chiar dacă este asimptomatic","ritm de scăpare fix de 15-20/minut, indiferent de lățimea QRS"],"D",1055,"BAV complet — Forme congenitale",
 "Recunoașterea indicației de pacing în BAV congenital chiar asimptomatic.",
 ["Nu: cardiostimularea este recomandată și pentru BAV congenitale asimptomatice.","Nu: verapamilul nu este tratamentul BAV congenital; se recomandă cardiostimularea.","Nu: boala Lev este fibroza distală a vârstnicului; forma congenitală se asociază cu LES matern sau transpoziție.","Cardiostimularea este recomandată pentru BAV congenitale, chiar dacă sunt asimptomatice.","Nu: ritmul de scăpare depinde de sediu — 50-60 b.p.m. cu QRS îngust, 15-40 b.p.m. cu QRS larg."]],
 [8,"Extinde „watchful waiting” al BAV dobândit îngust asimptomatic la forma congenitală, pe care textul o pacează."],["BAV congenitale","LES matern"]),

q("cardiologie-adv-032",["Blocurile de ramură și hemiblocurile:",
 ["bloc incomplet: QRS până la 0,12 sec; complet: ≥0,12 sec","BRD: S adânc în DI/V6, R amplu tardiv în V1","hemiblocul antero-superior: deviație axială dreaptă","BRS păstrează activarea inițială, fără unde Q anormale","hemiblocul postero-inferior: ax QRS inferior și spre dreapta"],"ABE",1056,"Blocul de ramură — ECG și hemiblocuri",
 "Corelarea morfologiei QRS și a axului cu ramul sau fasciculul blocat.",
 ["Întârzierea incompletă de ramură alungește QRS până la 0,12 sec; blocul complet are QRS ≥0,12 sec.","În BRD ventriculul drept se activează tardiv: unde S adânci în DI și V6, unde R ample tardive în V1.","Nu: blocarea fasciculului antero-superior orientează activarea spre stânga și superior, cu deviație axială stângă.","Nu: ramul stâng inițiază activarea ventriculară, astfel că BRS determină și unde Q anormale.","Blocarea fasciculului postero-inferior orientează axul QRS inferior și spre dreapta."]],
 [8,"Neagă undele Q ale BRS, deși textul le leagă de inițierea stângă a activării ventriculare."],["0,12 sec","deviaţie axială stângă"]),

q("cardiologie-adv-033",["Etiologia blocului de ramură dreaptă:",
 ["anomalie congenitală izolată la 5% dintre sănătoși","BRD cu deviație axială stângă: DSA ostium primum","BRD izolat deviază axul la dreapta, fără hipertrofie VD","BRS complet se asociază rar cu insuficiența VS","DSA ostium secundum produce tipic BRS complet"],"AB",1057,"Bloc de ramură dreaptă — Etiologie",
 "Recunoașterea BRD-ului congenital la 5% din sănătoși și a asocierii ostium primum cu BRD plus ax stâng.",
 ["BRD poate fi o anomalie congenitală izolată, prezentă la 5% din populația sănătoasă.","Asocierea BRD cu deviație axială stângă este întâlnită în DSA de tip ostium primum.","Nu: BRD izolat nu afectează în general axul, decât în prezența HVD, a suprasarcinii de VD sau a unui bloc fascicular.","Nu: BRS complet este frecvent asociat cu insuficiența ventriculară stângă.","Nu: ostium primum, nu secundum, este legat de BRD cu deviație axială stângă."]],
 [8,"Transformă BRD-ul izolat într-un determinant al axului drept și mută markerul ostium primum pe ostium secundum."],["5% din populaţia sănătoasă","ostium primum"]),

q("cardiologie-adv-034",["Tahicardia prin reintrare în nodul atrioventricular (AVNRT):",
 ["este de două ori mai frecventă la femei","TSV paroxistice nodale: prevalență 2,5/1.000, debut la 12-30 de ani","forma tipică: anterograd pe calea lentă, retrograd pe rapidă","calea lentă are refractaritate lungă, cea rapidă scurtă","tahicardia sinusală inadecvată apare tipic la bărbatul vârstnic"],"ABC",1057,"TSV — AVNRT și tahicardia sinusală inadecvată",
 "Aplicarea epidemiologiei (femei ×2, 2,5/1.000, vârsta 12-30) și a circuitului slow-fast.",
 ["AVNRT este de două ori mai frecventă la femei.","TSV paroxistice dependente de nodul AV au o prevalență de aproximativ 2,5/1.000 și debut de obicei între 12 și 30 de ani.","În forma tipică (slow-fast), extrasistola găsește calea rapidă refractară, conduce anterograd pe calea lentă și revine retrograd pe calea rapidă.","Nu: calea lentă are perioadă refractară scurtă și conducere lentă, iar calea rapidă perioadă refractară lungă și conducere rapidă.","Nu: tahicardia sinusală inadecvată apare mai frecvent la femeile tinere, nu la bărbatul vârstnic cu boală structurală."]],
 [8,"Inversează proprietățile electrofiziologice ale căilor lentă/rapidă, capcana clasică a AVNRT."],["2,5/1.000","slow-fast"]),

q("cardiologie-adv-035",["Aspectul ECG tipic al AVNRT:",
 ["QRS normale, regulate, 140-240/min, P absente sau lângă QRS","unde F în dinți de fierăstrău, 300/min, conducere 2:1","RR neregulat neregulate, fără activitate atrială organizată","PR scurt și undă delta, în tahicardie ortodromică","QRS larg, prin activare ventriculară pe calea Kent"],"A",1058,"TSV — Aspectul ECG al AVNRT",
 "Recunoașterea QRS îngust 140-240/min cu P simultane ca tipar al AVNRT, distinct de flutter, FA și WPW.",
 ["AVNRT tipică are QRS normale, regulate, 140-240/min, cu unde P absente sau imediat înainte/după QRS.","Nu: undele F în dinți de fierăstrău la 300/min aparțin flutterului atrial.","Nu: intervalele RR neregulat neregulate definesc fibrilația atrială.","Nu: PR scurt și unda delta sunt semnele preexcitației în ritm sinusal, nu ale AVNRT.","Nu: AVNRT are de obicei QRS îngust; QRS larg prin calea Kent aparține AVRT antidromice."]],
 [8,"Oferă tipare ECG reale ale altor TSV din același cadran ca alternative la AVNRT."],["140-240/min","AVNRT"]),

q("cardiologie-adv-036",["Fibrilația atrială preexcitată din sindromul WPW:",
 ["cale cu refractaritate anterogradă <250 ms: risc de FV","moarte subită: 0,15-0,39% per pacient-an","verapamilul și digoxinul se evită, putând precipita FV","adenozina 6 mg, apoi 12 mg, este tratamentul de elecție","AVRT ortodromică dă de regulă tahicardie cu QRS larg"],"ABC",1059,"WPW — Fibrilația atrială preexcitată",
 "Recunoașterea pragului <250 ms, a riscului de moarte subită și a interdicției verapamil/digoxin în FA-WPW.",
 ["O perioadă refractară anterogradă <250 ms a căii accesorii permite frecvențe ventriculare foarte înalte, cu risc de fibrilație ventriculară.","Incidența morții subite este 0,15-0,39% per pacient-an, putând fi prima manifestare la tineri.","Verapamilul sau digoxinul pot accelera conducerea pe calea accesorie și precipita FV, deci nu se folosesc în FA asociată WPW.","Nu: adenozina termină AVNRT/AVRT; FA preexcitată cu QRS larg nu se tratează astfel.","Nu: AVRT ortodromică produce de obicei QRS înguste; cea antidromică produce QRS largi."]],
 [8,"Extinde adenozina (utilă în AVNRT) la FA preexcitată și inversează lățimea QRS a AVRT ortodromice."],["<250 ms","0,15-0,39%"]),

q("cardiologie-adv-037",["Tratamentul tahicardiilor dependente de nodul AV:",
 ["modificarea căii lente: succes 96%, BAV complet 1%","ablația unei căi accesorii: succes 95%, recurență 5%","în AVNRT: succes circa 50%, BAV complet 20%","verapamil după beta-blocant în tahicardia cu QRS >0,12 sec","adenozina este interzisă la astmatici, nu folosită cu precauție"],"AB",1059,"AVNRT/AVRT — Tratament pe termen lung și ablație",
 "Memorarea ratelor de succes 96%/95% și a riscului de 1% BAV la modificarea căii lente.",
 ["Modificarea căii lente este eficientă la 96% dintre pacienții cu AVNRT, cu risc de 1% de BAV complet.","Ablația unei căi accesorii unice are succes de 95% și recurență de 5%.","Nu: modificarea căii lente reușește la 96% dintre pacienți, iar BAV complet apare la 1%.","Nu: verapamilul nu trebuie administrat după beta-blocante sau în tahicardiile cu QRS >0,12 sec.","Nu: adenozina se utilizează cu precauție la astmatici, fără a fi interzisă."]],
 [8,"Înlocuiește 96%/1% și 95%/5% cu eșecuri de ordinul zecilor de procente, plauzibile pentru o procedură „invazivă”."],["96%","risc de 1%"]),

q("cardiologie-adv-038",["Epidemiologia și cauzele fibrilației atriale:",
 ["1-2% din populație și 5-15% peste 75 de ani","hipertensiunea și insuficiența cardiacă: cauze principale în țările dezvoltate","30-40% au cel puțin un părinte cu FA","apare la o treime după chirurgia cardiacă","boala reumatică: cauza principală în țările dezvoltate"],"ABCD",1059,"Fibrilația atrială — Epidemiologie",
 "Aplicarea cifrelor 1-2%, 5-15% peste 75 de ani, 30-40% istoric parental și o treime postoperator.",
 ["FA apare la 1-2% din populația generală și la 5-15% dintre persoanele peste 75 de ani.","Hipertensiunea și insuficiența cardiacă sunt cele mai frecvente cauze de FA în țările dezvoltate.","Aproximativ 30-40% dintre pacienți, mai ales cei tineri, au cel puțin un părinte cu FA.","FA apare la o treime dintre pacienții post-chirurgie cardiacă.","Nu: boala reumatică, alcoolul și tireotoxicoza sunt cauze clasice, dar hipertensiunea și insuficiența cardiacă sunt cele mai frecvente în țările dezvoltate."]],
 [8,"Păstrează etiologia „clasică” reumatică ca dominantă în Occident, deși textul o înlocuiește cu HTA și IC."],["1-2%","5-15%"]),

q("cardiologie-adv-039",["Clasificarea clinică a fibrilației atriale:",
 ["paroxistică: convertită spontan în cel mult 7 zile","persistentă: continuă, peste 7 zile","persistentă îndelungată: continuă, peste 1 an","permanentă: FA cu durată peste 48 de ore","nou diagnosticată: FA cu durată sub 24 de ore"],"ABC",1060,"Fibrilația atrială — Clasificare clinică",
 "Diferențierea pragurilor de 7 zile și 1 an și a FA permanente ca decizie comună, nu ca durată brută.",
 ["FA paroxistică se convertește spontan în cel mult 7 zile.","FA persistentă este continuă, cu durată >7 zile.","FA persistentă îndelungată este continuă, cu durată >1 an.","Nu: FA permanentă înseamnă decizia comună de a abandona reconversia, nu simpla durată de peste 48 de ore.","Nu: FA nou diagnosticată se definește independent de durată sau de severitatea simptomelor."]],
 [8,"Confundă pragul de anticoagulare al cardioversiei (48 h) cu definiția FA permanente."],["7 zile",">1 an"]),

q("cardiologie-adv-040",["Cardioversia electivă a fibrilației atriale cu durată peste 48 de ore:",
 ["DOAC scutesc de anticoagularea prealabilă de 3 săptămâni","anticoagulare 3 săptămâni înainte, minimum 4 săptămâni după","conversia electrică: succes circa 80%, bifazic mai eficient","ecografia transesofagiană e inutilă în cardioversia urgentă, neanticoagulată","pill in pocket: digoxin oral, netestat în prealabil"],"BC",1061,"Fibrilația atrială — Cardioversie și anticoagulare peri-procedurală",
 "Aplicarea ferestrei 3 săptămâni înainte / 4 după și a ratei de succes de 80% a cardioversiei electrice.",
 ["Nu: DOAC sau warfarina se folosesc 3 săptămâni înainte (excepție FA <48 de ore); DOAC nu scutesc de această fereastră.","Se anticoagulează 3 săptămâni anterior (warfarină cu INR 2,0-3,0 sau DOAC) și cel puțin 4 săptămâni după cardioversie.","Conversia electrică reușește la aproximativ 80% dintre pacienți; defibrilarea bifazică este mai eficientă.","Nu: dacă cardioversia este urgentă și pacientul nu este anticoagulat, ecografia transesofagiană exclude trombii intraatriali.","Nu: „pill in pocket” înseamnă flecainidă sau propafenonă orală, testate în prealabil în spital."]],
 [8,"Anulează fereastra de 3 săptămâni sub pretextul DOAC și înlocuiește antiaritmicul de buzunar cu digoxin."],["3 săptămâni","80%"]),

q("cardiologie-adv-041",["Controlul ritmului și al frecvenței în fibrilația atrială:",
 ["AFFIRM și AF-CHF: fără diferență de mortalitate între strategii","pentru ritm, în insuficiența cardiacă sau hipertrofia VS: doar amiodaronă","frecvența de repaus <110 b.p.m. este considerată controlată","ablația de vene pulmonare elimină nevoia de anticoagulare","amiodarona, prima alegere la tânărul fără boală structurală"],"ABC",1061,"Fibrilația atrială — Controlul ritmului și al frecvenței",
 "Aplicarea rezultatelor AFFIRM/AF-CHF, a restricției amiodaronei în IC/HVS și a țintelor de frecvență <110 apoi 60-80.",
 ["Studiile AFFIRM (>65 ani) și AF-CHF nu au arătat o diferență netă de mortalitate sau simptomatologie între strategii.","În insuficiența cardiacă sau hipertrofia de VS se recomandă doar amiodarona pentru menținerea ritmului sinusal.","Frecvența de repaus <110 b.p.m. este considerată controlată; dacă simptomele persistă, ținta este 60-80 în repaus și <110 la efort moderat.","Nu: o ablație aparent reușită nu elimină necesitatea unei anticoagulări eficiente.","Nu: amiodarona se rezervă cazurilor în care celelalte antiaritmice au eșuat, din cauza efectelor extracardiace."]],
 [8,"Transformă ablația într-un substitut al anticoagulării și promovează amiodarona ca primă linie la cordul structural normal."],["AFFIRM","sub 110 b.p.m."]),

q("cardiologie-adv-042",["Scorul HAS-BLED de 3 sau mai mult:",
 ["risc de hemoragie majoră de circa 1%/an, ca scorul 0","risc anual de hemoragie majoră de peste 5%","risc anual de hemoragie majoră sub 0,1%","estimează riscul anual de AVC, ca CHA2DS2-VASc","estimează sângerarea minoră, nu hemoragia majoră"],"B",1062,"Fibrilația atrială — Scorul HAS-BLED",
 "Reținerea pragului HAS-BLED ≥3 ca risc anual de hemoragie majoră >5%.",
 ["Nu: riscul anual de circa 1% corespunde scorului 0 (risc scăzut).","Un scor HAS-BLED de 3 sau mai mult indică risc crescut, cu risc anual de hemoragie majoră >5%.","Nu: la un scor ≥3 riscul anual de hemoragie majoră este >5%; valoarea <0,1% nu apare.","Nu: scorul HAS-BLED estimează riscul de sângerare, nu riscul de AVC.","Nu: scorul HAS-BLED estimează riscul de hemoragie majoră, nu de sângerare minoră."]],
 [8,"Confundă 1% al scorului 0 cu >5% al scorului ≥3, două capete ale aceleiași scale."],["HAS-BLED",">5%"]),

q("cardiologie-adv-043",["Flutterul atrial tipic, dependent de istm:",
 ["macro-reintrare în jurul inelului tricuspidian, 250-350/minut","cel mai frecvent antiorar: F negative inferior, pozitive în V1","conducere AV tipic 2:1, cu frecvență ventriculară 150/minut","forma antiorară: F pozitive inferior, negative în V1","ablația de istm cavo-tricuspidian e ineficientă în forma tipică"],"ABC",1062,"Flutterul atrial — Mecanism și ECG",
 "Recunoașterea circuitului antiorar 250-350/min și a conducerii 2:1 la 150 b.p.m.",
 ["Flutterul tipic este un ritm atrial organizat de 250-350 b.p.m., prin macro-reintrare atrială dreaptă în jurul inelului tricuspidian.","Modelul cel mai frecvent este antiorar, cu unde F negative în derivațiile inferioare și pozitive în V1 și V2.","Cel mai frecvent este condusă fiecare a doua undă (2:1), cu frecvență ventriculară de 150 b.p.m.","Nu: undele F pozitive inferior și negative în V1 descriu flutterul orar, nu pe cel antiorar.","Nu: ablația de istm cavo-tricuspidian este terapia de elecție în flutterul tipic recurent, aproape definitivă."]],
 [8,"Inversează polaritatea undelor F antiorar/orar și degradează ablația de istm, metoda de elecție."],["250-350 b.p.m.","dinţi de fierăstrău"]),

q("cardiologie-adv-044",["Tahicardia atrială:",
 ["prevalență sub 1% dintre tipurile de aritmii","forma automată (125-250/minut): frecvent „warm-up” și „cool-down”","masajul sinusului carotidian o oprește, ca pe AVNRT","forma cu bloc e benignă, fără legătură cu digitala","forma prin reintrare, mai rapidă (>250/minut) decât cea automată"],"AB",1063,"Tahicardia atrială",
 "Diferențierea formei automate cu warm-up/cool-down de reintrarea mai lentă 125-150 și de efectul masajului carotidian.",
 ["Tahicardia atrială reprezintă sub 1% din toate tipurile de aritmii.","Forma prin automatism crescut (125-250 b.p.m.) are frecvent creștere și scădere progresivă a frecvenței („warm-up”, „cool-down”).","Nu: masajul sinusului carotidian poate crește gradul de BAV și ajută diagnosticul, dar nu oprește tahicardia.","Nu: tahicardia atrială cu bloc este de multe ori rezultatul intoxicației digitalice.","Nu: forma prin reintrare este de obicei mai lentă (125-150 b.p.m.)."]],
 [8,"Atribuie masajului carotidian oprirea AVNRT-like și inversează vitezele reintrare versus automatism."],["warm-up","sub 1%"]),

q("cardiologie-adv-045",["Pledează pentru tahicardie ventriculară, față de TSV cu aberanță:",
 ["QRS foarte larg, peste 0,14 sec","disociația atrioventriculară pe ECG","concordanța polarității QRS în V1-V6","unda S adâncă în derivația V6","QRS <0,10 sec, morfologie tipică de BRD"],"ABCD",1063,"Aritmiile ventriculare — Criterii ECG (Cadranul 30.17)",
 "Aplicarea criteriilor din Cadranul 30.17 și a regulii că 80% dintre tahicardiile cu QRS larg sunt ventriculare.",
 ["Cadranul 30.17 include QRS foarte larg (>0,14 sec) printre criteriile de tahicardie ventriculară.","Disociația atrioventriculară pledează pentru tahicardie ventriculară.","Concordanța QRS (aceeași polaritate în V1-V6) este un criteriu de tahicardie ventriculară.","Unda S adâncă în V6 este enumerată printre criteriile de tahicardie ventriculară.","Nu: QRS îngust cu morfologie tipică de bloc de ramură pledează pentru TSV cu aberanță, nu pentru TV."]],
 [8,"Cele patru criterii reale stau alături de morphologia care, dimpotrivă, susține TSV cu aberanță."],[">0,14 sec","disociaţie atrioventriculară"]),

q("cardiologie-adv-046",["Sindromul Brugada:",
 ["beta-blocantele sunt tratamentul de elecție","mutația SCN5A explică circa 80% din cazuri","singurul tratament eficient: ICD","testul de provocare folosește amiodarona","predomină la femei vârstnice din Europa de Nord"],"C",1064,"Sindromul Brugada",
 "Recunoașterea ICD ca unică terapie eficientă și a potențialului nociv al beta-blocantelor.",
 ["Nu: beta-blocantele nu sunt utile în sindromul Brugada, putând fi chiar nocive.","Nu: doar în circa 20% din cazuri boala este moștenită prin mutația SCN5A; sunt implicate și alte gene.","Singurul tratament eficient este implantarea ICD; beta-blocantele nu sunt utile, putând fi chiar nocive.","Nu: testul de provocare folosește antiaritmice de clasă I (flecainidă sau ajmalină).","Nu: sindromul se întâlnește mai frecvent la tineri de sex masculin și în Asia de Sud-Est."]],
 [8,"Promovează beta-blocantul — util în LQTS — ca terapie Brugada, deși textul îl consideră potențial nociv."],["SCN5A","sindrom Brugada"]),

q("cardiologie-adv-047",["Sindromul QT lung congenital:",
 ["Jervell-Lange-Nielsen: autozomal recesiv, cu surditate","LQT1 (KCNQ1): aritmii la efort, mai ales înot","LQT2 (KCNH2): aritmii la emoții sau stimuli acustici","LQT3 (SCN5A): aritmii la efort maximal, nu în somn","isoprenalina, tratament de elecție în forma congenitală"],"ABC",1065,"Sindromul QT lung congenital — LQT1–3",
 "Potrivirea genei cu trigger-ul (înot, stimuli acustici, somn) și a transmiterii Jervell versus Romano-Ward.",
 ["Jervell-Lange-Nielsen este autozomal recesiv, cu surditate; Romano-Ward este autozomal dominant, fără surditate.","În LQT1 (KCNQ1) aritmiile sunt declanșate de efort, în special înot.","În LQT2 (KCNH2) aritmiile sunt declanșate de emoții sau stimuli acustici.","Nu: în LQT3 (SCN5A) aritmiile apar în repaus sau în timpul somnului, nu la efort maximal.","Nu: isoprenalina poate fi eficientă în QT lung dobândit și este contraindicată în forma congenitală."]],
 [8,"Schimbă trigger-ul LQT3 cu efortul (al LQT1) și inversează indicația isoprenalinei congenital/dobândit."],["LQT1","Romano-Ward"]),

q("cardiologie-adv-048",["Tratamentul acut al torsadei din QT lung dobândit include:",
 ["sulfat de magneziu 8 mmol în 10-15 minute","isoprenalină intravenos, eficientă în forma dobândită","isoprenalină ca primă linie și în forma congenitală","reducerea frecvenței cardiace pentru scurtarea QT","menținerea medicamentului cauzator până la dispariția aritmiei"],"AB",1065,"QT lung dobândit — Tratament acut",
 "Reținerea dozei de magneziu 8 mmol și a distincției isoprenalină: utilă dobândit, contraindicată congenital.",
 ["În QT lung dobândit se administrează sulfat de magneziu 8 mmol (Mg2+) în 10-15 minute.","Isoprenalina intravenos poate fi eficientă în QT lung dobândit.","Nu: isoprenalina este contraindicată la pacienții cu QT lung congenital.","Nu: prelungirea QT și torsada sunt provocate de obicei de bradicardie; frecvența se menține prin stimulare.","Nu: medicamentele care induc QT lung se sistează."]],
 [8,"Extinde isoprenalina — legitimă în forma dobândită — la LQTS congenital, unde textul o contraindică."],["8 mmol","lsoprenalină"]),

q("cardiologie-adv-049",["Tahicardia ventriculară nesusținută (TVNS):",
 ["≥5 bătăi ventriculare consecutive, sub 30 de secunde","6% la cord structural normal, de regulă netratată","60-80% la pacienții cu boală cardiacă structurală","supresia cu antiaritmice de clasă I, necesară pentru prognostic","ICD fără beneficiu la fracția de ejecție <30%"],"ABC",1066,"Tahicardia ventriculară nesusținută",
 "Aplicarea definiției ≥5 bătăi/<30 s și a prevalențelor 6% versus 60-80%.",
 ["TVNS se definește ca o succesiune de 5 sau mai multe bătăi ventriculare, cu durată sub 30 de secunde.","TVNS poate apărea la 6% dintre pacienții cu cord structural normal, de regulă fără a necesita tratament.","TVNS apare la 60-80% dintre pacienții cu boală cardiacă structurală.","Nu: supresia cu antiaritmice nu este necesară pentru prognostic; beta-blocantele pot îmbunătăți calitatea vieții.","Nu: ICD a îmbunătățit supraviețuirea la pacienții cu fracție de ejecție <30%."]],
 [8,"Inversează indicația ICD la FE<30% și transformă antiaritmicele de clasă I în terapie de prognostic."],["5 sau mai multe","<30%"]),

q("cardiologie-adv-050",["Tahicardia ventriculară idiopatică pe cord structural normal:",
 ["prognostic infaust, ca TV din cardiopatia ischemică","ablație prin radiofrecvență curativă în 90% la simptomatici","nu poate porni din tractul de ejecție al VD","verapamilul este contraindicat în formele idiopatice","forma Gallavardin e nesusținută, fără risc de cardiomiopatie"],"B",1066,"TV pe cord structural normal",
 "Reținerea ratei de 90% a ablației curative și a originii RVOT/septal stâng.",
 ["Nu: TV pe cord structural normal este de obicei benignă, cu prognostic excelent pe termen lung.","La simptomatici, ablația prin radiofrecvență este foarte eficientă, curativă în 90% din cazuri.","Nu: TV idiopatică poate origina în tractul de ejecție al VD sau la nivelul VS septal.","Nu: există o formă sensibilă la verapamil, care răspunde la blocantele de calciu non-dihidropiridinice.","Nu: tahicardia Gallavardin este forma incesantă care, netratată, poate conduce la cardiomiopatie."]],
 [8,"Atribuie formei idiopatice prognosticul TV ischemice și interzice verapamilul, deși există o variantă sensibilă la acesta."],["90% din cazuri","tahicardia Gallavardin"]),

q("cardiologie-adv-051",["Clasificarea Vaughan Williams a antiaritmicelor:",
 ["clasa Ia (disopiramidă) prelungește potențialul de acțiune","clasa II: beta-blocante (atenolol, bisoprolol, esmolol)","clasa IV (verapamil, diltiazem) scurtează faza de platou","vernakalantul, beta-blocant pur fără efect pe canale","clasa Ic în boala structurală, III la cord normal"],"ABC",1067,"Antiaritmice — Vaughan Williams (clasele II, III, IV)",
 "Completarea tabelului: Ia prelungește PA, II = beta-blocante, IV scurtează platoul; vernakalant pentru cardioversia FA.",
 ["Cadranul 30.19: clasa Ia (disopiramidă) prelungește potențialul de acțiune.","Clasa II cuprinde beta-blocantele: atenolol, acebutolol, bisoprolol, propranolol, esmolol.","Clasa IV (verapamil, diltiazem) scurtează potențialul de acțiune (faza de platou).","Nu: vernakalantul blochează mai multe canale și este aprobat intravenos pentru cardioversia FA paroxistice.","Nu: regula generală este inversă — clasa Ic la cord structural normal, clasa III în bolile structurale."]],
 [8,"Inversează regula Ic/III pe cord normal versus structural și degradează vernakalantul la un beta-blocant pur."],["Prelungesc potenţialul de acţiune","Vernakalant"]),

q("cardiologie-adv-052",["Ablația cu cateter și defibrilatorul implantabil:",
 ["ablația e foarte eficientă în AVNRT, AVRT/WPW, flutter, FA paroxistică","WPW simptomatic: ablația este terapie de primă linie","izolarea venelor pulmonare în FA paroxistică la tineri: succes 70-80%","ablația flutterului tipic: eficiență 90-95%","ICD-ul nu poate livra overdrive pacing, ci șocuri"],"ABCD",1068,"Ablația cu cateter și ICD",
 "Reținerea ratelor de succes (PV 70-80%, flutter 90-95%) și a ablației WPW ca primă linie.",
 ["Ablația este foarte eficientă în AVNRT, AVRT/WPW, TV pe cord normal, flutter, tahicardie atrială și FA paroxistică (izolarea venelor pulmonare).","Pacienții simptomatici cu preexcitație (WPW) sunt sfătuiți să recurgă la ablație ca terapie de primă linie, din cauza riscului de moarte subită.","Izolarea venelor pulmonare are succes pe termen lung de 70-80% la tineri cu FA paroxistică, AS normal și fără boală structurală.","Ablația flutterului tipic este eficientă în 90-95% din cazuri.","Nu: ICD-ul poate suprima TV și prin overdrive pacing, procedură lipsită de durere."]],
 [8,"Neagă overdrive pacing-ul nedureros, deși textul îl opune explicit șocurilor dureroase la conștient."],["70-80%","90-95%"]),

q("cardiologie-adv-053",["ICD în prevenția primară a morții subite:",
 ["a redus mortalitatea cu 23-31% (MADIT II, SCD-HeFT)","poate fi indicat la FEVS ≤35% și NYHA sub IV","e inutil, stopul extraspitalicesc având supraviețuire de 80%","are ca indicație preferată IC NYHA IV terminală","nu se indică în CMD, CMH sau ARVC familiale"],"AB",1068,"ICD — Prevenție primară (MADIT II, SCD-HeFT)",
 "Aplicarea reducerii de mortalitate de 23-31% prin ICD și a criteriului FEVS ≤35% cu NYHA <IV în prevenția primară.",
 ["În MADIT II și SCD-HeFT, ICD a redus mortalitatea cu 23-31% față de tratamentul convențional.","Pot beneficia pacienții cu IC, FEVS ≤35% și clasă NYHA <IV; dacă există BRS major (QRS >120 ms) se poate asocia CRT.","Nu: șansele de supraviețuire după un stop cardiac extraspitalicesc sunt de doar 10%.","Nu: pacienții în clasa NYHA IV sau cu comorbidități care reduc durata de viață nu sunt, în general, candidați la ICD.","Nu: indicațiile de prevenție primară includ CMD, CMH, QT lung, sindromul Brugada, canalopatiile cu istoric familial și ARVC."]],
 [8,"Înlocuiește 10% supraviețuire extraspatială cu 80% și face din NYHA IV indicația preferată, contrar textului."],["23-31%","35%"]),

q("cardiologie-adv-054",["Insuficiența cardiacă, din punct de vedere epidemiologic:",
 ["afectează circa 26 de milioane de persoane în lume","are mortalitate de circa 50% la 5 ani","are drept cauză principală, în Occident, boala coronariană","reprezintă circa 25% din internările în secțiile medicale","are prognostic neschimbat în ultimii 10 ani"],"ABC",1069,"Insuficiența cardiacă — Epidemiologie",
 "Reținerea cifrei de 26 de milioane de persoane, a mortalității de 50% la 5 ani și a bolii coronariene ca etiologie dominantă în Occident.",
 ["Insuficiența cardiacă afectează aproximativ 26 de milioane de persoane; în Marea Britanie incidența globală este de circa 2 din 1.000.","Mortalitatea rămâne ridicată: aproximativ 50% dintre pacienți decedează la 5 ani.","În țările occidentale, cea mai frecventă cauză de insuficiență cardiacă este boala coronariană.","Nu: insuficiența cardiacă reprezintă circa 5% din internările în secțiile medicale.","Nu: prognosticul s-a îmbunătățit în ultimii 10 ani, datorită terapiei bazate pe dovezi."]],
 [8,"Umflă ponderea internărilor de la 5% la 25% și neagă îmbunătățirea prognosticului din ultimul deceniu."],["26 de milioane","2 din 1.000"]),

q("cardiologie-adv-055",["Etiologia și fiziopatologia insuficienței cardiace:",
 ["boala ischemică explică 35-40% din cazuri, iar CMD 30-34%","tahicardia sinusală compensează scăderea volumului-bătaie","legea Laplace: tensiunea miocardică e invers proporțională cu raza","activarea simpatică cronică e benefică, fără down-regulation β","peptidele natriuretice compensează parțial retenția de sodiu"],"ABE",1070,"Insuficiența cardiacă — Fiziopatologie și cauze",
 "Aplicarea ponderilor etiologice, a legii Laplace și a consecințelor activării simpatice cronice în insuficiența cardiacă.",
 ["Ponderile etiologice sunt: boală ischemică 35-40%, cardiomiopatie dilatativă 30-34%, hipertensiune 15-20%.","Fracția de ejecție scade precoce, iar tahicardia sinusală compensează scăderea volumului-bătaie.","Nu: conform legii Laplace, tensiunea miocardică este proporțională cu presiunea înmulțită cu raza cavității.","Nu: activarea simpatică cronică este nocivă (neurohormoni, apoptoză) și este compensată prin down-regulation de receptori β.","Retenția de sodiu din insuficiența cardiacă este parțial compensată de peptidele natriuretice."]],
 [8,"Prezintă hiperactivarea simpatică cronică ca mecanism pur protector, deși textul o descrie ca cerc vicios."],["35-40%","legea Laplace"]),

q("cardiologie-adv-056",["Terapiile care reduc morbiditatea și mortalitatea în IC au beneficii dovedite:",
 ["la pacienții cu HFrEF (fracție de ejecție <40%)","la fel în HFpEF (FE >50%) ca în HFrEF","în HFmrEF (FE 40-50%), nu și în HFrEF","în disfuncția izolată de ventricul drept","inclusiv în pericardita constrictivă"],"A",1071,"HFrEF versus HFpEF",
 "Recunoașterea faptului că beneficiul de mortalitate al terapiilor clasice este demonstrat în HFrEF (FE <40%).",
 ["Terapiile care au redus morbiditatea și mortalitatea au avut beneficii dovedite doar la grupul HFrEF (FE <40%).","Nu: în HFpEF (FE >50%), definită simptomatic, aceleași terapii nu au același nivel de dovadă ca în HFrEF.","Nu: HFmrEF (FE 40-50%) este o zonă gri recent clasificată; beneficiul de mortalitate este dovedit în HFrEF.","Nu: disfuncția de ventricul drept are cauze proprii, iar beneficiul de mortalitate al acestor terapii este dovedit în HFrEF.","Nu: pericardita constrictivă nu este HFrEF, iar beneficiul este dovedit la grupul HFrEF (FE <40%)."]],
 [8,"Extinde beneficiul de mortalitate al IECA/BB/ARNI de la HFrEF la HFpEF, eroarea terapeutică clasică."],["fracţie de ejecţie <40%","HFREF"]),

q("cardiologie-adv-057",["Peptidele natriuretice și insuficiența cardiacă cu FE prezervată:",
 ["ANP este eliberat din miocitele atriale, la întindere","BNP este secretat predominant de ventriculi","HFpEF este mai frecventă la hipertensivii vârstnici","BNP se monitorizează de rutină pentru ajustarea dozelor","CNP este secretat predominant de ventriculul stâng"],"ABC",1071,"Peptidele natriuretice; HFpEF",
 "Diferențierea originii ANP (atrii) versus BNP (ventriculi) și a terenului HFpEF al vârstnicului hipertensiv.",
 ["ANP este eliberat din miocitele atriale ca răspuns la întindere și induce diureză, natriureză, vasodilatație și supresia SRAA.","BNP este secretat predominant de ventriculi; NT-proBNP este proteina inactivă scindată din proBNP.","HFpEF (FE >50%) este mai frecventă la hipertensivii vârstnici și în cardiomiopatiile hipertrofice, restrictive și infiltrative.","Nu: nivelurile de BNP se corelează cu severitatea, dar monitorizarea nu se folosește de rutină pentru ghidarea tratamentului.","Nu: CNP este limitat la endoteliul vascular și la SNC; nu este echivalentul ventricular al BNP."]],
 [8,"Transformă BNP-ul de prognostic într-un ghid de rutină al dozelor și mută CNP-ul în ventricul."],["NT-proBNP","HFPEF"]),

q("cardiologie-adv-058",["Clasificarea NYHA și diagnosticul de HFrEF:",
 ["clasa I: fără limitarea activității fizice obișnuite","clasa IV: simptome în repaus, agravate de orice efort","clasa II: simptome prezente și în repaus","clasa III: simptome la eforturi peste cele obișnuite, nu la activitatea obișnuită","HFrEF se diagnostichează pe FE scăzută, fără simptome sau semne"],"AB",1072,"Insuficiența cardiacă — Clasificarea NYHA",
 "Fixarea extremelor NYHA I și IV și a triadei simptome-semne-FE pentru diagnosticul HFrEF.",
 ["Clasa I NYHA: fără limitare; activitatea fizică obișnuită nu determină oboseală, dispnee sau palpitații.","Clasa IV NYHA: simptome în repaus, exacerbate de orice activitate fizică.","Nu: clasa II nu are simptome în repaus; simptomele apar la activitatea fizică obișnuită.","Nu: în clasa III simptomele apar la activități mai reduse decât cele obișnuite, nu la efort intens.","Nu: diagnosticul de HFrEF după ESC necesită trei condiții: simptome, semne și FE scăzută."]],
 [8,"Suprapune clasa II peste IV (simptome de repaus) și anulează cerința clinică a criteriilor ESC."],["Clasa I","Clasa IV"]),

q("cardiologie-adv-059",["IECA, ARA și diureticele în insuficiența cardiacă cronică:",
 ["IECA reduc mortalitatea în NYHA I-IV (CONSENSUS, SOLVD)","ARA nu dau tuse și înlocuiesc IECA la intoleranță","diureticele ameliorează dispneea, cu dovezi limitate de supraviețuire","IECA se inițiază în doză maximă, fără monitorizarea creatininei","asocierea ansă plus tiazidă e contraindicată în IC severă"],"ABC",1073,"Insuficiența cardiacă — IECA, ARA, diuretice",
 "Recunoașterea beneficiului IECA pe tot spectrul NYHA, a ARA ca alternativă fără tuse și a limitei de supraviețuire a diureticelor.",
 ["În CONSENSUS și SOLVD, IECA au ameliorat simptomele și au redus mortalitatea, cu beneficiu în clasele NYHA I-IV.","ARA (candesartan în CHARM alternativ) sunt linia a doua la intoleranța la IECA; nu afectează metabolismul bradikininei și nu determină tuse.","Diureticele ameliorează dispneea și toleranța la efort, dar dovezile privind efectul asupra supraviețuirii sunt limitate.","Nu: IECA se inițiază în doză mică, crescută treptat, cu monitorizarea TA și a funcției renale.","Nu: în IC severă poate fi necesară asocierea diureticului de ansă cu o tiazidă, inclusiv metolazona."]],
 [8,"Inițiază IECA la doză maximă fără monitorizare renală și interzice dubla diureză folosită tocmai în IC severă."],["CONSENS","CHARM"]),

q("cardiologie-adv-060",["Studiul SHIFT cu ivabradină în insuficiența cardiacă a arătat:",
 ["creșterea mortalității la pacienții în fibrilație atrială","decese CV și spitalizări reduse la FEVS ≤35%, în ritm sinusal","lipsa beneficiului când frecvența cardiacă rămâne crescută sub beta-blocant","eficiență superioară ICD în prevenția morții subite","utilitatea ca substitut al diureticelor de ansă"],"B",1075,"Insuficiența cardiacă — Ivabradina (SHIFT)",
 "Reținerea populației SHIFT: ritm sinusal, FEVS ≤35%, reducere a deceselor CV și a spitalizărilor.",
 ["Nu: SHIFT nu a vizat pacienții în FA ca populație principală; ivabradina inhibă curentul If sinoatrial, iar beneficiul s-a obținut în ritm sinusal.","SHIFT a raportat scăderea deceselor cardiovasculare și a spitalizărilor la IC cronică cu disfuncție de VS (FEVS ≤35%), în ritm sinusal.","Nu: ivabradina poate fi folosită tocmai când frecvența cardiacă rămâne crescută sub beta-blocante sau la intoleranța la acestea.","Nu: SHIFT nu a comparat ivabradina cu ICD; reducerea mortalității cu 23% prin ICD provine din SCD-HeFT.","Nu: ivabradina scade selectiv frecvența cardiacă, fără să înlocuiască diureticele."]],
 [8,"Mută populația SHIFT din sinus cu FE≤35% în FA și o pune în competiție falsă cu ICD."],["Studiul SHIFT","ritm sinusal"]),

q("cardiologie-adv-061",["În insuficiența cardiacă:",
 ["digoxinul a redus spitalizările în studiul DIG","hidralazina plus nitrați a redus mortalitatea la afro-americani","amiodarona a redus mortalitatea cu 23% în SCD-HeFT","digoxinul este inotropul de primă linie în SCA cu IC","anticoagularea orală e indicată în ritm sinusal fără tromb, anevrism sau embolie"],"AB",1075,"Insuficiența cardiacă — Digoxin, hidralazină-nitrați, SCD-HeFT",
 "Contrastul DIG (spitalizări) versus ROCKET AF (mortalitate) și al A-HeFT, față de absența beneficiului amiodaronei în SCD-HeFT.",
 ["Studiul DIG a arătat reducerea spitalizărilor cu digoxin; o subanaliză ROCKET AF a sugerat însă o mortalitate posibil crescută.","În A-HeFT, hidralazina plus nitrați a redus mortalitatea la afro-americani; asocierea se folosește la intoleranța la IECA/ARA.","Nu: în SCD-HeFT amiodarona nu a avut beneficiu față de placebo; ICD a redus mortalitatea cu 23%.","Nu: digoxinul se evită în SCA și nu este inotrop de primă linie în IC acută de cauză coronariană.","Nu: în ritm sinusal, anticoagularea orală se rezervă cazurilor cu tromboembolism în antecedente, anevrism de VS sau tromb."]],
 [8,"Atribuie amiodaronei reducerea de 23% care aparține ICD în același trial SCD-HeFT."],["studiul DIG","A-HeFT"]),

q("cardiologie-adv-062",["Resincronizarea, miocardul hibernant și transplantul cardiac:",
 ["miocardul hibernant apare la circa 33% dintre coronarienii revascularizați","CRT reduce mortalitatea în NYHA III-IV cu QRS larg","transplantul: supraviețuire >90% la 1 an, 75% la 5 ani","IC NYHA IV terminală e indicația preferată de ICD","rezistențele vasculare pulmonare crescute indică transplantul"],"ABC",1076,"CRT, miocard hibernant și transplant cardiac",
 "Reținerea prevalenței de 33% a hibernării, a trialurilor CARE-HF/COMPANION și a supraviețuirii post-transplant 90%/75%.",
 ["Hibernarea este estimată la circa 33% dintre coronarieni, pe baza ameliorării cineticii după revascularizare.","CARE-HF și COMPANION: CRT ameliorează simptomele, reduce evenimentele și mortalitatea în NYHA III-IV cu QRS prelungit/BRS.","La recipienții selecționați, supraviețuirea după transplant este de peste 90% la 1 an și de 75% la 5 ani.","Nu: pacienții în clasa NYHA IV sau cu comorbidități care reduc durata de viață nu sunt, în general, candidați la ICD.","Nu: creșterea rezistențelor vasculare pulmonare este contraindicație absolută de transplant, ca și cancerul activ."]],
 [8,"Transformă contraindicația de rezistențe pulmonare crescute în indicație și promovează ICD-ul în NYHA IV terminal."],["33%","CARE-HF"]),

q("cardiologie-adv-063",["Insuficiența cardiacă acută:",
 ["are mortalitate de aproape 10% la 60 de zile","cu edem pulmonar acut: mortalitate 12% în spital, 30% la 12 luni","este sugerată de BNP >100 pg/ml sau NT-proBNP >300 pg/ml","are prognostic nefavorabil la PCWP >16 mmHg și hiponatremie","nu mai necesită ecocardiografie dacă BNP este crescut"],"ABCD",1077,"Insuficiența cardiacă acută — Prognostic și diagnostic",
 "Aplicarea ratelor de mortalitate 10%/35% la 60 de zile și 12%/30% în edemul pulmonar, plus pragurile de peptide.",
 ["Mortalitatea este de aproape 10% la 60 de zile, iar mortalitatea sau respitalizarea ajung la 35% la 60 de zile.","În edemul pulmonar acut, mortalitatea intra-spitalicească este de 12% și crește la 30% în 12 luni.","Valorile BNP >100 pg/ml sau NT-proBNP >300 pg/ml sunt sugestive pentru insuficiență cardiacă.","PCWP >16 mmHg, hiponatremia, diametrul telediastolic VS crescut și consumul miocardic de O2 scăzut sunt indicatori nefavorabili.","Nu: peptidele natriuretice nu înlocuiesc ecocardiografia transtoracică, care trebuie efectuată fără întârziere."]],
 [8,"Folosește pragurile reale de peptide ca argument fals că ecografia ar deveni superfluă."],["10% la 60 de zile","NT-proB"]),

q("cardiologie-adv-064",["Tratamentul insuficienței cardiace acute:",
 ["dopamina sub 2 µg/kg/min acționează pe receptorii dopaminergici periferici","dopamina peste 2 µg/kg/min stimulează receptorii β, crescând debitul","levosimendanul sensibilizează proteinele contractile la calciu","CPAP/NIPPV reduce mortalitatea față de oxigenul pe mască","digoxinul i.v. este inotropul de primă intenție în SCA"],"ABC",1078,"Insuficiența cardiacă acută — Terapie farmacologică",
 "Diferențierea treptelor de doză ale dopaminei, a mecanismului levosimendanului și a efectului CPAP asupra dispneei, nu a mortalității.",
 ["În doză mică (<2 µg/kg/min), dopamina acționează pe receptorii dopaminergici periferici, fără dovezi clare de ameliorare a prognosticului.","În doză medie (>2 µg/kg/min), dopamina acționează pe receptorii β, crescând contractilitatea și debitul cardiac.","Levosimendanul este inotrop pozitiv vasodilatator: crește sensibilitatea proteinelor contractile la calciu și deschide canalele de K+.","Nu: CPAP/NIPPV ameliorează precoce dispneea față de oxigenul pe mască, dar nu afectează mortalitatea.","Nu: digoxinul se folosește în FA și trebuie evitat în SCA."]],
 [8,"Inversează interdicția digoxinului în SCA și confundă beneficiul simptomatic al CPAP cu un efect de mortalitate."],["Levosimendan","<2 µg/kg pe min"]),

q("cardiologie-adv-065",["Dispozitivele de asistare ventriculară (VAD):",
 ["LVAD-ul ejectează în aortă sângele din VS","se complică cu tromboembolism, sângerări și infecții","extracorporale sunt destinate suportului pe termen lung","RVAD-ul ejectează în aortă sângele din VD","nu se folosesc ca punte către transplant cardiac"],"AB",1079,"Dispozitive de asistare ventriculară",
 "Recunoașterea circuitelor LVAD/RVAD și a complicațiilor trombotice, hemoragice și infecțioase.",
 ["LVAD preia sânge din ventriculul stâng și îl trimite în aortă; RVAD, din ventriculul drept în artera pulmonară.","Principalele complicații sunt tromboembolismul, sângerările, infecțiile și defecțiunile dispozitivului.","Nu: dispozitivele extracorporale sunt pentru asistare de scurtă durată; cele intracorporale servesc pe termen lung, ca punte sau terapie de destinație.","Nu: RVAD trimite sângele din ventriculul drept în artera pulmonară; LVAD îl trimite din ventriculul stâng în aortă.","Nu: VAD-urile pot servi ca punte către chirurgie sau transplant ori ca terapie de destinație."]],
 [8,"Inversează destinațiile LVAD/RVAD și atribuie extracorporealului rolul de destinație pe termen lung."],["LVAD","tromboembolismul"]),

q("cardiologie-adv-066",["În boala coronariană:",
 ["reducerea cu 70% a diametrului scade aria luminală cu circa 50%","unul din trei infarcte rămâne nerecunoscut inițial","30-40% dintre pacienții cu SCA nu au simptome de alarmă prealabile","postinfarct, riscul de IC sau AVC crește de 3-6 ori","rezerva coronariană rămâne intactă până la stenoze de 90%"],"BCD",1080,"Boala coronariană — Stenoză critică și prezentare clinică",
 "Aplicarea echivalenței 50% diametru ≈ 70% arie și a ponderii infarctelor nerecunoscute sau fără simptome de alarmă.",
 ["Nu: reducerea cu 50% a diametrului luminal corespunde unei reduceri de circa 70% a suprafeței secțiunii.","Unul din trei infarcte miocardice rămâne inițial nerecunoscut.","Între 30 și 40% dintre pacienții cu SCA se prezintă fără simptome de alarmă precedente.","După primul infarct, riscul de insuficiență cardiacă sau de AVC este de 3-6 ori mai mare.","Nu: la o reducere de 50% a diametrului, arteriolele distale sunt deja dilatate maximal și rezerva de flux este zero, nu abia la 90%."]],
 [8,"Mută pragul de rezervă zero de la 50% diametru la 90%, deși textul leagă ischemia de dilatarea maximală distală."],["50%","70%"]),

q("cardiologie-adv-067",["Recomandarea NICE pentru tratamentul cu statine:",
 ["atorvastatină 20 mg în prevenția primară și 80 mg în cea secundară","atorvastatină 80 mg în prevenția primară și 20 mg în cea secundară","atorvastatină 10 mg, la fel în prevenția primară și în cea secundară","ezetimib în locul statinei, în prevenția primară","rosuvastatină 5 mg în locul atorvastatinei 80 mg, de rutină"],"A",1081,"Boala coronariană — Tratamentul cu statine",
 "Diferențierea atorvastatinei 20 mg (prevenție primară, risc ≥10%) de 80 mg (boală cardiovasculară confirmată).",
 ["NICE recomandă atorvastatină 20 mg în prevenția primară la risc CV la 10 ani ≥10% și 80 mg în boala cardiovasculară confirmată, dacă nu există interacțiuni sau intoleranță.","Nu: raportul este inversat; 20 mg se dă în prevenția primară, iar 80 mg în boala cardiovasculară confirmată.","Nu: doza unică de 10 mg nu este recomandarea NICE, care prevede 20 mg în prevenția primară și 80 mg în boala confirmată.","Nu: statinele sunt fundamentul prevenției, nu ezetimibul izolat.","Nu: recomandarea NICE nu prevede înlocuirea de rutină a atorvastatinei 80 mg cu rosuvastatină 5 mg."]],
 [8,"Inversează dozele 20 mg (primară) și 80 mg (secundară), perechea NICE cea mai ușor de confuzat."],["Atorvastatina 20 mg","80 mg"]),

q("cardiologie-adv-068",["Angina pectorală:",
 ["are la femeile de 45-64 ani o prevalență de 5-7%","vasospastică (Prinzmetal) apare în repaus, cu subdenivelare ST tranzitorie","microvasculară apare la efort, fără stenoze coronariene semnificative","stabilă are o mortalitate anuală de circa 10-15%","clasică, după NICE, întrunește una din cele trei caracteristici"],"AC",1081,"Angina — Epidemiologie, Prinzmetal și forma microvasculară",
 "Reținerea prevalențelor pe sexe și vârste și a tiparului ECG al anginei Prinzmetal.",
 ["Prevalența la femei este de 5-7% între 45 și 64 de ani și de 10-12% între 65 și 84 de ani; la bărbați, 4-7%, respectiv 12-14%.","Nu: angina vasospastică (Prinzmetal) apare fără declanșator, de obicei în repaus, cu supradenivelare tranzitorie de segment ST.","Angina microvasculară este angină de efort fără stenoze coronariene semnificative, cu prognostic general favorabil, dar cu simptome adesea incomplet controlate.","Nu: mortalitatea anuală a anginei stabile este de 1,2-2,4%, cu deces cardiac de 0,6-1,4%.","Nu: angina clasică are toate cele trei caracteristici; cea atipică are două, iar durerea non-anginoasă una."]],
 [8,"Umflă mortalitatea anuală de la 1,2-2,4% la 10-15% și degradează angina clasică la un singur criteriu NICE."],["Prinzmetal","5-7%"]),

q("cardiologie-adv-069",["Clasificarea CCS a anginei și rezerva fracționată de flux (FFR):",
 ["clasa I: angină la efort intens, nu la activitățile zilnice","leziunile cu FFR >0,80 pot fi tratate medicamentos","clasa IV: angină la urcatul rapid al scărilor, nu în repaus","o FFR sub 0,50 contraindică tratamentul medicamentos","clasa III: angină nocturnă, fără limitarea activității zilnice"],"AB",1082,"Angina stabilă — CCS și FFR",
 "Aplicarea claselor CCS I versus IV și a pragului FFR >0,80 pentru tratament conservator.",
 ["Clasa CCS I: fără angină la activitățile zilnice obișnuite; angina apare la efort intens.","Leziunile cu FFR >0,80 pot fi tratate medicamentos, fără stent, cu prognostic bun.","Nu: urcatul rapid al scărilor este exemplu de clasă II; clasa IV înseamnă angină în repaus sau la orice nivel de efort.","Nu: pragul relevant este FFR >0,80, care permite tratament medicamentos; nu există un prag de 0,50 care să-l interzică.","Nu: clasa III înseamnă angină la efort redus (50-100 m, un etaj), cu limitare marcată a activității."]],
 [8,"Atribuie clasei IV un exemplu de clasă II și inventează un prag FFR 0,50 inexistent."],["0,80","Clasa I"]),

q("cardiologie-adv-070",["PCI în angina stabilă:",
 ["are complicații majore: infarct 2%, AVC 0,4%, deces 1%","pe cale radială reduce complicațiile la locul de puncție","impune DAPT timp de 6-12 săptămâni după stentare","cu stent metalic simplu: restenoză 20-30% la 6-9 luni","folosește de rutină stenturile metalice simple, nu DES"],"ABD",1082,"PCI — Complicații, stenturi și DAPT",
 "Memorarea ratelor 2%/0,4%/1% și a ferestrei DAPT de 6-12 luni, cu superioritatea DES de generația a doua.",
 ["Complicațiile majore sunt infarctul acut (2%), accidentul vascular cerebral (0,4%) și decesul (1%).","Abordul radial este preferat, reducând hematoamele, disecțiile și pseudoanevrismele de la locul de puncție.","Nu: DAPT (aspirină + inhibitor P2Y12) se administrează 6-12 luni după stentare.","BMS au restenoză de 20-30% în 6-9 luni, de aceea DES de generația a doua sunt recomandate la majoritatea pacienților.","Nu: DES de generația a doua sunt recomandate la majoritatea; BMS pot fi preferate doar dacă e nevoie de anticoagulare prelungită sau de chirurgie precoce."]],
 [8,"Inversează ierarhia DES versus BMS, deși textul rezervă BMS doar unor nișe (anticoagulare, chirurgie precoce)."],["20-30%","6-12 luni"]),

q("cardiologie-adv-071",["Revascularizarea în boala coronariană complexă:",
 ["CABG are mortalitate sub 1% la funcție sistolică normală","grafturile arteriale sunt mai durabile decât cele venoase","PCI e preferată în boala uni-/bivasculară, fără IVA proximală sau trunchi comun","PCI e preferată în boala trivasculară cu diabet sau SYNTAX >22","SYNTAX 0-22 contraindică PCI în stenoza de IVA proximală"],"ABC",1083,"Revascularizare — PCI versus CABG (SYNTAX)",
 "Aplicarea pragului SYNTAX >22, a preferinței CABG în boala trivasculară cu diabet și a mortalității CABG <1%.",
 ["Mortalitatea chirurgicală a CABG este sub 1% la pacienții cu funcție sistolică de VS normală.","Grafturile arteriale (mamare interne in situ, gastro-epiploice) funcționează mai durabil decât grafturile venoase.","PCI este preferată în boala uni- sau bivasculară fără afectarea IVA proximale sau a trunchiului comun.","Nu: în boala trivasculară cu diabet sau cu scor SYNTAX >22 este preferat CABG.","Nu: la un scor SYNTAX 0-22, atât CABG, cât și PCI pot fi folosite în IVA proximală, trunchi comun sau boală trivasculară fără diabet."]],
 [8,"Transformă fereastra SYNTAX 0-22 — unde ambele metode sunt posibile — într-o dublă contraindicație."],["SYNTAX","sub 1%"]),

q("cardiologie-adv-072",["Definiția universală a infarctului și troponina înalt sensibilă:",
 ["tipul 1: IM spontan, prin ruptura sau eroziunea plăcii","tipul 2: IM prin dezechilibru între ofertă și necesar","tipul 4a: IM asociat PCI; tipul 5: IM asociat CABG","troponina <5 ng/L are valoare predictivă negativă de 99,4%","tipul 3: IM fără necroză, diagnosticat prin durere atipică"],"ABCD",1085,"SCA — Tipurile de IM și troponina",
 "Potrivirea tipurilor 1, 2, 4a/4b și 5 cu mecanismul și a VPN de 99,4% la pragul <5 ng/L.",
 ["Tipul 1 este IM spontan prin eveniment coronarian primar: eroziune, ruptură, fisură sau disecție de placă.","Tipul 2 este secundar dezechilibrului ofertă/necesar (spasm, embolie, anemie, aritmii, hiper- sau hipotensiune).","Tipul 4a este IM determinat de PCI, 4b de tromboza de stent, iar tipul 5 de CABG.","Un rezultat <5 ng/L are valoare predictivă negativă de 99,4%; dacă primul test este negativ, se repetă la 3 ore.","Nu: tipul 3 este IM cu moarte cardiacă subită, nu un infarct fără necroză."]],
 [8,"Înlocuiește tipul 3 (moarte subită) cu un tablou de durere atipică fără necroză."],["5 ng/L","99,4%"]),

q("cardiologie-adv-073",["Scorul TIMI pentru NSTEMI/angină instabilă punctează, printre altele:",
 ["vârsta peste 75 de ani, cu 3 puncte","vârsta >65 ani și aspirina în ultimele 7 zile","troponina crescută, dar nu și modificarea segmentului ST","întârzierea de peste 4 ore a tratamentului","clasa Killip la momentul internării"],"B",1085,"SCA — Scorul TIMI NSTEMI/AI",
 "Recunoașterea celor 7 itemi TIMI pentru NSTEMI, distinct de itemii TIMI STEMI.",
 ["Nu: vârsta >75 ani cu 3 puncte aparține scorului TIMI pentru STEMI; scorul pentru NSTEMI/AI include vârsta >65 ani.","Cadranul 30.35 enumeră cei 7 itemi: vârsta >65 ani, >3 factori de risc, stenoze >50%, aspirină în ultimele 7 zile, angină de repaus >2 episoade/24 h, modificare ST, markeri de necroză.","Nu: scorul combină date clinice, ECG și markeri; modificarea segmentului ST este unul dintre cei 7 itemi.","Nu: întârzierea tratamentului >4 ore este item al scorului TIMI pentru STEMI, nu al celui pentru NSTEMI/AI.","Nu: clasa Killip intră în scorul GRACE și nu figurează printre cei 7 itemi TIMI pentru NSTEMI/AI."]],
 [8,"Amestecă itemii TIMI NSTEMI cu cei STEMI (greutate, delay, vârstă >75 cu 3 puncte)."],["TIMI",">65 ani"]),

q("cardiologie-adv-074",["În NSTEMI, riscul intra-spitalicesc scăzut după scorul GRACE corespunde:",
 ["unui scor >140, cu mortalitate intra-spitalicească >3%","unui scor ≤108, cu mortalitate <1%","unui scor între 126 și 154 de puncte","unui scor între 109 și 140 de puncte","unui scor ≤108, dar cu mortalitate >3%"],"B",1086,"SCA — Scorul GRACE",
 "Reținerea pragului GRACE ≤108 pentru mortalitate intra-spitalicească <1% în NSTEMI.",
 ["Nu: un scor >140 definește riscul înalt intra-spitalicesc în NSTEMI, cu mortalitate >3%.","Cadranul 30.37: în NSTEMI, riscul intra-spitalicesc scăzut corespunde unui scor GRACE ≤108, cu mortalitate <1%.","Nu: 126-154 este intervalul de risc mediu intra-spitalicesc în STEMI; GRACE are praguri diferite pentru NSTEMI și STEMI.","Nu: un scor GRACE de 109-140 corespunde riscului intermediar; riscul scăzut înseamnă un scor ≤108.","Nu: scorul ≤108 corespunde unei mortalități intra-spitalicești <1%; mortalitatea >3% caracterizează scorul >140."]],
 [8,"Confundă pragul NSTEMI ≤108 (<1%) cu pragul de risc înalt >140 sau cu benzile STEMI."],["108","<1"]),

q("cardiologie-adv-075",["Momentul coronarografiei în NSTEMI, după categoria de risc ESC:",
 ["risc foarte înalt (șoc, IC, aritmii maligne): sub 2 ore","risc înalt (troponină în creștere, GRACE >140): în 24 de ore","risc intermediar (diabet, GRACE 109-140): în 72 de ore","risc înalt: amânare la 7 zile, pentru stabilizarea plăcii","GRACE 109-140: coronarografie de urgență, sub 2 ore"],"ABC",1087,"NSTEMI — Stratificarea și timing-ul angiografiei",
 "Aplicarea ferestrelor <2 h / 24 h / 72 h în funcție de GRACE și de instabilitatea clinică.",
 ["Riscul foarte înalt (angină persistentă, IC, șoc, aritmii maligne) impune coronarografie în primele 2 ore.","Riscul înalt (troponină în crescendo, ST dinamic, GRACE >140) impune coronarografie în primele 24 de ore.","Riscul intermediar (diabet, eRFG <60, FEVS <40%, GRACE 109-140, PCI/CABG anterior) impune coronarografie în primele 72 de ore.","Nu: la riscul înalt coronarografia se face în primele 24 de ore, fără amânare de o săptămână.","Nu: GRACE 109-140 înseamnă risc intermediar, cu coronarografie în 72 de ore, nu urgență de tip șoc."]],
 [8,"Suprapune banda intermediară GRACE 109-140 peste urgența de sub 2 ore a șocului."],["<2 ore",">140"]),

q("cardiologie-adv-076",["Fiziopatologia și mortalitatea în STEMI:",
 ["necroza începe la 15-30 de minute de la ocluzie, subendocardic","mortalitatea intra-spitalicească este de 6-14%","reperfuzia precoce salvează miocard și reduce mortalitatea","necroza devine transmurală în sub 5 minute, fără etapă subendocardică","mortalitatea în STEMI necomplicat depășește 50%"],"ABC",1088,"STEMI — Fiziopatologie și mortalitate",
 "Reținerea ferestrei de 15-30 de minute până la necroză și a mortalității intra-spitalicești de 6-14%.",
 ["Necroza începe în 15-30 de minute de la ocluzie, întâi subendocardic, apoi transmural, cu undă Q.","Mortalitatea intra-spitalicească în STEMI este între 6 și 14%.","Reperfuzia precoce salvează miocard și reduce mortalitatea și morbiditatea.","Nu: primul afectat este miocardul subendocardic; necroza devine transmurală pe măsură ce ischemia se prelungește.","Nu: mortalitatea intra-spitalicească este de 6-14%, nu peste 50% în forma necomplicată."]],
 [8,"Comprimă necroza la 5 minute sau umflă mortalitatea peste 50%, deși textul dă 15-30 min și 6-14%."],["15-30 minute","6 şi 14%"]),

q("cardiologie-adv-077",["Reperfuzia în STEMI:",
 ["prin PCI primară vizează trecerea ghidului de ocluzie în 60 de minute","prin tromboliză, dacă PCI nu e posibilă în 120 de minute","prin tromboliză în primele 6 ore evită 30 de decese la 1.000","prin tromboliză după 12 ore aduce beneficii limitate","include tromboaspirația de rutină în PCI primară"],"ABCD",1089,"STEMI — PCI primară și tromboliză",
 "Aplicarea ferestrelor de 60 de minute (PCI) și 120 de minute (trecerea la tromboliză), plus 30 versus 20 de decese evitate la 1.000.",
 ["PCI primară, metoda preferată în centrele cu laborator, are ca țintă trecerea ghidului distal de ocluzie în primele 60 de minute de la prezentare.","Tromboliza este indicată dacă PCI primară nu poate fi efectuată în primele 120 de minute de la diagnostic.","Meta-analiza arată că tromboliza previne 30 de decese la 1.000 de pacienți tratați în primele 6 ore și 20 la 1.000 între 7 și 12 ore.","După 12 ore beneficiile sunt limitate, mai ales la vârstnici, care au risc crescut de AVC.","Nu: tromboaspirația de rutină nu este recomandată în PCI primară."]],
 [8,"Adaugă tromboaspirația de rutină, pe care textul o respinge explicit în PCI primară."],["60 de minute","120 minute"]),

q("cardiologie-adv-078",["În PCI primară pentru STEMI se preferă:",
 ["abordul radial (studiile RIVAL, RIFLE STEACS)","stenturile farmacologic active față de cele metalice simple","aspirina asociată cu prasugrel sau ticagrelor","inhibitorii GP IIb/IIIa administrați de rutină","tratarea leziunii culprit, cu completare amânată la 6 luni"],"ABC",1089,"STEMI — Detalii de PCI primară",
 "Recunoașterea abordului radial, a DES și a antiagregării duale cu prasugrel/ticagrelor, față de GP IIb/IIIa care nu mai sunt de rutină.",
 ["RIVAL și RIFLE STEACS susțin abordul radial, care reduce complicațiile arteriale și poate ameliora supraviețuirea.","Stenturile farmacologic active sunt preferate față de stenturile metalice simple în PCI primară.","Antiagregarea duală preferată este aspirina plus prasugrel sau ticagrelor.","Nu: utilizarea de rutină a inhibitorilor GP IIb/IIIa nu mai este recomandată.","Nu: ghidurile ESC recomandă revascularizarea completă în timpul spitalizării inițiale, înainte de externare."]],
 [8,"Păstrează GP IIb/IIIa ca rutină — strategie abandonată — și amână completarea revascularizării 6 luni."],["artera radială","prasugrel sau ticagrelor"]),

q("cardiologie-adv-079",["Clasificarea Killip și contraindicațiile trombolizei în STEMI:",
 ["Killip III: raluri pe peste jumătate din câmpurile pulmonare","AVC hemoragic oricând în antecedente contraindică absolut tromboliza","Killip II se definește prin prezența șocului cardiogen","AVC ischemic de acum 5 ani contraindică absolut tromboliza","TAS >180 mmHg refractară e contraindicație absolută de tromboliză"],"AB",1090,"STEMI — Killip și contraindicațiile trombolizei",
 "Fixarea celor patru clase Killip și a contraindicațiilor absolute ale trombolizei, distincte de cele relative.",
 ["Killip I: fără raluri sau galop; II: raluri pe mai puțin de jumătate din baze sau galop; III: raluri pe >50% din câmpuri; IV: șoc cardiogen.","Contraindicațiile absolute ale trombolizei includ AVC hemoragic de orice vechime, AVC ischemic în ultimele 3 luni, disecția de aortă și sângerarea digestivă în luna precedentă.","Nu: șocul cardiogen definește clasa Killip IV; clasa II are raluri pe mai puțin de jumătate din baze sau galop.","Nu: contraindicația absolută este AVC ischemic în ultimele 3 luni; unul vechi de 5 ani nu este listat ca atare.","Nu: hipertensiunea refractară (TAS >180 mmHg) este contraindicație relativă a trombolizei."]],
 [8,"Mută șocul din Killip IV în II și promovează o HTA relativă la rang de contraindicație absolută."],["Kil/ip IV","Disecţia de aortă"]),

q("cardiologie-adv-080",["Defectul septal ventricular post-STEMI:",
 ["apare la 1-2%; fără chirurgie, mortalitatea la 1 an poate atinge 92%","are mortalitate sub 5% la 1 an, fără intervenție","contraindică folosirea balonului de contrapulsație intraaortic (IABP)","apare la peste 30% dintre STEMI reperfuzate precoce","se diagnostichează pe radiografie toracică, fără ecografie"],"A",1090,"Complicațiile STEMI — Defect septal ventricular",
 "Reținerea incidenței de 1-2% și a mortalității de 92% la 12 luni fără chirurgie.",
 ["DSV apare la 1-2% dintre pacienți; fără corecție chirurgicală, mortalitatea la 12 luni poate ajunge la 92%.","Nu: DSV post-STEMI nu este benign; fără corecție chirurgicală, mortalitatea la 12 luni poate ajunge la 92%.","Nu: balonul de contrapulsație intraaortic și angiografia pot permite diagnosticul complet înaintea chirurgiei.","Nu: DSV apare la 1-2% și se asociază cu fibrinoliza tardivă sau ineficientă, nu cu reperfuzia precoce.","Nu: diagnosticul se sprijină pe contextul clinic și pe ecografie, nu pe radiografia toracică izolată."]],
 [8,"Transformă o complicație cu mortalitate 92% într-o evoluție „benignă”, inversând prognosticul real."],["1-2%","92%"]),

q("cardiologie-adv-081",["Complicațiile mecanice și aritmice precoce ale STEMI:",
 ["regurgitarea mitrală severă are trei mecanisme, precizate prin ETE","ruptura de mușchi papilar produce edem pulmonar acut și șoc","potasemia trebuie menținută peste 4,5 mmol/L","ruptura de perete liber este de obicei bine tolerată","bradiaritmiile impun direct stimulare permanentă, fără atropină"],"ABC",1091,"STEMI — IM mitrală, ruptură și aritmii",
 "Diferențierea celor trei mecanisme ale regurgitării mitrale post-STEMI și a țintelor K+ >4,5 mmol/L și Mg 8 mmol.",
 ["Regurgitarea mitrală severă are trei mecanisme (dilatarea inelului, disfuncția mușchiului papilar inferior, ruptura), iar ETE precizează etiologia.","Ruptura de mușchi papilar produce edem pulmonar acut și șoc, cu indicație de IABP, coronarografie și chirurgie precoce.","Potasiul seric se menține peste 4,5 mmol/L; TV/FV incesantă poate răspunde la magneziu 8 mmol i.v. în 15 minute.","Nu: ruptura de perete liber este cel mai frecvent fatală, prin disociație electromecanică.","Nu: bradiaritmiile se tratează inițial cu atropină 0,5 mg i.v., repetată până la șase ori în 4 ore."]],
 [8,"Minimizează ruptura de perete liber — complicație de obicei fatală — și interzice atropina, primul pas al bradiaritmiei."],["4,5 mmol/L","8 mmol/L"]),

q("cardiologie-adv-082",["Tratamentul după SCA cu stentare:",
 ["în FA cu HAS-BLED 0-2: triplă terapie 6 luni, apoi dublă","în FA cu HAS-BLED >2: triplă terapie 4 săptămâni, apoi dublă","în FA cu HAS-BLED >2: triplă terapie 12 luni, fără de-escaladare","antialdosteronicele se evită la FEVS <40% cu semne de IC","ținta LDL-colesterolului este sub 3,5 mmol/L"],"AB",1091,"Post-SCA — Tripla terapie și prevenție secundară",
 "Aplicarea ferestrelor de 6 luni versus 4 săptămâni de triplă terapie în funcție de HAS-BLED.",
 ["La HAS-BLED 0-2: triplă terapie 6 luni, apoi dublă terapie (antiagregant + AVK/DOAC).","La HAS-BLED >2: triplă terapie 4 săptămâni, apoi dublă terapie încă 11 luni.","Nu: la HAS-BLED >2 de-escaladarea este explicită (triplă terapie 4 săptămâni, apoi dublă), nu triplă terapie 12 luni.","Nu: antagonistul de aldosteron este indicat dacă există semne de IC și FEVS <40%, cu creatinina și potasiul controlate.","Nu: ținta LDL după IMA este <1,8 mmol/L, cu statină de potență înaltă."]],
 [8,"Prelungește tripla terapie la 12 luni tocmai la HAS-BLED înalt, unde textul o scurtează la 4 săptămâni."],["HAS-BLED","<1.8 mmol/L"]),

q("cardiologie-adv-083",["Stenoza mitrală reumatismală:",
 ["este severă la o arie valvulară sub 2 cm²","afectează mai frecvent femeile decât bărbații","devine de obicei simptomatică la o arie sub 2 cm²","devine severă, în Europa, la câteva decenii după RAA","e severă sub 4 cm², aria normală fiind 1 cm²"],"BCD",1092,"Stenoza mitrală — Arie valvulară și epidemiologie",
 "Aplicarea pragurilor 4-6 cm² (normal), <2 cm² (simptome) și <1 cm² (sever) și a diferenței geografice de evoluție.",
 ["Nu: stenoza severă se definește la o arie sub 1 cm² (normal 4-6 cm²); sub 2 cm² apar de obicei simptomele.","Stenoza mitrală afectează mai frecvent femeile decât bărbații.","Simptomele apar de obicei când aria valvulară scade sub 2 cm².","În Europa, intervalul de la RAA la stenoza severă este de câteva decenii; în țările cu venituri mici și medii, stenoza severă apare la 10-20 de ani.","Nu: valorile sunt inversate; aria normală este de 4-6 cm², iar stenoza severă se definește sub 1 cm²."]],
 [8,"Inversează ariile normal/sever (4-6 versus <1), capcana numerică centrală a stenozei mitrale."],["4-6 cm2","sub 1 cm2"]),

q("cardiologie-adv-084",["În stenoza mitrală se pot constata:",
 ["zgomot 1 întărit la valve mobile, clacment de deschidere, uruitură apicală","accentuare presistolică a uruiturii, în fibrilație atrială","suflu Graham-Steell, prin regurgitare pulmonară din HTP","undă P bifidă, prin activarea întârziată a atriului stâng","zgomot 1 diminuat, chiar la valve mobile, necicatrizate"],"ACD",1093,"Stenoza mitrală — Auscultație și P mitral",
 "Reconstituirea secvenței Z1 intens – clacment – uruitură, a accentuării presistolice și a suflului Graham-Steell.",
 ["Zgomotul 1 este întărit dacă valvele sunt mobile și este urmat de clacment de deschidere și de uruitura diastolică apicală, audibilă în decubit lateral stâng, în expir.","Nu: accentuarea presistolică apare la pacienții în ritm sinusal, prin contracția atrială stângă.","Suflul Graham-Steell este suflul diastolic pulmonar al regurgitării pulmonare din hipertensiunea pulmonară.","Unda P bifidă (P mitral) reflectă activarea întârziată a atriului stâng.","Nu: zgomotul 1 este întărit dacă valvele sunt mobile; diminuarea apare la calcificare."]],
 [8,"Inversează intensitatea S1 la valvele mobile, semnul clasic al stenozei mitrale încă „pliabile”."],["clacment de deschidere","Graham-Steell"]),

q("cardiologie-adv-085",["Timpul de înjumătățire a presiunii (PHT) în stenoza mitrală severă este:",
 ["între 40 și 70 ms","între 71 și 139 ms","între 140 și 219 ms","peste 219 ms","sub 40 ms"],"D",1094,"Stenoza mitrală — Cadranul 30.42 (PHT)",
 "Reținerea PHT >219 ms (și a ariei <1,0 cm²) ca prag de stenoză mitrală severă.",
 ["Nu: 40-70 ms este intervalul normal al PHT.","Nu: 71-139 ms corespunde stenozei mitrale ușoare.","Nu: 140-219 ms corespunde stenozei mitrale moderate.","Cadranul 30.42: stenoza mitrală severă are PHT >219 ms, gradient mediu >10 mmHg și arie <1,0 cm².","Nu: un PHT sub 40 ms nu corespunde unei categorii de severitate; intervalul normal este 40-70 ms."]],
 [8,"Cele patru benzi PHT din același tabel sunt aproape consecutive; doar >219 ms este severă."],[">219","<1,0"]),

q("cardiologie-adv-086",["Regurgitarea mitrală severă, conform ESC:",
 ["chirurgie la simptomatici: FEVS >30%, diametru telediastolic <55 mm","chirurgie la asimptomatici: diametru telesistolic >45 mm sau FEVS <60%","chirurgie posibilă la asimptomatici cu FE prezervată și FA sau HTP","urmărire conservatoare nelimitată la simptomatici cu FE 55%","dispozitivul MitraClip în locul chirurgiei la pacienții operabili"],"ABC",1097,"Regurgitarea mitrală — Indicații chirurgicale ESC",
 "Aplicarea pragurilor FEVS >30%/diametru telediastolic <55 mm la simptomatici și diametru telesistolic >45 mm sau FEVS <60% la asimptomatici.",
 ["ESC: chirurgie la pacienții simptomatici cu FEVS >30% și diametru telediastolic al VS <55 mm.","ESC: chirurgie la asimptomaticii cu disfuncție de VS (diametru telesistolic >45 mm și/sau FEVS <60%).","La asimptomaticii cu FE prezervată, prezența FA și/sau a hipertensiunii pulmonare justifică luarea în considerare a chirurgiei.","Nu: regurgitarea mitrală severă simptomatică are indicație chirurgicală, nu urmărire nelimitată.","Nu: MitraClip este o opțiune la pacienții neeligibili chirurgical, nu un substitut al chirurgiei."]],
 [8,"Amână chirurgia la simptomaticul cu FE 55% — tocmai populația cu indicație clară."],[">45 mm","FEVS <60%"]),

q("cardiologie-adv-087",["Prolapsul mitral (boala Barlow) și valvulopatiile aortice:",
 ["boala Barlow: exces de țesut valvular, degenerescență mixomatoasă","bicuspidia aortică: transmitere familială în circa 9% din cazuri","boala Barlow: mai frecventă la bărbații vârstnici","bicuspidia aortică: prezentă la sub 0,1% dintre nou-născuți","valva aortică calcificată a vârstnicului: leziune congenitală"],"AB",1097,"Prolaps mitral (Barlow) și bicuspidie aortică",
 "Contrastul boala Barlow (femei tinere, degenerescență mixomatoasă) versus bicuspidia aortică (1-2%, 9% familială).",
 ["Boala Barlow: exces de țesut, inel dilatat, cordaje alungite și degenerescență mixomatoasă; este mai frecventă la femeile tinere, posibil familială, asociată cu Marfan sau Ehlers-Danlos.","Bicuspidia aortică afectează 1-2% dintre nou-născuți; circa 9% din cazuri au transmitere familială, cu posibilă asociere cu coarctația, dilatarea rădăcinii aortice și disecția.","Nu: boala Barlow este mai frecventă la femeile tinere decât la bărbați sau la femeile în vârstă.","Nu: bicuspidia aortică afectează 1-2% dintre nou-născuți, nu sub 0,1%.","Nu: valva aortică calcificată a vârstnicului rezultă dintr-un proces inflamator cu macrofage și limfocite T, nu dintr-o malformație."]],
 [8,"Inversează sexul/vârsta Barlow și reduce bicuspidia de la 1-2% la o raritate de 0,1%."],["1-2%","boală Barlow"]),

q("cardiologie-adv-088",["Stenoza aortică:",
 ["severă: velocitate maximă >4,0 m/s și gradient mediu >40 mmHg","simptomatică necorectată duce la deces în medie în 2-3 ani","dă simptome când orificiul scade la o treime din normal","are de obicei funcția sistolică VS prezervată","critică: velocitate >2,0 m/s, cu arie valvulară >2,0 cm²"],"ABCD",1098,"Stenoza aortică — Severitate eco și prognostic",
 "Aplicarea pragurilor ecografice de severitate și a ferestrei prognostice de 2-3 ani de la apariția simptomelor.",
 ["Cadranul 30.43: stenoza aortică severă are velocitate maximă >4,0 m/s, gradient maxim >64 mmHg, gradient mediu >40 mmHg și arie <1,0 cm².","Din momentul apariției simptomelor, fără corecție, decesul survine în medie la 2-3 ani.","Simptomele (sincopă de efort, angină, dispnee) apar când orificiul scade la circa o treime din normal.","Funcția sistolică a VS este de cele mai multe ori prezervată.","Nu: velocitatea >2,0 m/s este încă în banda ușoară (1,7-2,9 m/s), iar aria >2,0 cm² este normală."]],
 [8,"Folosește pragul de stenoză ușoară (≈2 m/s) ca „critic”, inversând tabelul 30.43."],[">4,0","2-3 ani"]),

q("cardiologie-adv-089",["Implantarea transcateter a valvei aortice (TAVI) s-a dovedit:",
 ["reușită în 86%; deces 2% periprocedural, 12% la 30 de zile","reușită în 86% din cazuri, cu mortalitate periprocedurală de 12%","echivalentă valvuloplastiei cu balon a adultului, ca soluție definitivă","contraindicată la pacienții inoperabili chirurgical","o punte temporară, ca valvulotomia chirurgicală la copil"],"A",1099,"Stenoza aortică — TAVI",
 "Reținerea triadei: succes 86%, mortalitate periprocedurală 2% și mortalitate de 12% la 30 de zile.",
 ["TAVI a avut succes în 86% din cazuri, cu mortalitate periprocedurală de 2% și de 12% la 30 de zile.","Nu: mortalitatea periprocedurală a fost de 2%; 12% reprezintă mortalitatea la 30 de zile.","Nu: valvuloplastia cu balon la adult are rezultate slabe; TAVI este alternativa pentru pacienții inoperabili.","Nu: TAVI se adresează tocmai pacienților la care nu se poate interveni chirurgical.","Nu: valvulotomia copilului este o soluție temporară, pe când TAVI este alternativa la chirurgia clasică pentru inoperabili."]],
 [8,"Înlocuiește 86/2/12 cu un eșec de 20/40, ordine de mărime alăturate dar false."],["86%","12%"]),

q("cardiologie-adv-090",["Semnele circulației hiperdinamice în regurgitarea aortică includ:",
 ["semnul Quincke: pulsații capilare în patul unghial","semnul de Musset: mișcarea capului la fiecare bătaie","semnul Duroziez: suflu „du-te-vino” pe femurala comprimată","uruitura Austin Flint: suflu mezodiastolic apical","șoc apexian susținut, nedeplasat inferior sau lateral"],"ABCD",1100,"Regurgitarea aortică — Semne periferice",
 "Recunoașterea semnelor Quincke, de Musset, Duroziez și a uruiturii Austin Flint, distincte de șocul apexian nedeplasat al stenozei.",
 ["Semnul Quincke constă în pulsații capilare vizibile în patul unghial.","Semnul de Musset constă în mișcarea capului cu fiecare bătaie cardiacă.","Semnul Duroziez este un suflu continuu „du-te-vino” pe artera femurală comprimată distal, semn de regurgitare aortică severă.","Uruitura Austin Flint este un suflu mezodiastolic apical: jetul regurgitant împiedică deschiderea cuspei mitrale anterioare.","Nu: în regurgitarea aortică șocul apexian este hiperdinamic, deplasat inferior și lateral; cel nedeplasat și susținut aparține stenozei aortice."]],
 [8,"Atribuie regurgitării apexul nedeplasat al stenozei aortice, semnul palpator clasic de confuzie SA/RA."],["Quincke","Austin Flint"]),

q("cardiologie-adv-091",["Valvulopatiile tricuspidiene și regurgitarea pulmonară:",
 ["stenoza tricuspidiană: de obicei reumatică, mai frecventă la femei","regurgitarea tricuspidiană funcțională dispare de obicei sub tratament medical","suflul Graham Steell este protodiastolic, accentuat în inspir","endocardita tricuspidiană a consumatorului i.v. impune proteză mecanică","stenoza tricuspidiană izolată e cea mai frecventă valvulopatie a adultului"],"ABC",1101,"Valva tricuspidă și suflul Graham Steell",
 "Diferențierea stenozei tricuspidiene reumatice/carcinoide de regurgitarea tricuspidiană funcțională reversibilă și de suflul Graham Steell inspirator.",
 ["Stenoza tricuspidiană este mai frecventă la femei, de obicei reumatică și asociată valvulopatiei mitrale sau aortice; poate apărea și în sindromul carcinoid.","Regurgitarea tricuspidiană funcțională dispare de obicei după tratamentul medicamentos al cauzei dilatării cordului drept.","Suflul Graham Steell al regurgitării pulmonare este protodiastolic, accentuat în inspir și greu de diferențiat de cel al regurgitării aortice.","Nu: la consumatorii de droguri i.v. cu endocardită tricuspidiană se recomandă îndepărtarea chirurgicală a valvei pentru eradicarea infecției, de obicei bine tolerată pe termen scurt.","Nu: stenoza tricuspidiană este rară și aproape nu se întâlnește ca leziune izolată."]],
 [8,"Înlocuiește excizia valvei infectate a CDIV — strategie citată explicit — cu protezarea mecanică de primă intenție."],["Graham Steell","sindromului carcinoid"]),

q("cardiologie-adv-092",["Anticoagularea la purtătorii de proteze valvulare:",
 ["valve slab trombogene: INR 2,5, cu factori de risc 3,0","valve înalt trombogene: INR 3,5, cu factori de risc 4,0","DOAC pot înlocui AVK la protezele valvulare mecanice","bioprotezele se anticoagulează pe viață, la INR 4,0","anticoagularea se oprește cu 5 zile înaintea unei extracții dentare"],"AB",1103,"Proteze valvulare — INR țintă și DOAC",
 "Aplicarea treptelor INR 2,5/3,0 versus 3,5/4,0 după trombogenitate și a absenței indicației DOAC la protezele valvulare.",
 ["Valvele slab trombogene (Carbomedics aortic, Medtronic Hall, St Jude fără Silzone): INR 2,5 fără factori adiționali și 3,0 cu factori.","Valvele înalt trombogene (Lillehei-Kaster, Omniscience, Starr-Edwards): INR 3,5 fără factori adiționali și 4,0 cu factori.","Nu: nu există indicație pentru DOAC la protezele valvulare.","Nu: bioprotezele necesită anticoagulare limitată (ESC: 3 luni, INR 2,5) sau aspirină 75-100 mg, apoi întrerupere dacă nu persistă alt risc.","Nu: pentru extracții dentare și endoscopie diagnostică anticoagularea nu se întrerupe, iar INR-ul țintă se reduce la 2,0."]],
 [8,"Pune biologicul la INR 4,0 pe viață și tratează extracția dentară ca o chirurgie majoră cu întrerupere de 5 zile."],["INR 2,5","DOAC"]),

q("cardiologie-adv-093",["Incidența anuală a endocarditei în Marea Britanie și mortalitatea ei netratată:",
 ["6-7/100.000, cu mortalitate de aproape 100%","1/1.000.000, cu mortalitate sub 5%","60-70/100.000, cu mortalitate de aproape 100%","6-7/100.000, cu mortalitate sub 5%","0,1/100.000, limitată la purtătorii de proteze valvulare"],"A",1103,"Endocardita infecțioasă — Epidemiologie",
 "Reținerea incidenței de 6-7/100.000 și a mortalității aproape complete fără tratament.",
 ["Incidența în Marea Britanie este de 6-7/100.000 (mai mare în țările în curs de dezvoltare), iar fără tratament mortalitatea se apropie de 100%.","Nu: incidența este de 6-7/100.000, iar fără tratament mortalitatea se apropie de 100%.","Nu: incidența în Marea Britanie este de 6-7/100.000, de zece ori mai mică.","Nu: incidența de 6-7/100.000 este corectă, dar fără tratament mortalitatea se apropie de 100%.","Nu: endocardita nu este limitată la purtătorii de proteze, iar incidența populațională este de 6-7/100.000."]],
 [8,"Subestimează cu două ordine de mărime o infecție a cărei mortalitate netratată se apropie de 100%."],["6-7 /100.000","100%"]),

q("cardiologie-adv-094",["Criteriile Duke modificate și endocardita pe proteză:",
 ["diagnosticul cert: 2 majore, 1 major și 3 minore sau 5 minore","hemoculturile persistent pozitive sunt criteriu major","endocardita precoce pe proteză apare în primele 60 de zile","endocardita tardivă pe proteză: viridans în 50-70% din cazuri","un singur set de hemoculturi de pe cateter e criteriu major"],"ABCD",1104,"Endocardita — Duke și proteza precoce/tardivă",
 "Aplicarea combinațiilor Duke și a pragului de 60 de zile care separă endocardita precoce stafilococică de cea tardivă streptococică.",
 ["Diagnosticul clinic cert cere două criterii majore, un criteriu major și trei minore sau cinci criterii minore.","Hemoculturile persistent pozitive (același germen la ≥12 ore distanță sau 3 din ≥4 seturi) sunt criteriu major.","Endocardita precoce pe proteză survine în primele 60 de zile, de obicei cu stafilococ nosocomial, și are prognostic rezervat.","Endocardita tardivă, după 60 de zile, este mai degrabă comunitară: streptococi viridans 50-70%, S. aureus 25%.","Nu: criteriul major cere două hemoculturi tipice fără focar primar sau hemoculturi persistent pozitive pe mai multe seturi, nu un singur set de pe cateter."]],
 [8,"Reduce bacteriologia Duke la un singur set de pe cateter, tocmai scenariul de contaminare."],["60 de zile","HACEK"]),

q("cardiologie-adv-095",["Frecvența aproximativă a manifestărilor în endocardita infecțioasă:",
 ["pirexie și suflu, fiecare la circa 90% dintre pacienți","noduli Osler circa 15%, degete hipocratice circa 10%","hematurie circa 70%, splenomegalie circa 40%","insuficiență cardiacă circa 50%, artralgii circa 25%","pete Roth la circa 90%, hipocratism la circa 2%"],"ABCD",1105,"Endocardita — Tablou clinic (procente)",
 "Memorarea ordinelor de mărime: febră/suflu ~90%, hipocratism 10%, pete Roth 5%, hematurie 70%.",
 ["Pirexia apare la circa 90%, suflul la circa 90%, iar starea generală alterată la circa 95% dintre pacienți.","Nodulii Osler apar la circa 15%, degetele hipocratice la circa 10%, iar petele Roth la circa 5%.","Hematuria apare la circa 70%, splenomegalia la circa 40%, iar emboliile cerebrale la circa 20%.","Insuficiența cardiacă apare la circa 50%, iar artralgiile la circa 25% dintre pacienți.","Nu: petele Roth apar la circa 5%, nu la 90%, iar hipocratismul digital la circa 10%, nu la 2%."]],
 [8,"Schimbă petele Roth (5%) cu febra (90%), două procente din același tabel."],["90","Pete Roth"]),

q("cardiologie-adv-096",["Profilaxia antibiotică a endocarditei infecțioase:",
 ["se adresează purtătorilor de proteze valvulare, inclusiv TAVI","se adresează celor cu endocardită infecțioasă în antecedente","include cardiopatiile congenitale cianogene necorectate","se indică în stenoza mitrală ușoară, la proceduri digestive","exclude, după AHA, transplantul cardiac cu valvulopatie"],"ABC",1106,"Endocardita — Profilaxie ESC",
 "Recunoașterea celor trei grupuri ESC de risc major și a ferestrei de 6 luni după corecția congenitală.",
 ["Grupul ESC de risc major include protezele valvulare, inclusiv cele implantate transcateter, și materialul intracardiac de reparare.","Antecedentele de endocardită infecțioasă încadrează pacientul în grupul ESC de risc major.","Cardiopatiile congenitale cianogene necorectate sau cu șunturi paliative sunt risc major; după corecția completă, riscul rămâne crescut 6 luni.","Nu: ESC limitează profilaxia la grupurile de risc major, pentru proceduri stomatologice cu manipulare gingivală, periapicală sau a mucoasei.","Nu: AHA consideră că și transplantul cardiac cu boală valvulară trebuie socotit risc înalt."]],
 [8,"Extinde profilaxia la stenoza mitrală ușoară și orice gest digestiv, contrar restricției ESC la stomatologie de risc."],["proteze valvulare","6 luni"]),

q("cardiologie-adv-097",["Miocardita acută:",
 ["are frecvent VSH, PCR și troponina crescute în faza acută","se confirmă prin IRM: edem pe T2, captare neuniformă de gadoliniu","impune evitarea sportului timp de 6 săptămâni","cu celule gigante are evoluție rapidă și prognostic infaust","se confirmă de primă intenție prin serologie virală, nu prin IRM"],"ABD",1119,"Bolile miocardului — Miocardita acută",
 "Recunoașterea inutilității serologiei virale, a IRM de confirmare și a ferestrei de 6 luni fără sport.",
 ["VSH, PCR, troponina și CK sunt frecvent crescute în faza acută, pe când serologia virală de obicei nu este utilă.","IRM confirmă diagnosticul (edem pe T2, captare neuniformă de gadoliniu); biopsia este gold standard, rezervată formelor fulminante sau cu agravare.","Nu: sportul se evită timp de 6 luni; majoritatea cazurilor se vindecă în câteva săptămâni.","Miocardita cu celule gigante are evoluție rapid progresivă și prognostic infaust și se tratează imunosupresor.","Nu: serologia virală de obicei nu este utilă și nu înlocuiește IRM-ul, recomandat pentru confirmare."]],
 [8,"Pune serologia virală — explicit neutilă — în locul IRM-ului de confirmare."],["6 luni","celule gigante"]),

q("cardiologie-adv-098",["Cardiomiopatia hipertrofică:",
 ["e prima cauză de MSC la tineri, cu prevalență de 1/500","are ca mutații cele mai frecvente MYH7 și MYBPC3","are obstrucție dinamică a tractului de ejecție la circa 25%","cu mutații de troponină T: hipertrofie marcată, risc mic de MSC","se distinge ușor ecografic de bolile de depozit (Fabry, Pompe)"],"ABC",1119,"Cardiomiopatia hipertrofică — Genetică și LVOTO",
 "Reținerea prevalenței de 1/500, a genelor MYH7/MYBPC3 și a obstrucției dinamice la 25%.",
 ["CMH afectează 1 din 500 de locuitori și este cea mai frecventă cauză de moarte subită cardiacă la tineri.","Cele mai frecvente mutații sunt MYH7 (lanțul greu al β-miozinei) și MYBPC3 (proteina C de legare a miozinei).","Circa 25% dintre pacienți au obstrucție dinamică a tractului de ejecție, prin HVS, SAM mitral și ejecție rapidă.","Nu: mutațiile troponinei T se asociază cu hipertrofie ușoară, dar cu risc crescut de moarte subită; hipertrofia marcată ține mai degrabă de MYH7.","Nu: bolile de depozit (Danon, Pompe, Fabry) sunt dificil de diferențiat ecografic de CMH ereditară."]],
 [8,"Inversează fenotipul troponinei T (hipertrofie ușoară, risc înalt) cu cel al MYH7 (hipertrofie marcată)."],["1 din 500","25%"]),

q("cardiologie-adv-099",["Cardiomiopatia hipertrofică — moartea subită și suflul de obstrucție:",
 ["grosimea parietală >30 mm crește riscul de moarte subită","istoricul familial de MSC sub 50 de ani crește riscul","TV nesusținută la Holter crește riscul de moarte subită","suflul de obstrucție scade la Valsalva și crește la ghemuit","amiodarona e superioară ICD la riscul înalt de moarte subită"],"ABC",1120,"CMH — Risc de moarte subită și suflu dinamic",
 "Listarea markerilor de risc de moarte subită și a regulii ≥2 factori pentru evaluarea ICD.",
 ["Hipertrofia masivă, cu grosime parietală >30 mm, este factor de risc de moarte subită.","Istoricul familial de moarte subită cardiacă sub 50 de ani este factor de risc.","TV nesusținută la Holter, sincopa inexplicabilă și răspunsul TA plat sau hipotensiv la efort sunt factori de risc de moarte subită.","Nu: suflul de obstrucție se amplifică la Valsalva și în ortostatism și se diminuează la ghemuit.","Nu: la ≥2 factori de risc se face evaluarea pentru ICD; amiodarona este o alternativă la riscul mai mic, nu superioară ICD."]],
 [8,"Inversează dinamica suflului la Valsalva/ghemuit, manevra clasică de obstrucție dinamică."],[">30 mm","Valsalva"]),

q("cardiologie-adv-100",["În cardiomiopatia aritmogenă:",
 ["ECG arată tipic BRS și unde Q inferioare, fără unde epsilon","pot apărea unde epsilon și T inversat în V1-V3","IRM nu poate arăta infiltrația fibro-grăsoasă","amiodarona este contraindicată în aritmiile simptomatice","boala debutează prin insuficiență ventriculară stângă, fără aritmii"],"B",1122,"Cardiomiopatia aritmogenă — ECG și tratament",
 "Recunoașterea undelor epsilon și a undelor T inversate în V1-V3 în cardiomiopatia aritmogenă.",
 ["Nu: ECG-ul este de obicei normal; pot apărea unde T inversate în V1-V3, unde epsilon și BRD.","Pot fi prezente unde epsilon (potențiale mici la sfârșitul QRS) și inversarea undei T în V1-V3; beta-blocantele sunt prima linie în aritmiile neamenințătoare.","Nu: ecografia poate fi normală, iar IRM evaluează mai acurat VD și poate arăta infiltrația fibro-grăsoasă.","Nu: amiodarona sau sotalolul se folosesc în aritmiile simptomatice, iar ICD în cele refractare sau amenințătoare de viață.","Nu: în stadiile precoce domină aritmiile și riscul de moarte subită."]],
 [8,"Neagă unda epsilon — semnul ECG eponim — și inversează cronologia aritmii versus insuficiență."],["unde epsilon","V1-"]),

q("cardiologie-adv-101",["Noncompactarea VS și cardiomiopatiile restrictive:",
 ["noncompactarea VS evoluează cu IC, embolii, aritmii și moarte subită","cardiomiopatia restrictivă: ventriculi dilatați și FE mult scăzută","amiloidoza: miocard „strălucitor” la ecografie; biopsia e frecvent utilă","noncompactarea afectează predominant bazele ventriculului drept","cardiomiopatia restrictivă: PVJ plat, fără semn Kussmaul"],"AC",1123,"Noncompactare VS și cardiomiopatie restrictivă",
 "Recunoașterea fenotipului spongiform apical, a profilului restrictiv cu semne de umplere (Friedreich, Kussmaul) și a aspectului de amiloid.",
 ["Noncompactarea VS are aspect spongiform, predominant apical, și evoluează cu IC, tromboembolism, aritmii și moarte subită.","Nu: în cardiomiopatia restrictivă primară volumele ventriculare sunt normale sau scăzute, cu dilatare biatrială și FE aproape normală.","Amiloidoza dă un miocard „strălucitor” și aspect de „șine de tramvai” în mod M; biopsia este frecvent utilă, spre deosebire de alte cardiomiopatii.","Nu: noncompactarea afectează predominant segmentele apicale ale ventriculului stâng.","Nu: în cardiomiopatia restrictivă PVJ este accentuat, cu colaps diastolic (Friedreich) și semn Kussmaul."]],
 [8,"Mută noncompactarea de la apexul stâng la bazele drepte și anulează semnele venoase clasice ale restrictivei."],["şine de tramvai","spongiform"]),

q("cardiologie-adv-102",["Cardiomiopatiile Tako-tsubo și peripartum:",
 ["Tako-tsubo: akinezie tipic bazală, cu apex prezervat","Tako-tsubo: recuperare de obicei în 4-6 săptămâni","peripartum: în ultimul trimestru sau primele 5 luni postpartum","peripartum: aproape jumătate își recuperează funcția în 6 luni","Tako-tsubo: mai frecventă la bărbații tineri"],"BCD",1124,"Tako-tsubo și cardiomiopatia peripartum",
 "Potrivirea terenului (femei de vârstă medie versus multipare peste 30 de ani) și a ferestrelor de recuperare de 4-6 săptămâni / 6 luni.",
 ["Nu: în Tako-tsubo, cu coronare neobstruate, akinezia este medio-apicală, cu baze prezervate.","Tako-tsubo este mai frecventă la femeile de vârstă medie; recuperarea are loc de obicei în 4-6 săptămâni, cu posibile recurențe.","Cardiomiopatia peripartum apare în ultimul trimestru sau în primele 5 luni postpartum, mai frecvent la obeze, multipare, peste 30 de ani, cu preeclampsie.","Aproape jumătate dintre paciente își recuperează funcția în 6 luni.","Nu: Tako-tsubo este mai frecventă la femeile de vârstă medie, cu recuperare în 4-6 săptămâni și posibile recurențe."]],
 [8,"Mută Tako-tsubo pe bărbatul tânăr cu vindecare într-o zi, inversând epidemiologia și cinetica de recuperare."],["Tako-tsubo","4-6 săptămâni"]),

q("cardiologie-adv-103",["Pericardita acută:",
 ["explică circa 5% din urgențele pentru durere toracică","se diagnostichează pe 2 din 4: durere, frecătură, modificări ECG, revărsat","se tratează cu AINS 1-2 săptămâni plus colchicină 3 luni","are drept primă linie corticosteroizii, care scad recurențele","permite atleților reluarea efortului după 48 de ore"],"ABC",1125,"Pericardita acută — Diagnostic și tratament",
 "Aplicarea regulii 2 din 4, a dozelor de AINS plus colchicină și a rezervării corticosteroizilor, plus restricția de efort la atleți.",
 ["Pericardita acută poate explica 5% din prezentările de urgență pentru durere toracică și este mai frecventă la bărbații tineri.","Diagnosticul clinic cere două din patru criterii: durere, frecătură, ST concav în sus (în șa) cu PR coborât, revărsat.","Aspirină 750-1.000 mg ×3/zi sau ibuprofen 600-800 mg ×3/zi, 1-2 săptămâni, plus colchicină 0,5 mg ×2/zi timp de 3 luni.","Nu: corticosteroizii se rezervă etiologiei imune și se asociază cu risc crescut de recurență.","Nu: atleții evită efortul cel puțin 3 luni, iar activitatea se limitează până la normalizarea markerilor."]],
 [8,"Comprimă interdicția de efort a atleților de la 3 luni la 48 de ore, contrar textului."],["5%","colchicină"]),

q("cardiologie-adv-104",["Pericardita incesantă, cronică și tuberculoasă:",
 ["e cronică la o durată de peste 6 săptămâni","la HIV, în țări în dezvoltare, TB depășește 90% din cazuri","sindromul Dressler: pericardită autoimună tardivă post-infarct","în forma TB, prednisolonul 60 mg se asociază tuberculostaticelor","TB explică peste 50% din pericardite în țările dezvoltate"],"BCD",1126,"Pericardită incesantă, TB și Dressler",
 "Diferențierea pericarditei incesante de cea cronică (>3 luni) și a ponderii TB >50% (>90% la HIV) în țările în curs de dezvoltare.",
 ["Nu: pericardita cronică durează peste 3 luni; pragul de 6 săptămâni ține de forma incesantă.","În țările în curs de dezvoltare, TB poate depăși 50% din pericardite, iar la pacienții cu HIV peste 90%; în țările dezvoltate este rară (<5%).","Sindromul Dressler este o reacție autoimună tardivă după infarctul miocardic.","Prednisolonul 60 mg zilnic, timp de 2-6 săptămâni, se asociază tratamentului antituberculos.","Nu: în țările dezvoltate TB explică sub 5% din pericardite; peste 50% se întâlnește în țările în curs de dezvoltare."]],
 [8,"Mută ponderea TB >50% din țările în dezvoltare în Occident, unde textul o plasează sub 5%."],["6 săptămâni","Dressler"]),

q("cardiologie-adv-105",["Revărsatul pericardic cu tamponadă se caracterizează prin:",
 ["QRS microvoltate, tahicardie și posibilă alternanță electrică","cord globulos „în pară”, cu vene pulmonare tipic nedilatate","colabarea telediastolică a AD și protodiastolică a VD","semnul Ewart: matitate sub unghiul scapulei drepte","siluetă cardiacă mică, cu vene pulmonare foarte dilatate"],"ABC",1127,"Revărsat pericardic și tamponadă",
 "Reunirea microvoltajului cu alternanță electrică, a siluetei „în pară”, a colabării AD/VD și a semnului Ewart (scapula stângă).",
 ["Pe ECG apar complexe QRS microvoltate (<0,5 mV în derivațiile membrelor), tahicardie sinusală și, posibil, alternanță electrică.","Radiografia arată un cord globulos, „în pară”, cu vene pulmonare tipic nedilatate.","Ecografia arată colabarea telediastolică a AD și protodiastolică a VD, cu VCI dilatată și colaps inspirator sub 50%.","Nu: semnul lui Ewart este matitatea sub unghiul scapulei stângi, prin comprimarea bazei pulmonare stângi.","Nu: cordul mic este propriu constricției; tamponada produce o siluetă cardiacă mărită, globuloasă."]],
 [8,"Atribuie tamponadei cordul mic al constricției, inversând perechea radiologică clasică."],["semnul lui Ewart","alternanţă electrică"]),

q("cardiologie-adv-106",["În pericardita constrictivă:",
 ["calcificări în până la 50%, fără să însemne constricție","radiografia arată un cord globulos, ca în tamponadă","ECG-ul este normal, fără QRS microvoltate","cateterismul: presiuni telediastolice inegale în VS și VD","pericardectomia se amână până la atrofia miocardică maximă"],"A",1127,"Pericardita constrictivă — Imagistică și cateterism",
 "Reținerea calcificărilor la până la 50% și a faptului că ele nu echivalează constricția, plus egalizarea presiunilor telediastolice.",
 ["Calcificările pericardice pot fi prezente în până la 50% din cazuri, dar un pericard calcificat nu înseamnă constricție.","Nu: radiografia arată un cord relativ mic, în context de insuficiență cardiacă; silueta globuloasă este a tamponadei.","Nu: ECG-ul arată complexe QRS microvoltate, cu unde T aplatizate sau inversate.","Nu: la cateterism, presiunile telediastolice din VS și VD sunt egale.","Nu: pericardectomia precoce se recomandă înaintea constricției severe și a atrofiei miocardice, care fac intervenția riscantă."]],
 [8,"Transformă calcificarea într-un echivalent de constricție și amână chirurgia până la atrofia care crește riscul."],["50%","telediastolice"]),

q("cardiologie-adv-107",["În pericardita constrictivă tuberculoasă, pericardectomia:",
 ["se face precoce, sub antituberculoase, dacă există calcificări","fără calcificări, după o probă terapeutică eșuată de 4-6 săptămâni","se face imediat, fără antituberculoase, în cazurile necalcificate","se amână până după 12 luni de antituberculoase","este contraindicată de calcificare, considerată semn de vindecare"],"AB",1127,"Pericardita constrictivă — Momentul pericardectomiei în TB",
 "Diferențierea cazului calcificat (chirurgie precoce sub tuberculostatice) de cel necalcificat (probă terapeutică 4-6 săptămâni).",
 ["Calcificările marchează afectarea cronică și orientează spre pericardectomie precoce, sub medicație antituberculoasă.","Fără calcificări se încearcă întâi cura antituberculoasă; dacă starea rămâne staționară sau se deteriorează după 4-6 săptămâni, se indică pericardectomia.","Nu: fără calcificări nu se operează imediat, fără tratament etiologic; se încearcă întâi cura antituberculoasă.","Nu: proba terapeutică durează 4-6 săptămâni, nu 12 luni, iar lipsa ameliorării indică pericardectomia.","Nu: calcificarea marchează cronicitatea și orientează spre pericardectomie precoce, nu o contraindică."]],
 [8,"Inversează rolul calcificării: din argument de chirurgie precoce în „semn de vindecare” care ar interzice operația."],["4-6 săptămâni","Calcificărilor pericardice"]),

q("cardiologie-adv-108",["Febra persistentă în endocardită, după 48 de ore de antibiotic adecvat:",
 ["impune căutarea extensiei paravalvulare, cu posibil abces","poate ține de o reacție adversă medicamentoasă","poate indica infecție nosocomială sau embolie pulmonară","impune schimbarea empirică a schemei, chiar cu culturi negative","impune colaborare cu microbiologia și chirurgia cardiovasculară"],"ABCE",1106,"Endocardita — Febra persistentă",
 "Interpretarea febrei după 48 de ore ca abces, alergie, infecție nosocomială sau embolie, nu ca semnal de schimbare empirică a antibioticului.",
 ["Extensia paravalvulară, cu un posibil abces, este prima preocupare când febra persistă după 48 de ore.","O reacție adversă medicamentoasă poate întreține febra, care cedează după întreruperea medicamentului.","Infecțiile nosocomiale (loc de puncție, tract urinar) și embolia pulmonară, mai ales în endocardita dreaptă sau la spitalizare lungă, pot explica febra.","Nu: schimbarea empirică a schemei trebuie evitată, cu excepția culturilor noi pozitive sau a suspiciunii de alergie.","Se colaborează cu microbiologia și se solicită consult de chirurgie cardiovasculară; apariția unei rezistențe noi este rară."]],
 [8,"Transformă febra persistentă într-un pretext de schimbare empirică, pe care textul o descurajează explicit."],["48 de ore","Febra persistentă"]),

q("cardiologie-adv-109",["Decesele cardiace din primele 24 de ore de la simptome, în Marea Britanie:",
 ["până la 100.000, majoritatea prin FV/TV rapidă","mai ales prin bradiaritmii severe, FV fiind rară","nu sunt declanșate de ischemia tranzitorie","majoritatea supraviețuitorilor au infarct acut evident clinic","impun amânarea BLS până la confirmarea necrozei"],"A",1045,"Proceduri terapeutice — Resuscitarea cardiacă",
 "Reținerea ordinii de mărime 100.000 și a mecanismului FV/TV, nu bradiaritmic, al deceselor cardiace din primele 24 de ore.",
 ["Până la 100.000 de decese survin în primele 24 de ore de la simptomele cardiace; aproape jumătate rapid, majoritatea prin FV sau TV rapidă.","Nu: majoritatea se datorează FV sau TV rapide; bradiaritmiile severe produc o proporție mai mică de decese.","Nu: ischemia tranzitorie este suspectată ca factor declanșator major.","Nu: doar o mică proporție dintre supraviețuitori au un infarct acut evident clinic.","Nu: BLS se inițiază imediat la stop, fără a aștepta markerii de necroză."]],
 [8,"Inversează mecanismul dominant (FV/TV) cu bradiaritmia și amână BLS până la enzime."],["100.000 de decese","tahicardie ventriculară rapidă"]),

q("cardiologie-adv-110",["Suportul vital de bază la un pacient neresponsiv:",
 ["începe cu evitarea expunerii la pericole suplimentare","începe imediat la respirație absentă sau anormală","are șanse de revenire mai mici în stopul prelungit","are ca prim gest palparea prelungită a pulsului","solicită ajutor abia după 10 minute de observație"],"ABC",1045,"Proceduri terapeutice — Primii pași BLS",
 "Ordinea: siguranța scenei, stimuli, apel, apoi BLS dacă respirația lipsește sau este anormală.",
 ["Primul pas al BLS este evitarea expunerii la pericole suplimentare.","După testarea răspunsului la stimuli verbali sau dureroși, BLS se începe imediat dacă pacientul nu respiră sau respiră anormal.","Cu cât stopul cardio-respirator durează mai mult, cu atât șansa de revenire este mai mică.","Nu: detectarea pulsului poate fi dificilă și nu este primul pas; primul pas este evitarea pericolelor.","Nu: dacă pacientul nu răspunde, ajutorul se solicită imediat."]],
 [8,"Pune palparea pulsului înaintea siguranței scenei, inversând algoritmul BLS."],["pericole suplimentare","stimuli verbali"]),

q("cardiologie-adv-111",["La adult, după 30 de compresiuni, fiecare respirație de salvare durează:",
 ["3-4 secunde","10 secunde","1 secundă","2 secunde","5 secunde"],"C",1046,"Suportul vital de bază — Respirația de salvare",
 "Reținerea duratei de 1 secundă a fiecărei respirații eficiente la adult.",
 ["Nu: fiecare respirație eficientă durează 1 secundă; 3-4 secunde este o durată excesivă.","Nu: insuflația durează 1 secundă; 10/minut este rata de ventilație după abordarea avansată a căilor aeriene.","După 30 de compresiuni se administrează două respirații eficiente, fiecare timp de 1 secundă.","Nu: fiecare respirație de salvare durează 1 secundă, nu 2 secunde.","Nu: fiecare respirație de salvare durează 1 secundă, nu 5 secunde."]],
 [8,"Confundă durata de 1 secundă a insuflației cu rata 10/min post-intubație sau cu fereastra pediatrică de 1 minut."],["1 secundă","Două respiraţii eficiente"]),

q("cardiologie-adv-112",["Suportul vital cardiac avansat (ACLS):",
 ["include monitorizare ECG, cale aeriană avansată, abord venos","permite abordul intraosos dacă cel venos este imposibil","se ghidează după ritmul stabilit cu DAE sau defibrilator","începe înaintea compresiunilor, fără BLS prealabil","limitează abordul vascular la venele dorsului mâinii"],"ABC",1046,"Suportul vital avansat — Componente ACLS",
 "Recunoașterea triadei monitorizare–căi aeriene–acces vascular, inclusiv opțiunea intraosoasă.",
 ["ACLS cuprinde monitorizarea ECG, managementul avansat al căilor aeriene și abord venos periferic mare sau central.","Abordul intraosos este permis atunci când abordul venos nu este posibil.","Tipul de ritm, stabilit cu DAE sau cu defibrilatorul standard, determină aplicarea algoritmului ACLS.","Nu: ACLS urmează după ce BLS a fost asigurat.","Nu: se vizează o venă periferică mare sau o venă centrală, nu venele de pe dorsul mâinii."]],
 [8,"Inversează ordinea BLS→ACLS și limitează accesul vascular la venele mici de la mână."],["intraosos","algoritmul ACLS"]),

q("cardiologie-adv-113",["Tratamentul imediat după revenirea circulației spontane include:",
 ["evaluarea după algoritmul ABCDE","o țintă a SpO2 de 94-98%","menținerea unui PaCO2 normal","ECG în 12 derivații, tratarea cauzei și controlul temperaturii","hiperventilație, cu PaCO2 foarte scăzut"],"ABCD",1047,"Post-ROSC — Ținte imediate",
 "Aplicarea ABCDE, a ferestrei SpO2 94-98% și a PaCO2 normal după ROSC.",
 ["Algoritmul ABCDE face parte din tratamentul imediat după ROSC.","Ținta saturației periferice în oxigen după ROSC este 94-98%.","Se urmărește un PaCO2 normal, nu hipocapnie indusă.","ECG în 12 derivații, tratamentul cauzei și controlul temperaturii sunt măsuri explicite după ROSC.","Nu: se urmărește PaCO2 normal; hiperventilația agresivă nu face parte din algoritm."]],
 [8,"Înlocuiește țintele 94-98% și PaCO2 normal cu hiperventilație, eroare clasică post-ROSC."],["94-98%","Algoritmul ABCDE"]),

q("cardiologie-adv-114",["După abordarea avansată a căilor aeriene, ventilația în timpul RCP se face:",
 ["cu 20/minut, cu întreruperea masajului la fiecare ciclu","în raport 30:2, ca în BLS fără cale avansată","cu 10/minut, fără a întrerupe masajul cardiac","cu 6/minut, fără a întrerupe masajul cardiac","în apnee, până la revenirea circulației spontane"],"C",1048,"ACLS — Ventilație după cale aeriană avansată",
 "Reținerea ratei de 10/minut fără întreruperea compresiilor, odată calea aeriană asigurată.",
 ["Nu: ventilația se face cu 10/minut, fără pauze de masaj.","Nu: raportul 30:2 se aplică în BLS, înaintea abordării avansate a căilor aeriene.","După abordarea avansată a căilor aeriene, ventilația continuă cu 10/minut, fără a întrerupe masajul cardiac.","Nu: rata de ventilație citată este 10/minut, nu 6/minut.","Nu: ventilația continuă pe parcursul RCP; nu se așteaptă ROSC în apnee."]],
 [8,"Păstrează 30:2 sau 20/min cu pauze — tocmai ce textul abandonează după intubație."],["10/minut","masajul cardiac"]),

q("cardiologie-adv-115",["Defibrilarea externă — poziția padelelor și tipul de undă:",
 ["la dreapta sternului superior și deasupra apexului","sub vârful scapulei stângi și pe hemitoracele stâng anterior","sub clavicula stângă și deasupra apexului","sub scapula dreaptă, poziția stern-apex fiind abandonată","monofazică, preferată pentru energia mai mică decât bifazica"],"AB",1048,"Defibrilarea — Plasarea padelor",
 "Memorarea celor două poziții (stern-apex și scapulă stângă–hemitorace stâng anterior).",
 ["Prima poziție acceptată: o padelă la dreapta sternului superior și cealaltă deasupra apexului cardiac.","A doua poziție acceptată: o padelă sub vârful scapulei stângi și cealaltă pe peretele anterior al hemitoracelui stâng.","Nu: pozițiile acceptate sunt dreapta sternului superior–apex și sub scapula stângă–hemitorace stâng anterior, nu sub clavicula stângă.","Nu: poziția stern–apex rămâne una dintre cele două poziții acceptate.","Nu: defibrilatoarele bifazice necesită energie mai mică și sunt din ce în ce mai utilizate."]],
 [8,"Inversează ierarhia bifazic/monofazic și anulează una dintre cele două poziții clasice."],["dreapta sternului","scapulei stângi"]),

q("cardiologie-adv-116",["Recuperarea neurologică după stop cardiac pare mai bună la pacienții cu:",
 ["absența activității EEG timp de 3 săptămâni","areactivitate prelungită, fără mișcări voluntare","hipertermie menținută în jur de 40°C","mișcări voluntare și activitate EEG în primele 3 zile","lipsa controlului temperaturii corporale după resuscitare"],"D",1048,"Post resuscitare — Prognostic neurologic",
 "Reținerea ferestrei de 3 zile (mișcări voluntare + EEG) ca marker de prognostic mai bun.",
 ["Nu: lipsa prelungită a activității EEG nu este markerul favorabil citat; contează activitatea EEG din primele 3 zile.","Nu: areactivitatea fără mișcări voluntare este un semn nefavorabil.","Nu: hipertermia de 40°C nu face parte din îngrijirea descrisă; după ROSC temperatura se controlează.","Prognosticul neurologic este mai bun dacă apar mișcări voluntare și activitate EEG în primele 3 zile.","Nu: controlul temperaturii face parte din îngrijirea post-ROSC."]],
 [8,"Transformă fereastra favorabilă de 3 zile într-un argument pentru areactie prelungită sau hipertermie."],["3 zile","mişcări voluntare"]),

q("cardiologie-adv-117",["Nodul sinusal și ritmul sinusal normal:",
 ["parasimpaticul reduce frecvența de la circa 100 la circa 70/min","unde P pozitive în DI și DII, negative în aVR","frecvența sinusală este ușor mai mare la femei","la sportiv, tonusul vagal crescut dă tahicardie patologică","aritmia sinusală inspiratorie este patologică la copii și tineri"],"ABC",1051,"Aritmii — Nodul sinusal și aritmia sinusală",
 "Contrastul modulării vagale 100→70 b.p.m. cu polaritatea P și cu caracterul fiziologic al aritmiei sinusale.",
 ["În mod normal predomină parasimpaticul, care scade rata de descărcare a nodului sinusal de la circa 100 la circa 70 b.p.m.","În ritmul sinusal, undele P sunt pozitive în DI și DII și negative în aVR.","Frecvența sinusală este ușor mai crescută la femei.","Nu: la sportivi, tonusul vagal crescut produce bradicardie fiziologică.","Nu: creșterea inspiratorie a frecvenței (aritmia sinusală) este normală, mai ales la copii și tineri."]],
 [8,"Etichetează aritmia sinusală a tânărului și bradicardia sportivului drept patologie, deși textul le consideră fiziologice."],["70 b.p.m","negative în AVR"]),

q("cardiologie-adv-118",["Mecanismele de producere a aritmiilor:",
 ["post-potențialele precoce apar de obicei la sfârșitul fazei 3","post-potențialele tardive apar înainte de sfârșitul fazei 3","intoxicația digitalică dă tahicardii atriale prin activitate declanșată","reintrarea necesită un miez excitabil, fără zonă cicatricială","majoritatea tahicardiilor paroxistice regulate apar prin automatism sinusal"],"AC",1052,"Mecanisme aritmogene — Post-potențiale",
 "Diferențierea post-potențialelor precoce (sfârșit de fază 3) de cele tardive și legătura cu digitala.",
 ["Post-potențialele precoce apar de obicei la sfârșitul fazei 3, înainte ca potențialul transmembranar să atingă pragul.","Nu: post-potențialele tardive apar după ce potențialul transmembranar atinge pragul, nu înaintea sfârșitului fazei 3.","Activitatea declanșată, agravată de catecolamine, tulburări electrolitice, hipoxie, acidoză sau medicamente, explică tahicardiile atriale din intoxicația digitalică.","Nu: reintrarea se organizează în jurul unui miez inexcitabil, cum este o cicatrice.","Nu: majoritatea tahicardiilor paroxistice regulate au la bază reintrarea."]],
 [8,"Suprapune precocele peste tardive și atribuie tahicardiilor paroxistice automatismul sinusal, nu reintrarea."],["post-potenţiale precoce","intoxicaţia digitalică"]),

q("cardiologie-adv-119",["În sincopa vasovagală se recomandă:",
 ["clinostatism sau poziție șezândă și contrapresiune la prodrom","aport crescut de sare, ciorapi de compresie sau midodrină","ablația nodului AV, ca tratament de primă linie","interzicerea poziției șezânde, care ar agrava prodromul","în forma malignă, stimulare bicamerală cu „rate drop response”"],"ABE",1053,"Bradicardii — Tratamentul sincopei vasovagale",
 "Recunoașterea măsurilor non-farmacologice, a midodrinei și a stimulării cu rate-drop în forma malignă.",
 ["Se recomandă evitarea situațiilor declanșatoare, clinostatismul sau poziția șezândă și manevrele de contrapresiune la prodrom.","Aportul crescut de sare, ciorapii de compresie, midodrina, beta-blocantele sau disopiramida sunt opțiuni listate.","Nu: ablația nodului AV nu este un tratament al sincopei vasovagale.","Nu: clinostatismul sau poziția șezândă sunt recomandate la prodrom, nu interzise.","Forma „malignă” (traumatisme, asistolă documentată) beneficiază de stimulare bicamerală cu funcția „rate drop response”."]],
 [8,"Înlocuiește contrapresiunea și midodrina cu ablația de nod AV, strategie a FA-ului „ablate and pace”."],["midodrina","rate drop response"]),

q("cardiologie-adv-120",["Blocul atrioventricular de gradul I:",
 ["PR peste 0,20 sec, fiecare undă P fiind condusă","absența conducerii undelor P spre ventriculi","PR care crește progresiv până la o undă P blocată","un tip de Mobitz II, cu QRS peste 0,12 sec","conducere atrioventriculară 2:1"],"A",1053,"BAV — Gradul I",
 "Fixarea pragului PR >0,20 sec cu conducere 1:1, distinct de Mobitz și de conducerea 2:1.",
 ["BAV de gradul I înseamnă PR peste 0,20 sec, fiecare depolarizare atrială fiind condusă la ventriculi, cu întârziere.","Nu: absența conducerii undelor P definește BAV complet.","Nu: prelungirea progresivă a PR până la o undă P blocată definește Mobitz I.","Nu: Mobitz II este un subtip de BAV de gradul II, nu de gradul I.","Nu: conducerea 2:1 este o formă aparte de BAV de gradul II."]],
 [8,"Confundă BAV I (toate P conduse, PR lung) cu Mobitz sau cu conducerea 2:1."],["0,20 sec","BAV de gradul I"]),

q("cardiologie-adv-121",["Cauzele blocului atrioventricular complet:",
 ["boala Lev la vârstnici, boala Lenegre la tineri","boala Lyme, boala Chagas, LES matern (forma congenitală)","hipertiroidismul netratat, ca etiologie dominantă","digoxinul, beta-blocantele, amiodarona, protezarea valvei aortice","nu includ boli infiltrative sau neuromusculare"],"ABD",1055,"BAV complet — Etiologie (Cadranul 30.13)",
 "Potrivirea Lev/Lenegre cu vârsta și a cauzelor infecțioase (Lyme, Chagas) și medicamentoase.",
 ["Cadranul opune fibroza progresivă a vârstnicului (boala Lev) celei a tânărului (boala Lenegre).","Boala Lyme, boala Chagas și, în forma congenitală, LES matern figurează printre cauze.","Nu: hipertiroidismul nu figurează ca etiologie dominantă a BAV complet.","Digoxinul, beta-blocantele, non-dihidropiridinicele și amiodarona, ca și chirurgia (înlocuire de valvă aortică, CABG, DSV), figurează în cadran.","Nu: pe lângă ischemie, cauzele includ boli infecțioase, infiltrative, iatrogene și neuromusculare."]],
 [8,"Reduce BAV complet la ischemie și ignoră perechea Lev/Lenegre și infecțiile clasice (Lyme, Chagas)."],["Boala Lev","Boala Lyme"]),

q("cardiologie-adv-122",["Ritmul de scăpare cu QRS larg (>0,12 sec) în BAV complet:",
 ["origine hisiană, 50-60/min și stabilitate relativă","origine sub His, 15-40/min, instabil, cu sincope Stokes-Adams","are indicație de stimulare permanentă, care scade mortalitatea","răspunde durabil la atropină, stimularea fiind inutilă","boala Lev afectează mai ales pacienții tineri"],"BC",1055,"BAV complet — Scăpare cu QRS larg",
 "Contrastul scăpării distale lente (15-40, Stokes-Adams) față de cea hisiană 50-60.",
 ["Nu: originea hisiană, frecvența de 50-60 b.p.m. și stabilitatea relativă caracterizează scăparea cu QRS îngust.","Scăparea cu QRS larg are origine sub His, frecvență de 15-40 b.p.m., este instabilă și se asociază cu sincopa Stokes-Adams.","Cardiostimularea permanentă este indicată, deoarece reduce semnificativ mortalitatea.","Nu: atropina poate fi încercată în BAV recent cu QRS îngust și cauză tranzitorie; nu vindecă forma distală cronică.","Nu: boala Lev este o fibroză a sistemului de conducere la vârstnici; boala Lenègre apare la pacienți mai tineri."]],
 [8,"Atribuie scăpării largi frecvența hisiană 50-60 și inversează sediul Lev/Lenegre."],["15-40 b.p.m","Stokes-Adams"]),

q("cardiologie-adv-123",["Blocul de ramură dreaptă (BRD) față de cel stâng (BRS):",
 ["în BRD, unde S adânci în DI și V6","BRS: R tardiv în V6 și unde Q anormale","Z2: dedublare largă fiziologică în BRD, posibil inversată în BRS","în BRD lipsesc undele S din DI","BRS nu modifică Z2, iar BRD produce dedublare paradoxală"],"ABC",1056,"Bloc de ramură — ECG și zgomotul 2",
 "Opunerea vectorilor BRD/BRS și a dedublării fiziologice largi versus paradoxale.",
 ["În BRD activarea VD este tardivă, cu unde S adânci în DI și V6 și unde R ample tardive în V1.","BRS are modificări opuse (S adânc în V1, R amplu tardiv în DI și V6) și produce unde Q anormale.","BRD determină de regulă o dedublare largă, dar fiziologică, a zgomotului 2, iar BRS poate cauza dedublare inversată.","Nu: BRD întârzie activarea VD și produce unde S adânci în DI și V6.","Nu: relația este inversată; BRS poate da dedublare inversată (paradoxală), iar BRD dedublare largă fiziologică."]],
 [8,"Inversează dedublarea Z2 (fiziologică largă în BRD versus paradoxală în BRS)."],["dedublare distanţată","unde Q anormale"]),

q("cardiologie-adv-124",["Tahicardia sinusală inadecvată (IST) și tahicardia sinusală secundară:",
 ["IST: tahicardie de repaus persistentă, mai ales la femei tinere","cauze secundare acute: febră, durere, embolie pulmonară, hipovolemie","ivabradina se poate folosi dacă beta-blocantele nu sunt tolerate","IST, diagnostic de primă intenție la vârstnicul cu boală structurală","tratarea răspunsului compensator primează față de identificarea cauzei"],"ABC",1057,"TSV — Tahicardia sinusală inadecvată",
 "Recunoașterea terenului (femei tinere) și a ivabradinei ca alternativă, după tratarea cauzei secundare.",
 ["IST înseamnă creșterea persistentă a frecvenței de repaus, disproporționată față de stres, mai frecventă la femei tinere.","Cauzele acute ale tahicardiei sinusale secundare includ efortul, durerea, febra, infecțiile, ICA, embolia pulmonară și hipovolemia.","Ivabradina (blocant al curentului If) poate fi folosită când beta-blocantele nu sunt tolerate.","Nu: IST este mai frecventă la femei tinere și nu este diagnosticul de primă intenție la vârstnicul cu boală structurală.","Nu: identificarea și tratarea factorului declanșator sunt preferabile tratării răspunsului compensator."]],
 [8,"Pune IST pe bărbatul vârstnic structural și tratează compensarea înaintea cauzei."],["femeile tinere","ivabradina"]),

q("cardiologie-adv-125",["Cea mai frecventă tahicardie la pacienții peste 65 de ani este:",
 ["AVNRT (reintrare nodală)","fibrilația atrială (FA)","tahicardia atrială multifocală","tahicardia joncțională accelerată","AVRT (fascicul Kent)"],"B",1058,"TSV — Cadranul 30.14 (comentarii)",
 "Reținerea FA ca tahicardie dominantă peste 65 de ani, distinct de AVNRT a tânărului.",
 ["Nu: AVNRT este cea mai comună cauză de palpitații la cord normal, nu tahicardia dominantă după 65 de ani.","Fibrilația atrială este cea mai frecventă tahicardie la pacienții peste 65 de ani.","Nu: tahicardia atrială multifocală este rară și se asociază cu BPOC semnificativă.","Nu: tahicardia joncțională accelerată este rară la adulți.","Nu: AVRT se datorează unei căi accesorii și nu este aritmia dominantă a vârstnicului."]],
 [8,"Atribuie vârstnicului AVNRT-ul tânărului cu cord normal, deși tabelul rezervă FA categoriei >65 ani."],[">65 ani","Fibrilaţia atrială"]),

q("cardiologie-adv-126",["AVNRT atipică și alte tahicardii supraventriculare:",
 ["AVNRT „fast-slow” (AP' lung) reprezintă 5-10% din cazuri","tahicardia atrială multifocală apare mai ales în BPOC","flutterul este exclus la o TSV regulată cu 150/min","AVNRT, cauza principală de palpitații la cord normal","tahicardia joncțională accelerată, cea mai frecventă TSV la adult"],"ABD",1058,"TSV — AVNRT fast-slow și MAT",
 "Memorarea ponderii 5-10% a formei fast-slow și a asocierii MAT–BPOC.",
 ["În 5-10% din cazuri AVNRT este „fast-slow” (anterograd pe calea rapidă, retrograd pe cea lentă), cu interval AP' lung.","Tahicardia atrială multifocală are unde P cu cel puțin 3 morfologii și RR neregulate, cel mai frecvent în BPOC semnificativă.","Nu: la o TSV regulată cu 150/min trebuie luat în considerare flutterul atrial.","AVNRT este cea mai comună cauză de palpitații la pacienții cu cord normal.","Nu: tahicardia joncțională accelerată este rară la adulți."]],
 [8,"Omite flutterul de la 150/min — capcana clasică de TSV regulată — și umflă raritatea joncționalei."],["5-10%","fast-slow"]),

q("cardiologie-adv-127",["În AVNRT și AVRT:",
 ["palpitații cu debut și final brusc, oprite adesea prin Valsalva","poliurie prin eliberare de peptid natriuretic atrial","verapamil i.v. imediat după beta-blocant, chiar cu QRS larg","adenozina nu influențează aceste TSV, fiind rezervată TV","pulsații venoase jugulare proeminente în AVNRT"],"ABE",1059,"AVNRT/AVRT — Tablou clinic",
 "Reunirea Valsalvei, a poliuriei prin ANP și a pulsațiilor jugulare din AVNRT.",
 ["Palpitațiile sunt regulate, cu debut și final brusc, și sunt adesea terminate prin manevra Valsalva.","Poliuria prin eliberare de peptid natriuretic atrial apare mai ales în AVNRT și în fibrilația atrială.","Nu: verapamilul nu se administrează după beta-blocante și nici la QRS larg.","Nu: adenozina este foarte eficientă în AVNRT/AVRT și influențează rar TV.","În AVNRT apar pulsații venoase jugulare proeminente, prin contracția atriilor pe valve AV închise."]],
 [8,"Interzice adenozina (tocmai agentul de elecție) și asociază verapamilul cu beta-blocantul la QRS larg."],["peptid natriuretic atrial","Valsalva"]),

q("cardiologie-adv-128",["Tratamentul acut al AVNRT/AVRT:",
 ["cardioversie de urgență la instabilitate (hipotensiune, edem pulmonar)","manevre vagale: masaj carotidian, Valsalva, imersia feței în apă rece","digoxin i.v., antiaritmicul de elecție în WPW cu QRS larg","verapamil i.v. imediat după beta-blocant, la QRS >0,12 sec","diferențierea AVNRT de AVRT înaintea tratamentului, care diferă radical"],"AB",1059,"AVNRT/AVRT — Tratament acut",
 "Prioritatea cardioversiei la instabil și a manevrelor vagale la stabil, înaintea adenozinei.",
 ["Instabilitatea hemodinamică (hipotensiune, edem pulmonar) impune cardioversie de urgență.","Masajul carotidian, manevra Valsalva și imersia feței în apă rece pot opri criza.","Nu: digoxinul, ca și verapamilul, poate accelera conducerea pe calea accesorie în FA preexcitată.","Nu: verapamilul nu se dă după beta-blocante și nici la QRS larg.","Nu: diferențierea AVNRT/AVRT nu este esențială în acut, ambele răspunzând la același tratament."]],
 [8,"Cere diferențierea AVNRT/AVRT înaintea manevrelor, deși textul spune că tratamentul acut este comun."],["cardioversie de urgenţă","imersia feţei"]),

q("cardiologie-adv-129",["În fibrilația atrială:",
 ["activare atrială 300-600/min, adesea din venele pulmonare","circa 30% din cazuri sunt descoperiri incidentale","frecvența ventriculară netratată este de obicei 120-180/min","pulsul rămâne neregulat la efort, spre deosebire de extrasistole","aritmia este definită de unde P înalte și regulate"],"ABCD",1060,"Fibrilația atrială — Mecanism și tablou",
 "Aplicarea ferestrelor 300-600/min atrial, 120-180 ventricular netratat și a ponderii 30% incidente.",
 ["Activarea atrială este continuă și rapidă (300-600/min), adesea din focare situate la venele pulmonare.","La circa 30% dintre pacienți fibrilația atrială este o descoperire incidentală.","Fără tratament, frecvența ventriculară este de obicei 120-180/min.","Neregularitatea pulsului persistă la efort, spre deosebire de extrasistole sau de Wenckebach.","Nu: fibrilația atrială se caracterizează prin absența undelor P și oscilații fine ale liniei de bază."]],
 [8,"Pune unde P regulate pe FA — tocmai aritmia definită prin absența lor."],["300-600 b.p.m.","120-180 b.p.m"]),

q("cardiologie-adv-130",["Controlul frecvenței ca strategie primară în fibrilația atrială:",
 ["combină în general digoxin, beta-blocante sau verapamil/diltiazem","digoxinul în monoterapie poate fi suficient la vârstnicii inactivi","la vârstnicii slab controlați, „ablate and pace”, cu anticoagulare continuă","urmărește la tineri o frecvență de repaus sub 50/min, fără Holter","ablația nodului AV permite oprirea anticoagulării, riscul trombotic dispărând"],"ABC",1061,"Fibrilația atrială — Controlul frecvenței și „ablate and pace”",
 "Recunoașterea combinației digoxin/BB/non-DHP și a strategiei ablate-and-pace cu anticoagulare pe viață.",
 ["Controlul frecvenței se obține în general prin combinații de digoxin, beta-blocante sau non-dihidropiridinice (verapamil, diltiazem).","La vârstnicii inactivi digoxinul în monoterapie poate fi suficient; la tineri efectul vagotonic este anulat de catecolamine.","La vârstnicii cu control slab sub terapie optimă se poate abla nodul AV cu implantarea unui stimulator („ablate and pace”), cu anticoagulare continuă.","Nu: țintele citate sunt <110/min în repaus, apoi 60-80/min și <110/min la efort dacă simptomele persistă; tinerii au nevoie de Holter și test de efort.","Nu: riscul tromboembolic persistă după ablația nodului AV, deci anticoagularea continuă."]],
 [8,"Oprește anticoagularea după „ablate and pace”, deși textul o menține din cauza riscului trombotic persistent."],["ablate and pace","Digoxinul în monoterapie"]),

q("cardiologie-adv-131",["Complicațiile majore ale ablației FA (AVC, sângerări) apar în circa:",
 ["20%","10%","2%","0,01%","0,2%"],"C",1061,"Fibrilația atrială — Riscurile ablației",
 "Reținerea ordinii de mărime 2% pentru AVC și sângerări post-ablație.",
 ["Nu: AVC și sângerările complică ablația în circa 2% din cazuri; 20% este cu un ordin de mărime peste.","Nu: complicațiile majore apar în circa 2% din cazuri, nu în 10%.","AVC și sângerările apar după ablația fibrilației atriale în aproximativ 2% din cazuri.","Nu: 0,01% subestimează riscul, care este de circa 2%.","Nu: riscul de AVC și sângerări este de circa 2%, nu 0,2%."]],
 [8,"Umflă complicațiile ablației de la 2% la 20-50%, ordine de mărime alăturate dar false."],["2% din cazuri","vene pulmonare"]),

q("cardiologie-adv-132",["Anticoagularea orală în fibrilația atrială non-valvulară:",
 ["warfarină cu INR 2,0-3,0 sau un DOAC","DOAC: acțiune mai rapidă, înjumătățire mai scurtă, fără monitorizare INR","antiagregantele sunt alternativa recomandată pentru prevenția AVC","la contraindicație se poate închide percutan urechiușa atrială stângă","antiagregantele nu sunt recomandate pentru prevenția AVC"],"ABDE",1062,"Fibrilația atrială — DOAC, warfarină și LAAO",
 "Contrastul cascadei DOAC versus warfarină și respingerea antiagregantelor ca substitut de prevenție a AVC.",
 ["Se folosește warfarina cu INR 2,0-3,0 sau un DOAC: dabigatran (inhibitor direct de trombină) ori rivaroxaban/apixaban (anti-Xa).","Față de warfarină, DOAC au acțiune mai rapidă, timp de înjumătățire mai scurt, mai puține interacțiuni și nu necesită monitorizarea INR.","Nu: antiagregantele plachetare nu sunt recomandate pentru prevenția AVC în fibrilația atrială.","La contraindicația sau intoleranța anticoagulării se poate considera închiderea percutană a urechiușei atriale stângi.","Antiagregantele plachetare nu sunt recomandate pentru prevenția AVC în fibrilația atrială."]],
 [8,"Pune antiagregantul în locul anticoagulării — strategie pe care textul o respinge explicit."],["INR de 2,0-3,0","urechiuşei atriale stângi"]),

q("cardiologie-adv-133",["La un scor CHA2DS2-VASc de 0 puncte, riscul anual de AVC ischemic este:",
 ["2,2%, cu anticoagulare orală imediată","0%, fără indicație de profilaxie","5%, ca la un HAS-BLED ≥3","1,3%, ca la scorul de 1 punct","35,9%, ca în TIMI STEMI 9-16"],"B",1062,"Fibrilația atrială — CHA2DS2-VASc 0 puncte",
 "Reținerea perechii 0 puncte = 0% risc, fără profilaxie.",
 ["Nu: 2,2% corespunde unui scor de 2 puncte; la 0 puncte riscul este 0%.","Scorul CHA2DS2-VASc de 0 puncte corespunde unui risc de 0%, fără profilaxie.","Nu: >5% este riscul hemoragic la HAS-BLED ≥3, nu riscul de AVC la CHA2DS2-VASc 0.","Nu: 1,3% corespunde scorului de 1 punct.","Nu: 35,9% aparține scorului TIMI pentru STEMI, nu scorului CHA2DS2-VASc."]],
 [8,"Confundă 0% de la 0 puncte cu 2,2% (2+ puncte) sau cu HAS-BLED hemoragic."],["0% risc","Fără profilaxie"]),

q("cardiologie-adv-134",["În flutterul atrial:",
 ["antiorar: F negative inferior, pozitive în V1-V2","orar: orientarea undelor F este inversată","conducere 2:1 cu frecvență ventriculară de 300/min","antiorar: F pozitive inferior, negative în V1","masajul carotidian nu poate demasca undele F"],"AB",1062,"Flutter atrial — Antiorar, orar și 1:1",
 "Opunerea polarității F antiorar/orar și recunoașterea răspunsului 1:1 la 300/min.",
 ["În flutterul antiorar, undele F sunt negative în derivațiile inferioare și pozitive în V1-V2.","În flutterul orar, orientarea undelor F este inversă față de forma antiorară.","Nu: frecvența ventriculară de 300/min corespunde conducerii 1:1 a undelor F.","Nu: undele F pozitive inferior și negative în V1 caracterizează flutterul orar, nu pe cel antiorar.","Nu: masajul sinusului carotidian, adenozina sau verapamilul pot demasca undele F."]],
 [8,"Inversează polaritatea F antiorar/orar și neagă manevra de demascare a flutterului."],["flutter antiorar","300 b.p.m."]),

q("cardiologie-adv-135",["Tahicardia atrială prin automatism crescut:",
 ["are 125-250/min și adesea fenomene de „warm-up” și „cool-down”","pornește mai ales din crista terminalis, vene pulmonare sau urechiușe","se oprește prin masajul sinusului carotidian, ca AVNRT","poate fi incesantă, ducând la cardiomiopatie tahiaritmică","este mai lentă decât forma prin reintrare (125-150/min)"],"ABD",1063,"Tahicardia atrială — Automatism",
 "Contrastul 125-250/min cu warm-up față de forma prin reintrare mai lentă și a riscului de cardiomiopatie.",
 ["Frecvența este de 125-250/min, adesea cu fenomene de „warm-up” și „cool-down”.","Focarul este cel mai frecvent pe crista terminalis, lângă o venă pulmonară sau în jurul unei urechiușe.","Nu: masajul carotidian crește gradul de bloc AV și ajută diagnosticul, dar nu oprește tahicardia.","Forma incesantă poate duce la cardiomiopatie tahiaritmică.","Nu: forma prin reintrare este de obicei mai lentă (125-150/min), nu cea prin automatism."]],
 [8,"Oprește tahicardia atrială cu masaj carotidian — manevră care doar crește BAV-ul — și inversează vitezele automatism/reintrare."],["warm-up","cristei terminalis"]),

q("cardiologie-adv-136",["Dintre tahicardiile cu complexe QRS largi, sunt ventriculare circa:",
 ["80%, și mai mult la boala cardiacă structurală","5%, restul fiind TSV cu aberanță","50% fără boală structurală și 10% cu boală structurală","sub 1%, dacă QRS depășește 0,14 sec","20%, mai ales la pacienții fără boală structurală"],"A",1063,"TV versus TSV cu aberanță — Ponderea 80%",
 "Reținerea regulii 80% (și mai mult la boală structurală) în fața unei tahicardii cu QRS larg.",
 ["Circa 80% din tahicardiile cu complexe largi sunt ventriculare, proporția fiind și mai mare la boala cardiacă structurală.","Nu: 5% subestimează net; circa 80% sunt ventriculare.","Nu: proporția este de circa 80% și crește, nu scade, la boala structurală.","Nu: un QRS peste 0,14 sec orientează spre TV, nu o face rară.","Nu: circa 80% sunt ventriculare, proporția fiind mai mare la boala structurală."]],
 [8,"Subestimează ponderea TV în tahicardia cu QRS larg, deși textul o plasează la 80%."],["80%","complexe largi"]),

q("cardiologie-adv-137",["Fibrilația ventriculară și infarctul miocardic acut:",
 ["FV precoce (1-2 zile post-IMA) nu necesită de obicei profilaxie","FV neasociată unui IMA are risc mare de moarte subită tardivă","ICD de primă linie la supraviețuitorii fără cauză reversibilă","FV din primele 24 de ore post-IMA impune ICD la externare","cauzele reversibile nu modifică indicația de ICD"],"ABC",1064,"Fibrilația ventriculară — Fereastra peri-infarct",
 "Aplicarea ferestrei 1-2 zile: FV precoce post-IMA fără profilaxie versus FV fără cauză reversibilă cu ICD.",
 ["FV apărută în primele 1-2 zile post-IMA nu necesită, de obicei, terapie profilactică.","Când episodul nu este legat de un IMA, riscul pe termen lung de stop cardiac și moarte subită este mare.","La supraviețuitorii fără cauză reversibilă, ICD este tratamentul de primă linie.","Nu: FV din primele 1-2 zile post-IMA nu impune de la sine ICD.","Nu: prezența unei cauze reversibile (IMA, tulburări metabolice severe) schimbă strategia, inclusiv indicația de ICD."]],
 [8,"Implantează ICD pentru FV-ul precoce post-IMA, tocmai scenariul în care textul nu cere profilaxie."],["1-2 zile","Defibrilatoarele implantabile"]),

q("cardiologie-adv-138",["În sindromul Brugada:",
 ["20% din cazuri: mutație SCN5A cu câștig de funcție","implică și SCN5B, GPD1L, CACNA1C și CACNB2","beta-blocantele sunt tratamentul de elecție și reduc mortalitatea","predomină la femeile vârstnice din Europa de Nord","poate debuta prin moarte subită în somn sau sincopă"],"BE",1064,"Sindromul Brugada — Gene și prezentare",
 "Reținerea ponderii 20% SCN5A cu pierdere de funcție și a prezentării nocturne, față de ineficiența beta-blocantelor.",
 ["Nu: în 20% din cazuri, mutația SCN5A determină pierderea funcției canalelor de sodiu.","Au fost implicate și SCN5B, GPD1L și subunități ale canalelor de calciu (CACNA1C, CACNB2).","Nu: beta-blocantele nu sunt utile și pot fi chiar nocive; tratamentul eficient este ICD.","Nu: sindromul predomină la bărbații tineri din Asia de Sud-Est.","Prezentarea poate fi moarte subită în somn, stop resuscitat, sincopă sau descoperire incidentală ori familială."]],
 [8,"Păstrează beta-blocantul ca elecție — agent pe care textul îl consideră inutil sau nociv — și inversează epidemiologia."],["20% din cazuri","SCN5A"]),

q("cardiologie-adv-139",["În sindromul QT lung congenital:",
 ["beta-blocante, uneori stimulator sau denervare simpatică stângă","LQT1 răspunde mai bine la blocantele de sodiu, LQT3 la beta-blocante","isoprenalina i.v. este prima linie și în forma congenitală","ICD de obicei dacă rămân simptomatici, cu QT marcat și MSC familială","între crize, QTc depășește de obicei 0,50 sec"],"ADE",1065,"QT lung congenital — Tratament de durată",
 "Potrivirea LQT1–beta-blocant versus LQT3–blocant de Na+ și a pragului QTc >0,50 sec.",
 ["Tratamentul de durată folosește beta-blocante, uneori stimulator și uneori denervare simpatică cardiacă stângă.","Nu: LQT1 răspunde bine la beta-blocante, iar LQT3 mai bine la blocantele canalelor de sodiu.","Nu: isoprenalina este contraindicată în forma congenitală; este utilă în forma dobândită.","Pacienții care rămân simptomatici, cu QT marcat și istoric familial de moarte subită, necesită de obicei ICD.","Între episoade, QTc măsoară de obicei peste 0,50 sec."]],
 [8,"Folosește isoprenalina — utilă în QT dobândit — ca primă linie în forma congenitală, unde este contraindicată."],["0,50 sec","denervare simpatică"]),

q("cardiologie-adv-140",["Sindromul QT scurt și extrasistolele ventriculare:",
 ["QT scurt: 2 tipuri, fără risc de moarte subită","QT scurt: 5 tipuri, risc de moarte subită, ICD optim","fenomenul R pe T poate precipita FV, mai ales post-infarct","ESV post-infarct se tratează de rutină cu clasa Ic","ESV nu sunt urmate de pauză compensatorie"],"BC",1066,"QT scurt și extrasistole ventriculare",
 "Reținerea celor 5 tipuri de QT scurt cu indicație de ICD și a riscului R-pe-T post-IMA.",
 ["Nu: sunt descrise 5 tipuri de QT scurt, care pot predispune la aritmii ventriculare și moarte subită.","Sunt descrise 5 tipuri de QT scurt, care pot predispune la aritmii ventriculare și moarte subită; ICD este tratamentul optim.","Fenomenul R pe T poate precipita fibrilația ventriculară, mai ales după infarct.","Nu: ESV se tratează doar dacă sunt simptomatice; clasa I post-IMA a crescut mortalitatea în CAST.","Nu: după o ESV urmează de obicei o pauză compensatorie completă."]],
 [8,"Reduce QT scurt la o raritate benignă și tratează ESV post-IMA cu clasa Ic, strategia CAST nocivă."],["5 tipuri","R pe T"]),

q("cardiologie-adv-141",["Antiaritmicele de clasă I (blocante ale canalelor de sodiu):",
 ["reduc influxul de sodiu și pot încetini conducerea","în trialurile CAST, clasa Ic a redus mortalitatea post-infarct","se evită în boala coronariană, disfuncția VS sau boala structurală semnificativă","clasa Ib (lidocaină, mexiletină) scurtează potențialul de acțiune","clasa Ic prelungește potențialul de acțiune, la fel ca Ia"],"ACD",1067,"Antiaritmice — Clasa I și CAST",
 "Aplicarea lecției CAST: clasa I se evită pe cord ischemic/structural; Ib scurtează PA, Ic nu-l afectează.",
 ["Clasa I reduce influxul de sodiu și poate încetini conducerea, prelungi repolarizarea și reduce automatismul.","Nu: în trialurile CAST, clasa Ic a crescut mortalitatea la pacienții cu extrasistole ventriculare post-IMA.","Utilizarea clasei I, inclusiv a flecainidei, se limitează la pacienții fără boală coronariană, disfuncție VS sau altă boală structurală semnificativă.","Clasa Ib (lidocaina, mexiletina) scurtează potențialul de acțiune.","Nu: clasa Ic nu afectează durata potențialului de acțiune."]],
 [8,"Atribuie clasei Ic prelungirea de PA a Ia, deși tabelul o lasă fără efect pe durata PA."],["trialurile CAST","canalelor de sodiu"]),

q("cardiologie-adv-142",["Mecanismul principal al antiaritmicelor de clasă III este:",
 ["blocarea influxului de sodiu, ca la clasa I","antagonismul beta pur, fără efect pe canalele de potasiu","blocarea IKr, cu prelungirea potențialului de acțiune","scurtarea fazei de platou, la fel ca verapamilul","activarea (agonismul) canalelor de calciu"],"C",1067,"Antiaritmice — Clasa III (IKr)",
 "Reținerea blocadei IKr fără efect pe sodiu ca mecanism de clasă III.",
 ["Nu: blocarea influxului de sodiu este mecanismul clasei I.","Nu: sotalolul are și efect beta-blocant, dar clasa III nu se reduce la antagonism beta pur.","Clasa III prelungește potențialul de acțiune prin blocarea componentei rapide a curentului de potasiu (IKr), fără a afecta transportul de sodiu.","Nu: scurtarea fazei de platou este mecanismul clasei IV.","Nu: agonismul pe canalele de calciu nu este mecanismul clasei III."]],
 [8,"Reduce clasa III la un beta-blocant pur sau o confundă cu clasa I/IV, deși nucleul este IKr."],["curentului de potasiu","sotalolul"]),

q("cardiologie-adv-143",["Căile accesorii și ablația prin cateter:",
 ["ablația AVNRT și a căilor accesorii reușește în peste 95%","căile doar retrograde nu cresc riscul de MSC","ablația profilactică se recomandă la asimptomaticii cu ECG de WPW","la căile stângi, riscul principal este blocul de ramură","TV pe cord normal are risc crescut de MSC"],"ABC",1068,"Ablație — WPW simptomatic, ascuns și profilactic",
 "Contrastul căii doar retrograde (fără MSC) versus recomandarea profilactică la ECG WPW și succesul >95%.",
 ["Rata de succes a ablației în AVNRT și pe căile accesorii depășește 95%.","Căile care conduc doar retrograd nu au risc crescut de moarte subită, dar pot produce AVRT.","Ablația profilactică a căii accesorii se recomandă la asimptomaticii cu traseu ECG sugestiv de WPW.","Nu: la ablația căilor stângi, riscul principal este tromboembolismul.","Nu: TV pe cord structural normal nu are risc crescut de moarte subită și se tratează ușor prin ablație."]],
 [8,"Neagă indicația profilactică la WPW-ul ECG și înlocuiește tromboembolismul căii stângi cu un BRD inofensiv."],["mai mare de 95%","pre-excitaţie"]),

q("cardiologie-adv-144",["ICD în prevenția secundară a tahiaritmiilor ventriculare:",
 ["a îmbunătățit supraviețuirea în trialul AVID","are baterie de litiu pentru circa 100 de șocuri de 30 J","livrează șocuri nedureroase la pacientul conștient","reduce moartea subită la 40% pe an","nu poate avea și o sondă în atriul drept"],"AB",1068,"ICD — AVID, energie și durere",
 "Reținerea AVID, a celor 100 de șocuri de 30 J și a caracterului dureros al șocului la conștient.",
 ["Trialul AVID (antiaritmice versus ICD) a demonstrat un beneficiu de supraviețuire al ICD.","Bateria de litiu asigură circa 100 de șocuri de 30 J.","Nu: șocurile sunt dureroase la pacientul conștient; stimularea overdrive este nedureroasă.","Nu: rata morții subite scade la circa 2% pe an; 40% este mortalitatea în primul an fără o strategie adecvată.","Nu: dispozitivele moderne pot avea sonde atât în AD, cât și în VD."]],
 [8,"Umflă MSC sub ICD de la 2% la 40% pe an — tocmai mortalitatea netratată din primul an."],["100 şocuri","30 J"]),

q("cardiologie-adv-145",["Insuficiența cardiacă — epidemiologie și cauze:",
 ["este cauza principală de spitalizare după 65 de ani","costă anual peste 1 miliard de lire în Marea Britanie","poate fi cauzată de trastuzumab, tireotoxicoză sau boli pericardice","are, în Occident, drept cauză dominantă boala reumatică","are în prezent o mortalitate la 5 ani sub 5%"],"ABC",1069,"Insuficiența cardiacă — Spitalizări, cost și cauze rare",
 "Completarea epidemiologiei cu spitalizarea post-65 de ani, costul >1 miliard și etiologiile chimioterapice/hiperdinamice.",
 ["Insuficiența cardiacă este cauza principală de spitalizare după vârsta de 65 de ani.","Costul managementului insuficienței cardiace în Marea Britanie depășește 1 miliard de lire sterline pe an.","Printre cauzele „alte” se numără trastuzumab/imatinib, circulația hiperdinamică (anemie, tireotoxicoză, Paget) și bolile pericardice.","Nu: în țările occidentale cauza cea mai frecventă este boala coronariană.","Nu: prognosticul s-a îmbunătățit, dar mortalitatea la 5 ani rămâne de circa 50%, nu sub 5%."]],
 [8,"Repune reumatismul ca etiologie occidentală dominantă și comprimă mortalitatea la 5 ani de la 50% la 5%."],["1 miliard","trastuzumab"]),

q("cardiologie-adv-146",["Adaptările hemodinamice în insuficiența cardiacă:",
 ["redistribuția sângelui menține perfuzia inimii, creierului și rinichilor","creșterea postsarcinii crește debitul și scade volumul telediastolic","activarea simpatică cronică nu produce down-regulation a receptorilor β","în forma foarte severă, debitul scade și în repaus","în disfuncția ușoară, creșterea presiunii venoase poate menține debitul de repaus"],"ADE",1070,"Insuficiența cardiacă — Redistribuție și postsarcină",
 "Recunoașterea redistribuției spre organele vitale și a menținerii debitului de repaus prin presiune venoasă în disfuncția ușoară.",
 ["Redistribuția sângelui menține perfuzia inimii, creierului și rinichilor, în detrimentul tegumentelor și mușchilor.","Nu: postsarcina crescută scade debitul și crește volumul telediastolic, dilatând VS și mărind și mai mult postsarcina.","Nu: activarea simpatică cronică este nocivă (neurohormoni, apoptoză) și este compensată prin down-regulation a receptorilor β.","În insuficiența cardiacă foarte severă debitul scade și în repaus, deși presiunile venoase sunt mari.","În disfuncția ușoară, debitul de repaus se poate menține prin creșterea presiunii venoase."]],
 [8,"Prezintă hiperpostsarcina ca un mecanism care crește debitul, inversând cercul vicios Laplace."],["inimii, creierului şi rinichilor","tegumentelor şi muşchilor"]),

q("cardiologie-adv-147",["Endoteliul și hormonul antidiuretic în insuficiența cardiacă:",
 ["vasodilatația endotelială afectată poate contribui la intoleranța la efort","endotelina plasmatică crescută se corelează cu severitatea hemodinamică","hiponatremia prin ADH crescut are prognostic nefavorabil","oxidul nitric este în exces și explică vasodilatația de efort","peptidul natriuretic de tip C este secretat mai ales de ventriculi"],"ABC",1071,"Insuficiența cardiacă — Endotelină și ADH",
 "Legarea disfuncției endoteliale și a ET crescute de hiponatremia prin ADH ca marker nefavorabil.",
 ["Vasodilatația dependentă de endoteliu este afectată în vasele periferice și poate contribui la scăderea toleranței la efort.","Endotelina plasmatică este crescută și se corelează cu severitatea hemodinamică; antagoniștii i.v. ameliorează acut hemodinamica.","ADH crește în IC cronică severă, mai ales sub diuretice, iar hiponatremia precipitată este un indicator prognostic nefavorabil.","Nu: activitatea oxidului nitric este insuficientă, nu în exces.","Nu: CNP este limitat la endoteliu și SNC; peptidul de origine ventriculară este BNP."]],
 [8,"Pune NO-ul — descris ca insuficient — în exces și mută CNP-ul în ventricul."],["endotelina","Hormonul antidiuretic"]),

q("cardiologie-adv-148",["Investigațiile în insuficiența cardiacă:",
 ["radiografia nu evaluează liniile Kerley B sau redistribuția vasculară","ecocardiografia cu dobutamină arată rezerva contractilă (siderat, hibernant)","biopsia endomiocardică este de primă linie în HFpEF","IRM-ul evaluează viabilitatea prin dobutamină sau gadoliniu tardiv","cateterismul nu poate măsura presiunea capilară pulmonară blocată"],"BD",1072,"Insuficiența cardiacă — Investigații (eco de stres, IRM)",
 "Rolul dobutaminei pentru rezerva contractilă și al IRM cu gadoliniu tardiv ca „imagistică de infarct”.",
 ["Nu: radiografia evaluează cardiomegalia, redistribuția spre lobii superiori, scizurile, liniile Kerley B și edemul.","Ecocardiografia de stres cu dobutamină identifică rezerva contractilă a miocardului siderat sau hibernant.","Nu: biopsia endomiocardică se folosește în amiloidoză și în rejetul de grefă, nu ca screening în HFpEF.","IRM evaluează structura, funcția și viabilitatea, cu dobutamină sau cu gadoliniu tardiv („imagistica de infarct”).","Nu: cateterismul măsoară presiunea în artera pulmonară, presiunea capilară blocată (atrială stângă) și PTDVS."]],
 [8,"Anulează liniile Kerley B — semn radiologic clasic de IC — și promovează biopsia ca screening HFpEF."],["Kerley B","imagistica de infarct"]),

q("cardiologie-adv-149",["În insuficiența cardiacă cronică se recomandă:",
 ["restricție de sare și, în forma severă, de lichide","exerciții de anduranță de nivel scăzut, fără efort izometric intens","vaccinarea antipneumococică și antigripală","interdicția de a conduce autobuze la FEVS <40% (Marea Britanie)","asocierea de rutină a nitraților cu sildenafil"],"ABCD",1073,"Insuficiența cardiacă — Stil de viață, vaccin și condus",
 "Aplicarea ferestrelor de antrenament, a vaccinării și a pragului FEVS <40% pentru vehicule grele.",
 ["Se recomandă restricția de sare, iar în forma severă reducerea aportului de lichide și cântărirea zilnică.","Se recomandă exerciții de anduranță de nivel scăzut (de exemplu 20-30 min de mers de 3-5 ori pe săptămână); efortul izometric intens se evită.","Vaccinarea împotriva infecției pneumococice și a gripei este recomandată.","În Marea Britanie, pacienții cu IC simptomatică sau FEVS <40% nu au voie să conducă camioane mari și autobuze.","Nu: asocierea nitraților cu inhibitori de PDE5 (sildenafil) poate induce hipotensiune severă."]],
 [8,"Asociază nitrații cu sildenafil — combinație pe care textul o interzice din cauza hipotensiunii."],["20-30 min","FEVS mai mică de 40%"]),

q("cardiologie-adv-150",["În insuficiența cardiacă, VO2 maxim la testul de efort cardiopulmonar este:",
 ["lipsit de valoare prognostică","predictiv pentru mortalitate, dar nu și pentru spitalizări","fără alternativă, testul de mers de 6 minute neavând rol în IC","un criteriu pentru oprirea diureticelor","predictiv pentru spitalizări și mortalitate"],"E",1073,"Insuficiența cardiacă — VO2 și testul de 6 minute",
 "Reținerea valorii prognostice a VO2 și a testului de 6 minute ca alternativă.",
 ["Nu: VO2 maxim are valoare predictivă pentru spitalizări și mortalitate.","Nu: VO2 maxim este predictiv atât pentru spitalizări, cât și pentru mortalitate.","Nu: testul de mers de 6 minute este o alternativă la testul de efort cardiopulmonar.","Nu: VO2 maxim nu ghidează oprirea diureticelor.","VO2 maxim este predictiv pentru spitalizări și mortalitate, testul de mers de 6 minute fiind o alternativă."]],
 [8,"Neagă valoarea prognostică a VO2, deși textul o leagă explicit de spitalizări și mortalitate."],["V02","6 minute"]),

q("cardiologie-adv-151",["Dozele și precauțiile în tratamentul insuficienței cardiace:",
 ["ramipril 1,25-2,5 mg/zi inițial, cu prudență la creatinină >250 µmol/L","sacubitril/valsartan: IECA se opresc cu 3 zile înainte","bisoprolol 1,25-10 mg/zi, de evitat în IC acută nestabilizată","digoxin peste 2,5 mg/zi de rutină la eRFG <30 ml/min/1,73 m²","metolazona este interzisă în insuficiența cardiacă severă"],"ABC",1074,"Insuficiența cardiacă — Cadranul 30.25 (doze)",
 "Aplicarea treptelor ramipril/bisoprolol, a ferestrei de 3 zile IECA→ARNI și a pragului de creatinină 250 µmol/L.",
 ["Ramiprilul se începe cu 1,25-2,5 mg/zi (maximum 10 mg/zi), cu prudență dacă creatinina >250 µmol/L sau TAS <90 mmHg.","Înaintea sacubitril/valsartanului, IECA se opresc cu 3 zile înainte, iar ARA în ziua administrării.","Bisoprololul se crește de la 1,25 mg la 10 mg/zi și se evită în IC acută până la stabilizarea cardiovasculară.","Nu: dozele de digoxin peste 2,5 mg/zi sunt rar necesare, iar eficiența scade la eRFG <30 ml/min/1,73 m².","Nu: metolazona se folosește în insuficiența cardiacă severă."]],
 [8,"Crește digoxinul peste 2,5 mg tocmai la eRFG <30, unde tabelul cere prudență și doze mici."],["3 zile înainte","250 µmol/L"]),

q("cardiologie-adv-152",["Nebivololul, în insuficiența cardiacă, se utilizează:",
 ["în forma stabilă, ușoară sau moderată, peste 70 de ani","ca substitut al diureticelor de ansă la tineri","în NYHA IV refractar, ca alternativă la transplant","intravenos, ca inotrop de primă linie în FA rapidă","sub 70 de ani, fiind contraindicat peste această vârstă"],"A",1074,"Insuficiența cardiacă — Nebivolol",
 "Reținerea nișei nebivololului: IC stabilă ușoară/moderată la >70 de ani.",
 ["Nebivololul se folosește în insuficiența cardiacă stabilă, ușoară sau moderată, la pacienții peste 70 de ani.","Nu: nebivololul nu înlocuiește diureticele de ansă.","Nu: nebivololul nu este o alternativă la transplant în clasa NYHA IV.","Nu: nebivololul nu este un inotrop intravenos pentru fibrilația atrială.","Nu: indicația citată este tocmai la pacienții peste 70 de ani, nu o contraindicație."]],
 [8,"Inversează nișa de vârstă: din indicație la >70 de ani în contraindicație."],["peste 70 de ani","Nebivololul"]),

q("cardiologie-adv-153",["Miocardul hibernant și miocardul siderat:",
 ["hibernantul are disfuncție reversibilă prin boală coronariană cronică","sideratul rămâne disfuncțional după ischemie, deși fluxul s-a normalizat","hibernarea este consecința necrozei transmurale ireversibile","hibernarea rezultă din episoade repetate de siderare","sideratul contraindică revascularizarea, fiind echivalent cicatricii"],"ABD",1075,"Miocard hibernant versus siderat",
 "Contrastul hipoperfuziei cronice viabile (hibernant) versus mismatch-ul post-ischemic cu flux restabilit (siderat).",
 ["Miocardul hibernant are disfuncție reversibilă prin boală coronariană cronică, este viabil la stres inotrop și se recuperează după revascularizare.","Miocardul siderat are o disfuncție reversibilă care persistă după un episod de ischemie, deși fluxul a revenit la normal (mismatch flux-funcție).","Nu: necroza (cicatricea) nu se recuperează; miocardul hibernant este viabil și răspunde la revascularizare.","Hibernarea rezultă din episoade repetate de siderare, de exemplu la efort repetat.","Nu: atât miocardul siderat, cât și cel hibernant justifică revascularizarea, spre deosebire de cicatrice."]],
 [8,"Echivalează hibernarea cu necroza ireversibilă, inversând tocmai rațiunea revascularizării."],["Miocardul siderat","mismatch"]),

q("cardiologie-adv-154",["La pacientul cu angină și disfuncție de ventricul stâng:",
 ["revascularizarea chirurgicală are mortalitate perioperatorie sub 0,1%","mortalitate chirurgicală 10-20%, dar câștig ulterior maxim","decizia ține cont de simptome, vârstă, comorbidități și ischemie reversibilă","rolul revascularizării în insuficiența cardiacă este clarificat","inotropele i.v. scad mortalitatea pe termen lung față de placebo"],"BC",1075,"Insuficiența cardiacă — Revascularizare la disfuncție de VS",
 "Reținerea paradoxului 10-20% mortalitate chirurgicală versus cel mai mare câștig ulterior.",
 ["Nu: mortalitatea chirurgicală este de 10-20%; 0,1% subestimează net riscul.","Revascularizarea chirurgicală are o mortalitate de 10-20%, dar acești pacienți au cel mai mult de câștigat ulterior (simptome și prognostic).","Decizia de revascularizare ține cont de simptome, vârstă, comorbidități și de dovada ischemiei reversibile.","Nu: rolul revascularizării în insuficiența cardiacă nu este clarificat.","Nu: inotropele ameliorează hemodinamica, dar nu s-a dovedit că scad mortalitatea pe termen lung."]],
 [8,"Comprimă mortalitatea chirurgicală de la 10-20% la 0,1% și atribuie inotropelor un beneficiu de supraviețuire nedovedit."],["10-20%","Miocardul „hibernant"]),

q("cardiologie-adv-155",["Insuficiența cardiacă terminală — transplant și dispozitive:",
 ["după transplant, infecțiile oportuniste apar în lunile 2-6","vasculopatia de alogrefă: 30-50% din pacienți la 5 ani","contraindicații la transplant: cancer activ, rezistență vasculară pulmonară crescută","denervarea scade frecvența de repaus și crește variabilitatea TA diurnă","NYHA IV terminal, indicație preferată de ICD izolat"],"ABC",1076,"Transplant cardiac — Infecții, vasculopatie, contraindicații",
 "Memorarea ferestrei 2-6 luni a oportuniștilor și a vasculopatiei 30-50% la 5 ani.",
 ["Infecțiile cu germeni oportuniști (toxoplasmoză, CMV, fungi, Pneumocystis) apar tardiv, în lunile 2-6 după transplant.","Vasculopatia de alogrefă apare la 30-50% dintre pacienți la 5 ani și este principala cauză de eșec tardiv al grefei.","Contraindicațiile includ vârsta >60 de ani (variabil între centre), rezistența vasculară pulmonară crescută și cancerul activ.","Nu: denervarea crește frecvența de repaus și duce la pierderea variabilității diurne a TA.","Nu: pacienții în clasa NYHA IV terminală nu sunt, în general, candidați la ICD."]],
 [8,"Inversează efectele denervării (tahicardie de repaus, pierderea variației diurne) și promovează ICD-ul în NYHA IV terminal."],["30-50%","2-6 luni"]),

q("cardiologie-adv-156",["Sindroamele clinice ale insuficienței cardiace acute:",
 ["ICA hipertensivă: TA crescută, funcție VS păstrată, edem pulmonar radiologic","șocul cardiogen: TAS <90 mmHg, diureză <0,5 ml/kg/oră, frecvență >60/min","IC dreaptă: debit scăzut, PVJ crescută, hepatomegalie, hipotensiune","edemul pulmonar acut: SpO2 >98% în aer atmosferic, fără raluri","IC cu debit crescut: periferie caldă, congestie pulmonară, ex. șoc septic"],"ABCE",1077,"Insuficiența cardiacă acută — Cadranul 30.28",
 "Potrivirea celor patru fenotipuri (hipertensiv, șoc, drept, debit crescut) cu saturația <90% din edemul pulmonar.",
 ["ICA hipertensivă: tensiune arterială crescută, funcție VS păstrată și edem pulmonar pe radiografie.","Șocul cardiogen se definește prin TAS <90 mmHg, diureză <0,5 ml/kg pe oră și frecvență >60 b.p.m.","IC dreaptă are debit scăzut, PVJ crescută, hepatomegalie și hipotensiune.","Nu: edemul pulmonar acut are tahipnee, ortopnee, raluri și saturație <90% în aer atmosferic.","IC cu debit crescut are periferie caldă, congestie pulmonară și tensiune posibil scăzută (de exemplu în șocul septic)."]],
 [8,"Definește edemul pulmonar prin saturație >98% fără raluri, inversul cadranului (<90%, raluri, ortopnee)."],["<90 mmHg","Periferie caldă"]),

q("cardiologie-adv-157",["În insuficiența cardiacă acută, doza inițială de furosemid este:",
 ["5 mg intravenos","500 mg intravenos în bolus","1 mg subcutanat","50 mg intravenos","0,125 mg intravenos"],"D",1077,"Insuficiența cardiacă acută — Furosemid inițial",
 "Reținerea bolusului de 50 mg i.v. de furosemid ca terapie inițială, alături de oxigen.",
 ["Nu: 5 mg i.v. este doza de atenolol din SCA; furosemidul inițial se dă 50 mg i.v.","Nu: 500 mg depășește doza inițială citată, care este de 50 mg i.v.","Nu: furosemidul se administrează intravenos, 50 mg, nu 1 mg subcutanat.","Terapia inițială a ICA include furosemid 50 mg i.v., alături de oxigen.","Nu: 0,125 mg este doza de întreținere a digoxinului, nu a diureticului."]],
 [8,"Confundă 50 mg furosemid cu 5 mg atenolol sau 0,125 mg digoxin, doze din același capitol."],["50 mg i.v.","furosemid"]),

q("cardiologie-adv-158",["În insuficiența cardiacă acută:",
 ["se indică profilaxie cu HGMM","nitroglicerina i.v. 10-200 µg/min cere monitorizarea TA","deteriorarea hemodinamică poate necesita cateter arterial pulmonar","nitroglicerină de primă intenție la TAS <85 mmHg","ecocardiografia transtoracică se amână cu 7 zile"],"ABC",1077,"ICA — HGMM, GTN și monitorizare invazivă",
 "Aplicarea ferestrei GTN 10-200 µg/min și a anticoagulației profilactice, nu a nitratului la TAS <85 mmHg.",
 ["Toți pacienții cu ICA necesită profilaxie cu heparină cu masă moleculară mică (HGMM).","Nitroglicerina (gliceril trinitrat) i.v. 10-200 µg/min cere monitorizarea atentă a TA, de exemplu în ischemie concomitentă sau HTA severă.","La deteriorare hemodinamică pot fi necesare linie arterială, cateter venos central și cateter de arteră pulmonară.","Nu: la TAS <85 mmHg algoritmul indică inotrope sau vasopresoare, nu nitratul de primă intenție.","Nu: ecocardiografia transtoracică trebuie efectuată fără întârziere."]],
 [8,"Pune nitratul ca primă linie la TAS <85 mmHg — pragul la care textul trece pe inotrope/vasopresoare."],["10-200 µg/min","heparină cu greutate mole"]),

q("cardiologie-adv-159",["Terapia inițială a insuficienței cardiace acute include:",
 ["oxigen inspirat în concentrație de 35-50%","morfină 2,5-5,0 mg și metoclopramid 10 mg, intravenos","enoxaparină profilactică 40 mg s.c. pe zi","dopamină în doză mare, sub 2 µg/kg/min","oxigen 100% de rutină, cu evitarea NIPPV"],"ABC",1078,"Insuficiența cardiacă acută — Oxigen, morfină, HGMM",
 "Aplicarea concentrației 35-50%, a morfinei cu antiemetic și a dozei profilactice de enoxaparină.",
 ["Cadranul ICA indică oxigen inspirat în concentrație de 35-50%.","Morfina 2,5-5,0 mg i.v. se asociază cu metoclopramid 10 mg i.v. ca antiemetic.","Tabelul dă enoxaparină 40 mg s.c. zilnic ca profilaxie și 1 mg/kg s.c. de două ori pe zi în SCA.","Nu: doza mare de dopamină este >5 µg/kg/min; sub 2 µg/kg/min este doza mică.","Nu: NIPPV/CPAP figurează alături de oxigen, care se dă în concentrație de 35-50%."]],
 [8,"Inversează treptele de dopamină și impune oxigen 100% în locul ferestrei 35-50%."],["35-50%","metoclopramid 10 mg"]),

q("cardiologie-adv-160",["Agenții inotropi în insuficiența cardiacă acută:",
 ["dobutamina se titrează în intervalul 2-20 µg/kg/min","dopamina peste 5 µg/kg/min acționează ca vasopresor","milrinona: bolus 25-75 µg/kg, apoi 0,375-0,75 µg/kg/min","dobutamina este contraindicată sub beta-blocant cronic","dopamina >5 µg/kg/min, prima linie în SCA"],"ABC",1078,"ICA — Doze de dobutamină, dopamină mare, milrinonă",
 "Memorarea ferestrelor 2-20 (dobutamină) și >5 (dopamină vasopresoare) plus bolusul de milrinonă.",
 ["Dobutamina se titrează 2-20 µg/kg/min; sub beta-blocante pot fi necesare doze mari.","Dopamina în doză mare (>5 µg/kg/min) are efect vasopresor.","Milrinona se dă în bolus de 25-75 µg/kg în 10-20 min, apoi 0,375-0,75 µg/kg/min.","Nu: sub beta-blocante pot fi necesare doze mari de dobutamină; nu este contraindicată.","Nu: în SCA cu IC acută cadranul evită inotropele ca primă linie; dopamina în doză mare nu este elecția universală."]],
 [8,"Interzice dobutamina la beta-blocant — tocmai situația în care tabelul cere doze mai mari."],["2-20 µg/kg pe min",">5 µg/kg pe min"]),

q("cardiologie-adv-161",["Fiziopatologia sindromului coronarian acut:",
 ["mecanismul comun: ruptura sau eroziunea capișonului fibros","capișonul subțire și miezul lipidic mare favorizează ruptura","serotonina și tromboxanul A2 produc vasodilatație coronariană","SCA apare prin stenoză lentă, fără tromb","capișonul fibros gros caracterizează placa vulnerabilă"],"AB",1080,"SCA — Placa vulnerabilă și tromboxanul A2",
 "Recunoașterea substratului (capișon subțire, miez lipidic) și a vasoconstricției prin serotonină/TxA2.",
 ["Ruptura sau eroziunea capișonului fibros al plăcii este mecanismul comun al SCA.","Miezul lipidic abundent cu capișon fibros subțire se asociază cu risc crescut de ruptură.","Nu: serotonina și tromboxanul A2 eliberate din plachete produc vasoconstricție, reduc fluxul coronarian și agravează ischemia.","Nu: în SCA sunt descrise tromb local, vasoconstricție și embolizare distală, nu o stenoză lentă fără tromb.","Nu: vulnerabile sunt leziunile cu capișon subțire și miez bogat în lipide."]],
 [8,"Inversează morfologia plăcii vulnerabile (capișon subțire/miez lipidic versus capișon gros)."],["capişonului fibros","tromboxanului A2"]),

q("cardiologie-adv-162",["Prevenția bolii coronariene prin stilul de viață presupune:",
 ["săptămânal: 75 min efort moderat sau 150 min intens","IMC <25 kg/m²; alcool sub 14 măsuri/săptămână (UK)","≥5 porții de fructe și legume pe zi","înlocuirea grăsimilor nesaturate cu grăsimi saturate","renunțarea la efort fizic după 45 de ani"],"BC",1081,"Boala coronariană — Stil de viață",
 "Aplicarea ferestrelor 150/75 minute, IMC <25 și a pragului de 14 unități de alcool.",
 ["Nu: se recomandă cel puțin 150 de minute de activitate aerobică moderată sau 75 de minute de intensitate crescută pe săptămână.","Se recomandă IMC <25 kg/m² și, în UK, sub 14 măsuri de alcool pe săptămână, distribuite în cel puțin 3 zile.","Se recomandă cel puțin cinci porții de fructe și legume pe zi și două porții de pește pe săptămână.","Nu: grăsimile saturate se înlocuiesc cu nesaturate, iar colesterolul alimentar trebuie să fie <300 mg/zi.","Nu: efortul aerobic regulat este recomandat, nu interzis."]],
 [8,"Interzice efortul și preferă grăsimile saturate, inversul dietei și al protocolului de 150 de minute."],["150 minute","<25 kg/m2"]),

q("cardiologie-adv-163",["Definițiile NICE ale anginei:",
 ["atipică: 2 din cele 3 caracteristici clasice","instabilă: debut <24 h sau agravarea anginei stabile","non-anginoasă: 3 din 3 caracteristici clasice","clasică: o singură caracteristică din trei","instabilă: echivalentul clasei CCS I"],"AB",1081,"Angina — Definiții NICE și forma instabilă",
 "Diferențierea 3/3 (clasică), 2/3 (atipică), 1/3 (non-anginoasă) și a ferestrei <24 de ore a instabilei.",
 ["NICE definește angina atipică prin 2 dintre cele 3 caracteristici ale anginei clasice.","Angina instabilă are debut recent (<24 de ore) sau agravează angina stabilă, adesea cu durere în repaus.","Nu: durerea non-anginoasă are o singură caracteristică din cele trei.","Nu: angina clasică are toate cele trei caracteristici.","Nu: CCS I înseamnă angină doar la efort intens, fără limitarea activității zilnice, nu angină instabilă."]],
 [8,"Degradează angina clasică la un singur criteriu și confundă instabilitatea cu CCS I."],["<24 ore","2 dintre cele 3"]),

q("cardiologie-adv-164",["Durerea toracică fără boală coronariană cunoscută:",
 ["angina tipică/atipică: angio-CT coronarian ≥64 slice","angio-CT neconcludent: teste funcționale neinvazive","se comunică o mortalitate anuală sub 2%","durere non-anginoasă cu ECG normal: PCI primară","examenul nu caută gerontoxonul sau stenoza aortică"],"ABC",1082,"Angina stabilă — Angio-CT și prognostic <2%",
 "Algoritmul CT ≥64 slice-uri, apoi teste funcționale, plus mesajul de mortalitate anuală <2%.",
 ["Angina tipică sau atipică (și durerea non-anginoasă cu modificări ST sau unde Q) se îndrumă la angio-CT coronarian multi-slice ≥64.","Dacă angio-CT este neconcludent, urmează teste funcționale neinvazive (SPECT, eco de stres, IRM de stres).","Pacienții sunt informați că prognosticul vital este bun, cu mortalitate anuală <2%.","Nu: durerea non-anginoasă cu ECG normal se investighează pentru diagnostice alternative, nu prin PCI primară.","Nu: examenul obiectiv caută anemie, hipertiroidism, gerontoxon sau xantelasme și stenoză aortică."]],
 [8,"Trimite durerea non-anginoasă cu ECG normal la PCI primară, sărind algoritmul NICE."],["64 slice","<2%"]),

q("cardiologie-adv-165",["Angina stabilă necontrolată sub beta-blocant sau blocant de calciu:",
 ["trecere pe nitrat retard, ivabradină, nicorandil sau ranolazină","asociere beta-blocant plus blocant de calciu","se consideră revascularizarea sub două antianginoase","triplă terapie plus inhibitor GPIIb/IIIa de rutină","revascularizare în CCS I, fără alt antianginos"],"ABC",1082,"Angina stabilă — Algoritmul Fig. 30.64",
 "Secvența: un antianginos → schimb sau asociere → două antianginoase → revascularizare.",
 ["A doua linie include nitratul cu acțiune prelungită, ivabradina, nicorandilul sau ranolazina.","Dacă pacientul rămâne simptomatic, următorul pas este asocierea beta-blocant plus blocant de calciu.","Revascularizarea se ia în considerare când simptomele persistă sub două antianginoase.","Nu: inhibitorii GPIIb/IIIa nu apar în algoritmul anginei stabile.","Nu: revascularizarea se discută la simptome persistente sub tratament, nu la angina CCS I controlată."]],
 [8,"Sare la triple+GPIIb/IIIa și rezervă revascularizarea clasei I, inversând Fig. 30.64."],["Nicorandil","Ranolazină"]),

q("cardiologie-adv-166",["Antianginoasele de linia a doua:",
 ["nicorandilul, activator K+-ATP, poate da ulcerații orale","ranolazina 375-750 mg ×2/zi inhibă canalele de Na+","ivabradina se folosește în fibrilația atrială","verapamilul este de elecție în BAV II-III","nitroglicerina se asociază în siguranță cu sildenafil"],"AB",1083,"Angina — Nicorandil, ranolazină, ivabradină",
 "Recunoașterea ulcerațiilor orale (nicorandil), a ferestrei 375-750 mg (ranolazină) și a folosirii ivabradinei în ritm sinusal.",
 ["Nicorandilul activează canalele de K+ sensibile la ATP, are proprietăți de nitrat și poate produce ulcerații orale.","Ranolazina (375-750 mg ×2/zi) inhibă canalele de Na+ din cardiomiocite, este metabolizată de CYP3A4 și poate prelungi QT.","Nu: ivabradina se folosește în ritm sinusal; poate produce fosfene și bradicardie.","Nu: verapamilul și diltiazemul sunt contraindicate în BAV de grad II-III și în disfuncția VS cu stază pulmonară.","Nu: nitrații sunt contraindicați în asociere cu inhibitorii PDE5, precum sildenafilul."]],
 [8,"Pune verapamilul pe BAV II-III — contraindicație de tabel — și asociază nitratul cu sildenafil."],["ulceraţii orale","375-750 mg"]),

q("cardiologie-adv-167",["În angina stabilă, ținta LDL-colesterolului sub atorvastatină 80 mg este:",
 ["sub 3,5 mmol/L","<1,8 mmol/L","<5 mmol/L","sub 2,5 mmol/L","<0,5 mmol/L"],"B",1083,"Angina — Ținta LDL",
 "Reținerea țintei LDL <1,8 mmol/L sub atorvastatină 80 mg.",
 ["Nu: 3,5 mmol/L nu este ținta citată; cadranul cere LDL <1,8 mmol/L.","Cadranul recomandă reducerea LDL la <1,8 mmol/L cu atorvastatină 80 mg.","Nu: 5,0 mmol/L nu apare ca țintă; ținta este LDL <1,8 mmol/L.","Nu: ținta citată sub atorvastatină 80 mg este LDL <1,8 mmol/L; statinele sunt fundamentul reducerii evenimentelor.","Nu: ținta este <1,8 mmol/L, obținută cu atorvastatină 80 mg, nu prin ezetimib izolat."]],
 [8,"Mută ținta de la <1,8 la <3,5 mmol/L, praguri alăturate dar false."],["<1,8 mmol/L","Atorvastatina 80 mg"]),

q("cardiologie-adv-168",["Diferența dintre angina instabilă și NSTEMI constă în:",
 ["necroza miocardică, cu troponină crescută, în NSTEMI","unda Q, prezentă constant în NSTEMI","troponina crescută în AI, normală în NSTEMI","BRS nou, criteriu de angină instabilă","diagnosticul radiologic al NSTEMI, fără troponină"],"A",1084,"SCA — AI versus NSTEMI",
 "Reținerea necrozei (troponină/CK-MB) ca element care desparte NSTEMI de angina instabilă.",
 ["În NSTEMI apare trombusul ocluziv, care duce la necroză și la creșterea troponinei sau a CK-MB.","Nu: unda Q nu definește NSTEMI, iar angina instabilă se însoțește de durere.","Nu: troponina sau CK-MB cresc în NSTEMI, prin necroză, nu în angina instabilă.","Nu: BRS nou orientează spre STEMI și reperfuzie, nu spre angina instabilă.","Nu: diagnosticul NSTEMI combină anamneza, ECG-ul și markerii de necroză."]],
 [8,"Anulează rolul troponinei — tocmai criteriul care desparte NSTEMI de AI."],["trombusului ocluziv","CK-MB"]),

q("cardiologie-adv-169",["Mortalitatea la 42 de zile la troponină I >9 ng/ml, în SCA:",
 ["1%","1,7%","3,4%","7,5%","sub 0,1%"],"D",1085,"SCA — Troponina I și mortalitatea la 42 de zile",
 "Memorarea treptei >9 ng/ml → 7,5% mortalitate la 42 de zile, versus 1% la valori nedetectabile.",
 ["Nu: 1,0% corespunde troponinei I între 0 și <0,4 ng/ml.","Nu: 1,7% corespunde intervalului 0,4-<1,0 ng/ml.","Nu: 3,4% corespunde intervalului 1,0-<2,0 ng/ml.","Cadranul 30.34: troponina I >9,0 ng/ml corespunde unei mortalități la 42 de zile de 7,5%.","Nu: valoarea subestimează net riscul; la >9,0 ng/ml mortalitatea este de 7,5%."]],
 [8,"Cele cinci trepte consecutive din același tabel sunt ușor de permutat; doar >9 ng/ml dă 7,5%."],[">9,0","7,5"]),

q("cardiologie-adv-170",["După NSTEMI, riscul GRACE scăzut la 6 luni înseamnă:",
 ["scor >118 și mortalitate >8%","scor ≤88 și mortalitate <3%","scor între 126 și 154 de puncte","scor ≥200, indiferent de moment","scor 89-118 și mortalitate 3-8%"],"B",1086,"SCA — GRACE la 6 luni (NSTEMI)",
 "Reținerea pragului ≤88 (<3%) pentru NSTEMI la 6 luni, distinct de >118 (>8%) și de benzile STEMI.",
 ["Nu: scorul >118, cu mortalitate >8%, definește riscul înalt la 6 luni după NSTEMI.","Cadranul 30.37: după NSTEMI, riscul scăzut la 6 luni înseamnă scor ≤88 și mortalitate <3%.","Nu: 126-154 este banda de risc mediu pentru STEMI în spital, nu riscul scăzut la 6 luni după NSTEMI.","Nu: ≥200 nu este o categorie a riscului la 6 luni după NSTEMI.","Nu: riscul scăzut la 6 luni cere scor ≤88 și mortalitate <3%, praguri depășite aici."]],
 [8,"Confundă ≤88 (<3% la 6 luni) cu pragul înalt >118 sau cu benzile STEMI intra-spital."],[":S88","<3"]),

q("cardiologie-adv-171",["Tratamentul antitrombotic și beta-blocant în SCA:",
 ["aspirină 300 mg încărcare, apoi 75-100 mg/zi","prasugrel 60 mg încărcare, apoi 10 mg/zi","în lipsa contraindicațiilor, beta-blocant titrat la 50-60/min","clopidogrel 300-600 mg încărcare, apoi 75 mg/zi","inhibitori GPIIb/IIIa administrați de rutină"],"ABCD",1086,"SCA — DAPT și frecvența 50-60/min",
 "Fixarea dozelor de încărcare (inclusiv clopidogrel 300-600 mg) și a țintei de frecvență 50-60/min.",
 ["Aspirina se încarcă cu 300 mg, apoi se continuă 75-100 mg/zi.","Prasugrelul se încarcă cu 60 mg, apoi 10 mg/zi; ticagrelorul 180 mg, apoi 90 mg de două ori pe zi.","În absența contraindicațiilor, beta-blocantele se titrează către o frecvență de repaus de 50-60/min.","Clopidogrelul se încarcă cu 300-600 mg, apoi 75 mg/zi.","Nu: inhibitorii GPIIb/IIIa se rezervă încărcării trombotice marcate sau complicațiilor PCI."]],
 [8,"Atribuie prasugrelului încărcarea de clopidogrel și readuce GPIIb/IIIa ca rutină."],["50-60 pe minut","60 mg"]),

q("cardiologie-adv-172",["Anticoagulantele în sindromul coronarian acut:",
 ["fondaparinuxul inactivează factorul Xa prin antitrombină","bivalirudina se leagă reversibil de trombină","enoxaparina, s.c. ×2/zi, e superioară heparinei nefracționate","fondaparinuxul inactivează direct trombina","heparina nefracționată nu necesită monitorizarea aPTT"],"ABC",1086,"SCA — Antitrombinice",
 "Contrastul fondaparinux (anti-Xa via AT) versus bivalirudină (inhibitor direct reversibil) și superioritatea enoxaparinei.",
 ["Fondaparinuxul, un pentazaharid, activează antitrombina și inactivează factorul Xa, fără a inactiva direct trombina și fără efect antiplachetar.","Bivalirudina se leagă reversibil de trombină; în ACUITY a avut eficacitate similară heparinei plus GPIIb/IIIa, cu risc hemoragic mai mic.","Enoxaparina, administrată subcutanat de două ori pe zi, este superioară heparinei nefracționate.","Nu: fondaparinuxul inactivează factorul Xa prin antitrombină, nu trombina direct.","Nu: heparina nefracționată cere monitorizarea aPTT la 6-12 ore."]],
 [8,"Transformă fondaparinux-ul — pentazaharid anti-Xa — într-un inhibitor direct de trombină."],["Fondaparinux","bivalirudina"]),

q("cardiologie-adv-173",["Dozele medicamentelor în sindromul coronarian acut:",
 ["prasugrel 5 mg/zi la <60 kg sau >75 de ani","fondaparinux 2,5 mg/zi s.c., maximum 8 zile","morfină 2,5-5,0 mg și metoclopramid 10 mg, intravenos","înlocuirea aspirinei cu inhibitori GPIIb/IIIa","atenolol i.v. de primă linie în astm"],"ABC",1087,"SCA — Prasugrel 5 mg, fondaparinux 2,5 mg",
 "Aplicarea reducerii prasugrelului la vârstnici/greutate mică și a ferestrei fondaparinux 8 zile.",
 ["Prasugrelul 10 mg/zi se reduce la 5 mg/zi sub 60 kg sau peste 75 de ani.","Fondaparinuxul se dă 2,5 mg s.c. pe zi, până la 8 zile.","Morfina 2,5-5,0 mg i.v. se asociază cu metoclopramid 10 mg i.v.","Nu: aspirina 150-300 mg mestecabilă rămâne baza tratamentului și nu se înlocuiește cu GPIIb/IIIa.","Nu: beta-blocantele sunt contraindicate în astm, IC, hipotensiune și bradiaritmii."]],
 [8,"Omite reducerea prasugrelului la >75 de ani/<60 kg — capcana de dozaj a cadranului."],["<60 kg","2,5 mg s.c."]),

q("cardiologie-adv-174",["Scorul de risc TIMI în STEMI:",
 ["acordă 3 puncte vârstei >75 de ani","punctează întârzierea tratamentului peste 4 ore","punctează TAS <100 mmHg și FC >100/min","se bazează pe troponina izolată","scorul 0 prezice o mortalitate de 35,9%"],"ABC",1088,"STEMI — Scorul TIMI (Cadranul 30.39)",
 "Recunoașterea itemilor TIMI pentru STEMI (vârsta >75 de ani cu 3 puncte, întârzierea tratamentului, TAS, FC, Killip), distincți de TIMI NSTEMI.",
 ["În scorul TIMI pentru STEMI, vârsta >75 de ani primește 3 puncte.","Întârzierea tratamentului peste 4 ore este un item al scorului TIMI pentru STEMI.","TAS <100 mmHg, FC >100/min, clasa Killip II-IV și IM anterior sau BRS sunt itemi ai scorului.","Nu: scorul TIMI pentru STEMI combină date clinice și ECG, nu troponina izolată.","Nu: scorul 0 corespunde unei mortalități la 30 de zile de 0,8%; 35,9% aparține scorurilor celor mai mari."]],
 [8,"Atribuie scorului 0 mortalitatea benzii 9-16 (35,9%) și reduce TIMI STEMI la troponină."],[">75 ani",">67 kg"]),

q("cardiologie-adv-175",["Diagnosticul STEMI:",
 ["ECG în 10 minute de la primul contact medical","supradenivelare ST ≥0,1 mV în V1-V3, ≥0,2 mV în rest","durere >20 min, de obicei rezistentă la nitroglicerină","BRS nou sau presupus nou nu necesită reperfuzie","o primă ECG normală exclude infarctul"],"AC",1088,"STEMI — ECG, 10 minute și 0,2 mV",
 "Aplicarea ferestrei de 10/15 minute, a pragului 0,2 mV în V1-V3 și a durerii >20 de minute.",
 ["ECG-ul se face în primele 10 minute de la primul contact medical și se repetă la 15 minute dacă e neschimbat și durerea persistă.","Nu: pragurile sunt inversate; supradenivelarea ST nouă la punctul J este ≥0,2 mV în V1-V3 și ≥0,1 mV în celelalte derivații.","Durerea tipică depășește 20 de minute și de obicei nu cedează la nitroglicerină sublinguală.","Nu: BRS major nou sau presupus nou se asociază cu ocluzie și impune reperfuzie urgentă.","Nu: ECG-ul inițial este rar normal și nu exclude infarctul, iar monitorizarea ritmului rămâne necesară."]],
 [8,"Anulează reperfuzia din BRS nou — indicație explicită — și tratează prima ECG normală ca excludere."],["10 minute","20 de minute"]),

q("cardiologie-adv-176",["Tromboliza sistemică în STEMI:",
 ["bolusul, în primele 10 minute de la diagnostic","fără rezoluția ST >50% la 60-90 min: PCI de salvare","aspirină plus clopidogrel; anticoagulant 5-7 zile","tromboaspirația de rutină înlocuiește tromboliza","inhibitor GPIIb/IIIa de rutină, în locul heparinei"],"ABC",1089,"STEMI — Tromboliză, salvare și 5-7 zile",
 "Reținerea bolusului în 10 minute, a criteriului 50% la 60-90 min și a anticoagulației 5-7 zile.",
 ["Ținta este administrarea bolusului de trombolitic în primele 10 minute de la diagnostic.","Eșecul trombolizei (ST nu scade cu >50% față de referință la 60-90 de minute) impune PCI de salvare.","Antiagregarea cu aspirină plus clopidogrel se asociază cu HNF, enoxaparină sau fondaparinux timp de 5-7 zile.","Nu: tromboaspirația de rutină nu este recomandată, nici în PCI primară.","Nu: inhibitorii GPIIb/IIIa de rutină nu mai sunt recomandați după tromboliză."]],
 [8,"Înlocuiește criteriul 50%/60-90 min de salvare cu tromboaspirație de rutină, respinsă de text."],["10 minute","60-90 minute"]),

q("cardiologie-adv-177",["Boala cardiacă ischemică produce anual în Europa:",
 ["aproximativ 1,8 milioane de decese","aproximativ 18.000 de decese","aproximativ 180.000 de decese","aproximativ 18 milioane de decese","sub 1.000 de decese, prin STEMI neperfuzat"],"A",1088,"STEMI — Epidemiologie europeană",
 "Reținerea ordinii de mărime 1,8 milioane de decese anuale prin BCI în Europa.",
 ["Aproximativ 1,8 milioane de oameni mor anual în Europa din cauza bolii cardiace ischemice.","Nu: 18.000 subestimează cu două ordine de mărime; decesele sunt circa 1,8 milioane.","Nu: decesele anuale prin BCI în Europa sunt circa 1,8 milioane, nu 180.000.","Nu: cifra citată este de circa 1,8 milioane de decese, nu 18 milioane.","Nu: ordinul de mărime este de milioane de decese prin BCI, nu de mii."]],
 [8,"Subestimează cu două-trei ordine de mărime mortalitatea europeană prin BCI."],["1,8 milioane","boala cardiacă ischemică"]),

q("cardiologie-adv-178",["Valvulotomia mitrală percutană cu balon este preferabilă când:",
 ["valvele sunt suple, cu aparat subvalvular minim afectat","ETE preprocedurală exclude tromboza atrială stângă","există calcificări importante sau tromb atrial stâng","se asociază regurgitare mitrală moderată","abordul se face fără puncția septului interatrial"],"AB",1094,"Stenoza mitrală — Valvuloplastie cu balon",
 "Criteriile de fezabilitate (valve suple, RM minimă) și rolul ETE de excludere a trombului.",
 ["Procedura se rezervă valvelor suple, cu aparat subvalvular minim afectat și regurgitare mitrală minimă.","ETE preprocedurală exclude trombul atrial stâng înaintea puncției transseptale.","Nu: calcificarea importantă, regurgitarea mitrală mai mult decât ușoară și trombul atrial stâng sunt contraindicații.","Nu: regurgitarea mitrală mai mult decât ușoară contraindică procedura.","Nu: procedura presupune puncția transseptală, cu abord din vena femurală."]],
 [8,"Transformă contraindicațiile (calcificare, RM, tromb) în indicații ale balonului."],["trombozei atriale stângi","puncţie transseptală"]),

q("cardiologie-adv-179",["Scorul Wilkins, pentru fezabilitatea valvuloplastiei mitrale, evaluează:",
 ["cuspele (mobilitate, îngroșare, calcificare) și aparatul subvalvular","gradientul transmitral mediu, fără criterii morfologice","ritmul cardiac, sinusal sau fibrilație atrială","grosimea pereților ventriculului stâng și a septului interventricular","diametrul rădăcinii aortice și al aortei ascendente"],"A",1094,"Stenoza mitrală — Scorul Wilkins",
 "Reținerea celor patru itemi Wilkins (mobilitate, îngroșare, calcificare, subvalvular).",
 ["Scorul Wilkins evaluează mobilitatea, îngroșarea și calcificarea cuspelor, plus îngroșarea aparatului subvalvular.","Nu: gradientul completează evaluarea severității, dar scorul Wilkins este morfologic.","Nu: fibrilația atrială influențează anticoagularea, nu este item al scorului Wilkins.","Nu: grosimea peretelui VS nu este item Wilkins; scorul privește valva mitrală și aparatul subvalvular.","Nu: rădăcina aortică ține de valva aortică, nu de scorul Wilkins."]],
 [8,"Înlocuiește cei patru itemi morfologici Wilkins cu un gradient izolat sau cu grosimea din CMH."],["Scorul Wilkins","aparatului subvalvular"]),

q("cardiologie-adv-180",["Regurgitarea mitrală:",
 ["poate fi produsă de fenfluramină sau cabergolină","Carpentier tip I: mobilitate normală; II: crescută; III: restricționată","suflu holosistolic iradiat în axilă","dă tromboembolii mai frecvent decât stenoza mitrală","S1 întărit, ca în stenoza mitrală"],"ABC",1095,"Regurgitarea mitrală — Carpentier și auscultație",
 "Potrivirea clasificării Carpentier cu suflul holosistolic axilar și cu cauzele medicamentoase.",
 ["Pe lângă degenerescența mixomatoasă, ischemie, reumatism și endocardită, regurgitarea mitrală poate fi indusă de fenfluramină sau cabergolină.","Clasificarea Carpentier: tipul I cu mobilitate normală a cuspelor, tipul II cu mobilitate crescută (prolaps), tipul III cu mobilitate restricționată.","Suflul holosistolic iradiază în axilă; HVS pe ECG apare la circa 50% dintre pacienți.","Nu: tromboembolia este mai rară decât în stenoza mitrală, iar endocardita subacută este mai frecventă.","Nu: S1 este diminuat prin apoziția incompletă a valvelor, nu întărit."]],
 [8,"Inversează S1 (diminuat în RM versus întărit în SM) și umflă riscul embolic peste pe cel al stenozei."],["fenfluramină","50%"]),

q("cardiologie-adv-181",["Stenoza aortică și valva aortică bicuspidă:",
 ["simptomele indică severitatea și impun înlocuirea valvulară","bicuspidie cu aorta ascendentă >50 mm: se consideră chirurgia","stenoza severă asimptomatică cu FEVS <50% are indicație","valvuloplastia cu balon, superioară TAVI la adult","stenoza simptomatică cu FEVS 55% se urmărește conservator"],"ABC",1099,"Stenoza aortică — Indicații chirurgicale",
 "Aplicarea pragurilor 50 mm/5 mm/an la bicuspidie și a criteriilor de intervenție la asimptomatici (FEVS <50%, 5,5 m/s, 60 mmHg).",
 ["Simptomele sunt un bun indicator de severitate, iar pacienții simptomatici trebuie să beneficieze de înlocuire valvulară.","La bicuspidie, chirurgia se consideră dacă aorta ascendentă depășește 50 mm sau crește cu peste 5 mm/an.","La asimptomaticii cu SA severă, FEVS <50% este indicație, alături de Vmax >5,5 m/s, PAPS >60 mmHg sau simptome la efort.","Nu: valvuloplastia cu balon la adult are rezultate slabe; TAVI este alternativa pentru inoperabili.","Nu: pacientul simptomatic are indicație de corecție, nu urmărire conservatoare."]],
 [8,"Amână chirurgia simptomaticului cu FE 55% și promovează balonul adultului ca soluție definitivă."],["50 mm","5,5 m/s"]),

q("cardiologie-adv-182",["Fiziopatologia regurgitării aortice cronice:",
 ["volumul ejectat crește, cu dilatarea VS","VS dilatat, mai puțin eficient, devine ischemic","simptome tardive și aritmii relativ rare","creșterea TA diastolice ameliorează perfuzia coronariană","șoc apexian nedeplasat și susținut"],"ABC",1100,"Regurgitarea aortică — Fiziopatologie",
 "Legarea scăderii TA diastolice de hipoperfuzia coronariană și de ischemia VS dilatat.",
 ["Pentru a menține debitul net, volumul ejectat în aortă trebuie să crească, ceea ce dilată VS.","VS dilatat este mai puțin eficient, cu necesar de oxigen crescut și ischemie; scăderea TA diastolice reduce și perfuzia coronariană.","Simptomele semnificative apar târziu, odată cu insuficiența VS, iar aritmiile sunt relativ rare.","Nu: TA diastolică scade, ceea ce reduce perfuzia coronariană.","Nu: șocul apexian este hiperdinamic, deplasat inferior și lateral."]],
 [8,"Crește TA diastolică — inversul fiziopatologiei RA — și atribuie apexul nedeplasat al stenozei."],["perfuzia coronariană","Austin Flint"]),

q("cardiologie-adv-183",["Cauzele regurgitării aortice acute includ:",
 ["endocardita infecțioasă și disecția de aortă","sifilisul și osteogenesis imperfecta, de primă linie","stenoza aortică calcificată a pacientului vârstnic","hipotiroidismul mixedematos","pericardita constrictivă cronică"],"A",1100,"Regurgitarea aortică — Cadranul 30.44 (acută)",
 "Listarea cauzelor acute (RAA, endocardită, disecție, Valsalva, proteză), distincte de Marfan/sifilis cronice.",
 ["Cadranul 30.44 listează RAA, endocardita infecțioasă, disecția de aortă, anevrismul de sinus Valsalva rupt și proteza disfuncțională.","Nu: sifilisul și osteogenesis imperfecta sunt cauze ale formei cronice.","Nu: stenoza aortică calcificată a vârstnicului nu este o cauză de regurgitare aortică acută.","Nu: mixedemul ține de afectarea pericardică, nu de regurgitarea aortică acută.","Nu: pericardita constrictivă nu figurează printre cauzele regurgitării aortice acute."]],
 [8,"Mută sifilisul/Marfan din forma cronică în cea acută, amestecând cele două coloane ale tabelului."],["Disecţie de aortă","sinus Valsalva"]),

q("cardiologie-adv-184",["Stenoza pulmonară se caracterizează prin:",
 ["suflu de ejecție în spațiul II intercostal stâng","P2 întârziat și diminuat; clic de ejecție valvular","valvulotomie imediată și în forma ușoară","suflu protodiastolic Graham Steell, accentuat în inspir","P2 întărit, ca în hipertensiunea pulmonară"],"AB",1102,"Stenoza pulmonară — Semne și tratament",
 "Contrastul P2 diminuate din stenoză versus P2 întărite din regurgitarea pe HTP.",
 ["Suflul mezosistolic rugos de ejecție, maxim în inspir, se aude în spațiul II intercostal stâng, adesea cu freamăt.","P2 este întârziat și diminuat, iar clicul de ejecție apare când obstrucția este valvulară.","Nu: forma ușoară este asimptomatică; valvulotomia se rezervă formei severe.","Nu: suflul Graham Steell aparține regurgitării pulmonare.","Nu: P2 întărit aparține regurgitării pulmonare pe fond de HTP, nu stenozei."]],
 [8,"Pune P2 întărită și Graham Steell pe stenoza pulmonară, semnele regurgitării de HTP."],["spaţiul li intercostal","valvulotomie pulmo"]),

q("cardiologie-adv-185",["Protezele valvulare cardiace:",
 ["protezele biologice degenerează după circa 10 ani","valve moderat trombogene: INR 3,0, sau 3,5 cu factori","zgomotele mecanicelor se aud la deschidere și închidere","FA, AS >50 mm, FEVS <35%: risc tromboembolic crescut","DOAC sunt prima linie la protezele valvulare mecanice"],"ABCD",1102,"Proteze — Durabilitate 10 ani și INR 3,0/3,5",
 "Completarea treptei intermediare INR 3,0/3,5, a degenerării la circa 10 ani și a factorilor adiționali (AS >50 mm, FEVS <35%).",
 ["Protezele mecanice sunt mai durabile; cele biologice degenerează după circa 10 ani, dar sunt mai puțin trombogene.","Valvele moderat trombogene au ținta INR 3,0 fără factori adiționali de risc și 3,5 cu factori.","Zgomotele protezelor mecanice sunt mai puternice și se aud la deschidere și închidere; biologicele seamănă valvelor native.","Factorii adiționali de tromboembolism includ FA, diametrul AS >50 mm și FEVS <35%.","Nu: anticoagulantele orale directe nu au indicație la protezele valvulare mecanice."]],
 [8,"Pune biologicul la INR 4,0 pe viață — treapta Starr-Edwards — și introduce DOAC-ul interzis."],["10 ani","INR 3,0"]),

q("cardiologie-adv-186",["Anticoagularea protezei valvulare mecanice în sarcină:",
 ["warfarina: embriopatie în 5-12%, în trimestrul I","HGMM ×2/zi, anti-Xa 0,8-1,2 U/ml la 4 ore","heparina nefracționată: tromboză valvulară la circa 25%","HGMM traversează placenta, cu embriopatie ca warfarina","mortalitatea maternă asociată este sub 0,1%"],"ABC",1103,"Proteze — Sarcină, anti-Xa și UFH 25%",
 "Aplicarea ferestrei anti-Xa 0,8-1,2 și a riscului 25% de tromboză sub UFH, versus embriopatia 5-12%.",
 ["Warfarina traversează placenta, cu risc de 5-12% de embriopatie în primul trimestru și de hemoragie intracraniană fetală.","HGMM de două ori pe zi, cu anti-Xa 0,8-1,2 U/ml la 4 ore după doză, oferă un efect mai consistent.","Sub heparină nefracționată, incidența trombozei valvulare în sarcină este ridicată, circa 25%.","Nu: heparinele nu traversează placenta și nu produc embriopatie.","Nu: mortalitatea maternă asociată protezei mecanice în sarcină este de 1-4%, nu sub 0,1%."]],
 [8,"Atribuie HGMM embriopatia warfarinei și comprimă mortalitatea maternă de la 1-4% la 0,1%."],["0,8-1,2 U / ml","25%"]),

q("cardiologie-adv-187",["Sursele bacteriemiei în endocardita infecțioasă:",
 ["cavitatea orală (viridans), în 1/3-1/2 din cazuri","intestinul, cu Strep. bovis, asociat neoplaziei intestinale","consumatorii de droguri i.v.: S. aureus, rar Candida","originea orală a Strep. bovis, intestinală a viridansului","endocardita precoce pe proteză, comunitară, cu viridans"],"ABC",1104,"Endocardita — Porți de intrare",
 "Potrivirea viridans oral, enterococ/bovis intestinal și S. aureus la CDIV.",
 ["Cavitatea orală (streptococi viridans α-hemolitici) explică circa 1/3-1/2 din cazuri, mai multe în țările în dezvoltare.","Din intestin și perineu provin enterococii (E. faecalis) și Strep. bovis, legat de neoplazia intestinală.","La consumatorii de droguri i.v. apar S. aureus și, rar, Candida; heroina poate fi dizolvată în zeamă de lămâie contaminată.","Nu: Strep. bovis este intestinal, iar streptococii viridans provin din cavitatea orală.","Nu: endocardita precoce pe proteză este nosocomială, stafilococică, în primele 60 de zile."]],
 [8,"Inversează porțile viridans/bovis și tratează precocele de proteză ca infecție comunitară streptococică."],["Strep. bovis","zeamă de lămâie"]),

q("cardiologie-adv-188",["Investigațiile în endocardita infecțioasă:",
 ["trei seturi de hemoculturi din locuri diferite","serologie Coxiella și Bartonella la culturi negative","proteina C reactivă scade sub tratament eficient","un singur set, recoltat din cateterul central","prelungirea PR, semn de vindecare a infecției"],"ABC",1106,"Endocardita — Cadranul 30.47",
 "Trei seturi, serologia culturilor negative și dinamica PCR sub tratament.",
 ["Prima linie: trei seturi de hemoculturi recoltate din locuri de puncție diferite.","La hemoculturi negative se ia în considerare serologia pentru Coxiella, Bartonella, Legionella și Chlamydia.","Proteina C reactivă scade ca răspuns la terapia eficientă și poate crește din nou în recăderi.","Nu: un set recoltat de pe cateter nu înlocuiește cele trei seturi din locuri diferite.","Nu: prelungirea intervalului PR se asociază cu abcesul de rădăcină aortică."]],
 [8,"Reduce bacteriologia la un set de pe cateter și interpretează PR lung ca vindecare."],["Trei seturi","proteină C reactivă"]),

q("cardiologie-adv-189",["Boala Chagas cardiacă:",
 ["este produsă de Trypanosoma cruzi","în faza cronică: CMD, blocuri, aritmii ventriculare","beneficiază de amiodaronă pentru aritmiile ventriculare","este o boală sarcomerică autozomal dominantă","se confirmă prin serologie virală"],"ABC",1119,"Miocard — Boala Chagas",
 "Reținerea agentului (Trypanosoma cruzi), a evoluției acut→CMD și a rolului amiodaronei.",
 ["Boala Chagas este cauzată de Trypanosoma cruzi, endemic în America de Sud, cu peste 20 de milioane de infectați.","Faza acută este o miocardită cu febră și IC congestivă; faza cronică este o CMD cu tendință la blocuri și aritmii ventriculare.","Amiodarona este utilă pentru controlul aritmiilor ventriculare.","Nu: boala Chagas este infecțioasă, nu o mutație sarcomerică.","Nu: diagnosticul nu se bazează pe serologie virală."]],
 [8,"Transformă Chagas-ul parazitar sud-american într-o CMH sarcomerică."],["20 de milioane","Trypanosoma cruzi"]),

q("cardiologie-adv-190",["Clasificarea ESC a cardiomiopatiilor cuprinde:",
 ["formele hipertrofică, dilatativă, aritmogenă, restrictivă","formele ischemică și hipertensivă, fără criteriu morfologic","o entitate unică, cardiomiopatia nespecifică, fără subtipuri","formele Tako-tsubo și peripartum, ca fenotipuri principale","bolile de depozit Danon, Pompe și Fabry, ca bază a clasificării"],"A",1119,"Cardiomiopatii — Clasificarea ESC",
 "Memorarea celor cinci fenotipuri ESC și a diviziunii familial/non-familial.",
 ["ESC distinge formele hipertrofică, aritmogenă, dilatativă, restrictivă și neclasificate, apoi familiale versus non-familiale.","Nu: bolile ischemice și hipertensive sunt cauze alternative excluse din definiția CMH, nu clase ale clasificării ESC.","Nu: clasificarea ESC distinge fenotipuri diferite, nu o entitate unică.","Nu: Tako-tsubo și peripartum sunt cardiomiopatii dobândite, discutate separat.","Nu: bolile de depozit mimează CMH, dar nu reprezintă clasificarea ESC."]],
 [8,"Reduce clasificarea ESC la etiologii ischemice sau la formele dobândite, ignorând cele cinci fenotipuri."],["cardiomiopatia dilatativă","neclasificate"]),

q("cardiologie-adv-191",["Tratamentul cardiomiopatiei hipertrofice obstructive:",
 ["beta-blocante sau verapamil; alternativ disopiramidă","ablația septală cu alcool poate reduce obstrucția","evitarea vasodilatatoarelor, care pot agrava obstrucția","stimulare bicamerală la unii simptomatici","ablația septală cu alcool nu produce BAV"],"ABCD",1120,"CMH — LVOTO, alcool septal și vasodilatatoare",
 "Interdicția vasodilatatoarelor, riscurile ablației septale (BAV, IM) și opțiunea de stimulare bicamerală.",
 ["Durerea și dispneea se tratează cu beta-blocante, verapamil sau ambele; disopiramida este o alternativă dacă există LVOTO.","Ablația septală cu alcool poate reduce obstrucția, cu risc de BAV complet și infarct.","Vasodilatatoarele trebuie evitate: pot agrava LVOTO sau produce hipotensiune refractară.","La unii pacienți simptomatici cu obstrucție semnificativă se poate implanta un stimulator bicameral.","Nu: ablația septală cu alcool poate produce BAV complet și infarct."]],
 [8,"Pune vasodilatatorul — agent care agravează LVOTO — ca primă linie."],["Ablaţia cu alcool","Vasodilatatoarele"]),

q("cardiologie-adv-192",["Cardiomiopatia aritmogenă:",
 ["are o prevalență de 1 la 1.000-5.000","boala Naxos: keratodermă plantară și păr lânos","sindromul Carvajal se datorează mutației de plakoglobină","boala Naxos se datorează mutației RyR2","afectează VS excepțional, sub 5% din cazuri"],"AB",1121,"CMA — 1/1000-5000, Naxos, Carvajal",
 "Contrastul Naxos (plakoglobină) versus Carvajal (desmoplakină) și ponderea 75% a afectării de VS.",
 ["Prevalența cardiomiopatiei aritmogene este de 1 la 1.000-5.000.","Boala Naxos asociază keratodermă plantară și păr lânos, prin mutația plakoglobinei joncționale.","Nu: sindromul Carvajal se datorează mutației de desmoplakină; plakoglobina este afectată în boala Naxos.","Nu: RyR2 se asociază formei autozomal dominante și CPVT, nu bolii Naxos.","Nu: afectarea VS este raportată la până la 75% din cazuri."]],
 [8,"Inversează genele Naxos/Carvajal și comprimă afectarea VS de la 75% la 5%."],["75% din cazuri","boala Naxos"]),

q("cardiologie-adv-193",["Diagnosticul cardiomiopatiei aritmogene:",
 ["include anomalii structurale ale VD la eco/IRM","include anomalii de repolarizare sau de conducere","include TV sau ESV frecvente la Holter","admite testul de efort negativ ca criteriu unic","nu folosește biopsia, fibro-grăsosul nefiind criteriu"],"ABC",1122,"CMA — Criterii de diagnostic",
 "Listarea criteriilor (structură VD, histologie, ECG/Holter, familie, MSC <35 ani).",
 ["Anomaliile structurale ale VD sau ale tractului de ejecție, la eco sau IRM, sunt criterii.","Anomaliile de repolarizare sau de conducere, inclusiv ECG-ul cu semnal mediat, sunt criterii, alături de înlocuirea fibro-grăsoasă la biopsie.","TV sau ESV frecvente la Holter, o rudă de grad I sau II cu CMA și MSC prematură (<35 de ani) prin CMA completează criteriile.","Nu: un test de efort negativ nu este criteriu de diagnostic suficient.","Nu: înlocuirea fibro-grăsoasă la biopsie este un criteriu de diagnostic."]],
 [8,"Elimină histologia fibro-grăsoasă — criteriu de lucru explicit — și o înlocuiește cu un test de efort negativ."],["<35 ani","fibro-grăsoasă"]),

q("cardiologie-adv-194",["Cardiomiopatia dilatativă:",
 ["are prevalență 7-12/100.000, cu disfuncție sistolică","forma familială este predominant autozomal dominantă","poate fi produsă de alcool, chimioterapie sau cobalt","distrofina: forma AD; lamin A/C: forma X-linkată","grosime parietală marcat crescută, ca în CMH"],"ABC",1122,"CMD — 7-12/100.000, distrofină, toxice",
 "Potrivirea distrofinei X-linkate versus lamin A/C AD și a listei toxice/infecțioase sporadice.",
 ["Prevalența este de 7-12/100.000, cu dilatare ventriculară și disfuncție sistolică, la grosime parietală prezervată.","Forma familială este predominant autozomal dominantă, cu peste 20 de loci; distrofina ține de forma X-linkată, lamin A/C de forma AD.","Cauzele sporadice includ miocardita, toxicele (alcool, chimioterapie, cobalt, plumb, mercur, arsen), bolile autoimune, endocrine și neuromusculare.","Nu: atribuirea este inversată; distrofina explică forma X-linkată, iar lamin A/C forma autozomal dominantă.","Nu: grosimea parietală este prezervată, nu crescută ca în CMH."]],
 [8,"Inversează distrofina (XL) cu lamin a/c (AD) și pune hipertrofia CMH pe CMD."],["7-12 cazuri","Distrofină"]),

q("cardiologie-adv-195",["Amiloidoza cardiacă:",
 ["biopsia endomiocardică este frecvent utilă diagnostic","amiloidul reapare frecvent după transplantul cardiac","transplantul hepatic poate fi eficient în forma familială","cateterismul nu ajută la diferențierea de constricție","insuficiența cardiacă și emboliile nu se tratează"],"ABC",1124,"Amiloidoză — Biopsie, transplant hepatic",
 "Rolul biopsiei, al recurenței post-transplant cardiac și al transplantului hepatic în forma familială.",
 ["Spre deosebire de alte cardiomiopatii, biopsia endomiocardică este frecvent utilă și poate confirma amiloidul.","Prognosticul este mai grav decât în alte forme, iar amiloidul reapare des după transplantul cardiac.","În forma familială (prealbumină mutantă), transplantul hepatic poate fi eficient și poate inversa anomaliile cardiace.","Nu: cateterismul, uneori după încărcare volemică, ajută la diferențierea de constricție.","Nu: insuficiența cardiacă și emboliile se tratează; transplantul cardiac se discută în formele idiopatice severe."]],
 [8,"Neagă utilitatea biopsiei — tocmai excepția amiloidului — și a transplantului hepatic familial."],["prealbumină","Biopsia endomiocardică"]),

q("cardiologie-adv-196",["Tahicardiomiopatia:",
 ["rezultă din tahicardii supraventriculare sau ventriculare prelungite","funcția se poate recupera după cardioversie sau ablație","este o formă de Tako-tsubo, cu balonizare apicală","apare caracteristic în ultimul trimestru al sarcinii","duce la pierderea ireversibilă a funcției ventriculare"],"AB",1124,"Cardiomiopatii dobândite — Tahicardiomiopatia",
 "Recunoașterea CMD-ului indus de tahicardie prelungită și a reversibilității după cardioversie/ablație.",
 ["Perioadele lungi de tahicardie supraventriculară sau ventriculară pot conduce la cardiomiopatie dilatativă.","Cardioversia și ablația pot restabili ritmul sinusal și permit recuperarea funcției.","Nu: Tako-tsubo are alt mecanism (descărcare catecolaminică, balonizare apicală).","Nu: cardiomiopatia peripartum, nu tahicardiomiopatia, este legată de sarcină.","Nu: funcția se poate recupera după controlul ritmului."]],
 [8,"Suprapune tahicardiomiopatia peste Tako-tsubo sau peripartum, trei entități consecutive pe aceeași pagină."],["Tahicardiomiopatia","Cardioversia"]),

q("cardiologie-adv-197",["Pericardul și bolile pericardice:",
 ["sac fibros extern și sac seros intern","prezentări: pericardită, revărsat, tamponadă, constricție","cauze: virusuri Coxsackie, uremia, mixedemul, sindromul Dressler","volumul normal de lichid pericardic: 200-500 ml","pericardita acută predomină la femeile vârstnice"],"ABC",1125,"Pericard — Anatomie 20-49 ml și etiologii",
 "Reținerea volumului 20-49 ml și a spectrului clinic, plus etiologiile Dressler/uremie/mixedem.",
 ["Pericardul are un sac fibros extern și unul seros intern (epicard visceral și pericard parietal), cu 20-49 ml de lichid lubrifiant.","Bolile pericardice se prezintă ca pericardită acută, incesantă sau cronică, revărsat sau tamponadă, constricție ori formațiuni.","Etiologiile includ virusurile (Coxsackie, echo, HIV), sindromul Dressler, uremia, mixedemul, iradierea și post-pericardiotomia.","Nu: în mod normal pericardul conține 20-49 ml de lichid; 200-500 ml ar fi deja un revărsat mare.","Nu: pericardita acută predomină la bărbații tineri."]],
 [8,"Umflă lichidul normal de la 20-49 ml la 200-500 ml și inversează sexul/vârsta."],["20-49 ml","Sindrom Dressler"]),

q("cardiologie-adv-198",["Pericardita acută:",
 ["durerea se poate ameliora la aplecarea înainte","ECG: ST concav în sus și PR subdenivelat","febra >38°C sau revărsatul mare impun spitalizarea","70-90% din cazuri sunt autolimitate","atleții pot relua efortul după 48 de ore"],"ABCD",1125,"Pericardită acută — PR, febră >38°C, 70-90%",
 "Completarea criteriilor cu subdenivelarea PR, ponderea 70-90% autolimitată și pragul de spitalizare >38°C.",
 ["Durerea poate fi pleuritică, exacerbată de mișcare și ameliorată de aplecarea înainte.","ECG-ul arată ST concav în sus (în șa), ST reciproc coborât în aVR și V1 și subdenivelare PR.","Febra >38°C, debutul subacut, revărsatul mare, tamponada sau lipsa de răspuns impun spitalizarea.","70-90% dintre pericarditele acute sunt autolimitate.","Nu: atleții evită efortul cel puțin 3 luni."]],
 [8,"Comprimă interdicția de efort a atleților de la 3 luni la 48 de ore."],["70-90%",">38°C"]),

q("cardiologie-adv-199",["Aproximativ 20% dintre pericarditele acute evoluează spre:",
 ["pericardită idiopatică recurentă","vindecare completă în primele 24 de ore","endocardită infecțioasă pe proteza valvulară","CMH obstructivă","tamponadă cronică, cu cord mic calcificat"],"A",1126,"Pericardită — Recurența 20%",
 "Reținerea ponderii de 20% a recurenței idiopatice după un episod acut.",
 ["Circa 20% dintre pericarditele acute evoluează spre pericardită idiopatică recurentă, care poate fi incesantă.","Nu: majoritatea cazurilor sunt autolimitate în săptămâni, iar 20% evoluează spre recurență.","Nu: endocardita pe proteză este o altă entitate, fără legătură cu evoluția pericarditei.","Nu: cardiomiopatia hipertrofică nu este o sechelă a pericarditei.","Nu: proporția de 20% se referă la recurența idiopatică, nu la tamponadă cronică."]],
 [8,"Înlocuiește recurența de 20% cu vindecare într-o zi sau cu endocardită/CMH."],["20% din cazuri","incesantă"]),

q("cardiologie-adv-200",["Indicele gleznă-braț (IGB) și duplexul în boala arterială periferică:",
 ["IGB 0,5-0,9 se asociază cu claudicația intermitentă","IGB <0,5 indică ischemie critică de membru","IGB fals crescut pe arterele incompresibile","IGB 1,3-1,5 definește ischemia critică de membru","duplexul are sensibilitate 50% și specificitate 40%"],"ABC",1128,"BVP — IGB 0,5-0,9 versus <0,5",
 "Aplicarea benzilor IGB și a falsei creșteri pe artere calcificate.",
 ["IGB 0,5-0,9 corespunde claudicației intermitente.","IGB <0,5 corespunde ischemiei critice de membru.","Pe artere incompresibile (diabet, boală renală) IGB este fals crescut, iar presiunea de la degete este mai sensibilă.","Nu: IGB 1,3-1,5 sugerează artere incompresibile, nu ischemie critică.","Nu: duplexul are sensibilitate de 87% și specificitate de 95% față de angiografie."]],
 [8,"Inversează benzile IGB (pune 1,3-1,5 pe ischemia critică) și degradează duplexul de la 87/95% la 50/40%."],["0,5-0,9","< 0,5"]),

q("cardiologie-adv-201",["Boala arterială periferică:",
 ["prevalență la vârstă medie: 7% bărbați, 4,5% femei","Fontaine II: claudicație; III: durere de repaus","boala aorto-iliacă nu produce disfuncție erectilă","predomină la femeile tinere, fără ateroscleroză","Fontaine I: gangrenă; IV: forma asimptomatică"],"AB",1128,"BVP — 7%/4,5% și Fontaine",
 "Reținerea prevalențelor 7/4,5% și a celor patru stadii Fontaine, plus sindromul aorto-iliac.",
 ["Boala arterială periferică este prezentă la 7% dintre bărbații și 4,5% dintre femeile de vârstă medie.","Stadiile Fontaine: I asimptomatic, II claudicație, III durere de repaus/nocturnă, IV necroză sau gangrenă.","Nu: boala aorto-iliacă poate da durere de fesă, șold sau coapsă și disfuncție erectilă.","Nu: boala este aterosclerotică și mai frecventă la bărbații de vârstă medie.","Nu: stadiile sunt inversate; I este asimptomatic, iar IV înseamnă necroză sau gangrenă."]],
 [8,"Inversează stadiile Fontaine I/IV și mută epidemiologia pe femeia tânără fără ateroscleroză."],["7%","4,5%"]),

q("cardiologie-adv-202",["Imagistica în boala arterială periferică:",
 ["duplexul are sensibilitate 87% și specificitate 95%","angio-IRM: ambele membre, fără radiații ionizante","angio-CT este alternativa când IRM este contraindicată","angiografia cu subtracție digitală, ca screening inițial","IGB este fals scăzut pe arterele calcificate"],"ABC",1128,"BVP — Duplex 87%/95% și angio-IRM",
 "Ierarhia duplex → IRM → CT, cu ASD rezervată imediat înaintea intervenției.",
 ["Ecografia duplex, de obicei prima linie, are sensibilitate 87% și specificitate 95% față de angiografie.","Angio-IRM cu contrast vizualizează ambele membre cu o singură injecție, fără radiație ionizantă.","Angio-CT este alternativa când IRM este contraindicată; calcificările extinse pot masca stenozele.","Nu: ASD necesită canulare arterială și contrast iodat și se folosește imediat înaintea intervenției, nu ca screening.","Nu: pe arterele calcificate IGB este fals crescut, iar presiunea de la degete este mai sensibilă."]],
 [8,"Promovează ASD-ul invaziv ca screening și inversează direcția erorii IGB pe calcificare."],["87%","95%"]),

q("cardiologie-adv-203",["Managementul claudicației intermitente:",
 ["control agresiv al factorilor de risc cardiovascular","exerciții supervizate, minimum 2 ore pe săptămână","la diabetici, control glicemic atent și examinarea picioarelor","repaus prelungit la pat, pentru protecția plăcii","renunțarea la IGB, diagnosticul fiind pur clinic"],"ABC",1128,"BVP — Efort 2 ore/săptămână",
 "Protocolul de 2 ore/săptămână până la durerea maximală și controlul riscului CV asociat.",
 ["Riscul asociat de boală coronariană și cerebrovasculară justifică controlul agresiv al factorilor de risc.","Programul supervizat de exerciții aerobe, până la durerea maximală, durează cel puțin 2 ore pe săptămână.","La diabetici sunt necesare control glicemic atent și evaluări regulate ale picioarelor.","Nu: tratamentul include efort supervizat, nu repaus la pat.","Nu: IGB este folosit pentru stratificarea severității."]],
 [8,"Înlocuiește programul de 2 ore până la durere cu repaus la pat, inversul reabilitării."],["2 ore pe săptămână","claudicaţie intermitentă"]),

q("cardiologie-adv-204",["Diagnosticul diferențial al claudicației include:",
 ["claudicația de canal spinal, cu pulsuri prezente","osteoartrita de șold sau genunchi și neuropatia periferică","claudicația venoasă, la pacienți cu TVP în antecedente","claudicația de canal spinal, cu pulsuri absente bilateral","boala Buerger la femei vârstnice nefumătoare"],"ABC",1128,"BVP — Diagnostic diferențial",
 "Opunerea pulsurilor prezente din canalul spinal față de Buerger-ul tânărului fumător.",
 ["În claudicația de canal spinal pulsurile sunt prezente.","Osteoartrita de șold sau genunchi și neuropatia periferică (amorțeală, furnicături) intră în diagnosticul diferențial.","Claudicația venoasă (senzație de tensiune la mers, TVP în antecedente) și boala Buerger intră în diagnosticul diferențial.","Nu: în claudicația de canal spinal pulsurile sunt prezente, nu absente.","Nu: boala Buerger apare la bărbați tineri, mari fumători."]],
 [8,"Atribuie canalului spinal pulsuri absente și mută Buerger-ul pe femeia vârstnică nefumătoare."],["canal spinal","boala Buerger"]),

q("cardiologie-adv-205",["Ateroscleroza periferică prematură (<45 de ani) se poate asocia cu:",
 ["trombofilie și hiperhomocisteinemie","hipohomocisteinemie","hipotiroidism mixedematos, ca etiologie dominantă","pericardită recurentă familială","stadiul Fontaine 0"],"A",1128,"BVP — Ateroscleroză prematură <45 ani",
 "Reținerea asocierii <45 de ani cu trombofilie și hiperhomocisteinemie.",
 ["Textul leagă ateroscleroza prematură (<45 de ani) de trombofilie și hiperhomocisteinemie.","Nu: ateroscleroza prematură se asociază cu hiperhomocisteinemie și trombofilie, nu cu homocisteină scăzută.","Nu: textul leagă ateroscleroza prematură (<45 de ani) de trombofilie și hiperhomocisteinemie; hipotiroidismul nu este etiologia ei dominantă.","Nu: pericardita familială nu explică boala arterială periferică prematură.","Nu: clasificarea Fontaine începe de la stadiul I."]],
 [8,"Omite trombofilia/hiperhomocisteinemia — explicația citată a BVP sub 45 de ani."],["sub 45 ani","hiperhomocisteinemie"]),

q("cardiologie-adv-206",["Ischemia cronică de membru inferior:",
 ["membre reci, piele uscată, fără pilozitate, pulsuri diminuate","ulcerații, degete de culoare închisă sau gangrenă","durerea de repaus se calmează la ridicarea piciorului","membre calde, cu pulsuri săltărețe, hiperdinamice","perimetrul de mers este nereproductibil"],"AB",1128,"BVP — Semne și durere de repaus",
 "Recunoașterea tegumentelor ischemice și a ameliorării durerii de repaus prin atârnarea piciorului.",
 ["Membrele sunt reci, cu piele uscată, pilozitate absentă și pulsuri diminuate sau absente.","Pot apărea ulcerații, colorație închisă a degetelor sau gangrenă; abdomenul se palpează pentru anevrism de aortă.","Nu: durerea de repaus trezește din somn și este calmată parțial de atârnarea piciorului sau de podeaua rece.","Nu: căldura și pulsul săltăreț țin de circulația hiperdinamică, nu de ischemie.","Nu: perimetrul de mers poate fi reproductibil."]],
 [8,"Atribuie ischemiei pulsul săltăreț al regurgitării aortice și neagă reproductibilitatea perimetrului de mers."],["Durere de repaus","anevrism de aortă"]),

q("cardiologie-adv-207",["Cardiomiopatia Tako-tsubo:",
 ["formele severe pot avea șoc cardiogen și edem pulmonar","beta-blocante cu prudență la gradient VS semnificativ","funcția se recuperează de obicei în 4-6 săptămâni","vasodilatatoarele sunt prima linie la gradientul VS","ocluzie coronariană proximală, ca în STEMI"],"ABC",1124,"Tako-tsubo — Șoc, gradient și beta-blocant",
 "Nișa beta-blocantului cu prudență la gradient VS și a prezentării cu șoc/EPA.",
 ["Cazurile severe se pot prezenta cu șoc cardiogen și edem pulmonar.","Pacienții cu gradient VS semnificativ pot răspunde la beta-blocante, administrate cu prudență.","Recuperarea completă a funcției survine de obicei în 4-6 săptămâni, cu posibile recurențe.","Nu: vasodilatatoarele agravează obstrucția în CMH; textul nu le pune ca primă linie în Tako-tsubo cu gradient.","Nu: coronarele sunt tipic neobstruate."]],
 [8,"Ocluzează coronarele — tocmai elementul care desparte Tako-tsubo de STEMI — și pune vasodilatatorul pe gradient."],["şoc cardio","4-6 săptămâni"]),

q("cardiologie-adv-208",["Miocardita acută:",
 ["o minoritate agravată poate necesita ECMO sau transplant","se face adesea coronarografie pentru excluderea ischemiei","miocardita cu celule gigante: sarcoidoză, timoame","serologia virală înlocuiește biopsia ca standard de aur","activitatea sportivă se reia la 48 de ore"],"ABC",1119,"Miocardită — ECMO, coronarografie, celule gigante",
 "Rolul ECMO/transplantului în minoritatea agravată și al coronarografiei de excludere a ischemiei.",
 ["Un mic procent evoluează agravat și poate necesita transfer într-un centru cu ECMO și/sau transplant.","Angiografia coronariană se face adesea pentru a exclude ischemia acută ca mimă.","În faza acută se recomandă repaus la pat; celulele gigante se asociază cu sarcoidoză, timoame și boli autoimune.","Nu: serologia virală de obicei nu este utilă; biopsia este standardul de aur în forma fulminantă.","Nu: sportul se evită 6 luni."]],
 [8,"Pune serologia virală — explicit neutilă — în locul biopsiei de la fulminant și comprimă interdicția sportului la 48 de ore."],["extracorporală","celule gigante"]),

q("cardiologie-adv-209",["Managementul țintit al temperaturii după stopul cardiac:",
 ["în studiul din 2013, ținta de 33°C a fost superioară celei de 36°C","beneficiu neurologic, nu și de mortalitate, la ritmuri neșocabile","28°C timp de 72 de ore este standardul actual","importanța hipotermiei terapeutice rămâne încă neclară","hipertermia la 40°C scade mortalitatea în ritmurile șocabile"],"BD",1048,"Post resuscitare — Studiul de temperatură 2013",
 "Reținerea rezultatelor similare la 33°C și 36°C, a beneficiului neurologic (nu și de mortalitate) la ritmurile neșocabile și a rolului încă neclar al hipotermiei terapeutice.",
 ["Nu: studiul multinațional din 2013 a arătat rezultate similare ale hipotermiei moderate (33°C) față de normotermie (36°C).","Într-un grup cu ritmuri neșocabile s-au raportat rezultate neurologice mai bune, dar nu și o mortalitate mai mică.","Nu: 28°C timp de 72 de ore nu este protocolul citat; comparația relevantă este 33°C față de 36°C.","Concluzia textului este că importanța hipotermiei terapeutice este încă neclară.","Nu: hipertermia nu este o strategie descrisă; datele privesc hipotermia moderată (33°C) și normotermia (36°C)."]],
 [8,"Confundă țintele 33/36°C cu o hipotermie profundă de 28°C, deși textul lasă importanța metodei neclară."],["33°C","normotermie"]),

q("cardiologie-adv-210",["Automatismul accelerat se caracterizează prin:",
 ["depolarizare diastolică lentă până la potențialul prag","creșterea pantei depolarizării diastolice sau modificarea pragului","adrenalina produce tahicardie sinusală și ritmuri de scăpare","un miez inexcitabil cicatricial, ca element necesar","mecanismul majorității tahicardiilor paroxistice regulate"],"ABC",1051,"Aritmii — Automatismul accelerat",
 "Diferențierea automatismului (panta depolarizării diastolice, potențialul prag) de reintrarea în jurul unui miez inexcitabil.",
 ["Celulele pacemaker se depolarizează lent în diastolă până la potențialul prag, apoi descarcă potențialul de acțiune.","Automatismul se accelerează prin creșterea pantei depolarizării diastolice sau prin modificarea potențialului prag.","Stimularea simpatică eliberează adrenalină, care produce tahicardie sinusală, ritmuri de scăpare și ritmuri joncționale accelerate.","Nu: miezul inexcitabil (cicatricea) este elementul necesar reintrării, nu automatismului.","Nu: majoritatea tahicardiilor paroxistice regulate au la bază reintrarea, nu automatismul."]],
 [8,"Atribuie automatismului miezul cicatricial al reintrării, două mecanisme consecutive din Fig. 30.38."],["potenţialul prag","ritmuri de scăpare"]),

q("cardiologie-adv-211",["Cauze extrinseci de bradicardie sinusală și reflexul Bezold-Jarisch:",
 ["hipotermia, hipotiroidismul și icterul colestatic","beta-blocantele, digitalicele și alte antiaritmice","Bezold-Jarisch: bradicardie și vasodilatație periferică","hipertiroidismul netratat, ca etiologie extrinsecă dominantă","ischemia acută sau infarctul nodului sinusal"],"ABC",1052,"Bradicardii — Cauze extrinseci și Bezold-Jarisch",
 "Potrivirea listei de cauze extrinseci (inclusiv icterul colestatic) și a reflexului care asociază bradicardia cu vasodilatația.",
 ["Hipotermia, hipotiroidismul, icterul colestatic (și hipertensiunea intracraniană) sunt cauze extrinseci de bradicardie sinusală.","Tratamentul cu beta-blocante, digitalice sau alte antiaritmice este o cauză extrinsecă de bradicardie sinusală.","Reflexul Bezold-Jarisch poate produce bradicardie (sinusală, oprire sinusală sau BAV) și vasodilatație periferică.","Nu: hipertiroidismul produce tahicardie, nu bradicardie sinusală.","Nu: ischemia sau infarctul nodului sinusal sunt cauze intrinseci, nu extrinseci."]],
 [8,"Mută ischemia nodului — cauză intrinsecă — în lista extrinsecă și pune hipertiroidismul pe bradicardie."],["icterul colestatic","Bezold- Jarisch"]),

q("cardiologie-adv-212",["Sindromul de tahicardie ortostatică posturală (POTS) și sincopa iatrogenă:",
 ["POTS: tahicardie ortostatică marcată, TA normală sau ușor redusă","vasoconstricția periferică insuficientă, compensată tahicardic","antihipertensivele, triciclicele și neurolepticele pot produce sincopă","POTS: hipotensiune severă, fără creșterea frecvenței","sincopa iatrogenă se previne crescând dozele și asociind sedative"],"ABC",1052,"Bradicardii — POTS și sincopa medicamentoasă",
 "Recunoașterea vasoconstricției insuficiente ca mecanism al POTS și a claselor de medicamente care precipită sincopa, mai ales la vârstnici.",
 ["POTS înseamnă creșterea acută semnificativă a frecvenței cardiace, cu TA normală sau ușor redusă la ortostatism.","Mecanismul POTS este vasoconstricția periferică insuficientă, compensată prin creșterea frecvenței cardiace.","Medicamentele antihipertensive, antidepresivele triciclice și neurolepticele pot cauza sincopă, mai ales la vârstnici.","Nu: în POTS frecvența cardiacă crește semnificativ, iar TA este normală sau ușor redusă.","Nu: se adaptează posologia și se evită asocierea a două medicamente care pot produce pierderea conștienței."]],
 [8,"Inversează hemodinamica POTS (tahicardie cu TA păstrată) într-o hipotensiune fără răspuns cronotrop."],["ortostatică posturală","neurolep"]),

q("cardiologie-adv-213",["Cardiostimularea temporară în bradicardia sinusală este indicată:",
 ["în cauzele reversibile, până la revenirea sinusală","în afectarea degenerativă cronică, până la implantul permanent","ca substitut definitiv al stimulării DDD","condiționat de eșecul prealabil al ablației de nod AV","în POTS, ca primă linie, înaintea măsurilor de hidratare"],"AB",1053,"Bradicardii — Stimulare temporară",
 "Delimitarea indicațiilor stimulării temporare: cauză reversibilă până la ritmul sinusal versus punte către stimulatorul permanent.",
 ["Stimularea temporară se folosește în cauzele reversibile, până la restaurarea ritmului sinusal.","În afectarea cronică degenerativă, stimularea temporară face puntea până la implantarea stimulatorului permanent.","Nu: boala de nod simptomatică poate necesita stimulare DDD permanentă, pe care temporarul nu o înlocuiește.","Nu: ablația de nod AV nu este un pas prealabil al stimulării temporare din bradicardia sinusală.","Nu: POTS nu are ca primă linie cardiostimularea temporară."]],
 [8,"Transformă puntea temporară într-un substitut definitiv al DDD, inversând treptele de tratament."],["Cardiostimularea temporară","restaurarea ritmului sinusal"]),

q("cardiologie-adv-214",["Blocul AV complet (Cadranul 30.13):",
 ["poate urma chirurgiei cardiace: valvă aortică, by-pass, corecție de DSV","poate fi iatrogen, după ablația nodului AV","apare în boli neuromusculare, de exemplu distrofia Duchenne","are ca etiologie dominantă hipertiroidismul, înaintea fibrozei idiopatice","nu are printre cauze infecțiile sau bolile reumatice"],"ABC",1055,"BAV complet — Chirurgie, iatrogen, Duchenne",
 "Completarea cauzelor de BAV complet cu cele chirurgicale, iatrogene și neuromusculare (Duchenne), pe lângă ischemie.",
 ["Chirurgia cardiacă (înlocuirea valvei aortice, by-pass-ul coronarian, corectarea DSV) figurează printre cauzele BAV complet.","Ablația cu radiofrecvență a nodului AV figurează printre cauzele iatrogene de BAV complet.","Distrofia musculară Duchenne este exemplul de boală neuromusculară care produce BAV complet.","Nu: hipertiroidismul nu este cauza dominantă a BAV complet din cadran.","Nu: pe lângă ischemie, chirurgie și bolile neuromusculare, cadranul include și infecții și boli reumatice."]],
 [8,"Reduce etiologia BAV complet la ischemie, deși cadranul include AVR, DSV și Duchenne."],["Duchenne","By-pass coronarian"]),

q("cardiologie-adv-215",["Blocul bifascicular:",
 ["asociază BRD cu hemiblocul antero-superior sau postero-inferior","blocarea fasciculului rămas produce BAV complet","cu sincope impune studiu electrofiziologic","este identic cu hemiblocul antero-superior izolat, fără BRD","are QRS constant sub 0,10 sec, fără risc de BAV"],"ABC",1056,"Blocuri — Blocul bifascicular",
 "Recunoașterea combinației BRD + hemibloc și a riscului ca blocarea fasciculului rămas să producă BAV complet.",
 ["Blocul bifascicular este combinația dintre blocul de ramură dreaptă și hemiblocul antero-superior sau postero-inferior.","Blocarea fasciculului rămas determină BAV complet.","Sincopele, prin bloc complet intermitent sau tahiaritmii ventriculare, impun monitorizare ECG și studiu electrofiziologic.","Nu: hemiblocul antero-superior izolat, fără bloc de ramură dreaptă, nu este bloc bifascicular.","Nu: blocul complet de ramură presupune QRS ≥0,12 sec, iar riscul de BAV complet există."]],
 [8,"Reduce bifascicularul la un hemibloc izolat și anulează riscul de BAV la blocarea fasciculului rămas."],["Blocul bifascicular","hemibloc"]),

q("cardiologie-adv-216",["Tahicardia sinusală secundară:",
 ["are drept cauze cronice sarcina, anemia și hipertiroidismul","are drept cauze cronice efortul fizic intens, durerea și febra","are ca etiologie dominantă blocul de ramură stângă","are drept cauze hipotermia și icterul colestatic","se tratează cu ivabradină, fără căutarea cauzei declanșatoare"],"A",1057,"TSV — Cauze cronice de tahicardie sinusală",
 "Reținerea cauzelor cronice de tahicardie sinusală (sarcină, anemie, hipertiroidism, exces de catecolamine), distincte de cauzele acute.",
 ["Sarcina, anemia, hipertiroidismul și excesul de catecolamine sunt cauze cronice de tahicardie sinusală.","Nu: efortul fizic, durerea și febra sunt cauze acute, nu cronice, de tahicardie sinusală.","Nu: blocul de ramură stângă este o tulburare de conducere, nu o cauză de tahicardie sinusală.","Nu: hipotermia și icterul colestatic produc bradicardie sinusală, nu tahicardie.","Nu: identificarea factorului declanșator este preferabilă tratării răspunsului compensator."]],
 [8,"Mută cauzele de bradicardie (hipotermie, icter) pe tahicardia sinusală cronică."],["hipertiroidismul","excesul de catecolamine"]),

q("cardiologie-adv-217",["Căile accesorii (fascicule Kent) și sindromul WPW:",
 ["predomină în peretele liber sau septal","căile bidirecționale, vizibile pe ECG de suprafață, sunt manifeste","WPW: palpitații, PR alungit și undă delta","fibrele Mahaim pătrund în miocard pe inelul mitral stâng","căile ascunse conduc anterograd și dau undă delta în sinus"],"AB",1058,"TSV — Fascicule Kent, căi manifeste și WPW",
 "Potrivirea localizării căilor Kent (perete liber/septal) și a căilor manifeste cu definiția WPW (palpitații + PR scurt și undă delta).",
 ["Cele mai frecvente căi Kent sunt localizate în peretele liber sau septal.","Căile bidirecționale vizibile pe ECG-ul de suprafață se numesc căi manifeste.","Nu: WPW asociază istoricul de palpitații cu preexcitația pe ECG, adică PR scurt și undă delta.","Nu: fibrele Mahaim pătrund în miocardul ventricular în regiunea ramurii drepte.","Nu: căile ascunse conduc numai de la ventricul la atriu și nu sunt vizibile în ritm sinusal."]],
 [8,"Inversează Mahaim (ramură dreaptă) cu inelul mitral și face din calea ascunsă o cale anterogradă cu undă delta."],["fascicule Kent","undă delta"]),

q("cardiologie-adv-218",["Adenozina în tratamentul acut al AVNRT/AVRT:",
 ["inițial 6 mg i.v., apoi 12 mg la nevoie","nucleozidă purinică, dă BAV complet o fracțiune de secundă","are efecte adverse scurte; precauție la astmatici (bronhospasm)","influențează foarte rar tahicardiile ventriculare","este elecția în FA preexcitată cu QRS larg, ca și verapamilul"],"ABCD",1059,"AVNRT/AVRT — Adenozina 6/12 mg",
 "Aplicarea dozelor de 6 apoi 12 mg, a BAV-ului tranzitor și a precauției la astmatici, nu a folosirii în FA preexcitată.",
 ["Schema este de 6 mg i.v. în bolus, apoi 12 mg dacă este nevoie.","Adenozina este o nucleozidă purinică cu acțiune scurtă, care produce BAV complet pentru o fracțiune de secundă.","Durerea toracică, senzația de moarte iminentă, bronhospasmul și roșeața sunt de scurtă durată; se folosește cu precauție la astmatici.","Adenozina influențează foarte rar tahicardiile ventriculare.","Nu: verapamilul și digoxinul sunt interzise în FA cu WPW, iar adenozina nu este elecția în FA preexcitată cu QRS larg."]],
 [8,"Extinde adenozina — utilă în AVNRT — la FA preexcitată, unde textul interzice blocantele de nod."],["6 mg i.v.","12 mg"]),

q("cardiologie-adv-219",["Eficiența de durată a verapamilului, diltiazemului și beta-blocantelor în AVNRT/AVRT:",
 ["60-80% dintre cazuri","10% dintre cazuri","96% dintre cazuri","1% dintre cazuri","50% dintre cazuri"],"A",1059,"AVNRT/AVRT — Eficiența 60-80%",
 "Reținerea eficienței de 60-80% a blocantelor de nod AV, distinctă de cifrele ablației (96% succes, 1% BAV).",
 ["Textul citează o eficiență de 60-80% a verapamilului, diltiazemului și beta-blocantelor.","Nu: 10% subestimează; eficiența este de 60-80% dintre cazuri.","Nu: 96% este rata de succes a modificării căii lente, nu a tratamentului medicamentos.","Nu: 1% este riscul de BAV complet la ablația căii lente.","Nu: eficiența medicamentoasă este de 60-80%; recurența după ablația unei căi accesorii este de 5%."]],
 [8,"Confundă 60-80% al medicamentelor cu 96% al ablației de cale lentă, două procente alăturate pe aceeași pagină."],["60-80%","Verapamilul"]),

q("cardiologie-adv-220",["Fibrilația atrială familială și cea din stenoza mitrală reumatismală:",
 ["forma familială: gene de pe cromozomii 10, 6, 5 și 4","pe stenoză mitrală, debutul FA agravează mult insuficiența cardiacă","răspunsul ventricular depinde de nodul AV și de tonusul vegetativ","genele implicate nu includ canale de sodiu sau de potasiu","pe stenoză mitrală, FA ameliorează prognosticul hemodinamic"],"ABC",1060,"Fibrilația atrială — Cromozomi 10/6/5/4 și SM reumatismală",
 "Potrivirea locilor cromozomiali ai FA familiale cu deteriorarea hemodinamică de la debutul FA pe stenoza mitrală.",
 ["Defectele genelor de pe cromozomii 10, 6, 5 și 4 se asociază cu FA familială.","Când FA este cauzată de stenoza mitrală reumatismală, debutul ei corespunde unei agravări considerabile a insuficienței cardiace.","Răspunsul ventricular depinde de proprietățile nodului AV și de echilibrul simpatic–parasimpatic.","Nu: genele implicate privesc canale de sodiu și de potasiu, proteine de joncțiune gap și izomerismul.","Nu: pe stenoza mitrală, debutul FA agravează considerabil insuficiența cardiacă."]],
 [8,"Anulează agravarea clasică a stenozei mitrale la debutul FA și reduce genetica familială la canalele de calciu."],["cromozomii 10, 6, 5","stenoză mitrală reumatismală"]),

q("cardiologie-adv-221",["Riscul anual de AVC ischemic la un scor CHA2DS2-VASc de 1:",
 ["0%, fără indicație de anticoagulare","1,3%, anticoagulare de discutat la bărbați","2,2%, cu anticoagulare orală inițiată imediat","peste 5%, cu anticoagulare orală pe termen lung","3,2%, cu anticoagulare orală la ambele sexe"],"B",1062,"Fibrilația atrială — CHA2DS2-VASc 1 punct",
 "Reținerea riscului de 1,3% la 1 punct CHA2DS2-VASc (anticoagulare de luat în considerare la bărbați), între 0% (scor 0) și 2,2% (2 puncte).",
 ["Nu: riscul de 0% corespunde scorului 0; scorul de 1 punct are un risc anual de 1,3%.","Un punct CHA2DS2-VASc înseamnă un risc anual de 1,3%, iar la bărbați se ia în considerare anticoagularea.","Nu: 2,2% corespunde pragului de 2 puncte, nu scorului de 1 punct.","Nu: peste 5% este riscul hemoragic la HAS-BLED ≥3; scorul CHA2DS2-VASc de 1 are un risc de 1,3%.","Nu: scorul de 1 punct corespunde unui risc anual de 1,3%, nu de 3,2%."]],
 [8,"Confundă 1,3% (1 punct) cu 0% sau 2,2%, treptele adiacente ale aceluiași cadran."],["1,3% risc","1 puncte"]),

q("cardiologie-adv-222",["Scorul HAS-BLED:",
 ["include hipertensiunea cu TA sistolică ≥160 mmHg","include AVC, hemoragia, INR labil, funcția renală sau hepatică","include vârsta ≥65 de ani, medicația concomitentă, alcoolul","include diabetul zaharat și sexul feminin, câte un punct","corespunde la 0 puncte unui risc hemoragic anual >5%"],"ABC",1062,"Fibrilația atrială — Itemii HAS-BLED",
 "Listarea componentelor HAS-BLED (inclusiv TAS ≥160 mmHg), distincte de diabetul și sexul feminin din CHA2DS2-VASc.",
 ["Hipertensiunea cu TA sistolică ≥160 mmHg este primul item al scorului HAS-BLED.","Funcția renală sau hepatică anormală, AVC-ul în antecedente, hemoragia și INR-ul labil sunt itemi HAS-BLED.","Vârsta ≥65 de ani, medicația concomitentă și consumul de alcool completează scorul HAS-BLED.","Nu: diabetul zaharat și sexul feminin sunt itemi ai scorului CHA2DS2-VASc, nu ai HAS-BLED.","Nu: scorul 0 are un risc hemoragic de circa 1%; riscul >5% corespunde scorului ≥3."]],
 [8,"Introduce diabetul/sexul din CHA2DS2-VASc în HAS-BLED și inversează riscul scorului 0 cu al scorului ≥3."],["160 mmHg","INR labil"]),

q("cardiologie-adv-223",["DOAC-urile, comparativ cu warfarina, în prevenția AVC din FA:",
 ["blochează specific o singură treaptă a cascadei coagulării","au acțiune rapidă, înjumătățire scurtă, fără monitorizare INR","sunt la fel de eficiente și probabil mai sigure","inhibă simultan factorii vitamina K-dependenți II, VII, IX și X","pot fi înlocuite de antiagregante, alternativa recomandată"],"ABC",1062,"Fibrilația atrială — Factorii II, VII, IX, X versus DOAC",
 "Contrastul inhibiției unei singure trepte a cascadei (DOAC) cu acțiunea warfarinei pe factorii vitamina K-dependenți II, VII, IX și X.",
 ["DOAC-urile blochează specific o singură treaptă a cascadei, pe când warfarina acționează pe factorii vitamina K-dependenți II, VII, IX și X.","DOAC-urile au acțiune mai rapidă, timp de înjumătățire mai scurt, mai puține interacțiuni și nu necesită monitorizarea INR.","Datele din studii arată DOAC-urile la fel de eficiente și probabil mai sigure decât warfarina.","Nu: warfarina, nu DOAC-urile, acționează pe factorii vitamina K-dependenți II, VII, IX și X.","Nu: antiagregantele nu sunt recomandate pentru prevenția AVC în fibrilația atrială."]],
 [8,"Atribuie DOAC-ului spectrul de factori vitamina K al warfarinei, inversând mecanismele."],["factorul 11, VI I, IX","monitorizarea INR"]),

q("cardiologie-adv-224",["Extrasistolele atriale:",
 ["sunt de obicei asimptomatice, uneori resimțite ca bătăi neregulate","au unde P precoce, urmate de obicei de QRS normal","necesită de regulă tratament, chiar dacă nu precipită aritmii","impun ablația nodului AV ca tratament de primă intenție","sunt urmate de QRS larg și de pauză compensatorie completă"],"AB",1063,"Tahiaritmii atriale — Extrasistolele atriale",
 "Recunoașterea benignității uzuale a extrasistolelor atriale, a aspectului ECG și a rezervării beta-blocantului pentru cazurile care precipită aritmii semnificative.",
 ["Extrasistolele atriale sunt cel mai frecvent asimptomatice; uneori sunt resimțite ca bătăi neregulate sau puternice.","Pe ECG apar unde P precoce sau cu morfologie anormală, de cele mai multe ori urmate de complexe QRS normale.","Nu: tratamentul nu este de obicei necesar; beta-blocantele pot fi eficiente dacă extrasistolele precipită aritmii semnificative.","Nu: ablația nodului AV nu este tratamentul de primă linie al extrasistolelor atriale.","Nu: QRS-ul este de obicei normal, iar pauza compensatorie completă este descrisă la extrasistolele ventriculare."]],
 [8,"Promovează ablația de nod — terapie de rezervă a FA — ca tratament al extrasistolei atriale benigne."],["Extrasistolele atriale","beta-blocantele"]),

q("cardiologie-adv-225",["Tahicardia ventriculară susținută:",
 ["durează >30 s, la 120-220 b.p.m., cu unde „a” jugulare intermitente","QRS larg, cu capturi și bătăi de fuziune","la incertitudine, tahicardia cu QRS larg se consideră ventriculară","cu instabilitate hemodinamică impune cardioversie electrică urgentă","la pacientul stabil, se face întâi ablația istmului cavo-tricuspidian"],"ABCD",1063,"TV susținută — Capturi, fuziune și 120-220/min",
 "Reunirea semnelor de disociație AV (unde „a”, zgomot 1 variabil, capturi, fuziuni) cu regula că la incertitudine tahicardia cu QRS larg este ventriculară.",
 ["TV susținută durează peste 30 de secunde, la 120-220 b.p.m., cu unde „a” intermitente la jugulare și zgomot 1 de intensitate variabilă.","ECG-ul arată QRS largi (frecvent ≥0,14 sec), unde P aleatorii, capturi ventriculare și bătăi de fuziune.","Dacă există incertitudine, tahicardia cu QRS larg se consideră ventriculară.","Instabilitatea (hipotensiune, edem pulmonar) impune cardioversie electrică de urgență.","Nu: la pacientul stabil se pot folosi esmolol, antiaritmice de clasa I sau amiodaronă; ablația istmului cavo-tricuspidian ține de flutter."]],
 [8,"Înlocuiește cardioversia instabilului și antiaritmicele stabilului cu ablația de flutter, o procedură de pe pagina anterioară."],["capturi ventriculare","120-220 b.p.m."]),

q("cardiologie-adv-226",["Cauze dobândite de sindrom QT lung:",
 ["hipopotasemia, hipomagnezemia și hipercalcemia","quinidina, sotalolul, triciclicele, macrolidele, metadona","organofosforicele și postul prelungit","hiperkaliemia, ca etiologie electrolitică dominantă","beta-blocantele, contraindicate în QT lung congenital"],"BC",1064,"QT lung dobândit — Cadranul 30.18",
 "Listarea cauzelor dobândite de QT lung: deficitele de K/Mg/Ca, clasele medicamentoase și cauzele diverse (prolaps mitral, post prelungit, distrofie miotonică).",
 ["Nu: cauzele electrolitice sunt hipopotasemia, hipomagnezemia și hipocalcemia, nu hipercalcemia.","Quinidina, disopiramida, sotalolul, amiodarona, triciclicele, fenotiazinele, haloperidolul, macrolidele, quinolonele și metadona prelungesc QT.","Organofosforicele și cauzele diverse (bradicardie, prolaps de valvă mitrală, infarct acut, diabet, post prelungit, distrofie miotonică) sunt enumerate.","Nu: hiperkaliemia nu figurează; cauzele electrolitice sunt deficitele de potasiu, magneziu și calciu.","Nu: beta-blocantele sunt tratamentul de durată al formei congenitale, nu o cauză de QT lung."]],
 [8,"Pune hiperkaliemia — inversul hipoK din tabel — și interzice beta-blocantul, terapia LQTS congenital."],["Hipomagnezemia","Metadonă"]),

q("cardiologie-adv-227",["Extrasistolele ventriculare frecvente și pulsus bigeminus:",
 ["sunt urmate de obicei de pauză compensatorie completă","multe ESV predispun la disfuncție de VS","cu focar unic, mai ales în VD, ablația poate fi foarte eficientă","pulsus bigeminus: fiecare bătaie sinusală e urmată de o extrasistolă","post-infarct se tratează de rutină cu clasa Ic, scăzând mortalitatea"],"ABCD",1066,"ESV — Bigeminism, disfuncție de VS și ablație",
 "Legarea încărcăturii de ESV de disfuncția de VS, a focarului unic (mai ales drept) de ablația eficientă și definirea pulsus bigeminus.",
 ["După ESV urmează de obicei o pauză compensatorie completă, nodul AV sau ventriculul fiind refractar la impulsul sinusal următor.","O frecvență crescută a bătăilor premature predispune la disfuncție de ventricul stâng.","Dacă originea este un singur focar, ablația poate fi foarte eficientă, mai ales pentru focarele din ventriculul drept.","Pulsus bigeminus apare când fiecare bătaie sinusală este urmată regulat de o extrasistolă.","Nu: studiul CAST a arătat creșterea mortalității cu clasa Ic post-infarct; ESV se tratează dacă sunt simptomatice, de obicei cu beta-blocante."]],
 [8,"Reactivează clasa Ic post-infarct — tocmai situația interzisă de CAST — ca tratament de rutină al ESV."],["pulsus bigeminus","ventriculul drept"]),

q("cardiologie-adv-228",["Antiaritmicele de clasă II (beta-blocante):",
 ["previn efectele catecolaminelor asupra potențialului de acțiune","cardioselectivele (β1): metoprolol, bisoprolol, atenolol, acebutolol","încetinesc conducerea AV și previn fibrilația ventriculară post-IMA","scurtează potențialul de acțiune, ca antiaritmicele Ib","sunt contraindicate în tahiaritmiile simptomatice cu boală coronariană"],"ABC",1067,"Antiaritmice — Clasa II (β1 cardioselective)",
 "Potrivirea listei β1-selective (metoprolol, bisoprolol, atenolol, acebutolol) cu efectul pe nodul AV și prevenția FV post-infarct.",
 ["Beta-blocantele acționează prin prevenirea efectelor catecolaminelor asupra potențialului de acțiune.","Beta-blocantele cardioselective (β1) includ metoprololul, bisoprololul, atenololul și acebutololul.","Încetinesc conducerea în nodul AV, sunt antiischemice și antiadrenergice, cu beneficiu post-IMA (prevenția FV) și în IC congestivă.","Nu: scurtarea potențialului de acțiune caracterizează clasa Ib; clasa II acționează predominant pe nodul sinusal și încetinește conducerea AV.","Nu: sunt recomandate ca monoterapie sau în combinație tocmai în tahiaritmiile simptomatice, mai ales la coronarieni."]],
 [8,"Atribuie clasei II scurtarea PA a lidocainei și interzice beta-blocantul la ischemic — indicația citată."],["acebutolol","fibrilaţiei ventriculare"]),

q("cardiologie-adv-229",["Izolarea venelor pulmonare în FA paroxistică:",
 ["procedura durează de obicei peste 4 ore","are complicații majore sub 2% în centrele experimentate","reușește în 70-80% la tineri fără boală structurală","dă fistulă atrio-esofagiană la peste 50% din cazuri","nu are complicații majore cu crioenergie"],"ABC",1068,"Ablație FA — Durata >4 ore și fistula atrio-esofagiană",
 "Memorarea duratei de peste 4 ore, a plafonului de sub 2% al complicațiilor majore (inclusiv fistula atrio-esofagiană) și a succesului de 70-80% la tinerii fără boală structurală.",
 ["Procedura durează de obicei mai mult de 4 ore.","În centrele experimentate, complicațiile importante (AVC, pericardită hemoragică, stenoză de vene pulmonare, fistule atrio-esofagiene) sunt sub 2%.","Succesul pe termen lung de 70-80% privește tinerii cu FA paroxistică, atriu stâng normal și fără boală structurală.","Nu: fistula atrio-esofagiană este o complicație rară; complicațiile majore totale sunt sub 2% în centrele experimentate.","Nu: se folosesc atât radiofrecvența, cât și crioenergia, iar complicațiile nu dispar prin schimbarea sursei de energie."]],
 [8,"Transformă fistula atrio-esofagiană — complicație rară <2% — într-o regulă de peste 50%."],["mai mult de 4 ore","fistule atrio-esofagiene"]),

q("cardiologie-adv-230",["Homeostazia calciului în insuficiența cardiacă:",
 ["calciul extracelular intrat declanșează eliberarea din reticul","relaxarea urmează recaptării în reticul, controlată de oxidul nitric","în IC, curentul de calciu și contracția sunt prelungite","relaxarea este declanșată de eliberarea calciului din reticul","în IC, curentul de calciu este scurtat, accelerând relaxarea"],"ABC",1071,"Insuficiența cardiacă — Curentul de calciu prelungit",
 "Legarea curentului de calciu prelungit din IC de contracția și relaxarea prelungite, cu rolul oxidului nitric în recaptarea calciului.",
 ["La excitarea membranei, calciul extracelular intră rapid prin canale și declanșează eliberarea de calciu din reticulul sarcoplasmic.","Relaxarea urmează recaptării calciului în reticulul sarcoplasmic, proces controlat de modificările oxidului nitric.","În IC, curentul de calciu este prelungit și se asociază cu prelungirea contracției și a relaxării.","Nu: relaxarea urmează recaptării calciului în reticulul sarcoplasmic, nu eliberării lui.","Nu: în IC curentul de calciu este prelungit, cu prelungirea contracției și a relaxării."]],
 [8,"Scurtează curentul de calciu — inversul fiziopatologiei citate — și anulează cuplajul excitație-contracție."],["reticulul sarcoplasmic","oxidului nitric"]),

q("cardiologie-adv-231",["Diagnosticul HFpEF (Cadranul 30.24) necesită:",
 ["simptome caracteristice de insuficiență cardiacă","semne caracteristice de insuficiență cardiacă","FE normală sau ușor redusă, cu VS nedilatat","FE scăzută, ca în HFrEF","absența disfuncției diastolice și a modificărilor structurale"],"ABC",1072,"Insuficiența cardiacă — Cele patru condiții HFpEF",
 "Contrastul celor patru condiții ale HFpEF (simptome, semne, FE normală/ușor redusă cu VS nedilatat, HVS/AS sau disfuncție diastolică) cu triada HFrEF.",
 ["Simptomele caracteristice de insuficiență cardiacă sunt prima condiție a diagnosticului HFpEF.","Semnele caracteristice de insuficiență cardiacă sunt a doua condiție a diagnosticului HFpEF.","FE normală sau ușor redusă cu VS nedilatat, plus modificări structurale (HVS, dilatare de AS) și/sau disfuncție diastolică, completează cele patru condiții.","Nu: FE scăzută definește HFrEF (trei condiții); HFpEF cere patru condiții, cu FE normală sau ușor redusă.","Nu: diagnosticul HFpEF cere modificări structurale relevante (HVS, dilatare de AS) și/sau disfuncție diastolică."]],
 [8,"Reduce HFpEF la triada HFrEF (FE scăzută), deși cadranul cere patru condiții cu FE păstrată."],["HFPEF","atriu stâng"]),

q("cardiologie-adv-232",["Disfuncția sistolică a ventriculului drept poate fi:",
 ["secundară bolilor cronice ale cordului stâng","cauzată de hipertensiunea pulmonară sau de infarctul de VD","identică HFpEF, definită prin FE a VS >50%","un motiv de a evita evaluarea hipertensiunii pulmonare","produsă de stenoza aortică, fără cauze proprii de VD"],"AB",1072,"Insuficiența cardiacă — Disfuncția de ventricul drept",
 "Recunoașterea disfuncției de VD ca urmare a bolilor cronice ale cordului stâng sau a hipertensiunii pulmonare, infarctului de VD, cardiomiopatiei aritmogene și bolilor congenitale.",
 ["Disfuncția sistolică de VD poate fi secundară bolilor cronice ale cordului stâng.","Hipertensiunea pulmonară primară sau secundară, infarctul de VD, cardiomiopatia aritmogenă de VD și bolile congenitale ale adultului pot produce disfuncție de VD.","Nu: HFpEF este un fenotip al ventriculului stâng, nu definiția disfuncției sistolice de VD.","Nu: hipertensiunea pulmonară este tocmai o cauză de căutat în disfuncția de VD.","Nu: stenoza aortică ține de VS; disfuncția de VD are și cauze proprii (infarct de VD, cardiomiopatie aritmogenă de VD)."]],
 [8,"Suprapune DSVD peste HFpEF și anulează hipertensiunea pulmonară, o cauză citată."],["ventriculului drept","hipertensiunea pulmonară"]),

q("cardiologie-adv-233",["IECA în insuficiența cardiacă:",
 ["sunt contraindicați în stenoza de arteră renală","sunt contraindicați în sarcină","sunt contraindicați la antecedente de angioedem","se opresc la tuse, fără trecere pe un ARA","se inițiază în doză maximă, fără monitorizare"],"ABC",1073,"Insuficiența cardiacă — Contraindicațiile IECA",
 "Listarea contraindicațiilor IECA (stenoza de arteră renală, sarcina, angioedemul) și a regulii de inițiere în doză mică.",
 ["Stenoza de arteră renală este o contraindicație a IECA.","Sarcina este o contraindicație a IECA.","Antecedentele de angioedem contraindică IECA.","Nu: tusea orientează către un ARA, nu interzice orice blocadă a sistemului renină-angiotensină-aldosteron.","Nu: IECA se inițiază în doză mică, cu creștere treptată și monitorizarea creatininei."]],
 [8,"Transformă tusea — motiv de trecere pe ARA — într-o interdicție absolută a întregii clase SRAA."],["stenoza de arteră renală","angio-edem"]),

q("cardiologie-adv-234",["Durata medie de internare a unei decompensări de insuficiență cardiacă este de:",
 ["5-10 zile","o zi","4-6 săptămâni","3 săptămâni","sub 12 ore"],"A",1073,"Insuficiența cardiacă — Durata internării",
 "Reținerea duratei medii de internare de 5-10 zile pentru decompensarea insuficienței cardiace.",
 ["Durata medie de internare pentru o decompensare de insuficiență cardiacă este între 5 și 10 zile.","Nu: o zi subestimează; durata medie de internare este de 5-10 zile, iar reinternările sunt frecvente.","Nu: durata medie de internare este de 5-10 zile, nu de câteva săptămâni.","Nu: 3 săptămâni (de terapie intensivă) nu este cifra citată; media este de 5-10 zile.","Nu: decompensarea cere de obicei o internare de 5-10 zile, nu câteva ore de diuretic oral."]],
 [8,"Comprimă internarea de 5-10 zile la 24 de ore sau o dilată la 6 luni, ferestre din alte secțiuni."],["5 şi 10 zile","internare"]),

q("cardiologie-adv-235",["Dozele medicamentelor din insuficiența cardiacă (Cadranul 30.25):",
 ["candesartan 4 mg/zi inițial, maxim 32 mg/zi","carvedilol 3,125 mg ×2/zi, până la 50 mg ×2/zi","sacubitril/valsartan până la 97/103 mg ×2/zi","digoxin peste 2,5 mg/zi, de rutină, la eRFG <30","metoprolol succinat cu doză maximă de 25 mg/zi"],"ABC",1074,"Insuficiența cardiacă — Candesartan 32 mg, carvedilol, ARNI",
 "Memorarea treptelor de dozaj: candesartan 4→32 mg/zi, carvedilol 3,125→50 mg ×2/zi și sacubitril/valsartan până la 97/103 mg ×2/zi.",
 ["Candesartanul se inițiază cu 4 mg/zi și se crește până la maximum 32 mg/zi.","Carvedilolul se inițiază cu 3,125 mg de două ori pe zi și se crește până la 50 mg de două ori pe zi.","Sacubitril/valsartanul se inițiază cu 24/26–49/51 mg ×2/zi, până la maximum 97/103 mg ×2/zi.","Nu: peste 2,5 mg/zi de digoxin sunt rar necesare, iar la eRFG <30 ml/min/1,73 m² eficiența scade.","Nu: metoprololul succinat CR/XL se inițiază cu 12,5-25 mg/zi și se crește până la 200 mg/zi."]],
 [8,"Plafonează metoprololul la 25 mg — doza inițială — și crește digoxinul tocmai la eRFG <30."],["32 mg zilnic","97/103"]),

q("cardiologie-adv-236",["Studiile CIBIS, CIBIS II, MERIT-HF și COMET în insuficiența cardiacă:",
 ["au evaluat beta-blocantele la grade diferite de severitate","bisoprololul și carvedilolul scad mortalitatea la orice severitate","susțin inițierea în doză mică, cu titrare treptată","nebivololul înlocuiește bisoprololul la tinerii cu NYHA IV","permit inițierea beta-blocantului în IC acută, înaintea stabilizării"],"ABC",1074,"Insuficiența cardiacă — CIBIS, MERIT-HF, COMET",
 "Potrivirea studiilor cu beta-blocante cu reducerea mortalității (bisoprolol, carvedilol) și cu regula inițierii în doză mică în IC semnificativă.",
 ["Cele patru studii au evaluat efectele beta-blocantelor la grade diferite de severitate a insuficienței cardiace.","Bisoprololul și carvedilolul reduc mortalitatea în toate gradele de severitate ale insuficienței cardiace.","În IC semnificativă, beta-blocantul se inițiază în doză mică și se crește treptat, monitorizând frecvența și tensiunea.","Nu: nebivololul este indicat în IC stabilă ușoară sau moderată, la pacienții de peste 70 de ani.","Nu: beta-blocantele se evită în IC acută până la stabilizare."]],
 [8,"Mută nebivololul (>70 ani, IC stabilă) pe tânărul cu NYHA IV instabil, inversul nișei din același paragraf."],["CIBIS","MERIT-HF"]),

q("cardiologie-adv-237",["Insuficiența cardiacă crește riscul de accident vascular cerebral:",
 ["de patru ori","de două ori","de zece ori","de douăzeci de ori","cu 23%"],"A",1075,"Insuficiența cardiacă — Riscul de AVC ×4",
 "Reținerea creșterii de patru ori a riscului de accident vascular cerebral în insuficiența cardiacă.",
 ["Insuficiența cardiacă se asociază cu o creștere de patru ori a riscului de accident vascular cerebral.","Nu: creșterea riscului de AVC în insuficiența cardiacă este de patru ori, nu de două ori.","Nu: creșterea riscului de AVC în insuficiența cardiacă este de patru ori, nu de zece ori.","Nu: 20% este rata complicațiilor balonului de contrapulsație intraaortică; riscul de AVC crește de patru ori.","Nu: 23% este reducerea mortalității cu ICD în SCD-HeFT; riscul de AVC în IC crește de patru ori."]],
 [8,"Înlocuiește multiplicatorul ×4 cu 0% din CHA2DS2-VASc 0 sau cu 23% din SCD-HeFT."],["patru ori","accident vascular cerebral"]),

q("cardiologie-adv-238",["Boala coronariană în Marea Britanie (2010):",
 ["peste 180.000 de decese cardiovasculare, prima cauză de mortalitate","BC: 1 din 5 decese la bărbați, 1 din 10 la femei","1 din 6 infarcte se prezintă ca moarte subită, unicul simptom","mortalitatea cardiovasculară a fost sub 1.000 de decese","moartea subită nu poate fi prima manifestare a infarctului"],"ABC",1079,"Boala coronariană — 180.000 de decese și 1 din 6",
 "Aplicarea ordinului de mărime al mortalității (peste 180.000 CV, circa 80.000 prin BC) și a ponderii de 1 din 6 infarcte prezentate ca moarte subită.",
 ["Bolile cardiovasculare au produs peste 180.000 de decese, fiind cauza cea mai frecventă de mortalitate.","Boala coronariană a produs 1 din 5 decese la bărbați și 1 din 10 la femei, circa 80.000 de decese.","La 1 din 6 infarcte acute, moartea subită este primul, ultimul și unicul simptom.","Nu: ordinul de mărime este de peste 180.000 de decese cardiovasculare, nu de sub 1.000.","Nu: moartea subită poate fi primul, ultimul și unicul simptom al infarctului."]],
 [8,"Subestimează cu două ordine mortalitatea britanică și neagă moartea subită ca primă manifestare."],["180.000 de decese","1 din 6 infarcte"]),

q("cardiologie-adv-239",["Dezechilibrul aport–necesar de oxigen miocardic apare prin:",
 ["obstrucție mecanică: aterom, tromboză, spasm, embolie, vasculită","anemia, carboxihemoglobina sau hipotensiunea","creșterea necesarului: tireotoxicoză, stenoză aortică, HTA","spasmul, ca mecanism mai frecvent decât ateroscleroza","anemia, care scade necesarul de oxigen și previne ischemia"],"ABC",1079,"Boala coronariană — Aport versus necesar",
 "Potrivirea celor trei mecanisme ale ischemiei: obstrucția mecanică, scăderea conținutului de oxigen și creșterea necesarului (debit crescut, hipertrofie).",
 ["Obstrucția mecanică include ateroscleroza, tromboza supraadăugată, spasmul, embolia, stenozele ostiale și vasculitele (de exemplu LES).","Anemia, carboxihemoglobina și hipotensiunea (presiune de perfuzie scăzută) scad aportul de sânge oxigenat.","Debitul crescut (tireotoxicoza) și hipertrofia (stenoza aortică, HTA sistemică) cresc necesarul de oxigen.","Nu: ateroscleroza stenozantă este cauza cea mai frecventă, nu spasmul izolat.","Nu: anemia scade aportul de oxigen, nu necesarul, și favorizează ischemia."]],
 [8,"Anulează placa — cauza dominantă — și prezintă anemia ca protecție față de ischemie."],["carboxihemoglobinemia","tireotoxicoză"]),

q("cardiologie-adv-240",["Progresia leziunii aterosclerotice coronariene:",
 ["stria lipidică din celule spumoase cu LDL","placa de tranziție, cu lipide extracelulare subendoteliale","placa fibroasă, apoi complicată: ulcerare, tromboză, ocluzie","PDGF și TGF-β, care atrag macrofage și miocite netede din medie","stria lipidică, ca leziune finală, fără progresie spre placă"],"ABCD",1079,"Ateroscleroză — Strie lipidică, PDGF, placă complicată",
 "Secvența strie lipidică → placă de tranziție → placă fibroasă avansată/complicată, cu rolul PDGF și TGF-β.",
 ["Stria lipidică este formată din celule spumoase încărcate cu LDL.","Placa de tranziție conține lipide extracelulare în spațiul subendotelial.","Placa fibroasă avansată poate deveni placă complicată, cu ulcerare, tromboză și ocluzie acută.","PDGF și TGF-β stimulează acumularea de macrofage și migrarea celulelor musculare netede din medie.","Nu: stria lipidică poate progresa spre placa de tranziție și placa fibroasă; nu este stadiul final."]],
 [8,"Oprește aterogeneza la stria lipidică, deși textul o duce până la placa complicată ocluzivă."],["strii lipidice","celulelor spumoase"]),

q("cardiologie-adv-241",["Stenoza coronariană de 50% din diametru reduce aria lumenului cu circa:",
 ["70%, cu rezerva de flux epuizată","10%, fără ischemie la efort","50%, cu rezerva de flux păstrată","90% din suprafața luminală","0%, fără semnificație hemodinamică"],"A",1080,"Boala coronariană — Stenoză 50% diametru / 70% arie",
 "Reținerea echivalenței 50% din diametru ↔ circa 70% din arie, cu rezerva coronariană epuizată.",
 ["O reducere de 50% a diametrului corespunde unei reduceri de circa 70% a suprafeței, cu arteriole distale dilatate maximal și rezervă de flux zero.","Nu: 10% subestimează; reducerea suprafeței este de circa 70%.","Nu: reducerea ariei (circa 70%) este mai mare decât cea a diametrului, iar rezerva de flux este epuizată.","Nu: 90% nu este cifra citată; o stenoză de 50% din diametru reduce aria cu circa 70%.","Nu: o stenoză de 50% din diametru reduce aria cu circa 70% și este deja semnificativă hemodinamic."]],
 [8,"Echivalează greșit 50% diametru cu 50% arie și păstrează rezerva, deși textul o pune la zero."],["50%","70%"]),

q("cardiologie-adv-242",["Ateroscleroza ca boală sistemică și infarctul nerecunoscut:",
 ["claudicația intermitentă crește de 2-4 ori riscul de BC, AVC sau IC","după primul infarct, riscul de IC sau AVC crește de 3-6 ori","unul din trei infarcte rămâne inițial nerecunoscut","boala arterială periferică scade riscul de boală coronariană","sub 5% dintre SCA apar fără simptome prealabile de alarmă"],"ABC",1080,"Boala coronariană — Riscul 2-4× și infarctul tăcut",
 "Aplicarea multiplicatorilor de risc (2-4 ori la claudicație, 3-6 ori după infarct, dublare după AVC) și a ponderilor infarctului nerecunoscut (1 din 3) și SCA fără prodrom (30-40%).",
 ["Claudicația intermitentă se asociază cu un risc de 2-4 ori mai mare de boală coronariană, AVC sau insuficiență cardiacă.","După primul infarct, riscul de IC sau AVC crește de 3-6 ori, iar după un AVC riscul de IC și infarct se dublează.","Unul din trei infarcte rămâne inițial nerecunoscut.","Nu: boala arterială periferică crește, nu scade, riscul de boală coronariană.","Nu: 30-40% dintre SCA nu au simptome prealabile de alarmă."]],
 [8,"Inversează protecția falsă a BVP și neagă infarctul tăcut, deși un IMA din trei trece nerecunoscut."],["două până la de patru","30 şi 40%"]),

q("cardiologie-adv-243",["Prevenția primară (NICE) și suspiciunea de hipercolesterolemie familială:",
 ["scala QRISK3 definește riscul înalt ca ≥20% la 10 ani","lipidograma: colesterol total, HDL, non-HDL, trigliceride","colesterol >7,5 mmol/L și BC familială precoce sugerează forma familială","QRISK3 se aplică în prevenția secundară, de exemplu după un STEMI","colesterolul >7,5 mmol/L exclude hipercolesterolemia familială"],"BC",1080,"Boala coronariană — QRISK3 ≥10% și 7,5 mmol/L",
 "Aplicarea pragului QRISK3 de ≥10% la 10 ani și a pragului de >7,5 mmol/L cu istoric familial pentru suspiciunea de hipercolesterolemie familială.",
 ["Nu: scala QRISK3 definește riscul înalt ca ≥10% la 10 ani.","Tabloul lipidic complet cuprinde colesterolul total, HDL, non-HDL și trigliceridele.","Colesterolul >7,5 mmol/L plus istoricul familial de BC precoce poate indica hipercolesterolemia familială.","Nu: QRISK3 estimează riscul în prevenția primară.","Nu: colesterolul >7,5 mmol/L plus istoric familial de BC precoce ridică, nu infirmă, suspiciunea de formă familială."]],
 [8,"Mută QRISK3 în prevenția secundară post-STEMI și tratează 7,5 mmol/L ca argument împotriva formei familiale."],["7,5 mmol/L","QRISK"]),

q("cardiologie-adv-244",["Tromboza pe placa aterosclerotică se produce prin:",
 ["eroziune endotelială, cu adeziune plachetară la colagen","fisura capișonului fibros peste miezul lipidic","stenozare progresivă lentă, fără formare de tromb","eroziune care ocolește plachetele, fără contact cu colagenul","miezul lipidic, cu rol antitrombotic care previne ocluzia"],"AB",1080,"SCA — Eroziune superficială versus ruptură profundă",
 "Contrastul celor două mecanisme de tromboză pe placă: eroziunea superficială cu tromb aderent versus ruptura capișonului peste miezul lipidic.",
 ["Eroziunea endotelială superficială expune matricea subendotelială, plachetele aderă la colagen, iar trombul rămâne aderent la suprafața plăcii.","Ulcerarea sau fisura capișonului peste miezul lipidic permite pătrunderea sângelui în placă, expunerea factorului tisular din macrofage și extinderea trombului în lumen.","Nu: ambele mecanisme formează un tromb local; stenozarea lentă fără tromb nu este mecanismul descris.","Nu: eroziunea expune colagenul și inițiază adeziunea plachetară.","Nu: miezul lipidic are un potențial trombogenic major."]],
 [8,"Anulează trombul — elementul comun al celor două mecanisme — și face din miezul lipidic un factor protector."],["eroziunea endotelială","Miezul lipidic"]),

q("cardiologie-adv-245",["În angină, adenozina eliberată de miocardul ischemic:",
 ["stimulează terminațiile nervoase libere miocardice","nu contribuie la geneza durerii anginoase","blochează nociceptorii, ceea ce explică infarctul tăcut","stimulează terminațiile nervoase din pericard","înlocuiește nitroglicerina ca tratament de primă linie"],"A",1081,"Angina — Adenozina și terminațiile nervoase",
 "Reținerea adenozinei ca metabolit ischemic care stimulează terminațiile nervoase libere miocardice și produce durerea anginoasă.",
 ["Adenozina, ca metabolit ischemic, stimulează terminațiile nervoase libere din miocard și produce durerea anginoasă.","Nu: durerea anginoasă este indusă de metaboliții ischemici, inclusiv adenozina.","Nu: infarctul tăcut există, dar nu pentru că adenozina ar bloca nociceptorii.","Nu: adenozina stimulează terminațiile nervoase libere din miocard, nu din pericard.","Nu: adenozina este un mediator al durerii, nu un tratament antianginos."]],
 [8,"Transformă adenozina — mediator al durerii — în analgezic sau antianginos, inversul fiziologiei."],["adenozina","terminaţiile nervoase libere"]),

q("cardiologie-adv-246",["Clasa CCS III și angina refractară:",
 ["CCS III: angină după 50-100 m pe plat sau un etaj","refractară: BC severă nerevascularizabilă, necontrolată medicamentos","CCS III: angină la efort intens, fără limitarea activității zilnice","refractară: angină de efort controlată cu un beta-blocant","CCS IV exclude angina de repaus"],"AB",1081,"Angina — CCS III (50-100 m) și forma refractară",
 "Fixarea pragului CCS III (50-100 m pe plat sau un etaj) și a definiției anginei refractare (nerevascularizabilă, necontrolabilă medicamentos).",
 ["CCS III înseamnă angină la activități de intensitate redusă (mers 50-100 m pe plat sau urcarea unui etaj), cu limitare marcată.","Angina refractară înseamnă BC severă la care revascularizarea nu este realizabilă și simptomele nu sunt controlabile medicamentos.","Nu: angina doar la efort intens, fără limitarea activității obișnuite, definește clasa CCS I.","Nu: angina refractară presupune eșecul tratamentului medicamentos și imposibilitatea revascularizării.","Nu: CCS IV include angina în repaus sau la orice nivel de activitate."]],
 [8,"Degradează CCS III la efortul intens al clasei I și golește refractara de conținutul ei (nerevascularizabilă)."],["50-100 m","Angina refractară"]),

q("cardiologie-adv-247",["Factori de risc ai bolii coronariene (Cadranul 30.30):",
 ["fibrinogenul și factorul VII crescute, hiperhomocisteinemia","guta, apa moale, contraceptivele orale, inhibitorii COX-2","deleția DD a genei ECA, factor nemodificabil","guta și apa moale, ca factori protectori coronarieni","contraceptivele orale, factor nemodificabil ca vârsta"],"ABC",1081,"Boala coronariană — Cadranul 30.30 (fibrinogen, gută, apă)",
 "Recunoașterea factorilor de risc mai puțin citați (fibrinogen/factor VII, PCR, homocisteină, gută, apă moale, COX-2) și a deleției DD a genei ECA ca factor nemodificabil.",
 ["Creșterea fibrinogenului și a factorului VII, creșterea PCR și hiperhomocisteinemia sunt factori potențial modificabili.","Guta, duritatea redusă a apei și unele medicamente (contraceptive orale, analogi de nucleozide, inhibitori COX-2, rosiglitazonă) sunt factori potențial modificabili.","Deleția DD a genei ECA este un factor nemodificabil, alături de vârstă, sexul masculin și antecedentele familiale.","Nu: guta și apa cu duritate redusă (apa moale) sunt factori de risc coronarian, nu de protecție.","Nu: contraceptivele orale sunt un factor potențial modificabil, spre deosebire de vârstă."]],
 [8,"Transformă guta și apa moale în factori protectori și mută contraceptivele lângă vârstă, în coloana nemodificabilă."],["fibrinogenului","Duritatea redusă a apei"]),

q("cardiologie-adv-248",["Rezerva fracționată de flux (FFR) și complicațiile PCI:",
 ["FFR >0,80: se poate trata medicamentos, fără stent","complicații majore: infarct 2%, AVC 0,4%, deces 1%","stenturile metalice simple: restenoză 20-30% în primele 6-9 luni","FFR >0,80 impune stentarea imediată, fără tratament medicamentos","restenoză sub 1% în primul an după stent metalic"],"ABC",1082,"PCI — FFR >0,80, restenoză BMS 20-30%",
 "Aplicarea pragului FFR de 0,80, a ratelor complicațiilor majore (2%/0,4%/1%) și a restenozei de 20-30% la 6-9 luni după stent metalic simplu.",
 ["Leziunile cu FFR >0,80 pot fi tratate medicamentos, fără stent, cu prognostic bun.","Complicațiile majore ale PCI sunt infarctul acut (2%), accidentul vascular cerebral (0,4%) și decesul (1%).","Stenturile metalice simple au un risc de restenoză de 20-30% în primele 6-9 luni.","Nu: peste 0,80 se poate evita stentul, cu tratament medicamentos și prognostic bun.","Nu: restenoza după stent metalic simplu este de 20-30% în 6-9 luni; sub 1% este mortalitatea CABG la FE conservată."]],
 [8,"Inversează pragul FFR (stentează tocmai leziunile >0,80) și comprimă restenoza BMS de la 20-30% la 1%."],["0,80","20-30%"]),

q("cardiologie-adv-249",["Stenturile farmacologic active și abordul arterial în PCI:",
 ["abordul radial este preferat și reduce complicațiile locale","prima generație DES a redus restenoza, dar cu tromboză tardivă","a doua generație: rețea subțire, polimeri biocompatibili","abordul femural este standardul actual în Marea Britanie","prima generație DES (sirolimus) a eliminat tromboza de stent"],"ABC",1082,"PCI — Radial, DES de generația I/II",
 "Contrastul trombozei tardive a primei generații de DES cu rețeaua subțire și polimerii biocompatibili ai celei de-a doua, plus preferința pentru abordul radial.",
 ["Abordul radial este preferat în prezent și reduce complicațiile de la locul puncției.","Prima generație de DES (sirolimus, paclitaxel) a redus restenoza, dar a produs tromboză tardivă de stent.","A doua generație de DES are rețea mai subțire și polimeri biodegradabili sau biocompatibili.","Nu: abordul radial, nu cel femural, este standardul citat în Marea Britanie.","Nu: prima generație a redus restenoza, dar a adus tromboză tardivă de stent."]],
 [8,"Pune femuralul ca standard UK — inversul textului — și atribuie primei generații DES restenoza BMS."],["sirolimus","paclitaxel"]),

q("cardiologie-adv-250",["Doze antianginoase (Cadranul 30.33) și dubla antiagregare după stent:",
 ["nitroglicerină 0,3-1,0 mg sublingual, repetată după 5 minute","ivabradină 2,5-7,5 mg ×2/zi; nicorandil 5-30 mg ×2/zi","DAPT 6-12 luni după stentare (aspirină plus inhibitor P2Y12)","nitroglicerină sublinguală 80 mg, repetată la nevoie","DAPT de 24 de ore, BMS fiind interzise înaintea anticoagulării"],"ABC",1083,"Angina — NTG 0,3-1,0 mg, DAPT 6-12 luni",
 "Fixarea dozei de nitroglicerină cu repetare la 5 minute, a dozelor de ivabradină și nicorandil și a duratei DAPT de 6-12 luni după stentare.",
 ["Nitroglicerina se administrează 0,3-1,0 mg sublingual și se repetă după 5 minute dacă angina persistă.","Ivabradina se dozează 2,5-7,5 mg ×2/zi, iar nicorandilul 5-30 mg ×2/zi.","După stentare se face DAPT (aspirină plus inhibitor P2Y12) 6-12 luni; BMS pot fi preferate dacă e nevoie de anticoagulare prelungită sau de chirurgie precoce.","Nu: 80 mg este doza de atorvastatină din prevenția secundară; nitroglicerina se dă 0,3-1,0 mg sublingual.","Nu: DAPT durează 6-12 luni, iar BMS sunt preferate tocmai când e nevoie de anticoagulare prelungită."]],
 [8,"Confundă 0,3-1,0 mg de NTG cu 80 mg de atorvastatină și comprimă DAPT de la 6-12 luni la 24 de ore."],["0,3-1,0 mg","6-12 luni"]),

q("cardiologie-adv-251",["Tahicardiile:",
 ["sunt mai simptomatice dacă sunt rapide și susținute","sunt mai simptomatice când sunt lente și nesusținute","sunt mai simptomatice nocturn, sub 50 bătăi pe minut","sunt mai simptomatice ca extrasistole atriale izolate","nu influențează prognosticul vital la funcție miocardică depreciată"],"A",1051,"Aritmii — Simptomatologia tahicardiilor",
 "Reținerea relației dintre viteza și durata tahicardiei și simptome, plus impactul prognostic când funcția miocardică este depreciată.",
 ["Cu cât sunt mai rapide și mai susținute, tahicardiile tind să fie mai simptomatice, iar la funcție miocardică depreciată influențează prognosticul.","Nu: aritmiile lente și nesusținute, pe cord structural normal, pot fi paucisimptomatice.","Nu: frecvența sub 50 b.p.m. nocturn ține de definiția bradicardiei, nu de tahicardia simptomatică.","Nu: extrasistolele atriale izolate nu constituie o tahicardie susținută.","Nu: la funcție miocardică depreciată, aritmiile influențează prognosticul vital."]],
 [8,"Atribuie simptomatologia maximă bradicardiei nocturne, inversul paragrafului despre tahicardiile rapide susținute."],["mai rapide şi mai susţinute","funcţia miocardică"]),

q("cardiologie-adv-252",["Metoda „pill in pocket” pentru cardioversia FA presupune:",
 ["flecainidă sau propafenonă orală, testată anterior în spital","digoxin oral luat la domiciliu, fără testare prealabilă în spital","amiodaronă i.v. de rutină, fără evaluare prealabilă","flecainidă orală, luată fără testare prealabilă în spital","oprirea anticoagulării în ziua administrării"],"A",1061,"Fibrilația atrială — Pill in pocket",
 "Reținerea flecainidei sau propafenonei orale, testate în prealabil în spital, ca metodă „pill in pocket”.",
 ["Pacientul ia oral flecainidă sau propafenonă, testate în prealabil în spital și considerate sigure pentru el.","Nu: digoxinul nu este medicamentul metodei; se folosesc flecainida sau propafenona testate în spital.","Nu: amiodarona i.v. este o altă cale de cardioversie farmacologică, nu metoda „pill in pocket”.","Nu: flecainida sau propafenona se folosesc „pill in pocket” numai după ce au fost testate în spital și considerate sigure.","Nu: anticoagularea peri-cardioversie rămâne o problemă separată; riscul trombotic nu dispare."]],
 [8,"Înlocuiește flecainida/propafenona testate în spital cu digoxinul de domiciliu, capcana clasică a metodei."],["flecainidă","propafenonă"]),

q("cardiologie-adv-253",["Tahicardia cu QRS larg, cu diagnostic incert între TV și TSV, se consideră:",
 ["tahicardie ventriculară","TSV cu aberanță, până la proba contrarie","flutter antiorar cu conducere 1:1","AVNRT tipică de tip slow-fast","extrasistolie atrială bigeminată"],"A",1063,"TV versus TSV — Regula incertitudinii",
 "Aplicarea regulii că, la incertitudine, tahicardia cu QRS larg se tratează ca ventriculară.",
 ["În caz de incertitudine, tahicardia cu QRS larg se consideră ventriculară.","Nu: asumarea unei TSV cu aberanță este tocmai eroarea de evitat; la incertitudine se consideră TV.","Nu: flutterul cu conducere 1:1 este o TSV particulară, nu presupunerea de primă linie.","Nu: AVNRT are de obicei QRS îngust; la incertitudine tahicardia cu QRS larg se consideră ventriculară.","Nu: bigeminismul atrial nu explică o tahicardie regulată cu QRS larg."]],
 [8,"Inversează regula de siguranță (incertitudine = TV) în favoarea TSV cu aberanță."],["incertitudine","ventriculară"]),

q("cardiologie-adv-254",["În insuficiența cardiacă, secreția de endotelină este stimulată de:",
 ["hipoxie, catecolamine și angiotensina II","peptidul natriuretic de tip C","oxidul nitric produs în exces de endoteliu","adenozina din miocardul ischemic","ivabradina, prin blocarea curentului If sinoatrial"],"A",1071,"Insuficiența cardiacă — Stimulii endotelinei",
 "Reținerea stimulilor secreției de endotelină în IC: hipoxia, catecolaminele și angiotensina II.",
 ["Hipoxia, catecolaminele și angiotensina II stimulează secreția de endotelină.","Nu: peptidul natriuretic C are efecte similare ANP/BNP și nu stimulează secreția de endotelină.","Nu: în IC activitatea oxidului nitric este insuficientă, nu în exces.","Nu: adenozina ține de durerea anginoasă, nu de secreția de endotelină.","Nu: ivabradina inhibă curentul If sinoatrial, nu stimulează secreția de endotelină."]],
 [8,"Înlocuiește triadul hipoxie/catecolamine/angiotensină II cu NO-ul — descris ca insuficient — sau cu ivabradina."],["angiotensina li","catecolaminele"]),

q("cardiologie-adv-255",["Recomandările dietetice pentru prevenția bolii coronariene includ:",
 ["grăsimi ≤30% din calorii, saturate ≤7%","limitarea fructozei; 4-5 porții de nuci și semințe pe săptămână","colesterol alimentar nelimitat, cu preferarea grăsimilor saturate","evitarea efortului după 45 de ani, pentru protejarea plăcii","menținerea greutății la un IMC țintă de 25-30 kg/m²"],"AB",1081,"Boala coronariană — Grăsimi ≤30%/≤7% și 4-5 porții de nuci",
 "Completarea recomandărilor dietetice cu plafoanele de 30%/7%/<300 mg și cu 4-5 porții săptămânale de nuci și semințe.",
 ["Grăsimile ≤30% din calorii, cele saturate ≤7% și colesterolul <300 mg/zi; saturatele se înlocuiesc cu mono- și polinesaturate (rapiță, măsline).","Zaharurile rafinate (de exemplu fructoza) se limitează, iar nucile, semințele și legumele nesărate se consumă în 4-5 porții pe săptămână.","Nu: colesterolul alimentar trebuie să fie <300 mg/zi, iar grăsimile saturate se înlocuiesc cu nesaturate.","Nu: efortul fizic aerobic este recomandat în prevenția bolii coronariene.","Nu: IMC-ul țintă este <25 kg/m²."]],
 [8,"Preferă saturatele și IMC ≥30, inversul dietei cu ≤7% saturate și IMC <25."],["300 mg/zi","rapiţă"]),

q("cardiologie-adv-256",["Durerea toracică non-anginoasă este probabilă dacă este:",
 ["continuă, nelegată de efort, accentuată de respirație","retrosternală, de efort, ameliorată de nitrat","însoțită de cele trei caracteristici NICE ale anginei tipice","de clasă CCS IV, cu indicație de PCI primară","suficientă pentru diagnosticul de STEMI, fără criterii ECG"],"A",1082,"Angina — Durerea non-anginoasă probabilă",
 "Recunoașterea trăsăturilor durerii non-anginoase (continuă, nelegată de efort, accentuată respirator, cu amețeli, palpitații sau disfagie).",
 ["Durerea continuă, nelegată de efort, accentuată de mișcările respiratorii sau asociată cu amețeli, palpitații ori disfagie este probabil non-anginoasă.","Nu: durerea retrosternală de efort care cedează la nitrat este angina clasică.","Nu: prezența celor trei caracteristici definește angina clasică, nu durerea non-anginoasă.","Nu: durerea non-anginoasă cu ECG normal se investighează pentru diagnostice alternative, nu prin PCI primară.","Nu: diagnosticul de STEMI cere criterii ECG, nu acest tipar de durere."]],
 [8,"Trimite durerea continuă respirator-dependentă la PCI primară, sărind algoritmul NICE."],["disfagie","nelegată de efort"]),

q("cardiologie-adv-257",["Reintrarea:",
 ["cere țesut normal dispus circular în jurul unui miez inexcitabil","este inițiată de o extrasistolă care găsește o cale refractară","se întreține dacă circuitul durează mai mult decât refractaritatea","cere un miez excitabil, fără extrasistolă declanșatoare","stă la baza unei minorități a tahicardiilor paroxistice regulate"],"ABC",1052,"Aritmii — Reintrarea (miez inexcitabil)",
 "Recunoașterea condițiilor reintrării: miez inexcitabil, bloc unidirecțional și timp de circuit mai lung decât refractaritatea.",
 ["Reintrarea necesită țesut miocardic normal dispus circular în jurul unui miez inexcitabil, de exemplu o cicatrice.","O extrasistolă găsește o cale în perioada refractară (bloc unidirecțional), cealaltă fiind excitabilă, și inițiază circuitul.","Timpul de conducere pe circuit, mai lung decât perioadele refractare, întreține tahicardia.","Nu: miezul este inexcitabil, iar circuitul este inițiat de o extrasistolă cu bloc unidirecțional.","Nu: majoritatea tahicardiilor paroxistice regulate au la bază reintrarea."]],
 [8,"Cere un miez excitabil și neagă reintrarea ca mecanism dominant al tahicardiilor paroxistice regulate."],["miez","inexcitabil"]),

q("cardiologie-adv-258",["Dozele cronice de diuretice și vasodilatatoare (Cadranul 30.25):",
 ["furosemid 20-40 mg/zi, până la 250-500 mg/zi","bumetanid 0,5-1,0 mg/zi, maxim 5-10 mg/zi","isosorbid dinitrat 20-40 mg ×3/zi și hidralazină 37,5-75 mg ×3/zi","furosemid 50 mg i.v. ca doză cronică orală unică","bumetanid rezervat edemului pulmonar acut, nu IC cronice"],"ABC",1074,"Insuficiența cardiacă — Furosemid 250-500 mg, bumetanid, hidralazină",
 "Memorarea treptelor orale de furosemid (20-40 → 250-500 mg/zi) și bumetanid (0,5-1,0 → 5-10 mg/zi), plus schema isosorbid dinitrat–hidralazină ×3/zi.",
 ["Furosemidul se inițiază cu 20-40 mg/zi și se poate crește până la 250-500 mg/zi.","Bumetanidul se inițiază cu 0,5-1,0 mg/zi, cu un maxim de 5-10 mg/zi.","Isosorbidul dinitrat 20-40 mg ×3/zi se asociază cu hidralazina 37,5-75 mg ×3/zi.","Nu: 50 mg i.v. este doza inițială din insuficiența cardiacă acută, nu treapta cronică orală (20-40 mg/zi).","Nu: bumetanidul figurează în cadranul tratamentului insuficienței cardiace cronice."]],
 [8,"Confundă bolusul i.v. de 50 mg din ICA cu treapta cronică orală 20-40/250-500 mg."],["250-500 mg zilnic","37,5-75 mg"]),

q("cardiologie-adv-259",["În STEMI, oxigenul pe mască se administrează dacă saturația este sub:",
 ["90%","98%","70%","100%","80%"],"A",1088,"STEMI — Oxigen sub 90%",
 "Reținerea pragului SpO2 <90% pentru oxigenul pe mască în STEMI, distinct de ținta post-resuscitare.",
 ["În STEMI se administrează oxigen pe mască dacă saturația este mai mică de 90%.","Nu: 94-98% este ținta post-ROSC; în STEMI oxigenul se dă la saturație sub 90%.","Nu: pragul de 70% este prea jos; oxigenul se dă la saturație sub 90%.","Nu: oxigenul de rutină la toți pacienții nu este indicat; pragul este 90%.","Nu: pragul citat pentru oxigenul pe mască este 90%, nu 80%."]],
 [8,"Confundă pragul STEMI <90% cu ținta post-ROSC 94-98% sau cu oxigenul 100% de rutină."],["oxigenoterapia","mască"]),

q("cardiologie-adv-260",["Mortalitatea la 30 de zile pentru un scor TIMI STEMI de 5:",
 ["0,8%","4,4%","12,4%","35,9%","1,6%"],"C",1088,"STEMI — TIMI scor 5 → 12,4%",
 "Memorarea treptei TIMI STEMI de 5 puncte → 12,4% mortalitate la 30 de zile, între 4,4% (3 puncte) și 35,9% (9-16 puncte).",
 ["Nu: 0,8% este mortalitatea la scorul 0.","Nu: 4,4% este mortalitatea la scorul 3.","Un scor TIMI STEMI de 5 puncte corespunde unei mortalități la 30 de zile de 12,4%.","Nu: 35,9% este mortalitatea la scorurile 9-16.","Nu: 1,6% este mortalitatea la scorul 1."]],
 [8,"Permutează treptele consecutive ale aceluiași tabel; doar scorul 5 dă 12,4%."],["12,4%","30 zile"]),

q("cardiologie-adv-261",["Infarctul miocardic la vârstnici sau diabetici:",
 ["poate debuta cu dispnee, astenie, presincopă, sincopă","are o durere care cedează prompt la nitroglicerină","evoluează de regulă fără simptome vegetative","nu impune repetarea ECG-ului normal dacă durerea persistă","este atipic prin localizarea posterioară"],"A",1088,"STEMI — Prezentarea atipică",
 "Recunoașterea echivalentelor de infarct (dispnee, astenie, sincopă) la vârstnic și diabetic.",
 ["La vârstnici și diabetici, infarctul se poate prezenta atipic, prin dispnee, astenie, presincopă sau sincopă.","Nu: durerea din infarct nu cedează de obicei la nitratul sublingual.","Nu: simptomele vegetative sunt frecvente în infarctul miocardic.","Nu: primul ECG este rar normal și se repetă la 15 minute dacă durerea persistă.","Nu: atipia se referă la simptomele de prezentare, nu la o localizare posterioară."]],
 [8,"Atribuie STEMI-ului răspunsul la nitrat al anginei stabile și anulează simptomele vegetative."],["diabetici","presincopă"]),

q("cardiologie-adv-262",["Evoluția ECG în STEMI:",
 ["minute: T ample, ascuțite, supradenivelare ST","ore: T negativ, voltaj R crescut, apar unde Q","zile: ST izoelectric; luni: T pozitiv, Q persistent","unde Q dispărute în minute, ST neschimbat luni","debut cu unde T negative din primul minut"],"AC",1090,"STEMI — Evoluția ECG minute–ore–zile",
 "Secvența T hiperacute → Q și T negative → ST izoelectric → T recuperat cu Q persistent.",
 ["În primele minute apar unde T ample, ascuțite, simetrice și supradenivelare ST.","Nu: în ore T se negativează, voltajul undei R scade și apar unde Q.","În zile ST redevine izoelectric; în săptămâni-luni T se pozitivează, iar undele Q persistă.","Nu: undele Q apar după câteva ore și persistă, nu dispar în primele minute.","Nu: debutul este marcat de unde T hiperacute, nu de unde T negative."]],
 [8,"Inversează cronologia Q/ST: face Q-ul evanescent în minute și ST-ul persistent luni."],["câteva minute","undele Q"]),

q("cardiologie-adv-263",["Ruptura de perete liber și anevrismul post-STEMI:",
 ["ruptura: complicație mecanică precoce, de obicei fatală","ruptura: colaps și stop prin disociație electromecanică","ruptura subacută: pericardiocenteză, apoi chirurgie, posibil salvatoare","anevrismul: complicație tardivă, uneori reparată chirurgical","ruptura: complicație tardivă, cu evoluție benignă"],"ABCD",1090,"STEMI — Ruptura de perete liber și anevrismul",
 "Contrastul rupturii precoce fatale (EMD) cu anevrismul tardiv și cu fereastra subacută salvabilă.",
 ["Ruptura de perete liber este o complicație mecanică precoce, cel mai frecvent fatală.","Ruptura produce colaps și stop cardiac prin disociație electromecanică.","În forma subacută, pericardiocenteza urmată de chirurgie precoce poate fi salvatoare.","Anevrismul ventricular din teritoriul infarctizat este o complicație tardivă, care poate cere reparare chirurgicală.","Nu: ruptura de perete liber este precoce și de obicei fatală; anevrismul este complicația tardivă."]],
 [8,"Mută ruptura fatală precoce în „complicație tardivă benignă”, inversând prognosticul."],["disociaţie electromecanică","forma subacută"]),

q("cardiologie-adv-264",["Tratamentul insuficienței cardiace ușoare post-STEMI:",
 ["furosemid 40-80 mg i.v., nitroglicerină dacă TA permite","IECA din primele 24-48 ore, la TA normală","oxigen pe mască, cu monitorizare prin pulsoximetrie","digoxin i.v. de primă linie, înaintea diureticului","IECA evitat 7 zile, chiar la TA normală"],"ABC",1090,"STEMI — IC ușoară, furosemid 40-80 mg",
 "Aplicarea bolusului 40-80 mg și a ferestrei IECA 24-48 de ore la tensiune normală.",
 ["Furosemidul 40-80 mg în bolus i.v. și nitroglicerina în perfuzie, dacă TA permite, sunt recomandate explicit.","Un IECA se poate începe în primele 24-48 de ore, dacă TA este normală.","Oxigenul pe mască, cu monitorizare prin pulsoximetrie, face parte din tratament.","Nu: digoxinul nu este prima linie în insuficiența cardiacă ușoară post-STEMI.","Nu: IECA se poate începe precoce, în primele 24-48 de ore, dacă TA este normală."]],
 [8,"Interzice IECA-ul din 24-48 de ore — fereastra citată — și pune digoxinul înaintea diureticului."],["40-80 mg","24-48 ore"]),

q("cardiologie-adv-265",["Etiologii nereumatismale ale stenozei mitrale:",
 ["forma congenitală și sindromul Lutembacher (SM + DSA)","calcificarea inelului mitral (vârstnici, boală renală avansată)","carcinoidul cu metastaze pulmonare sau primar bronșic","bicuspidia aortică, anomalie congenitală a valvei mitrale","sindromul Lutembacher: SM + stenoză aortică"],"ABC",1092,"Stenoza mitrală — Lutembacher, inel calcificat, carcinoid",
 "Recunoașterea Lutembacher (SM+DSA), a calcificării de inel la vârstnic/CKD și a carcinoidului cu metastaze pulmonare.",
 ["Stenoza mitrală congenitală și sindromul Lutembacher (SM dobândită asociată cu DSA) sunt listate.","Calcificarea extensivă a inelului mitral apare mai ales la vârstnici și în boala renală avansată.","Tumorile carcinoide cu metastaze pulmonare sau carcinoidul primar bronșic pot produce stenoză mitrală.","Nu: bicuspidia ține de valva aortică, nu de valva mitrală.","Nu: sindromul Lutembacher asociază stenoza mitrală cu DSA, nu cu stenoza aortică."]],
 [8,"Înlocuiește DSA-ul din Lutembacher cu stenoza aortică, capcana eponimică clasică."],["Lutembacher","calcificarea inelului mitral"]),

q("cardiologie-adv-266",["În țările cu venituri mici-medii, stenoza mitrală reumatismală afectează circa:",
 ["20 de milioane de oameni","20.000 de oameni","2% dintre nou-născuți","1 din 500 de persoane","200 de milioane de oameni"],"A",1092,"Stenoza mitrală — 20 de milioane",
 "Reținerea ordinului de 20 de milioane de cazuri în țările cu venituri mici-medii.",
 ["Stenoza mitrală reumatismală afectează aproximativ 20 de milioane de oameni în țările cu venituri mici-medii.","Nu: sunt afectați circa 20 de milioane de oameni; 20.000 subestimează cu trei ordine de mărime.","Nu: 1-2% este prevalența bicuspidiei aortice, nu a stenozei mitrale reumatismale.","Nu: 1 din 500 este prevalența CMH, nu a stenozei mitrale reumatismale.","Nu: ordinul de mărime este de circa 20 de milioane de oameni, nu de sute de milioane."]],
 [8,"Subestimează cu trei ordine prevalența reumatismală din țările cu venituri mici-medii."],["20 de milioane","reumatismale"]),

q("cardiologie-adv-267",["Examenul clinic în stenoza mitrală:",
 ["pete malare roșiatice sau cianotice, prin stază","puls mic, neregulat dacă apare FA","pulsație parasternală stângă amplă la S1 (VD dilatat)","facies palid, de anemie, fără stază malară","puls amplu, săltăreț, ca în regurgitarea aortică"],"ABC",1092,"Stenoza mitrală — Flush malar și palpare",
 "Potrivirea flush-ului malar cu pulsul mic și cu pulsația parasternală de VD dilatat.",
 ["Flush-ul malar constă în pete roșiatice sau cianotice la pomeți, prin stază vasculară și anastomoze arterio-venoase.","Pulsul are amplitudine redusă și devine complet neregulat dacă se instalează FA.","Pulsația amplă parasternal stâng, corespunzând S1, se datorează VD dilatat care deplasează VS posterior.","Nu: faciesul mitral are flush malar prin stază, nu paloarea anemiei.","Nu: pulsul săltăreț ține de regurgitarea aortică; în stenoza mitrală pulsul are amplitudine redusă."]],
 [8,"Atribuie stenozei mitrale pulsul săltăreț al regurgitării aortice și anulează flush-ul malar."],["flush malar","pomeţilor"]),

q("cardiologie-adv-268",["Regurgitarea mitrală acută versus cronică:",
 ["cronic: atriu dilatat cu complianță scăzută","acut: undă „v” mare și edem pulmonar acut","cronic: volum-bătaie crescut progresiv, cu dilatarea VS","acut: undă „v” mică, edem pulmonar rar","acut: atriul normal previne creșterea presiunii"],"BC",1095,"Regurgitarea mitrală — Unda v și forma acută",
 "Contrastul atriului compliant cronic versus unda v și EPA din regurgitarea acută.",
 ["Nu: în forma cronică atriul dilatat progresiv are complianță crescută, cu creștere minimă a presiunii intraatriale.","În forma acută atriul de dimensiuni normale nu se dilată suficient, unda „v” crește semnificativ și apare edem pulmonar acut.","În forma cronică volumul-bătaie crește progresiv pentru a menține debitul net, cu dilatarea VS.","Nu: în forma acută unda „v” este semnificativ crescută, cu edem pulmonar acut.","Nu: atriul normal, nedilatat, nu poate preveni creșterea presiunii în regurgitarea acută."]],
 [8,"Inversează unda v (mare în acut) și neagă edemul pulmonar — tabloul clasic al RM acute."],["unda „v\"","edemului pulmo"]),

q("cardiologie-adv-269",["În regurgitarea mitrală, pe lângă suflul holosistolic:",
 ["clic mezosistolic (valve mixomatoase), uneori suflu telesistolic","S3 accentuat prin umplere rapidă a VS","HVS pe ECG: SV1 + RV5/V6 >35 mm","S3 absent, prin umplere lentă a VS","absența cașexiei, chiar în stadiile avansate"],"ABC",1095,"Regurgitarea mitrală — Clic mixomatos și Sokolow >35 mm",
 "Recunoașterea clicului mixomatos, a S3 de umplere rapidă și a sumei Sokolow >35 mm.",
 ["Pe valvele mixomatoase apare un clic mezosistolic, prin prolaps brusc și tensionarea cordajelor, urmat uneori de suflu telesistolic.","S3 este accentuat prin umplerea rapidă protodiastolică a VS dilatat.","HVS pe ECG se recunoaște prin suma S în V1 + R în V5/V6 peste 35 mm.","Nu: S3 este accentuat prin umplerea rapidă a VS, nu absent ca la o umplere lentă.","Nu: cașexia poate fi prezentă în stadiile avansate ale regurgitării mitrale."]],
 [8,"Neagă S3-ul de umplere rapidă — semnul VS dilatat — și anulează cașexia stadiilor avansate."],[">35 mm","Clic mezosistolic"]),

q("cardiologie-adv-270",["Stenoza tricuspidiană:",
 ["dureri abdominale (hepatomegalie), ascită, edeme periferice","undă „a” proeminentă, suflu mezodiastolic accentuat în inspir","unde P >3 mm în DII (dilatare AD)","de regulă izolată, fără valvulopatie reumatismală stângă","suflu diminuat în inspir, ca suflurile stângi"],"ABC",1101,"Stenoza tricuspidiană — Unda a, P >3 mm",
 "Potrivirea congestiei drepte cu unda a hepatică, suflul inspirator și P >3 mm în DII.",
 ["Simptomele de congestie sistemică sunt durerea abdominală (hepatomegalie), distensia (ascită) și edemele periferice.","În ritm sinusal unda jugulară „a” este proeminentă, palpabilă și la ficat, iar suflul mezodiastolic de la marginea sternală stângă inferioară se accentuează în inspir.","Dilatarea AD se traduce pe ECG prin unde P înalte, peste 3 mm, în DII.","Nu: pacienții au de obicei și afectare reumatismală mitrală sau aortică; stenoza tricuspidiană este rar izolată.","Nu: suflul stenozei tricuspidiene se accentuează în inspir, nu se diminuează."]],
 [8,"Izolează stenoza tricuspidă de reumatismul stâng — deși textul o leagă aproape constant de valvele stângi."],[">3 mm","edeme periferice"]),

q("cardiologie-adv-271",["Regurgitarea tricuspidiană:",
 ["cauze organice: reumatism, endocardită, carcinoid, Ebstein","undă „cv” mare, ficat pulsatil, suflu holosistolic inspirator","forma funcțională persistă după tratarea medicală a cauzei","forma funcțională ușoară: protezare de primă intenție","suflu diminuat în inspir, ca suflurile stângi"],"AB",1101,"Regurgitarea tricuspidă — Ebstein și undă cv",
 "Potrivirea etiologiilor organice (Ebstein, carcinoid) cu unda cv și ficatul pulsatil.",
 ["Cauzele organice includ reumatismul, endocardita, sindromul carcinoid, boala Ebstein și alte anomalii congenitale ale valvelor AV.","Semnele sunt unda jugulară „cv” mare, ficatul pulsatil sistolic și suflul holosistolic accentuat în inspir la marginea sternală stângă inferioară.","Nu: forma funcțională dispare de obicei după tratamentul medical al cauzei de dilatare a VD.","Nu: protezarea este rară; forma funcțională se tratează medical.","Nu: suflul regurgitării tricuspidiene se accentuează în inspir, nu se diminuează."]],
 [8,"Transformă forma funcțională — care cedează medical — în indicație de proteză de primă intenție."],["Ebstein","consumatorii de droguri"]),

q("cardiologie-adv-272",["Stenoza pulmonară congenitală:",
 ["asocieri: tetralogia Fallot, sindromul Noonan, rubeola congenitală","poate fi valvulară, subvalvulară sau supravalvulară","hipertrofie VD și dilatare AD, prin obstrucție","asociere tipică: boala Barlow a femeii tinere","exclude localizarea valvulară, obstrucția fiind infundibulară"],"ABC",1102,"Stenoza pulmonară — Fallot, Noonan, rubeolă",
 "Recunoașterea asocierilor congenitale (Fallot, Noonan, rubeolă) și a celor trei nivele de obstrucție.",
 ["Stenoza pulmonară congenitală se poate asocia cu tetralogia Fallot, sindromul Noonan sau rubeola congenitală.","Obstrucția poate fi valvulară, subvalvulară sau supravalvulară.","Obstrucția la ejecția VD produce hipertrofie de VD și dilatare atrială dreaptă.","Nu: boala Barlow ține de valva mitrală, nu de stenoza pulmonară.","Nu: obstrucția poate fi valvulară, subvalvulară sau supravalvulară, nu numai infundibulară."]],
 [8,"Mută stenoza pulmonară pe Barlow și neagă Fallot/Noonan, asocierile congenitale citate."],["Noonan","rubeola congenitală"]),

q("cardiologie-adv-273",["Criteriile Duke majore microbiologice includ:",
 ["Abiotrophia sau Granulicatella, fără focar primar","febra Q: IgG de fază 1 >1:800","același germen la ≥12 ore sau în 3/≥4 seturi","un singur set de hemoculturi de pe cateter","febra Q: IgG de fază 1 de 1:20"],"ABC",1104,"Endocardita — Duke: Abiotrophia, febra Q >1:800",
 "Completarea criteriului major cu Abiotrophia/Granulicatella și titrul IgG de fază 1 >1:800 pentru Coxiella.",
 ["Abiotrophia și Granulicatella figurează printre microorganismele tipice, alături de viridans, bovis, HACEK, S. aureus comunitar și enterococ.","Imunofluorescența pozitivă pentru febra Q, cu IgG de fază 1 în titru >1:800, este criteriu major.","Hemoculturile persistente înseamnă același germen la interval de minimum 12 ore sau 3 din ≥4 seturi.","Nu: un singur set recoltat pe cateter nu îndeplinește criteriul major de persistență.","Nu: titrul de IgG de fază 1 cerut pentru febra Q este >1:800, nu 1:20."]],
 [8,"Reduce bacteriologia Duke la un set de cateter și comprimă titrul Q de la >1:800 la 1:20."],["Abiotrophia",">1:800"]),

q("cardiologie-adv-274",["Suspiciune clinică înaltă de endocardită:",
 ["suflu nou de regurgitare sau embolie inexplicabilă","febră cu material protetic, CDIV sau prima IC","leziuni Osler, Janeway, Roth sau abcese fără focar","febra izolată, fără alte semne asociate","infirmată de o singură hemocultură negativă"],"ABC",1105,"Endocardita — Suspiciune înaltă versus joasă",
 "Listarea semnalelor de alarmă (suflu nou, embolie, proteză, Roth/Osler) versus febra izolată (suspiciune joasă).",
 ["Leziunea valvulară sau suflul de regurgitare nou, evenimentele embolice de cauză necunoscută și sepsisul fără focar definesc suspiciunea înaltă.","Febra asociată cu material protetic, CDIV, tulburări de conducere noi sau prima IC definește suspiciunea înaltă.","Leziunile Osler, Janeway, Roth și abcesele periferice (renale, splenice, spinale) fără focar completează criteriile.","Nu: febra izolată, fără alte elemente, definește suspiciunea joasă.","Nu: o hemocultură negativă nu închide cazul, iar nici o eco negativă nu exclude diagnosticul."]],
 [8,"Promotează febra izolată — tocmai suspiciunea joasă — ca alarmă înaltă și tratează o cultură negativă ca excludere."],["Noduli Osler","Leziuni Janeway"]),

q("cardiologie-adv-275",["Ecocardiografia și antibioterapia în endocardită:",
 ["eco-ul nu e screening la probabilitate pre-test redusă","eco negativă nu exclude; pe proteză ajută ETE, PET-CT","antibioterapie 4-6 săptămâni, combinații posibil sinergice","antibioterapie empirică începută înaintea hemoculturilor","eco ca screening de rutină la febra izolată"],"ABC",1105,"Endocardita — Eco nu e screening; 4-6 săptămâni",
 "Restrângerea eco-ului ca screening, rolul PET-CT pe proteză și fereastra 4-6 săptămâni.",
 ["Ecocardiografia nu este un test de screening la probabilitate pre-test redusă (doar febră sau o singură hemocultură pozitivă).","O eco negativă nu exclude diagnosticul; ETE și PET-CT pot ajuta, mai ales pe proteză.","Tratamentul durează 4-6 săptămâni, iar combinațiile pot fi sinergice și pot reduce rezistența.","Nu: hemoculturile se recoltează înaintea antibioterapiei empirice.","Nu: la probabilitate pre-test redusă, cum este febra izolată, eco-ul nu se folosește ca screening."]],
 [8,"Transformă eco-ul negativ al febrei izolate în confirmare chirurgicală, inversul regulii de screening."],["4-6 săptămâni","PET-CT"]),

q("cardiologie-adv-276",["Scheme de antibioterapie în endocardită (Cadranul 30.48):",
 ["fără suspiciune stafilococică: penicilină 1,2 g/4 h + gentamicină","suspiciune stafilococică: vancomicină 1 g/12 h + gentamicină","enterococ fără rezistență înaltă: ampicilină 2 g/4 h + gentamicină","suspiciune stafilococică: penicilină 1,2 g oral, monoterapie","CDIV: vancomicina evitată, rezervată streptococilor orali"],"ABC",1106,"Endocardita — Cadranul 30.48 (doze)",
 "Potrivirea penicilină 1,2 g la 4 ore versus vancomicină 1 g la 12 ore la suspiciunea stafilococică.",
 ["Fără suspiciune de stafilococ se dă penicilină 1,2 g la 4 ore plus gentamicină 80 mg la 12 ore.","La suspiciune stafilococică (CDIV, dispozitive, chirurgie recentă) se dă vancomicină 1 g la 12 ore plus gentamicină 80-120 mg la 8 ore.","Enterococul fără rezistență înaltă la gentamicină se tratează cu ampicilină/amoxicilină 2 g la 4 ore plus gentamicină 80 mg la 12 ore.","Nu: suspiciunea stafilococică nu se tratează cu penicilină orală în monoterapie, ci cu vancomicină plus gentamicină.","Nu: vancomicina este tocmai linia pentru CDIV și dispozitive."]],
 [8,"Inversează schemele: pune penicilina orală pe stafilococ și scoate vancomicina de la CDIV."],["1,2 g","Vancomicină 1 g"]),

q("cardiologie-adv-277",["Alergia la penicilină în endocardită:",
 ["poate pune probleme serioase, penicilinele fiind fundamentale","se investighează înainte de excluderea penicilinei","șocul anafilactic cântărește altfel decât disconfortul digestiv","disconfortul digestiv cântărește cât șocul anafilactic","gentamicina și vancomicina nu necesită monitorizare"],"ABC",1106,"Endocardita — Alergia la penicilină",
 "Diferențierea anafilaxiei de disconfortul digestiv înainte de a priva pacientul de penicilină.",
 ["Penicilinele sunt fundamentale în endocardită, iar alergia poate pune probleme serioase de alegere a schemei.","Caracterul alergiei trebuie investigat, ca pacientul să nu fie privat inutil de antibioticul adecvat.","Șocul anafilactic are altă pondere decât un simplu disconfort gastro-intestinal.","Nu: un disconfort digestiv nu are ponderea unui șoc anafilactic.","Nu: nivelurile de gentamicină și vancomicină trebuie monitorizate."]],
 [8,"Echivalează disconfortul digestiv cu anafilaxia — tocmai distincția pe care textul o cere."],["Şocul anafilactic","penicilină"]),

q("cardiologie-adv-278",["Imagistica în miocardita acută:",
 ["IRM: edem miocardic pe secvențele ponderate T2","IRM: captare neuniformă de gadoliniu, medio-epicardică","eco: funcție normală/redusă, anomalii de cinetică regională","IRM: captare subendocardică, într-un teritoriu coronarian","serologie virală confirmatorie, în locul IRM"],"ABC",1119,"Miocardită — T2, gadoliniu medio-epicardic",
 "Contrastul captării medio-epicardice neuniforme cu pattern-ul subendocardic de infarct.",
 ["Edemul miocardic apare pe secvențele IRM ponderate T2.","IRM-ul arată captare neuniformă de gadoliniu, în stratul mediu și epicardic.","Ecocardiografia poate arăta funcție biventriculară normală sau redusă și anomalii de cinetică regională.","Nu: captarea subendocardică sau transmurală într-un teritoriu coronarian este pattern-ul de infarct, nu de miocardită.","Nu: serologia virală de obicei nu este utilă; confirmarea se face prin IRM."]],
 [8,"Atribuie miocarditei captarea subendocardică de infarct, inversând localizarea gadoliniului."],["gadoliniu","ponderate T2"]),

q("cardiologie-adv-279",["Penetranța CMH în funcție de genă și vârstă:",
 ["hipertrofia poate lipsi înainte de adolescență","mutațiile MYBPC pot debuta abia în decada a șasea","moartea subită, până la 6%/an, culminează la vârstnici","hipertrofie deja prezentă la copii, diagnostic ușor","moarte subită sub 0,1%/an la adolescenți"],"AB",1120,"CMH — Decada a șasea, adolescență, 6%/an",
 "Potrivirea ferestrei pre-adolescență (hipertrofie absentă), a debutului MYBPC în decada a șasea și a vârfului de 6%/an la tineri.",
 ["Hipertrofia poate fi absentă înainte de adolescență, ceea ce îngreunează diagnosticul la copii.","CMH prin mutația proteinei de legare a miozinei (MYBPC) poate să nu se manifeste până în decada a șasea sau mai târziu.","Nu: rata cea mai înaltă de moarte subită, până la 6% pe an, este la adolescenți și adulți tineri.","Nu: hipertrofia poate lipsi înainte de adolescență, ceea ce îngreunează diagnosticul la copii.","Nu: la adolescenți și adulții tineri rata morții subite ajunge până la 6% pe an."]],
 [8,"Comprimă moartea subită a adolescentului de la 6%/an la 0,1% și cere hipertrofie neonatală constantă."],["6% pe an","decada a şasea"]),

q("cardiologie-adv-280",["Cardiomiopatia hipertrofică:",
 ["apex dublu, prin contracție atrială puternică (S4)","puls carotidian sacadat (ejecție rapidă, apoi obstrucție)","deteriorare rapidă cu edem pulmonar la debutul FA","unde Q patologice, mai ales infero-laterale","apex hiperdinamic deplasat, ca în regurgitarea aortică"],"ABCD",1120,"CMH — Apex dublu, puls sacadat, FA cu EPA",
 "Reunirea apexului dublu, a pulsului sacadat, a Q infero-laterale și a EPA la debutul FA.",
 ["Pulsația apicală dublă se datorează contracției atriale puternice, care produce S4.","Pulsul carotidian sacadat rezultă din ejecția rapidă și obstrucția bruscă telesistolică a tractului de ejecție.","La apariția FA, pierderea contracției atriale și tahicardia cresc presiunea în AS, cu deteriorare rapidă și edem pulmonar acut.","Undele Q patologice apar mai ales în derivațiile infero-laterale.","Nu: palparea arată apex dublu și puls sacadat, nu apexul hiperdinamic deplasat al regurgitării aortice."]],
 [8,"Atribuie CMH apexul hiperdinamic al regurgitării aortice și neagă EPA-ul de la debutul FA."],["Pulsaţie apicală dublă","sacadat"]),

q("cardiologie-adv-281",["Ecocardiografia și chirurgia septului în CMH:",
 ["clasic: perete posterior mai gros decât septul","orice tipar, inclusiv concentric sau apical","rezecția chirurgicală septală, uneori indicată","SAM-ul valvei mitrale exclude diagnosticul de CMH","ablația cu alcool, fără alternativă chirurgicală"],"BC",1120,"CMH — SAM, hipertrofie apicală, rezecție septală",
 "Recunoașterea tiparelor (asimetric, concentric, apical) și a rezecției septale ca alternativă a alcoolului.",
 ["Nu: clasic, HVS este asimetrică, cu septul mai gros decât peretele posterior, SAM mitral și VS care se contractă puternic.","Poate exista orice tipar de hipertrofie, inclusiv concentric și apical.","Uneori este indicată rezecția chirurgicală a miocardului septal.","Nu: SAM face parte din mecanismul obstrucției în CMH, nu o exclude.","Nu: rezecția chirurgicală a miocardului septal este o alternativă la ablația cu alcool."]],
 [8,"Interzice rezecția septală — opțiunea citată — și cere hipertrofie simetrică fără SAM."],["mişcare anterioară","rezecţia chirurgicală"]),

q("cardiologie-adv-282",["Cardiomiopatia aritmogenă:",
 ["majoritatea pacienților sunt asimptomatici","VD adesea normal morfologic, cu aritmii semnificative","testarea genetică ar putea deveni gold standard","IRM fără valoare pentru infiltrația fibro-grăsoasă","transplant contraindicat, chiar în aritmia netratabilă"],"ABC",1121,"CMA — VD morfologic normal, transplant",
 "Reținerea discordanței (aritmii severe, VD eco-normal) și a nișei de transplant.",
 ["Cei mai mulți pacienți sunt asimptomatici; ocazional apare IC dreaptă în stadiile tardive.","Aspectul morfologic al VD este frecvent normal, în ciuda unor aritmii semnificative.","Testarea genetică ar putea deveni gold standardul în cardiomiopatia aritmogenă.","Nu: IRM-ul evaluează VD mai acurat și poate arăta infiltrația fibro-grăsoasă.","Nu: transplantul este ocazional indicat pentru aritmie netratabilă sau IC."]],
 [8,"Anulează transplantul — nișa aritmiei refractare — și supraestimează eco-ul față de IRM."],["asimptomatici","transplantul cardiac"]),

q("cardiologie-adv-283",["Cardiomiopatia dilatativă familială:",
 ["forma AD: actină, desmină, sarcoglicani, lamin a/c","forma X-linkată implică gena distrofinei","posibilă miopatie scheletică sau boală de conducere","distrofină în forma AD, lamin a/c X-linkat","pereți marcat îngroșați, ca în CMH"],"ABC",1122,"CMD — Actină, desmină, sarcoglicani",
 "Completarea listei de proteine citoscheletale AD și a asocierii cu miopatia/conducerea.",
 ["Forma autosomal dominantă implică gene pentru actină, desmină, troponină T, lanțul greu al β-miozinei, sarcoglicani, vinculină și lamin a/c.","Distrofina este gena implicată în forma X-linkată.","Unele mutații se asociază cu miopatie scheletică sau boală a sistemului de conducere.","Nu: atribuirea este inversată; distrofina ține de forma X-linkată, lamin a/c de forma AD.","Nu: grosimea pereților este prezervată, nu crescută ca în CMH."]],
 [8,"Inversează distrofina XL cu lamin a/c AD și pune hipertrofia CMH pe CMD."],["Desmină","sarcoglican"]),

q("cardiologie-adv-284",["Investigațiile în cardiomiopatia dilatativă:",
 ["eco: cord globulos, camere dilatate, funcție redusă","IRM: fibroză, inclusiv hipercaptare septală medio-miocardică","coronarografie/angio-CT la cei cu risc, în general >40 ani","biopsie endomiocardică de rutină, ca în amiloidoză","ECG constant normal, fără aritmii sau tulburări de conducere"],"ABC",1123,"CMD — Cord globulos, fibroză medio-miocardică, >40 ani",
 "Ierarhia eco globulos → IRM medio-miocardic → excluderea bolii coronariene peste 40 de ani, fără biopsie de rutină.",
 ["Eco-ul arată un cord cu aspect globulos, camere dilatate și funcție globală redusă.","IRM-ul poate arăta fibroză, inclusiv hipercaptare septală medio-miocardică.","Angiografia coronariană sau angio-CT se face la cei la risc: în general peste 40 de ani sau mai tineri cu factori de risc ori simptome.","Nu: biopsia nu este de rutină în CMD, spre deosebire de amiloidoză.","Nu: ECG-ul poate arăta modificări ST-T difuze, tahicardie, tulburări de conducere, FA, ESV sau TV."]],
 [8,"Promotează biopsia de rutină — explicit nerezervată CMD — și declară ECG-ul normal."],["globulos","medio-miocardică"]),

q("cardiologie-adv-285",["Cardiomiopatia restrictivă:",
 ["are ca asociere cea mai frecventă sarcoidoza","endocardita Loeffler și fibroza endomiocardică au eozinofilie","poate avea o formă idiopatică, uneori familială","include noncompactarea VS cu aspect spongiform apical","are PVJ scăzut, fără semnele Friedreich și Kussmaul"],"BC",1123,"Restrictivă — Loeffler, eozinofilie, familială",
 "Potrivirea Loeffler/fibrozei endomiocardice cu eozinofilia, distincte de noncompactarea apicală.",
 ["Nu: amiloidoza este cea mai frecventă asociere; sarcoidoza, endocardita Loeffler și fibroza endomiocardică sunt alte cauze.","Endocardita Loeffler și fibroza endomiocardică se asociază cu eozinofilie și fibroză mio- și endocardică.","Există o formă idiopatică, posibil familială.","Nu: noncompactarea VS, cu aspect spongiform apical, este o entitate distinctă.","Nu: PVJ este crescut, cu semnele Friedreich și Kussmaul."]],
 [8,"Suprapune restrictiva peste noncompactarea apicală și anulează semnele venoase clasice."],["Loeffler","eozinofilie"]),

q("cardiologie-adv-286",["Cadranul 30.53 (etiologii mai puțin uzuale de pericardită):",
 ["include procainamida, hidralazina, izoniazida și doxorubicina","include stafilococul, pneumococul, meningococul și borelioza","include iradierea, post-pericardiotomia și forma familială","include uremia, dar nu și pericardita mixedematoasă","prezintă hidralazina ca factor protector, nu cauzal"],"ABC",1125,"Pericardită — Procainamidă, hidralazină, bacterii",
 "Listarea medicamentelor lupogene/citotoxice și a spectrului bacterian din cadran.",
 ["Cadranul listează procainamida, hidralazina, izoniazida, doxorubicina și ciclofosfamida.","Spectrul bacterian include stafilococ, streptococ, pneumococ, meningococ, H. influenzae, micoplasmă, borelioză și chlamidii.","Iradierea, post-pericardiotomia și forma familială/idiopatică sunt listate.","Nu: cadranul include și pericardita mixedematoasă, alături de uremie, medicamente și bacterii.","Nu: hidralazina este o cauză (autoimună indusă) de pericardită, nu o protecție."]],
 [8,"Transformă hidralazina — cauză clasică de pericardită indusă — în factor protector."],["procainamidă","hidralazină"]),

q("cardiologie-adv-287",["Pericardita malignă:",
 ["cel mai frecvent: carcinom bronșic, mamar, limfom Hodgkin","se întâlnește, de asemenea, în leucemie","revărsat mare, adesea hemoragic, prin obstrucție limfatică","radioterapia toracică: revărsat și fibroză pericardică","melanomul nu se asociază cu afectare pericardică"],"ABCD",1126,"Pericardită malignă — Hodgkin, revărsat hemoragic",
 "Potrivirea triadei sân/pulmon/Hodgkin cu caracterul hemoragic prin obstrucție limfatică.",
 ["Cele mai frecvente cauze sunt carcinomul bronșic, carcinomul mamar și limfomul Hodgkin.","Leucemia se asociază, de asemenea, cu pericardita malignă.","Revărsatul mare este tipic, adesea hemoragic, prin obstrucția drenajului limfatic cardiac.","Radioterapia toracică poate produce revărsat seros sau hemoragic și fibroză pericardică.","Nu: melanomul se asociază, ca și leucemia, cu pericardita malignă."]],
 [8,"Scoate melanomul din lista de cauze — deși textul îl leagă explicit de pericardită."],["limfomul Hodgkin","hemoragic"]),

q("cardiologie-adv-288",["Pericardita incesantă sau cronică:",
 ["AINS/aspirină plus colchicină, până la 6 luni","la rezistență: corticoizi orali, uneori pericardectomie","CT/IRM: îngroșare pericardică >4 mm sau inflamație","colchicină 48 de ore, apoi pericardectomie","îngroșarea pericardică >4 mm infirmă constricția"],"ABC",1126,"Pericardită incesantă — Colchicină 6 luni, >4 mm",
 "Fereastra de până la 6 luni a colchicinei și pragul imagistic >4 mm de îngroșare.",
 ["Tratamentul de primă linie este AINS sau aspirină plus colchicină, până la 6 luni.","În rezistență, corticoterapia orală poate fi eficientă, iar la unii pacienți se recurge la pericardectomie.","CT sau IRM pot arăta îngroșare pericardică peste 4 mm sau inflamație.","Nu: colchicina se administrează până la 6 luni, iar pericardectomia nu este primul gest.","Nu: îngroșarea peste 4 mm orientează spre constricție sau inflamație, nu o infirmă."]],
 [8,"Comprimă colchicina de la 6 luni la 48 de ore și promovează pericardectomia ca primă linie."],["6 luni",">4 mm"]),

q("cardiologie-adv-289",["Pericardita constrictivă:",
 ["cabergolina și pergolida pot produce fibroză pericardică","clacment pericardic protodiastolic, parasternal stâng inferior","FA la circa 30%, prin dilatare atrială","FA excepțională, deoarece atriile rămân mici","cabergolina protejează de fibroza pericardică"],"ABC",1127,"Constricție — Cabergolină, clacment, FA 30%",
 "Reținerea cabergolinei/pergolidei ca fibrozante, a clacmentului protodiastolic și a FA la 30%.",
 ["Agoniștii dopaminergici cabergolină și pergolidă pot produce fibroză pericardică.","Clacmentul pericardic protodiastolic se aude la marginea sternală stângă inferioară.","Circa 30% dintre pacienți au FA, prin dilatare atrială.","Nu: circa 30% dintre pacienți au FA, iar atriile se dilată.","Nu: cabergolina este o cauză de fibroză pericardică, nu o protecție."]],
 [8,"Scoate cabergolina din lista de fibrizanți — etiologia medicamentoasă citată — și neagă FA-ul de 30%."],["cabergolina","30% din cazuri"]),

q("cardiologie-adv-290",["Revărsatul pericardic — puncție și fenestrație:",
 ["puncție la suspiciune de revărsat tuberculos, malign, purulent","biopsie pericardică la suspiciune de TB, cu puncție nediagnostică","fereastră pericardică la refill neoplazic","majoritatea revărsatelor nu se remit spontan","fenestrația se rezervă constricției calcificate, nu neoplaziilor"],"ABC",1127,"Revărsat — Pericardiocenteză TB/malign și fereastră",
 "Nișa puncției (TB, malign, purulent) și a fenestrației pentru refill-ul neoplazic.",
 ["Pericardiocenteza, aseptică și ghidată eco, este indicată la suspiciune de revărsat tuberculos, malign sau purulent.","Biopsia pericardică poate fi necesară dacă se suspectează TB, iar puncția nu este diagnostică.","La refill neoplazic, cauza cea mai frecventă de recidivă în UK, se poate crea o fereastră pericardică, percutan sau chirurgical.","Nu: cele mai multe revărsate se remit spontan.","Nu: fenestrația este indicată tocmai în recidiva neoplazică, nu în constricția calcificată."]],
 [8,"Interzice fenestrația neoplazică — indicația citată — și neagă remisiunea spontană a majorității revărsatelor."],["fenestrarea pericardică","Pericardiocenteza"]),

q("cardiologie-adv-291",["Oxalatul de naftidrofuril în claudicația intermitentă:",
 ["vasodilatator, inhibă receptorii 5-HT2 vasculari și trombocitari","100-200 mg ×3/zi poate crește distanța de mers","probă de 3-6 luni după eșecul efortului supervizat","înlocuiește controlul riscului și efortul de 2 ore/săptămână","tratament de primă intenție, înaintea efortului supervizat"],"ABC",1128,"BVP — Naftidrofuril 100-200 mg, 5-HT2",
 "Nișa de 3-6 luni a naftidrofurilului 100-200 mg ×3/zi, după eșecul efortului supervizat.",
 ["Naftidrofurilul este un vasodilatator care inhibă receptorii 5-HT2 vasculari și trombocitari și poate reduce lactatul.","Doza de 100-200 mg de trei ori pe zi poate crește distanța de mers și calitatea vieții.","Se consideră o probă de 3-6 luni când pacientul evită intervenția, iar efortul supervizat nu controlează simptomele.","Nu: nu înlocuiește controlul factorilor de risc și programul de efort de 2 ore pe săptămână.","Nu: nu este prima linie înaintea efortului supervizat."]],
 [8,"Pune naftidrofurilul înaintea efortului supervizat, deși textul îl rezervă eșecului reabilitării."],["naftidrofuril","5-hidroxitriptamină2"]),

q("cardiologie-adv-292",["Diagnosticul diferențial al claudicației intermitente:",
 ["include compresia poplitee la tineri, cu pulsuri posibil normale","include displazia fibromusculară","include claudicația venoasă (tensiune la mers, TVP în antecedente)","nu include displazia fibromusculară","include compresia poplitee, tipică vârstnicului fără pulsuri"],"ABC",1128,"BVP — Poplitee, displazie fibromusculară",
 "Adăugarea compresiei poplitee a tânărului cu pulsuri prezente și a displaziei fibromusculare la lista DD.",
 ["Compresia arterei poplitee apare la tineri, care pot avea pulsuri normale.","Displazia fibromusculară figurează în diagnosticul diferențial al claudicației.","Claudicația venoasă se manifestă prin senzație de tensiune la mers, la pacienți cu TVP în antecedente.","Nu: displazia fibromusculară face parte din diagnosticul diferențial al claudicației.","Nu: compresia poplitee este tipică tinerilor, care pot avea pulsuri normale."]],
 [8,"Mută compresia poplitee pe vârstnicul fără pulsuri și scoate displazia fibromusculară din lista DD."],["poplitee","fibromusculară"]),

q("cardiologie-adv-293",["Sensibilitatea indicelui gleznă-braț poate fi îmbunătățită prin:",
 ["urmărirea scăderii indicelui gleznă-braț după efort","palparea pulsului radial în locul Doppler-ului tibial","măsurarea presiunii brahiale, fără gleznă","ignorarea calcificării arteriale, care nu modifică IGB","evitarea presiunii de la degete la arterele incompresibile"],"A",1128,"BVP — IGB după efort",
 "Reținerea manevrei de efort care crește sensibilitatea IGB, distinctă de falsa creștere pe calcificare.",
 ["Sensibilitatea poate fi îmbunătățită urmărind scăderea IGB după efort.","Nu: palparea pulsului radial nu înlocuiește Doppler-ul tibial.","Nu: raportul gleznă/braț cere ambele măsurători.","Nu: pe arterele calcificate IGB este fals crescut.","Nu: la arterele incompresibile, presiunea de la degete este mai sensibilă."]],
 [8,"Anulează manevra de efort — metoda citată de a crește sensibilitatea IGB."],["după efort","1GB"]),

q("cardiologie-adv-294",["Revascularizarea în claudicația intermitentă:",
 ["rezervată, în general, simptomelor severe sau invalidante","prima opțiune: angioplastie percutană pe cateter femural","nu înlocuiește controlul agresiv al riscului","precede efortul supervizat în claudicația neseveră","ASD de screening la asimptomaticii Fontaine I"],"ABC",1128,"BVP — PTA femurală, nu rutină",
 "Rezervarea angioplastiei cazurilor invalidante, cu abord femural ca primă opțiune intervențională.",
 ["Intervenția nu este în general recomandată, cu excepția simptomelor severe sau invalidante.","Angioplastia transluminală percutană, pe cateter inserat în artera femurală, este prima opțiune intervențională.","Controlul agresiv al riscului rămâne necesar, deoarece BVP expune la BCI și boală cerebrovasculară.","Nu: în claudicația neseveră efortul supervizat precede intervenția.","Nu: ASD se folosește imediat înaintea intervenției, nu ca screening în stadiul Fontaine I."]],
 [8,"Oferă PTA-ul de primă intenție claudicației ușoare, sărind efortul supervizat de 2 ore."],["Angioplastia transluminală","femurală"]),

q("cardiologie-adv-295",["Mortalitatea prin boli cardiovasculare și cerebrovasculare coexistente în BVP face ca:",
 ["doar o parte să ajungă la amputație","peste 90% să ajungă la amputație","boala aorto-iliacă să nu crească riscul coronarian","stadiul Fontaine I să corespundă gangrenei","IGB să nu mai stratifice severitatea"],"A",1128,"BVP — Amputația nu este regula",
 "Reținerea faptului că mortalitatea CV/cerebrovasculară coexistentă precede adesea amputația.",
 ["Din cauza mortalității cardiovasculare și cerebrovasculare coexistente, doar o parte dintre pacienții cu BVP ajung la amputație.","Nu: amputația nu este regula; doar o parte dintre pacienți ajung la ea.","Nu: boala aorto-iliacă se asociază cu risc de BCI.","Nu: stadiul Fontaine I este forma asimptomatică.","Nu: IGB stratifică severitatea BVP."]],
 [8,"Transformă amputația — evitată de mortalitatea CV competitivă — în soarta a peste 90% din BVP."],["amputaţie","cerebrovasculare"]),

q("cardiologie-adv-296",["IRM-ul cardiac în CMH:",
 ["detectează atât hipertrofia, cât și fibroza miocardică","evidențiază calcificările pericardice caracteristice CMH","arată tipic captare subendocardică de tip infarct","detectează hipertrofia, dar nu și fibroza miocardică","este inutil dacă eco-ul arată SAM"],"A",1120,"CMH — IRM: hipertrofie și fibroză",
 "Reținerea dublului rol al IRM (masă + fibroză), ilustrat în Fig. 30.109.",
 ["IRM-ul detectează atât hipertrofia, cât și fibroza miocardică.","Nu: calcificările pericardice țin de pericardita constrictivă, nu de CMH.","Nu: captarea subendocardică de tip infarct nu este pattern-ul tipic al fibrozei din CMH.","Nu: IRM-ul evidențiază și fibroza miocardică.","Nu: IRM-ul aduce informații despre fibroză, dincolo de SAM-ul vizibil la eco."]],
 [8,"Reduce IRM-ul CMH la un eco de SAM și neagă fibroza — tocmai ceea ce Fig. 30.109 arată."],["fibroză","hipertrofia"]),

q("cardiologie-adv-297",["Cardiomiopatia dilatativă sporadică:",
 ["poate urma miocarditelor: Coxsackie, eritrovirus, HIV, Chagas","poate fi toxică: alcool, chimioterapie, cobalt, plumb, arsen","apare și în boli autoimune, endocrine, neuromusculare","formă sarcomerică MYH7, cu fenotip identic CMH","are pereții îngroșați, fără dilatarea cavităților ventriculare"],"ABC",1122,"CMD sporadică — Eritrovirus, metale, autoimun",
 "Completarea listei sporadice cu eritrovirusul, micobacteriile și metalele (Co/Pb/Hg/As).",
 ["Miocardita (Coxsackie, adenovirus, eritrovirus, HIV, bacterii, fungi, micobacterii, paraziți ca în boala Chagas) poate cauza CMD sporadică.","Toxicele includ alcoolul, chimioterapia și metalele (cobalt, plumb, mercur, arsen).","Bolile autoimune, endocrine și neuromusculare completează lista cauzelor sporadice.","Nu: CMD, inclusiv cea sporadică, are pereți de grosime prezervată și cavități dilatate, nu fenotip de CMH; cauzele sporadice sunt infecțioase, toxice, autoimune, endocrine sau neuromusculare.","Nu: în CMD pereții au grosime prezervată, iar cavitățile sunt dilatate."]],
 [8,"Reduce CMD sporadică la MYH7 sarcomeric și cere hipertrofie, fenotipul CMH."],["eritrovirusuri","cobalt"]),

q("cardiologie-adv-298",["Cardiomiopatia dilatativă — evaluarea rudelor:",
 ["permite identificarea bolii în stadii precoce, asimptomatice","include istoricul familial și arborele genealogic","posibile manifestări: IC, aritmii, embolii, moarte subită","se amână până la primele complicații embolice","nu necesită arbore genealogic, boala fiind non-familială"],"ABC",1122,"CMD — Screening-ul rudelor",
 "Rolul screening-ului familial înaintea complicațiilor (embolie, MSC, blocuri).",
 ["Evaluarea rudelor identifică boala în stadii precoce, asimptomatice, înaintea complicațiilor.","Istoricul familial și arborele genealogic fac parte din evaluarea clinică.","Boala se poate manifesta prin IC, aritmii, tulburări de conducere, embolii sau moarte subită.","Nu: screening-ul familial precede complicațiile, nu le așteaptă.","Nu: există o formă familială autosomal dominantă, deci arborele genealogic contează."]],
 [8,"Amână screening-ul familial până după embolie, deși textul îl plasează înaintea complicațiilor."],["rudelor","arborelui genealogic"]),

q("cardiologie-adv-299",["Tratamentul cardiomiopatiei dilatative avansate:",
 ["NYHA III-IV: tratament IC, plus opțiunea CRT/ICD","transplantul cardiac, recomandat la unii pacienți","biopsia endomiocardică de primă intenție, înaintea terapiei IC","CRT/ICD indicate preferențial în NYHA I","contraindicarea transplantului la fibroză medio-miocardică"],"AB",1123,"CMD — CRT/ICD în NYHA III-IV",
 "Reținerea nișei CRT+ICD la NYHA III-IV și a transplantului la selecționați.",
 ["La clasele NYHA III-IV, abordarea include tratamentul general al IC, cu opțiunea CRT și ICD.","Transplantul cardiac este recomandat la unii pacienți.","Nu: biopsia nu este de rutină și nu precede terapia IC.","Nu: CRT și ICD sunt indicate la clasele NYHA III-IV, nu în clasa I.","Nu: fibroza medio-miocardică la IRM nu contraindică transplantul."]],
 [8,"Mută CRT-D de la NYHA III-IV la clasa I și interzice transplantul."],["NYHA III","IV"]),

q("cardiologie-adv-300",["Chilopericardul și pericardita mixedematoasă:",
 ["figurează ca entități distincte în Cadranul 30.53","mixedemul: cauză metabolică, alături de uremie","chilopericardul a înlocuit uremia ca etiologie dominantă","mixedemul: cauză de BAV complet, nu de pericardită","chilopericardul, inclus la tamponada malignă, fără linie proprie"],"AB",1125,"Pericard — Chilopericard și mixedem",
 "Recunoașterea celor două linii mai puțin citate din Cadranul 30.53 (chilopericard, mixedem).",
 ["Ambele figurează ca entități distincte în Cadranul 30.53.","Mixedemul ține de etiologiile metabolice, alături de forma uremică.","Nu: uremia rămâne o cauză clasică și nu este înlocuită de chilopericard.","Nu: în cadran mixedemul este o etiologie de pericardită.","Nu: chilopericardul are linie proprie în cadran."]],
 [8,"Scoate mixedemul din pericard — deși cadranul îl listează — și îl mută pe BAV."],["Chilopericardul","mixedematoasă"]),

q("cardiologie-adv-301",["Radiografia de profil în pericardita constrictivă este utilă pentru:",
 ["detectarea calcificărilor omise pe clișeul postero-anterior","înlocuirea ECG-ului, cu QRS normal în constricție","confirmarea constricției prin simpla prezență a calcificărilor","demonstrarea cordului globulos, ca în tamponadă","înlocuirea CT/IRM în evaluarea grosimii pericardului"],"A",1127,"Constricție — Radiografie de profil",
 "Reținerea nișei incidenței de profil pentru calcificări omise pe clișeul PA.",
 ["O radiografie de profil poate detecta calcificările omise pe incidența postero-anterioară.","Nu: ECG-ul nu se înlocuiește; în constricție arată microvoltaj cu unde T aplatizate sau inversate.","Nu: un pericard calcificat nu înseamnă constricție.","Nu: în constricție cordul este relativ mic, nu globulos.","Nu: CT și IRM evaluează grosimea pericardului, iar radiografia nu le înlocuiește."]],
 [8,"Transformă profilul — manevră pentru calcificări omise — într-un substitut de ECG normal sau de cord globulos."],["de profil","postero-anterioară"]),

q("cardiologie-adv-302",["Semnele tamponadei cardiace:",
 ["PVJ crescută, cu pantă descendentă X ascuțită","semnul Kussmaul (turgescență jugulară crescută în inspir)","puls paradoxal: TA sistolică scade ≥10 mmHg în expir","descendentă y adâncă (Friedreich), ca în constricție","zgomote cardiace accentuate și apex hiperdinamic"],"AB",1127,"Tamponadă — Pantă X, Kussmaul, paradox ≥10 mmHg",
 "Potrivirea pantei X ascuțite și a paradoxului ≥10 mmHg în inspir, distincte de y-ul constricției.",
 ["Pe măsură ce revărsatul crește, PVJ crește, cu ascuțirea pantei descendente X.","Semnul Kussmaul, creșterea turgescenței jugulare în inspir, este listat.","Nu: pulsul paradoxal este scăderea presiunii sistolice cu ≥10 mmHg în inspir, nu în expir.","Nu: descendenta y adâncă (Friedreich) aparține constricției, nu tamponadei.","Nu: în tamponadă zgomotele cardiace sunt diminuate, iar apexul este mascat."]],
 [8,"Atribuie tamponadei descendentul y al constricției și apexul hiperdinamic al regurgitării aortice."],["10 mmHg","Kussmaul"]),

q("cardiologie-adv-303",["Semne ecocardiografice de tamponadă:",
 ["septul interventricular deviat spre VS în inspir","flux venos hepatic diastolic inversat în expir","VCI mică, cu colaps inspirator >50%","septul interventricular deviat spre VD în inspir","flux venos hepatic diastolic inversat în inspir"],"AB",1127,"Tamponadă — Sept spre VS, vene hepatice",
 "Completarea criteriilor eco cu septul inspirator către VS și inversarea hepatică expiratorie.",
 ["În tamponadă septul interventricular se deplasează spre VS în inspir.","Fluxul diastolic din venele hepatice se inversează în expir.","Nu: VCI este dilatată, cu colaps inspirator sub 50%.","Nu: deplasarea inspiratorie a septului este spre VS, nu spre VD.","Nu: inversarea fluxului hepatic apare în expir, nu în inspir."]],
 [8,"Inversează direcția septului (spre VS) și timing-ul fluxului hepatic (expir)."],["venele hepatice","septului"]),

q("cardiologie-adv-304",["CT sau IRM-ul cardiac sunt utile în revărsatele pericardice:",
 ["închistate, apărute după chirurgia cardiacă","ca primă investigație, înaintea ecocardiografiei","purulente, în locul pericardiocentezei","ca alternativă la ghidajul eco al puncției","din pericardita virală autolimitată, ca screening"],"A",1127,"Revărsat — CT/IRM pentru loculări postoperatorii",
 "Reținerea nișei CT/IRM: revărsate închistate după chirurgia cardiacă.",
 ["CT-ul sau IRM-ul sunt rezervate revărsatelor închistate după chirurgia cardiacă.","Nu: ecocardiografia rămâne cea mai utilă tehnică de demonstrare a revărsatului.","Nu: suspiciunea de puroi este o indicație de pericardiocenteză, care nu se înlocuiește prin CT.","Nu: puncția se face sub ghidaj eco.","Nu: revărsatul din pericardita virală autolimitată nu cere CT sau IRM de screening; acestea se rezervă revărsatelor închistate după chirurgia cardiacă."]],
 [8,"Extinde CT/IRM-ul loculat postoperator la screening-ul pericarditei virale fără lichid."],["închistate","post-chirurgie cardiacă"]),

q("cardiologie-adv-305",["În cazurile dificile de constricție versus cardiomiopatie restrictivă, poate fi utilă:",
 ["biopsia endomiocardică","palparea izolată a apexului","radiografia de față, în locul CT/IRM","cateterismul, cu presiuni telediastolice inegale în constricție","evitarea biopsiei, diferențierea fiind imposibilă"],"A",1127,"Constricție — Biopsie versus restrictivă",
 "Reținerea biopsiei endomiocardice ca instrument de diferențiere constricție/restrictivă în cazurile dificile.",
 ["Biopsia endomiocardică poate fi utilă în cazurile dificile, pentru diferențierea de cardiomiopatia restrictivă.","Nu: palparea izolată nu înlocuiește imagistica.","Nu: CT/IRM evaluează grosimea pericardului, iar incidența de profil completează radiografia de față.","Nu: în constricție cateterismul arată presiuni telediastolice VS/VD egale, nu inegale.","Nu: biopsia este menționată tocmai pentru această diferențiere."]],
 [8,"Anulează biopsia — metoda citată de a despărți constricția de restrictivă — și inversează egalizarea presiunilor."],["Biopsia endomiocardică","restrictivă"]),

q("cardiologie-adv-306",["După pericardiocenteza pentru tamponadă:",
 ["un dren poate rămâne temporar, pentru evacuare suficientă","se caută și se tratează cauza subiacentă","hemoculturi sau autoanticorpi, după caz","drenajul prelungit face inutilă căutarea cauzei","fenestrație de primă intenție în revărsatul viral autolimitat"],"ABC",1127,"Revărsat — Dren temporar și cauza subiacentă",
 "Nișa drenului temporar post-puncție și a investigațiilor etiologice (culturi, autoanticorpi).",
 ["Un dren poate fi lăsat temporar pe loc, pentru eliminarea suficientă a lichidului.","Cauza subiacentă trebuie căutată și tratată ori de câte ori este posibil.","Hemoculturile sau determinarea autoanticorpilor se fac după caz.","Nu: revărsatul se poate reface, iar căutarea cauzei rămâne esențială.","Nu: fenestrația este pentru refill-ul neoplazic, nu pentru forma virală autolimitată."]],
 [8,"Pune fenestrația pe revărsatul viral autolimitat și anulează căutarea cauzei după puncție."],["dren","autoanticorpi"]),

q("cardiologie-adv-307",["Mortalitatea la 30 de zile pentru scorul TIMI STEMI 7 este de circa:",
 ["4,4%","12,4%","23,4%","35,9%","0,8%"],"C",1088,"STEMI — TIMI scor 7 → 23,4%",
 "Memorarea treptei 7 puncte → 23,4%, intercalată între 16,1% (6 puncte) și 26,8% (8 puncte).",
 ["Nu: 4,4% corespunde scorului TIMI 3.","Nu: 12,4% corespunde scorului TIMI 5.","Conform Cadranului 30.39, scorul TIMI STEMI 7 corespunde unei mortalități la 30 de zile de 23,4%.","Nu: 35,9% corespunde scorurilor de peste 8 puncte.","Nu: 0,8% corespunde scorului TIMI 0."]],
 [8,"Permutează treptele 5/7/9-16 ale aceluiași tabel; doar scorul 7 dă 23,4%."],["23,4%","30 zile"]),

q("cardiologie-adv-308",["Durabilitatea protezelor valvulare:",
 ["poate depăși 20 de ani de funcționare","impune înlocuirea de rutină după 2 ani","este limitată, în general, la circa 5 ani","rămâne, în general, sub 3 ani","se limitează la 1 an pentru protezele biologice"],"A",1095,"Proteze — Durabilitate peste 20 de ani",
 "Reținerea durabilității >20 de ani a protezelor, distinctă de degenerarea biologică la circa 10 ani.",
 ["Protezele valvulare pot avea o durabilitate de peste 20 de ani.","Nu: protezele pot funcționa peste 20 de ani, fără înlocuire de rutină la 2 ani.","Nu: durabilitatea protezelor poate depăși 20 de ani, nu se limitează la circa 5 ani.","Nu: protezele valvulare pot depăși 20 de ani de funcționare.","Nu: protezele biologice degenerează după circa 10 ani, nu după 1 an."]],
 [8,"Comprimă durabilitatea de peste 20 de ani la ferestre din SCA/FA (6 luni, 48 de ore)."],["20 de ani","Protezele valvulare"]),
];
